#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_SIZE 1024
#define RECORD_RANGE 1000

struct record {
    int value;
};

void* manage_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed. Exiting.\n");
        exit(1);
    }
    return ptr;
}

int initialize_records(int num_records, struct record** records) {
    for (int i = 0; i < num_records; i++) {
        int value = rand() % RECORD_RANGE;
        while (value == records[i]->value && i > 0) {
            value = rand() % RECORD_RANGE;
        }
        records[i]->value = value;
    }
    return 0;
}

void cleanup_resources(void* ptr, size_t size) {
    free(ptr);
}

int main(int argc, char** argv) {
    int num_records;
    printf("Enter the number of records: ");
    scanf("%d", &num_records);

    if (num_records > MAX_SIZE) {
        printf("Exceeding maximum size. Exiting.\n");
        return 1;
    }

    struct record* records = manage_memory(num_records * sizeof(struct record));
    initialize_records(num_records, &records);
    cleanup_resources(records, num_records * sizeof(struct record));

    return 0;
}
