#define MAX_FILE_SIZE 1000000 // adjust as needed

int main(int argc, char *argv[]) {
    int opt;
    FILE *fp = NULL;
    FILE *opfp = NULL;

    while ((opt = getopt(argc, argv, "hfl:i:o:")) != -1) {
        switch (opt) {
            case 'h':
                printf("Usage: %s [-h] [-f file] [-l] [-i input_file] [-o output_file]\n", argv[0]);
                return 0;
            case 'f':
                fp = fopen(optarg, "r");
                if (!fp) {
                    fprintf(stderr, "Error opening file '%s'\n", optarg);
                    return 1;
                }
                break;
            case 'l':
                // line count
                break;
            case 'i':
                printf("Input file: %s\n", optarg);
                break;
            case 'o':
                opfp = fopen(optarg, "w");
                if (!opfp) {
                    fprintf(stderr, "Error opening output file '%s'\n", optarg);
                    return 1;
                }
                break;
        }
    }

    if (!fp || !*argv[1]) {
        printf("Usage: %s [-h] [-f file] [-l] [-i input_file] [-o output_file]\n", argv[0]);
        return 0;
    }

    // logging setup
    struct timespec start, end;
    clock_gettime(CLOCK_REALTIME, &start);

    // processing loop
    char line[MAX_FILE_SIZE];
    int len;
    int line_count = 0;

    while (fgets(line, sizeof(line), fp)) {
        // process the line
        if (*line) {
            ++line_count;
        }
        len = strlen(line);
        if (len <= 100 && opfp) {
            fwrite(line, 1, len, opfp);
        }
    }

    fclose(fp);
    if (opfp) {
        fclose(opfp);
    }

    clock_gettime(CLOCK_REALTIME, &end);

    // logging and reporting
    printf("Lines processed: %d\n", line_count);
    printf("Time taken: %ld seconds\n", (end.tv_sec - start.tv_sec));

    return 0;
}
