#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <resolv.h>
#include <netinet/in.h>

#define MAX_HOSTNAME 256
#define MAX_IP_ADDRESS 16
#define BUFFER_SIZE 1024
#define AVERAGE_CALCULATION_WINDOW 2

typedef struct {
    unsigned long long average;
    int count;
} AverageStats;

int dns_resolve(char* hostname, u_char** ip_address) {
    struct hostent* host_entry = gethostbyname(hostname);
    if (host_entry == NULL) {
        return -1; // Error
    }
    char* ip_addr = inet_ntoa(*reinterpret_cast<in_addr*>(host_entry->h_addr));
    *ip_address = (u_char*)malloc(strlen(ip_addr) + 1);
    strcpy((char*)*ip_address, ip_addr);
    return 0;
}

AverageStats calculate_average(char* line) {
    AverageStats stats;
    stats.count = 0;
    stats.average = 0;

    char* token = strtok(line, " ");
    while (token != NULL && stats.count < AVERAGE_CALCULATION_WINDOW) {
        if (sscanf(token, "%llu", &stats.average) == 1) {
            stats.count++;
            token = strtok(NULL, " ");
        }
    }

    return stats;
}

int process_log_file(char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        return -1; // Error
    }

    char* line = (char*)malloc(BUFFER_SIZE);
    int total_lines = 0;

    AverageStats* average_stats = (AverageStats*)malloc(sizeof(AverageStats));
    average_stats->count = 0;
    average_stats->average = 0;

    while (fgets(line, BUFFER_SIZE, file) != NULL) {
        AverageStats line_stats = calculate_average(line);
        if (line_stats.count > 0) {
            average_stats->average += line_stats.average;
            average_stats->count++;
        }

        free(line);
        line = (char*)malloc(BUFFER_SIZE);

        total_lines++;

        if (total_lines >= 10000) {
            break; // Handle up to 10,000 lines efficiently
        }
    }

    fclose(file);
    free(average_stats);
    free(line);

    return 0;
}

int main() {
    u_char* ip_address = NULL;
    int status = dns_resolve("example.com", &ip_address);
    if (status == -1) {
        // Handle error
    }
    else {
        printf("%s\n", (char*)ip_address); // Print the resolved IP address

        char* filename = "large_log_file.txt";
        process_log_file(filename);

        free(ip_address);
    }

    return 0;
}
