#include <string.h>

int largest_integer(int* arr, int size);

int main() {
    int max_size = 10000; // Default maximum list size
    printf("Enter the maximum size of the input list (max: %d): ", max_size);
    scanf("%d", &max_size); // Validate user-provided maximum size

    int* integers = NULL;
    int size = 0;

    while (1) {
        char buffer[100];
        fgets(buffer, sizeof(buffer), stdin);

        // Check for invalid data or incomplete input
        if (strlen(buffer) <= 2 || strcmp(buffer + strlen(buffer) - 1, "\n") != 0) {
            printf("Invalid input. Please enter a list of integers separated by spaces.\n");
            continue;
        }

        char* token = strtok(buffer, " ");
        while (token) {
            int num = atoi(token);

            // Check for integer overflow
            if (num > INT_MAX || num < INT_MIN) {
                printf("Error: Integer out of range. Please enter a valid list.\n");
                exit(1);
            }

            size++;
            integers = realloc(integers, sizeof(int) * size);
            integers[size - 1] = num;

            token = strtok(NULL, " ");
        }

        if (size > max_size) {
            printf("Error: Input list exceeds the specified maximum size of %d.\n", max_size);
            free(integers);
            exit(1);
        }

        break;
    }

    int largest = largest_integer(integers, size);

    printf("The largest integer in the array is: %d\n", largest);

    free(integers);
    return 0;
}

int largest_integer(int* arr, int size) {
    int max = INT_MIN;

    for (int i = 0; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }

    return max;
}
