#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <pthread.h>

#define LOG_BUFFER_SIZE 1024
#define LOG_FORMATTED_LENGTH_MAX 512

typedef struct {
    pthread_mutex_t mutex;
    char buffer[LOG_BUFFER_SIZE];
    int head, tail, length;
} CircularBuffer;

CircularBuffer *log_buffer = NULL;

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);

    pthread_mutex_lock(&log_buffer->mutex);
    int length = snprintf(NULL, 0, format, args);
    if (length > LOG_FORMATTED_LENGTH_MAX) {
        length = LOG_FORMATTED_LENGTH_MAX;
    }

    char *formatted_message = malloc(length + 1);
    vsnprintf(formatted_message, length + 1, format, args);
    va_end(args);

    int buffer_left = LOG_BUFFER_SIZE - log_buffer->length;

    if (buffer_left < length) {
        // Buffer is full. Move old data to the beginning of the buffer.
        memmove(log_buffer->buffer, log_buffer->buffer + length, buffer_left);
        log_buffer->head += length;
        log_buffer->length -= length;
    }

    // Append new message
    memcpy(log_buffer->buffer + log_buffer->tail, formatted_message, length);
    log_buffer->tail = (log_buffer->tail + length) % LOG_BUFFER_SIZE;
    log_buffer->length += length;

    free(formatted_message);

    pthread_mutex_unlock(&log_buffer->mutex);
}

void init_log_buffer() {
    log_buffer = malloc(sizeof(CircularBuffer));
    pthread_mutex_init(&log_buffer->mutex, NULL);
    log_buffer->head = 0;
    log_buffer->tail = 0;
    log_buffer->length = 0;
}

void destroy_log_buffer() {
    pthread_mutex_lock(&log_buffer->mutex);
    free(log_buffer->buffer);
    pthread_mutex_unlock(&log_buffer->mutex);
    free(log_buffer);
}
