import yaml
import ruamel.yaml

def generate_kubernetes_deployment_yaml(params):
    deployment_template = """
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ params['deployment_name'] }}
spec:
  replicas: {{ params['replicas'] }}
  selector:
    matchLabels:
      app: {{ params['app_name'] }}
  template:
    metadata:
      labels:
        app: {{ params['app_name'] }}
    spec:
      containers:
      - name: {{ params['container_name'] }}
        image: {{ params['image'] }}
        resources:
          limits:
            cpu: {{ params['cpu_limit'] }}
            memory: {{ params['memory_limit'] }}
          requests:
            cpu: {{ params['cpu_request'] }}
            memory: {{ params['memory_request'] }}
    """

    deployment_yaml = ruamel.yaml.YAML().dump(deployment_template.format(params=params))

    try:
        yaml.safe_load(deployment_yaml)
    except Exception as e:
        raise ValueError(f"Invalid YAML: {str(e)}")

    return deployment_yaml
