package com.example.pokemonreporting;

import java.util.*;
import retrofit2.*;

public class PokemonReportingService {
    private static final String API_URL = "https://api.pokemontypes.com/types";
    private static final int CACHING_TIME_MINS = 30; // adjust to suit your needs

    public Map<String, PokemonReport> getReports() throws IOException {
        Map<String, PokemonReport> reports = new HashMap<>();

        // fetch data from API (with caching)
        Retrofit retrofit = new Retrofit.Builder()
                .baseUrl(API_URL)
                .addConverterFactory(CacheConverter.create(CACHING_TIME_MINS))
                .build();
        PokemonApi api = retrofit.create(PokemonApi.class);

        try {
            List<PokemonType> types = api.getTypes().execute().body();
            for (PokemonType type : types) {
                reports.put(type.getName(), processPokemon(type));
            }
        } catch (IOException e) {
            // handle API error
            System.out.println("Error fetching data: " + e.getMessage());
        }

        return reports;
    }

    private PokemonReport processPokemon(PokemonType pokemonType) {
        PokemonReport report = new PokemonReport();

        // analyze type for weaknesses, resistances, and immunities
        report.setWeaknesses(pokemonType.getWeaknesses());
        report.setResistances(pokemonType.getResistances());
        report.setImmunities(pokemonType.getImmunities());

        return report;
    }

    public class PokemonReport {
        private List<String> weaknesses;
        private List<String> resistances;
        private List<String> immunities;

        // getters and setters for each attribute
    }
}

// additional classes:

public interface PokemonApi {
    @GET("types")
    Call<List<PokemonType>> getTypes();
}

public class PokemonType {
    private String name;
    private List<String> weaknesses;
    private List<String> resistances;
    private List<String> immunities;

    // getters and setters for each attribute
}
