typedef enum {
    ENCRYPTION,
    DECRYPTION,
    SIGNING,
    VERIFICATION
} OperationType;

struct CipherContext {
    EVP_CIPHER_CTX* ctx;
    pthread_mutex_t mutex;
};

CipherContext* cipher_context_new(OperationType type) {
    CipherContext* ctx = malloc(sizeof(struct CipherContext));
    ctx->ctx = EVP_CIPHER_CTX_new();
    pthread_mutex_init(&ctx->mutex, NULL);
    return ctx;
}

void cipher_context_free(CipherContext* ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    pthread_mutex_destroy(&ctx->mutex);
    free(ctx);
}

EVP_CIPHER_CTX* get_cipher_ctx(CipherContext* ctx) {
    pthread_mutex_lock(&ctx->mutex);
    EVP_CIPHER_CTX* cipher_ctx = ctx->ctx;
    pthread_mutex_unlock(&ctx->mutex);
    return cipher_ctx;
}

void set_cipher_ctx(EVP_CIPHER_CTX** ctx, CipherContext* new_ctx) {
    *ctx = get_cipher_ctx(new_ctx);
}

int main() {
    // Initialize OpenSSL
    SSL_library_init();

    // Example usage:
    CipherContext* ctx1 = cipher_context_new(ENCRYPTION);
    CipherContext* ctx2 = cipher_context_new(DECRYPTION);

    set_cipher_ctx(&cipher_ctx1, ctx1);
    set_cipher_ctx(&cipher_ctx2, ctx2);

    // Perform cryptographic operations
    EVP_EncryptInit_ex(get_cipher_ctx(ctx1), ...);
    EVP_DecryptInit_ex(get_cipher_ctx(ctx2), ...);

    cipher_context_free(ctx1);
    cipher_context_free(ctx2);

    return 0;
}
