#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define MAX_CONCURRENCY 20
#define SEM_NAME "my_semaphore"

struct semaphore {
    sem_t *sem;
    pthread_mutex_t mutex;
    int count;
};

void init_semaphore(struct semaphore *s, int initial_value) {
    s->count = initial_value;
    if (sem_init(s->sem = sem_open(SEM_NAME, O_CREAT | O_EXCL, 0644), 0, initial_value) != 0) {
        perror("sem_init");
        exit(EXIT_FAILURE);
    }
}

void release_semaphore(struct semaphore *s) {
    pthread_mutex_lock(&s->mutex);
    if (s->count > 0) {
        s->count--;
    } else {
        sem_post(s->sem);
    }
    pthread_mutex_unlock(&s->mutex);
}

int acquire_semaphore(struct semaphore *s, int timeout_ms) {
    int ret = 0;
    pthread_mutex_lock(&s->mutex);
    while (1) {
        if (s->count > 0) {
            s->count--;
            ret = 1;
            break;
        } else {
            sem_wait(s->sem);
        }
        usleep(timeout_ms * 1000);
    }
    pthread_mutex_unlock(&s->mutex);
    return ret;
}

void destroy_semaphore(struct semaphore *s) {
    sem_close(s->sem);
    sem_unlink(SEM_NAME);
    pthread_mutex_destroy(&s->mutex);
}

void log_semaphore_operation(const char* op, int count) {
    printf("Semaphore %s: %d threads acquired/released\n", op, count);
}
