['```cpp
void insertOrAppend(Node** head, int target, bool append) {
    Node* current = *head;
    while (current != nullptr && current->data != target) {
        current = current->next;
    }
    if (append) {
        if (current == nullptr) { // not found and append
            Node* newNode = new Node(target);
            if (*head == nullptr) { // insert at the beginning
                newNode->next = *head;
                *head = newNode;
            } else {
                Node* last = *head;
                while (last->next != nullptr) {
                    last = last->next;
                }
                last->next = newNode;
            }
        } else if (current->data == target) { // found and append
            Node* newNode = new Node(target);
            current->next = newNode;
            newNode->next = current->next;
            current->next = nullptr; // mark as not last node
        }
    }
}
