#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <map>
#include <functional>
#include <chrono>

class Task {
public:
    std::string id;
    std::function<void()> func;
    int priority;
    bool retried = false;

    Task(std::string id, std::function<void()> func, int priority) : id(id), func(func), priority(priority) {}
};

class WorkerNode {
public:
    int id;
    std::mutex mtx;
    std::condition_variable cv;
    std::queue<Task*> taskQueue;
    bool busy = false;

    void Start() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this]{ return !taskQueue.empty() || busy; });
            if (!taskQueue.empty()) {
                Task* task = taskQueue.front();
                taskQueue.pop();
                lock.unlock();
                task->func();
                delete task;
            } else {
                lock.unlock();
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        }
    }

    void SubmitTask(Task* task) {
        {
            std::unique_lock<std::mutex> lock(mtx);
            taskQueue.push(task);
        }
        cv.notify_one();
    }

    void Busy() {
        std::lock_guard<std::mutex> lock(mtx);
        busy = true;
    }

    void Idle() {
        std::lock_guard<std::mutex> lock(mtx);
        busy = false;
    }
};

class Scheduler {
public:
    int workerCount = 0;
    WorkerNode* workers;
    std::map<std::string, Task*> taskMap;

    void Start(int workerCount) {
        this->workerCount = workerCount;
        workers = new WorkerNode[workerCount];
        for (int i = 0; i < workerCount; i++) {
            workers[i].id = i;
            std::thread(worker).detach();
        }
    }

    void SubmitTask(Task* task) {
        taskMap[task->id] = task;
        int workerIndex = rand() % workerCount;
        workers[workerIndex].SubmitTask(task);
    }

    Task* GetResult(std::string taskId) {
        if (taskMap.find(taskId) == taskMap.end()) return nullptr;
        Task* task = taskMap[taskId];
        task->func();
        taskMap.erase(taskId);
        return task;
    }
};

int main() {
    Scheduler scheduler(4);

    // Submit tasks
    for (int i = 0; i < 10; i++) {
        Task* task = new Task(std::to_string(i), []{ std::cout << "Task executed" << std::endl; }, 1);
        scheduler.SubmitTask(task);
    }

    return 0;
}
