            {
                try
                {
                    var response = await ProcessRequest(request);
                    if (response.IsSuccessStatusCode())
                    {
                        // Parse the response and create a ProcessedData object
                        var processData = CreateProcessedData(response);
                        processedRequests.Add(processData);
                    }
                    else
                    {
                        _logger.LogError("Failed request: {request}", request);
                    }
                }
                catch (HttpRequestException ex)
                {
                    _logger.LogError("HTTP request exception: {ex}", ex);
                }
                catch (OperationCanceledException ex)
                {
                    _logger.LogError("Request timed out: {ex}", ex);
                }
                catch (Exception ex)
                {
                    _logger.LogError("Unexpected error: {ex}", ex);
                }
            }

            return processedRequests;
        }

