using System;
using System.Xml.Linq;

public IEnumerable<XElement> GetFirstXmlElementByName(string xmlDocument, string elementName)
{
    try
    {
        XDocument doc = XDocument.Parse(xmlDocument);
        if (doc.Root == null) return Enumerable.Empty<XElement>();
        return doc.XPathSelectElements($"//{elementName}");
    }
    catch (XmlException ex)
    {
        Console.WriteLine("Error parsing XML: " + ex.Message);
        return Enumerable.Empty<XElement>();
    }
}
