use std::env;
use std::fs::create_dir_all;
use std::path::Path;

pub fn create_directory_with_env_var(directory_name: &str) -> Result<(), String> {
    let directory_path = format!("/{directory_name}");
    let env_var_name = format!("{}_PATH", directory_name);

    match env::var(&env_var_name) {
        Ok(existing_path) => {
            if existing_path == directory_path.as_str() {
                println!("Warning: Environment variable {} already set to {}, skipping creation of directory.", env_var_name, existing_path);
                return Ok(());
            }
            println!("Warning: Environment variable {} already set to {}, but creating new directory anyway.", env_var_name, existing_path);
        }
        Err(_) => {}
    }

    match create_dir_all(directory_path.as_ref()) {
        Ok(_) => {
            env::set_var(&env_var_name, &directory_path)?;
            println!("Directory created and environment variable set: {}", directory_path);
        }
        Err(err) => return Err(format!("Error creating directory: {}", err)),
    };

    Ok(())
}
