<?php

function manageUserAccount() {
    $requestData = $_REQUEST;
    $id = $requestData['id'];
    $name = $requestData['name'];
    $email = $requestData['email'];
    $password = $requestData['password'];
    $subAction = $requestData['sub_action'];

    // validate input data
    if (!isset($name) || !preg_match('/^[a-zA-Z0-9]{2,50}$/', $name)) {
        return json_encode(['status' => 'error', 'message' => 'Invalid name']);
    }
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return json_encode(['status' => 'error', 'message' => 'Invalid email']);
    }
    if (isset($password) && !preg_match('/^(?=.*[a-zA-Z])(?=.*\d)(?=.*[@$!%*#?&])[A-Za-z\d@$!#*?]{8,}$/', $password)) {
        return json_encode(['status' => 'error', 'message' => 'Invalid password']);
    }

    // handle sub-action
    switch ($subAction) {
        case 'update':
            if (!isset($id)) {
                // create new user account
                $query = "INSERT INTO users (name, email, password) VALUES (:name, :email, :password)";
                $stmt = db()->prepare($query);
                $stmt->execute([':name' => $name, ':email' => $email, ':password' => password_hash($password, PASSWORD_BCRYPT)]);
            } else {
                // update existing user account
                $query = "UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id";
                $stmt = db()->prepare($query);
                $stmt->execute([':name' => $name, ':email' => $email, ':password' => password_hash($password, PASSWORD_BCRYPT), ':id' => $id]);
            }
            break;
        case 'delete':
            // delete user account
            if (!isset($id)) {
                return json_encode(['status' => 'error', 'message' => 'User ID is required']);
            }
            $query = "SELECT COUNT(*) AS active_sessions FROM sessions WHERE user_id = :id";
            $stmt = db()->prepare($query);
            $result = $stmt->execute([':id' => $id]);
            if ($result['active_sessions'] > 0) {
                return json_encode(['status' => 'error', 'message' => 'User has active sessions']);
            }
            $query = "DELETE FROM users WHERE id = :id";
            $stmt = db()->prepare($query);
            $stmt->execute([':id' => $id]);
            break;
        case 'get':
            // retrieve user account data
            if (!isset($id)) {
                return json_encode(['status' => 'error', 'message' => 'User ID is required']);
            }
            $query = "SELECT * FROM users WHERE id = :id";
            $stmt = db()->prepare($query);
            $result = $stmt->execute([':id' => $id]);
            if (!$result) {
                return json_encode(['status' => 'error', 'message' => 'User not found']);
            }
            $user = $result[0];
            // validate permissions
            if (!hasPermission($user['id'])) {
                return json_encode(['status' => 'error', 'message' => 'Insufficient permissions']);
            }
            break;
        default:
            return json_encode(['status' => 'error', 'message' => 'Invalid sub-action']);
    }

    return json_encode(['status' => 'success', 'message' => 'Operation successful']);
}
