        private readonly IElementMetadataRetriever _elementMetadataRetriever;
        private readonly ILogger _logger;

        public async Task UpdateElementAsync(string pageSectionId, string elementId, string htmlContent)
        {
            try
            {
                // Sanitize and validate the HTML content using an external service
                var sanitizedHtml = await _htmlSanitizer.SanitizeAndValidate(htmlContent);

                // Retrieve metadata about the HTML content from multiple APIs
                var metadata = await _elementMetadataRetriever.RetrieveMetadataAsync(sanitizedHtml);

                // Update the element's HTML content with the sanitized and validated data
                await UpdateElementInternal(pageSectionId, elementId, sanitizedHtml, metadata);
            }
            catch (HttpRequestException ex)
            {
                // Handle external service failures by retrying after a delay
                await RetryServiceCallAsync(ex, _htmlSanitizer);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to update element");
                throw;
            }
        }

        private async Task RetryServiceCallAsync(Exception ex, IHtmlSanitizer htmlSanitizer)
        {
            const int maxRetries = 3;
            var retryCount = 0;

            while (retryCount < maxRetries && ex != null)
            {
                await Task.Delay(500); // Wait for a short duration before retrying
                try
                {
                    return await htmlSanitizer.SanitizeAndValidate(ex.Message);
                }
                catch (HttpRequestException innerEx)
                {
                    ex = innerEx;
                }

                retryCount++;
            }

            throw new Exception("Failed to sanitize and validate HTML content after " + maxRetries + " retries");
        }

        private async Task UpdateElementInternal(string pageSectionId, string elementId, string sanitizedHtml, Dictionary<string, object> metadata)
