const fs = require('fs');
const path = require('path');
const config = require('./config.json');

async function processDirectory(directory) {
  const allowedExtensions = new Set(config.allowedFileExtensions.split(','));
  let maxConcurrency = config.maxConcurrency;
  let logs = [];

  return new Promise((resolve, reject) => {
    async function processFiles(dir) {
      try {
        for await (const file of fs.readdirSync(dir)) {
          const filePath = path.join(dir, file);
          const stats = fs.statSync(filePath);

          if (stats.isDirectory()) {
            // Recursively process subdirectories
            await processFiles(filePath);
          } else {
            const extension = path.extname(filePath).toLowerCase();

            if (allowedExtensions.has(extension)) {
              try {
                const content = await fs.readFileSync(filePath, 'utf8');
                logs.push({ file: file, contentLength: content.length });
              } catch (err) {
                console.error(`Error processing ${file}:`, err);
              }
            }
          }
        }

        // Limit concurrent reads
        let currentReads = 0;
        const readFiles = [];
        async function readNextFile() {
          if (readFiles.length > maxConcurrency) {
            await new Promise((resolve) => setTimeout(resolve, 100));
          } else {
            while (readFiles.length < maxConcurrency && readFiles[readFiles.length]) {
              // Wait for some file to finish reading
              await readFiles.shift();
            }
          }

          if (readFiles.length < maxConcurrency) {
            const nextFile = readFiles.push(1);
            try {
              const content = await fs.readFile(nextFile - 1, 'utf8');
              logs.push({ file: nextFile - 1, contentLength: content.length });
            } catch (err) {
              console.error(`Error processing ${nextFile}:`, err);
              readFiles.pop();
            }
          }
        }

        for (let i = 0; i < readFiles.length; i++) {
          await readNextFile();
        }
      } catch (err) {
        reject(err);
      } finally {
        resolve({ [directory]: logs });
      }
    }

    processFiles(directory);
  });
}
