const loader = require('./loader');
const blueslip = require('blueslip');
const logger = require('./logger');

function testSuite(label, f, maxConcurrency) {
  const queue = [];
  let concurrentTests = 0;
  let results = [];

  function executeTest() {
    if (concurrentTests >= maxConcurrency) return;

    const test = queue.shift();
    if (!test) return;

    concurrentTests++;
    blueslip.reset();

    logger.start(test.label);

    try {
      f();
      results.push({ label: test.label, passed: true });
    } catch (error) {
      results.push({ label: test.label, passed: false, error });
    }

    logger.stop(test.label);
    blueslip.reset();

    concurrentTests--;
    executeTest();
  }

  function addTest(test) {
    queue.push(test);
  }

  function getResults() {
    return results;
  }

  async function run() {
    await loader.loadModules().then((modules) => {
      modules.forEach(addTest);

      setInterval(() => {
        if (queue.length > 0) executeTest();
      }, 100); // Run tests at most once every 100ms

      setTimeout(() => {
        const aggregatedResults = results.reduce((acc, test) => {
          if (!test.passed) acc.push(test);
          return acc;
        }, []);

        logger.send(aggregatedResults);
      }, 30000); // Send aggregated results after 30 seconds
    });
  }

  run();
}
