function renderFooterScripts(scripts, isDevelopment = false, footerSettings = {}) {
  const { asyncScript = true, deferScript = true, externalHosts = [] } = footerSettings;

  let footerHtml = '';

  scripts.forEach((script) => {
    if (!('key' in script || 'innerHTML' in script)) return; // handle invalid objects

    const isExternal = !script.key.startsWith('/'); // assume local script by default

    if (isExternal && !externalHosts.includes(new URL(script.key).origin)) return; // skip untrusted external scripts

    footerHtml += `<footer-scripts>
${isDevelopment ? `<!-- ${script.key} -->` : ''}
  <script${asyncScript ? ' async' : ''}${deferScript ? ' defer' : ''}>
    ${isExternal ? `src="${script.key}"` : ``}
    ${script.innerHTML}
  </script>
</footer-scripts>`;
  });

  if (!scripts.length) footerHtml = '<footer-scripts>No scripts to render.</footer-scripts>';

  return footerHtml;
}`']

