#include <forward_list>
#include <string>

void insertStringAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& insertion) {
  auto it = list.begin();
  bool found = false;
  while (it != list.end()) {
    if (*it == target) {
      found = true;
      break;
    }
    ++it;
  }
  if (found) {
    list.insert_after(it, insertion);
  } else {
    list.append(insertion);
  }
}
