function StreamingDataCollector(apiUrl, storageKey) {
  const storage = window.localStorage;
  let paused = false;
  let retries = 0;
  let restarts = 0;

  function collectData() {
    if (paused) return;

    fetch(apiUrl)
      .then(response => response.json())
      .then(data => {
        storage.setItem(storageKey, JSON.stringify(data));
      })
      .catch(error => {
        console.error('Error collecting data:', error);

        // Check for critical failure
        if (error.name === 'StreamingServiceFailure') {
          restarts++;
          setTimeout(() => {
            collectData();
          }, 1000);
        } else {
          retries++;

          // Wait before retrying
          setTimeout(() => {
            if (retries < 3) {
              collectData();
            } else {
              console.error('Maximum retries exceeded. Data collection failed.');
            }
          }, 2000);
        }
      });

    // Send restart and duration data to logging service
    fetch('https://logging-service.com/api/logs', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ restarts, storageKey }),
    });
  }

  function pauseDataCollection() {
    paused = true;
  }

  function resumeDataCollection() {
    paused = false;
    collectData();
  }

  return {
    collectData,
    pauseDataCollection,
    resumeDataCollection,
  };
}
