const { PassThrough } = require('stream');
const { StreamMerge } = require('merge-stream');

function aggregateStreams(...streams) {
  const merged = new StreamMerge();
  const bufferedStream = new PassThrough({ highWaterMark: 1024 * 64 });

  streams.forEach((stream) => {
    stream
      .on('data', (chunk) => {
        if (!bufferedStream.write(chunk)) {
          // Backpressure mechanism
          stream.pause();
        }
      })
      .on('end', () => {
        // Drain buffer when all streams end
        drainBuffer();
      });

    merged.add(stream);
  });

  function drainBuffer() {
    let buffer = '';
    bufferedStream.on('data', (chunk) => {
      buffer += chunk;
    });
    bufferedStream.on('end', () => {
      if (buffer.length > 0) {
        // Concatenate and emit final output
        const output = Buffer.from(buffer, 'utf8');
        process.stdout.write(output);
      }
    });

    merged.end();
  }

  return bufferedStream;
}

module.exports = aggregateStreams;
