function findMatchingElements(rootElement, predicate) {
  const queue = [rootElement];
  const results = [];
  let level = 0;

  while (queue.length > 0 && results.length < 50) {
    const element = queue.shift();
    if (!element || !element.tagName) continue;

    if (level >= 3 && predicate(element)) {
      results.push(element);
    }

    for (let child of Array.from(element.children)) {
      queue.push(child);
    }
  }

  return results;
}
