class ModuleLoader {
  constructor() {
    this.cachedModules = {};
    this.fallbackModuleId = null;
  }

  async loadModule(moduleName, version) {
    const moduleId = `${moduleName}-${performance.now().toFixed(3)}-${version}`;
    if (this.cachedModules[moduleId]) {
      return this.cachedModules[moduleId];
    }
    try {
      const response = await fetch(`https://example.com/${moduleName}.js`);
      const moduleContent = await response.text();
      const hash = createHash('sha256').update(moduleContent).digest('hex');
      const cachedModule = { moduleId, content: moduleContent };
      this.cachedModules[moduleId] = cachedModule;
      return cachedModule;
    } catch (error) {
      if (error.name === 'FetchError') {
        // Fallback mechanism for network failures
        if (!this.fallbackModuleId) {
          this.fallbackModuleId = await this.loadFallbackModule();
        }
        return this.cachedModules[this.fallbackModuleId];
      } else {
        throw error;
      }
    }
  }

  async loadFallbackModule() {
    // Load a fallback module or default behavior
    const response = await fetch('fallback.module.js');
    const fallbackContent = await response.text();
    return { moduleId: 'fallback', content: fallbackContent };
  }
}

module.exports = ModuleLoader;
