import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.json.simple.JSONArray;
import org.json.simple.JSONObject;
import org.json.simple.parser.JSONParser;

public class UserProcessor {

    private static final String JSON_FILE_EXTENSION = ".json";
    private static final int BUFFER_SIZE = 1024 * 8; // 8MB buffer size

    public Map<String, List<String>> processUserProfiles(String directoryPath) throws IOException {
        Map<String, List<String>> categorizedUsers = new HashMap<>();
        UnionFind unionFind = new UnionFind();

        long startTime = System.currentTimeMillis();
        File[] files = new File(directoryPath).listFiles((dir, name) -> name.endsWith(JSON_FILE_EXTENSION));

        for (File file : files) {
            try (FileReader reader = new FileReader(file)) {
                JSONParser parser = new JSONParser();
                JSONArray profiles = (JSONArray) parser.parse(new BufferedReader(new InputStreamReader(reader, "UTF-8")).lines().reduce("", (a, b) -> a + b));
                List<String> userProfiles = new ArrayList<>();

                for (Object profile : profiles) {
                    JSONObject userProfile = (JSONObject) profile;
                    String name = (String) userProfile.get("name");
                    int age = Integer.parseInt((String) userProfile.get("age"));
                    String email = (String) userProfile.get("email");

                    userProfiles.add(name + "," + age + "," + email);

                    if (!unionFind.containsGroup(age)) {
                        unionFind.createGroup(age);
                    }
                }

                processUserProfiles(userProfiles, categorizedUsers, unionFind);
            } catch (Exception e) {
                // Handle file processing failure
                System.out.println("Error processing file " + file.getName());
            }
        }

        long endTime = System.currentTimeMillis();
        System.out.println("Processing time: " + (endTime - startTime) + "ms");

        return categorizedUsers;
    }

    private void processUserProfiles(List<String> userProfiles, Map<String, List<String>> categorizedUsers, UnionFind unionFind) {
        for (String userProfile : userProfiles) {
            String[] attributes = userProfile.split(",");
            int age = Integer.parseInt(attributes[1]);

            if (!unionFind.containsGroup(age)) {
                // Create a new group
                unionFind.createGroup(age);
            }

            unionFind.addUserToGroup(unionFind.findGroup(age), attributes[0]);
        }

        for (String group : unionFind.getGroups()) {
            List<String> users = categorizedUsers.computeIfAbsent(group, k -> new ArrayList<>());
            users.addAll(unionFind.getUsersInGroup(group));
        }
    }
}

class UnionFind {
    private Map<Integer, String> groups;
    private Map<String, Integer> parent;

    public UnionFind() {
        this.groups = new HashMap<>();
        this.parent = new HashMap<>();
    }

    public void createGroup(int age) {
        if (!groups.containsKey(age)) {
            groups.put(age, "Group_" + age);
            parent.put("Group_" + age, age);
        }
    }

    public boolean containsGroup(int age) {
        return groups.containsKey(age);
    }

    public String findGroup(int age) {
        while (parent.get(groups.get(age)) != age) {
            age = parent.get(groups.get(age));
        }
        return groups.get(age);
    }

    public void addUserToGroup(String group, String user) {
        int age = Integer.parseInt(group.replace("Group_", ""));
        if (!parent.containsKey(user)) {
            parent.put(user, age);
        }
    }

    public List<String> getUsersInGroup(String group) {
        return groups.get(age).split(",");
    }

    public Map<String, List<String>> getGroups() {
        return new HashMap<>(groups);
    }
}
