    public void setTheme(String themeName, Bitmap bitmap) {
        if (themeCache.containsKey(themeName)) {
            Bitmap oldBitmap = themeCache.get(themeName);
            recycleBitmap(oldBitmap);
        }
        themeCache.put(themeName, bitmap);
    }

    private void recycleBitmap(Bitmap bitmap) {
        if (bitmap != null) {
            bitmap.recycle();
            bitmap = null;
        }
    }

    public Bitmap getTheme(String themeName) {
        return themeCache.getOrDefault(themeName, null);
    }

