import java.util.concurrent.*;
import org.apache.commons.lang3.tuple.*;

public class ServiceController {
    private ExecutorService executor;
    private ScheduledExecutorService scheduler;
    private Map<String, ServiceOperation> operations = new HashMap<>();
    private HealthMonitor healthMonitor;
    private AlertSystem alertSystem;

    public ServiceController() {
        executor = Executors.newCachedThreadPool();
        scheduler = Executors.newScheduledThreadPool(1);
        healthMonitor = new HealthMonitor();
        alertSystem = new AlertSystem();
    }

    public void startService(String serviceName) {
        ServiceOperation operation = operations.get(serviceName);
        if (operation == null) {
            // Add service operation to the map
            operation = new ServiceOperation(serviceName);
            operations.put(serviceName, operation);
        }
        executor.submit(() -> {
            try {
                operation.start();
            } catch (Exception e) {
                healthMonitor.recordFailure(serviceName);
                alertSystem.sendAlert("Service failed: " + serviceName);
            }
        });
    }

    public void stopService(String serviceName) {
        ServiceOperation operation = operations.get(serviceName);
        if (operation != null) {
            executor.submit(() -> {
                try {
                    operation.stop();
                } catch (Exception e) {
                    healthMonitor.recordFailure(serviceName);
                    alertSystem.sendAlert("Service failed: " + serviceName);
                }
            });
        }
    }

    public void startMonitoring() {
        scheduler.scheduleAtFixedRate(() -> {
            for (String serviceName : operations.keySet()) {
                if (!healthMonitor.isHealthy(serviceName)) {
                    healthMonitor.recordFailure(serviceName);
                    alertSystem.sendAlert("Service failed: " + serviceName);
                }
            }
        }, 0, 60 * 1000, TimeUnit.MILLISECONDS); // every minute
    }

    public class ServiceOperation implements Runnable {
        private String serviceName;
        private boolean running = false;

        public ServiceOperation(String serviceName) {
            this.serviceName = serviceName;
        }

        public void start() throws Exception {
            if (!running) {
                running = true;
                // Start service operation (e.g., call API, connect to cloud service)
                // ...
            }
        }

        public void stop() throws Exception {
            if (running) {
                running = false;
                // Stop service operation
                // ...
            }
        }
    }

    public class HealthMonitor {
        private Map<String, Long> failureCounts = new HashMap<>();

        public boolean isHealthy(String serviceName) {
            return failureCounts.getOrDefault(serviceName, 0L) < 3; // 3 failures before alert
        }

        public void recordFailure(String serviceName) {
            long count = failureCounts.getOrDefault(serviceName, 0L);
            failureCounts.put(serviceName, count + 1);
        }
    }

    public class AlertSystem {
        public void sendAlert(String message) {
            // Send alert to cloud-based monitoring service
            // ...
        }
    }
}
