            return 'staging';
        } elseif (isset($_SERVER['HTTP_HOST']) && str_contains($_SERVER['HTTP_HOST'], 'production')) {
            return 'production';
        } else {
            return 'development';
        }
    }

    private function getConfigPath()
    {
        // Determine the current environment and load the corresponding configuration file
        $environmentConfigPath = sprintf('%s/%s.yml', __DIR__, $this->environment);
        return $environmentConfigPath;
    }

    private function loadConfig($configPath)
    {
        $config = Yaml::parseFile($configPath);
        // Process the loaded configuration settings here
    }

    private function enableCaching()
    {
        // Implement caching strategy using a caching library like Redis or Memcached
    }

    private function disableCaching()
    {
        // Disable caching for this environment
    }

    private function applyMappingRules()
    {
        // Address potential discrepancies between expected configuration keys and actual values
        foreach ($this->mappingRules as $key => $value) {
            if (!isset($config[$key])) {
                $config[$key] = $value;
            }
        }
