['```rust
use tokio::net::TcpStream;
use tokio::sync::{mpsc, oneshot};
use reqwest::blocking::get;
use log::{info, warn};
use std::collections::HashMap;
use std::sync::Arc;

pub struct HttpClient {
    pool: Arc<mpsc::channel<i32>>,
    config: Config,
}

impl HttpClient {
    pub fn new(config: Config) -> Self {
        let (tx, rx) = mpsc::channel(100);
        let pool = Arc::new(tx);
        HttpClient { pool, config }
    }

    async fn get(&self, url: &str) -> Result<String, reqwest::Error> {
        let mut client = reqwest::blocking::Client::builder()
            .timeout(std::time::Duration::from_millis(5000))
            .cookie_store(false)
            .build()?;
        if !self.config.certificate_validation {
            client = client.badges().no_verify_hostname();
        }
        for (key, value) in &self.config.headers {
            client = client.header(key, value);
        }

        let response = client.get(url).send()?;

        match response.status().as_u16() {
            301 | 302 => self.follow_redirect(&response).await?,
            _ => {}
        }

        if !response.error_for_status_ref().unwrap_or(&response).is_success() {
            warn!("Request failed with status: {}", response.status());
        }

        Ok(response.text()?)
    }

    async fn follow_redirect(&self, response: &reqwest::blocking::Response) -> Result<(), reqwest::Error> {
        let new_url = response.headers().get("Location").unwrap_or(None).map(|v| v.to_str().unwrap()).unwrap();
        self.get(new_url).await
    }
}

pub struct Config {
    pub certificate_validation: bool,
    pub headers: HashMap<String, String>,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            certificate_validation: true,
            headers: HashMap::new(),
        }
    }
}
