const fs = require('fs');
const crypto = require('crypto');

async function generateDynamicPassword(defaultLength = 16, defaultCharacterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890', configFilePath) {
  try {
    const configFileData = await fs.promises.readFile(configFilePath, 'utf8');
    const configFileJson = JSON.parse(configFileData);

    if (configFileJson.length && configFileJson.characterSet) {
      return generateAndHashPassword(configFileJson.length, configFileJson.characterSet);
    }
  } catch (error) {
    // handle file read error
  }

  return generateAndHashPassword(defaultLength, defaultCharacterSet);
}

function generateAndHashPassword(length, characterSet) {
  const password = crypto.randomBytes(Math.ceil(length / 2)).toString('hex').slice(0, length).replace(/\//g, '').match(new RegExp(characterSet, 'g')).join('');

  return crypto.subtle.digest('SHA-256', new TextEncoder().encode(password));
}

