function generatePEMCertificate(oauthRequest) {
  const { privateKeySource, certificateSource } = oauthRequest;
  const { remotePrivateKeys, localPrivateKeys } = privateKeySource;
  const { remoteCertificates, localCertificates } = certificateSource;

  let privatekeyBuffer = [];
  let certificateBuffer = [];

  async function fetchAndMergeBuffers() {
    try {
      for (const source of [...remotePrivateKeys.values(), ...localPrivateKeys.values()]) {
        if (source.type === 'remote') {
          const response = await fetch(source.url);
          const buffer = await response.arrayBuffer();
          privatekeyBuffer.push(buffer);
        } else {
          privatekeyBuffer.push(fs.readFileSync(source.path));
        }
      }

      for (const source of [...remoteCertificates.values(), ...localCertificates.values()]) {
        if (source.type === 'remote') {
          const response = await fetch(source.url);
          const buffer = await response.arrayBuffer();
          certificateBuffer.push(buffer);
        } else {
          certificateBuffer.push(fs.readFileSync(source.path));
        }
      }

      return [privatekeyBuffer, certificateBuffer];
    } catch (error) {
      console.error('Error fetching and merging buffers:', error);
      throw new Error('Failed to generate PEM certificate');
    }
  }

  async function mergeAndFormatCertificate(privateKeys, certificates) {
    try {
      const mergedPrivateKeys = await Promise.all(privateKeys.map((buffer) => crypto.createPrivateKey({ key: buffer })));
      const mergedCertificates = await Promise.all(certificates.map((buffer) => crypto.createCertificate({ certificate: buffer })));

      const formattedCertificate = await crypto.createPemCertificate({
        privateKeys: mergedPrivateKeys,
        certificates: mergedCertificates
      });

      return formattedCertificate.toString();
    } catch (error) {
      console.error('Error merging and formatting certificate:', error);
      throw new Error('Failed to generate PEM certificate');
    }
  }

  async function generatePEMCertificate() {
    try {
      const [privateKeys, certificates] = await fetchAndMergeBuffers();

      if (!privateKeys.length || !certificates.length) {
        throw new Error('No private keys or certificates found');
      }

      const formattedCertificate = await mergeAndFormatCertificate(privateKeys, certificates);

      return formattedCertificate;
    } catch (error) {
      console.error('Error generating PEM certificate:', error);
      throw new Error('Failed to generate PEM certificate');
    }
  }

  return generatePEMCertificate();
}
