**C Function for DNS Resolution**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <unistd.h>

u_char* resolve_dns(const char* hostname) {
    struct addrinfo hints, *res;
    int s;
    u_char* ip = NULL;

    // Set up DNS resolution
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = 0;
    hints.ai_flags = AI_NUMERICSERV | AI_ADDRCONFIG;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        // Handle DNS resolution failure
        return NULL;
    }

    // Resolve IP address
    s = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (s < 0) {
        // Handle socket creation failure
        freeaddrinfo(res);
        return NULL;
    }

    // Set up DNS query
    struct sockaddr_in* addr = (struct sockaddr_in*)res->ai_addr;
    inet_ntop(res->ai_family, &addr->sin_addr, ip, sizeof(u_char));

    // Clean up
    close(s);
    freeaddrinfo(res);

    return ip;
}
