from threading import Lock
from collections import OrderedDict

class ConfigManager:
    def __init__(self):
        self.lock = Lock()
        self.config_versions = {}

    def read_config(self, env: str) -> dict:
        with self.lock:
            config_path = f'config_{env}.json'
            if not os.path.exists(config_path):
                raise FileNotFoundError(f'Environment {env} configuration file not found')
            with open(config_path, 'r') as f:
                return json.load(f)

    def write_config(self, env: str, config: dict) -> None:
        with self.lock:
            config_path = f'config_{env}.json'
            with open(config_path, 'w') as f:
                json.dump(config, f)

    def sort_and_extract_identifier(self, config: dict, key: str) -> str:
        sorted_config = OrderedDict(sorted(config.items(), key=lambda x: x[1][key]))
        return sorted_config.popitem(last=False)[0]

    def manage_config(self, env: str, key: str) -> None:
        try:
            config = self.read_config(env)
            identifier = self.sort_and_extract_identifier(config, key)
            # Integrate with external logging service
            logging.info(f'Updated {env} configuration with ID {identifier}')
            # Version control and file locking mechanism omitted for brevity
            self.write_config(env, config)
        except Exception as e:
            logging.error(f'Error managing {env} configuration: {e}')
