std::unique_ptr<OctreeNode> createOctree(int featureSize, int numLeafNodes, int maxDepth) {
    // Initialize the root node
    auto root = std::make_unique<OctreeNode>();
    root->id = 0;
    root->isLeaf = false;

    // Recursively build the octree
    if (maxDepth > 1) {
        for (int i = 0; i < 8; i++) {
            root->children.push_back(createOctree(featureSize, numLeafNodes / 2, maxDepth - 1));
        }
    } else {
        root->isLeaf = true;
    }

    return root;
}

void updateOctree(std::unique_ptr<OctreeNode>& octree, int featureSize) {
    // Update the node data
    for (auto& child : octree->children) {
        if (!child->isLeaf) {
            updateOctree(child, featureSize);
        }
    }

    // Rebalance or reallocate memory as needed
