using UnityEngine;

public class RandomValueGenerator
{
    private float minValue;
    private float maxValue;

    public RandomValueGenerator(float min, float max)
    {
        if (!IsValidRange(min, max))
        {
            throw new ArgumentException("Invalid range specified.");
        }
        minValue = min;
        maxValue = max;
    }

    public float GenerateRandomFloat(bool inclusiveMin, bool inclusiveMax)
    {
        if (!IsRangeValid(inclusiveMin, inclusiveMax))
        {
            throw new InvalidOperationException("Range constraints are invalid.");
        }
        return UnityEngine.Random.Range(AdjustForInclusivity(minValue, inclusiveMin), AdjustForInclusivity(maxValue, inclusiveMax));
    }

    public int GenerateRandomInt(bool inclusiveMin, bool inclusiveMax)
    {
        if (!IsRangeValid(inclusiveMin, inclusiveMax))
        {
            throw new InvalidOperationException("Range constraints are invalid.");
        }
        return UnityEngine.Random.Range((int)AdjustForInclusivity(minValue, inclusiveMin), (int)AdjustForInclusivity(maxValue, inclusiveMax) + 1);
    }

    private bool IsValidRange(float min, float max)
    {
        return min <= max;
    }

    private bool IsRangeValid(bool inclusiveMin, bool inclusiveMax)
    {
        return inclusiveMin && inclusiveMax || !inclusiveMin && !inclusiveMax;
    }

    private float AdjustForInclusivity(float value, bool inclusive)
    {
        return inclusive ? value : value - 1e-6f; // Subtle floating-point precision issue.
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }
}

