typedef struct {
    char *tag;
    void **children;
    int childCount;
} Node;

Node* processDOM(Node* node, int sizeLimit, void (*callback)(void*, const char*, const char*)) {
    if (!node) return NULL;

    Node* result = malloc(sizeof(Node));
    result->tag = strdup(node->tag);
    result->childCount = 0;
    result->children = NULL;

    void **matchedNodes = NULL;
    int matchedNodeCount = 0;
    for (int i = 0; i < node->childCount; i++) {
        Node* child = node->children[i];
        if (callback(child, node->tag, "class")) {
            if (matchedNodeCount >= sizeLimit) break;
            matchedNodeCount++;
            void **newMatchedNodes = realloc(matchedNodes, sizeof(void*) * (matchedNodeCount + 1));
            newMatchedNodes[matchedNodeCount - 1] = child;
            matchedNodes = newMatchedNodes;
        }
        Node* processedChild = processDOM(child, sizeLimit, callback);
        if (processedChild) {
            void **newChildren = realloc(result->children, sizeof(void*) * (result->childCount + 1));
            newChildren[result->childCount] = processedChild;
            result->children = newChildren;
            result->childCount++;
        }
    }

    for (int i = 0; i < matchedNodeCount; i++) {
        free((void*)matchedNodes[i]);
    }
    free(matchedNodes);

    if (node->tag && *node->tag != '#') {
        void **newChildren = realloc(result->children, sizeof(void*) * (result->childCount + 1));
        newChildren[result->childCount] = node;
        result->children = newChildren;
        result->childCount++;
    }

    return result;
}
