void process_line(const char *line) {
    char *line_copy = malloc(MAX_LINE_LENGTH);
    strcpy(line_copy, line);

    // Find the last two numerical fields
    int i = strlen(line_copy);
    int start_index = -1;
    for (; i > 0; --i) {
        if (isdigit(line_copy[i-1])) {
            start_index = i;
            break;
        }
    }

    if (start_index >= 0) {
        char *avg_field = malloc(strlen(line_copy) + 10);
        sprintf(avg_field, "%.*s,%f", strlen(line_copy) - start_index, line_copy + start_index, (atoi(line_copy + start_index) + atoi(line_copy + start_index + 1)) / 2.0);

        // Update the original line with the new average field
        strcpy(line_copy, avg_field);
        free(avg_field);
    }

    printf("%s\n", line_copy);
    free(line_copy);
}

int main() {
    FILE *fp = fopen("input.txt", "r");
    if (fp == NULL) {
        printf("Error opening file.\n");
        return 1;
    }

    char theme_cache_path[256];
    strcpy(theme_cache_path, THEME_CACHE_DIR);

    // Check if a default theme directory is set
