#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>
#include <md5.h>

typedef struct {
    uint16_t bitsPerSample;
    uint16_t samplesPerPixel;
    uint8_t extraSamples;
    char md5Hash[33];
} ImageMetadata;

ImageMetadata* parseAndProcessImage(const char *filePath) {
    TIFF *tiff = TIFFOpen(filePath, "r");
    if (!tiff) {
        return (ImageMetadata*)malloc(sizeof(ImageMetadata));
        ((ImageMetadata*)malloc)->bitsPerSample = 0;
        ((ImageMetadata*)malloc)->samplesPerPixel = 0;
        ((ImageMetadata*)malloc)->extraSamples = 0;
        strcpy(((ImageMetadata*)malloc)->md5Hash, "Error opening file");
        return (ImageMetadata*)malloc;
    }

    TIFFGetField(tiff, TIFF_FIELD_IMAGEWIDTH, &tiff->imageWidth);
    TIFFGetField(tiff, TIFF_FIELD_IMAGELENGTH, &tiff->imageLength);
    TIFFGetField(tiff, TIFF_FIELD_BITSPERSAMPLE, &(tiff->bitsPerSample));
    TIFFGetField(tiff, TIFF_FIELD_SAMPLESPERPIXEL, &(tiff->samplesPerPixel));
    tiff->extraSamples = TIFFGetField(tiff, TIFF_FIELD_EXTRASAMPLES);

    unsigned char *buffer = (unsigned char *)malloc(tiff->imageWidth * tiff->imageLength * tiff->samplesPerPixel);
    if (!buffer) {
        return NULL;
    }

    uint32_t *data = (uint32_t *)malloc(tiff->imageWidth * tiff->imageLength * tiff->samplesPerPixel / 4);
    TIFFReadImage(tiff, buffer);

    MD5_CTX md5ctx;
    unsigned char *hash = (unsigned char *)malloc(16);
    MD5Init(&md5ctx);
    for (int i = 0; i < tiff->imageWidth * tiff->imageLength * tiff->samplesPerPixel; i++) {
        MD5Update(&md5ctx, &buffer[i], 1);
    }
    MD5Final(&md5ctx, hash);

    ImageMetadata *metadata = (ImageMetadata*)malloc(sizeof(ImageMetadata));
    metadata->bitsPerSample = tiff->bitsPerSample;
    metadata->samplesPerPixel = tiff->samplesPerPixel;
    metadata->extraSamples = tiff->extraSamples;
    for (int i = 0; i < 16; i++) {
        sprintf(metadata->md5Hash + i * 2, "%02x", hash[i]);
    }

    free(buffer);
    free(data);
    TIFFClose(tiff);

    return metadata;
}

