char* generate_unique_identifier(const char* filename) {
    size_t len = strlen(filename);
    const char *start = filename;
    int i, j;

    // Extract the first three uppercase letters and last three lowercase letters
    for (i = 0; i < 3; ++i) {
        start += i;
        while (*start <= 'z' && i < 3) {
            ++start;
            ++i;
        }
    }
    char *id_start = malloc(strlen(start) + 1);
    strcpy(id_start, start);

    // Convert to lowercase and pad with zeros
    for (j = 0; j < len - (i + 4); ++j)
        id_start[j] = '0';
    id_start[j++] = '\0';

    // Add the extracted characters
    for (i -= 3; i < len - 1; ++i) {
        id_start[j++] = tolower(filename[i]);
    }
    id_start[j++] = '\0';

    size_t id_len = strlen(id_start);
    char *new_filename = malloc(len + id_len + 5);

    // Append the identifier to the original filename extension
    sprintf(new_filename, "%s.%s", filename, id_start);

    free(id_start);

    return new_filename;
}

int main() {
    const char *filename = "example.txt";
    char *new_filename = generate_unique_identifier(filename);
    printf("New filename: %s\n", new_filename);
    free(new_filename);
    return 0;
}
