    AES_set_encrypt_key(derivedKey, keyBytes, &aesKey);

    // Generate a random IV and store it alongside the ciphertext
    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, sizeof(iv));
    int ivLength = AES_BLOCK_SIZE;

    // Encrypt the plaintext using the AES-256-CBC cipher
    unsigned char* ciphertextBuffer = (unsigned char*)malloc(plaintextLength + ivLength);
    memcpy(ciphertextBuffer, iv, ivLength);
    AES_cbc_encrypt(plaintext, ciphertextBuffer + ivLength, plaintextLength, &aesKey, iv, AES_ENCRYPT);

    *ciphertext = ciphertextBuffer;
}

