    int iterationCount = 10000;
    size_t keyBytes = 32;
    unsigned char* derivedKey = (unsigned char*)malloc(keyBytes);
    PBKDF2(password, strlen(password), salt, 4, &iterationCount, keyBytes, derivedKey);

    // Initialize the AES-256-CBC cipher
    AES_KEY aesKey;
    AES_set_decrypt_key(derivedKey, keyBytes, &aesKey);

    // Extract the IV from the ciphertext
    unsigned char iv[AES_BLOCK_SIZE];
    memcpy(iv, ciphertext, AES_BLOCK_SIZE);
    int ivLength = AES_BLOCK_SIZE;

    // Decrypt the ciphertext using the AES-256-CBC cipher
    unsigned char* plaintextBuffer = (unsigned char*)malloc(ciphertextLength - ivLength);
    AES_cbc_decrypt(ciphertext + ivLength, plaintextBuffer, ciphertextLength - ivLength, &aesKey, iv, AES_DECRYPT);

    *plaintext = plaintextBuffer;
}

