int convert_file_to_pdf(const char *input_path, const char *output_path, size_t buffer_size) {
    pid_t child_pid = fork();
    if (child_pid == 0) {
        // Child process: run the conversion command
        execlp("convert", "convert", "-density", "150", "-compress", "lzw", input_path, output_path, NULL);
        perror("execlp");
        return -1;
    } else if (child_pid > 0) {
        // Parent process: wait for the child to finish
        int status = waitpid(child_pid, NULL, 0);
        if (status == -1) {
            perror("waitpid");
            return -1;
        }
    }

    // Read the generated PDF file into a dynamically allocated memory buffer
    FILE *output_file = fopen(output_path, "rb");
    if (!output_file) {
        printf("Failed to open output file: %s\n", output_path);
        return 1;
    }

    fseek(output_file, 0, SEEK_END);
    size_t pdf_size = ftell(output_file);
    rewind(output_file);

    char *pdf_buffer = malloc(pdf_size);
    if (!pdf_buffer) {
        printf("Failed to allocate memory for PDF buffer.\n");
        fclose(output_file);
        return 1;
    }

    fread(pdf_buffer, 1, pdf_size, output_file);
    fclose(output_file);

    // Deserialize the PDF content into an object of a specific class
    // (Assuming you have the necessary serialization mechanism and class definitions)

    // Handle potential deserialization errors or exceptions
