#include <signal.h>

int execute_commands(char **commands) {
    int i = 0, num_commands = sizeof(commands)/sizeof(commands[0]);
    pid_t *pids = (pid_t *)malloc(sizeof(pid_t) * num_commands);
    int status[num_commands];

    for(i=0; i<num_commands; i++) {
        pids[i] = fork();

        if(pids[i] < 0) {
            perror("fork");
            return -1;
        } else if (pids[i] == 0) { // child process
            execvp(commands[i], &commands[i]);
            printf("Command %s failed to execute.\n", commands[i]);
            exit(1);
        }
    }

    for(i=0; i<num_commands; i++) {
        waitpid(pids[i], &status[i], 0);

        if(WEXITSTATUS(status[i]) != 0) {
            printf("Command %s failed to execute.\n", commands[i]);
            for(int j = 0; j<i; j++) {
                kill(pids[j], SIGINT);
                wait(NULL);
            }
            return 0;
        }
    }

    free(pids);
    return 1;
}

int main() {
    char *commands[] = {"command1", "command2", "command3"};
    execute_commands(commands);
    return 0;
}
