public class WebSiteManager
{
    public void AddAndStartWebSite(string directoryPath, string siteName)
    {
        if (!Directory.Exists(directoryPath))
            throw new DirectoryNotFoundException("The specified directory does not exist.");

        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            GenerateBasicConfig(directoryPath);
        }

        if (IsWebsiteAlreadyRunning(directoryPath, siteName))
        {
            Console.WriteLine($"The website '{siteName}' is already running. Skipping addition and start.");
            return;
        }

        try
        {
            Process process = new Process
            {
                StartInfo = { FileName = "your-web-server.exe", Arguments = siteName }
            };
            process.Start();
        }
        catch (Exception ex)
        {
            LogError(ex);
        }
    }

    private void GenerateBasicConfig(string directoryPath)
    {
        // Predefined template for basic web.config file
        string template = @"<?xml version=""1.0""?>
                            <configuration>
                                <appSettings>
                                    <!-- Your app settings here -->
                                </appSettings>
                            </configuration>";

        File.WriteAllText(Path.Combine(directoryPath, "web.config"), template);
    }

    private bool IsWebsiteAlreadyRunning(string directoryPath, string siteName)
    {
        Process[] processes = Process.GetProcesses();
        return processes.Any(p => p.ProcessName.Contains(siteName));
    }

    private void LogError(Exception ex)
    {
        // Log the error message to a separate log file
        using (StreamWriter writer = File.CreateText("error.log"))
        {
            writer.WriteLine($"Error occurred: {ex.Message}");
            writer.WriteLine($"Exception details: {ex.StackTrace}");
        }
    }
}
