#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "base64.h"
#include "crypto.h"

typedef struct {
    char* message_id;
    void* connection;
    void (*callback)(const char*);
    void* config;
} MessageStruct;

int processAndHandleMessage(MessageStruct* msg) {
    if (!msg->message_id || strlen(msg->message_id) == 0) return -1; // error: empty or null message_id
    if (!msg->connection || !(*(char**)msg->connection)->title) return -2; // error: connection is not initialized properly
    if (!msg->callback) return -3; // error: callback function is NULL
    if (!msg->config) return -4; // error: configuration object is null or not initialized

    pthread_t thread;
    pthread_create(&thread, NULL, (void* (*)(void*))decryptAndInvokeCallback, msg);

    pthread_join(thread, NULL); // wait for decryption and callback completion

    return 0; // success
}

void* decryptAndInvokeCallback(void* arg) {
    MessageStruct* msg = (MessageStruct*)arg;

    char* encrypted_msg = base64_decode(msg->message_id);
    if (!encrypted_msg) return NULL; // error: unable to decode message

    crypto_decrypted_msg_t decrypted_msg;
    crypto_decrypt(encrypted_msg, msg->config, &decrypted_msg);

    if (!decrypted_msg.data) {
        free(encrypted_msg);
        return NULL; // error: decryption failed
    }

    // process decrypted message...
    (*msg->callback)(decrypted_msg.data);

    free(decrypted_msg.data);
    free(encrypted_msg);

    return NULL;
}
