        // Extract and validate configuration settings from the JSON object
        config->server_ip[0] = '\0';
        config->port = 0;
        config->max_connections = 0;
        config->timeout = 0;

        if (...) {
            // Configuration file is invalid
            json_object_put(json_obj);
            free(config);
            return NULL;
        }

        json_object_del(json_obj, "server_ip");
        strcpy(config->server_ip, json_object_get_string_value(json_obj));

        json_object_del(json_obj, "port");
        config->port = json_object_get_int_value(json_obj);

        json_object_del(json_obj, "max_connections");
        config->max_connections = json_object_get_int_value(json_obj);

        json_object_del(json_obj, "timeout");
        config->timeout = json_object_get_int_value(json_obj);

        json_object_put(json_obj);
    } else if (format == YAML) {
        yaml_parser_t parser;
        yaml_event_t event;

        yaml_parser_initialize(&parser);
        yaml_parser_set_input_string(&parser, file_path);

        // Parse the configuration file and validate settings
        while (yaml_parser_parse(&parser, &event)) {
            if (...) {
                // Configuration file is invalid
                yaml_parser_delete(&parser);
                free(config);
                return NULL;
            }
        }

        yaml_event_delete(&event);
        yaml_parser_delete(&parser);

        config->server_ip[0] = '\0';
        config->port = 0;
        config->max_connections = 0;
        config->timeout = 0;

        if (...) {
            // Configuration file is invalid
            free(config);
            return NULL;
        }
    }

    return config;
}

bool validate_config(config_t *config) {
    if (!validate_server_ip(config->server_ip)) {
        return false;
    }
    if (!validate_port(config->port)) {
        return false;
    }
    if (!validate_max_connections_and_timeout(config->max_connections, config->timeout)) {
        return false;
    }

    return true;
}

int main() {
    // Example usage
    char file_path[] = "path/to/config/file";
    config_format_t format = JSON;

    config_t *config = parse_config(file_path, format);

    if (!config) {
        printf("Failed to load configuration\n");
        return 1;
    }

    if (!validate_config(config)) {
        printf("Invalid configuration: %s\n", ... /* error message */);
        free(config);
        return 2;
    }

    // Configuration is valid, proceed with service initialization
    printf("Configuration loaded successfully\n");

    return 0;
}
