using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;

public static Dictionary<int, string> ProcessBase64Messages(string inputString)
{
    var decryptedMessages = new Dictionary<int, string>();

    if (string.IsNullOrEmpty(inputString))
        return decryptedMessages;

    var base64Segments = inputString.Split(new[] { Environment.NewLine }, StringSplitOptions.None);

    foreach (var segment in base64Segments)
    {
        try
        {
            var base64EncodedMessage = segment.Trim();
            if (string.IsNullOrEmpty(base64EncodedMessage))
                continue;

            var messageIndex = Array.IndexOf(base64Segments, segment);
            using var stream = new MemoryStream(Convert.FromBase64String(base64EncodedMessage));
            using var tripleDes = TripleDESCryptoServiceProvider.Create();
            using var decryptor = tripleDes.CreateDecryptor();

            byte[] buffer = new byte[16];
            using var cryptoStream = new CryptoStream(stream, decryptor, CryptoStreamMode.Read);
            int read;
            var decryptedBuffer = new byte[stream.Length];
            using (var memoryStream = new MemoryStream())
            {
                do
                {
                    read = cryptoStream.Read(buffer, 0, buffer.Length);
                    memoryStream.Write(buffer, 0, read);
                } while (read > 0);

                string decryptedMessage = Encoding.UTF8.GetString(memoryStream.ToArray());
                if (!string.IsNullOrEmpty(decryptedMessage))
                {
                    decryptedMessages.Add(messageIndex, decryptedMessage);
                }
            }
        }
        catch (Exception ex)
        {
            // Log failed decryption attempts and performance metrics
        }
    }

    return decryptedMessages;
}
