public class LogProcessor
{
    public Dictionary<string, int> ProcessLog(string filePath)
    {
        Dictionary<string, int> termFrequency = new Dictionary<string, int>();
        using (StreamReader reader = File.OpenText(filePath))
        {
            string line;
            while ((line = reader.ReadLine()) != null)
            {
                line = line.ToLower().Replace(@"\W", "").Trim();
                if (!string.IsNullOrEmpty(line))
                {
                    if (!termFrequency.ContainsKey(line))
                        termFrequency[line] = 1;
                    else
                        termFrequency[line]++;
                }
            }
        }
        return termFrequency;
    }
}
