public class AESCBCDecryptor
{
    private readonly Aes aes;
    private readonly byte[] key;
    private readonly byte[] iv;
    private readonly ICiphertextAuthenticator authenticator;
    private readonly IPaddingScheme padding;

    public AESCBCDecryptor(byte[] key, byte[] iv, ICiphertextAuthenticator authenticator, IPaddingScheme padding)
    {
        this.key = key;
        this.iv = iv;
        this.authenticator = authenticator;
        this.padding = padding;
        aes = Aes.Create();
        aes.Key = key;
        aes.IV = iv;
    }

    public async Task<byte[]> DecryptAsync(byte[] ciphertext, CancellationToken cancellationToken)
    {
        try
        {
            // Authenticate the ciphertext
            if (!await authenticator.AuthenticateAsync(ciphertext, cancellationToken))
                throw new AuthenticationException("Ciphertext is invalid");

            // Decrypt the ciphertext
            using (var decryptor = aes.CreateDecryptor())
            {
                var decryptedBytes = await Task.Run(() =>
                {
                    var buffer = new byte[ciphertext.Length];
                    var numRead = 0;
                    do
                    {
                        var readBytes = decryptor.TransformFinalBlock(buffer, numRead, buffer.Length - numRead);
                        numRead += readBytes;
                    } while (numRead < ciphertext.Length);
                    return buffer;
                }, cancellationToken);

                // Unpad the decrypted bytes
                var plaintext = padding.Unpad(decryptedBytes);

                // Return the decrypted plaintext
                return plaintext;
            }
        }
        catch (Exception ex)
        {
            // Log the error and rethrow it
            await Logger.LogErrorAsync(ex);
            throw;
        }
    }

