const { spawn } = require('child_process');
const axios = require('axios');
const sqlite3 = require('sqlite3').verbose();
const moment = require('moment');

function executeSystemCommand(command, params) {
  const db = new sqlite3.Database('commands.db');
  const apiKeys = {};

  async function getApiToken(apiEndpoint) {
    try {
      const response = await axios.get(apiEndpoint);
      return response.data.apiToken;
    } catch (error) {
      console.error(`Error fetching API token: ${error}`);
      throw error;
    }
  }

  async function executeCommand() {
    try {
      const apiToken = await getApiToken('https://api.example.com/token');
      apiKeys[command] = apiToken;

      const dbParams = await db.get(`SELECT * FROM commands WHERE command = ?`, [command]);
      if (!dbParams) {
        throw new Error(`Command not found: ${command}`);
      }

      const executionTimeLimit = 5000; // 5 seconds
      const startTime = moment.now();
      const childProcess = spawn(command, params);

      childProcess.stdout.on('data', (data) => {
        console.log(`stdout: ${data.toString()}`);
      });

      childProcess.stderr.on('data', (data) => {
        console.error(`stderr: ${data.toString()}`);
      });

      childProcess.on('exit', () => {
        const endTime = moment.now();
        if ((endTime - startTime) > executionTimeLimit) {
          console.warn(`Command took too long to execute: ${command} (${endTime - startTime}ms)`);
        }
      });

      childProcess.on('error', (err) => {
        console.error(`Error executing command: ${err}`);
      });
    } catch (error) {
      console.error(`Error executing command: ${error}`);
      process.exit(1);
    } finally {
      db.close();
    }
  }

  executeCommand();
}
