class DynamicJSONParser:
    def __init__(self):
        self.factory_registry = {}
        self.config_defaults = {}
        self.logger = logging.getLogger(__name__)

    def register_factory(self, factory_id: str, factory_func: Type['DynamicJSONParser']):
        self.factory_registry[factory_id] = factory_func

    def parse_json(self, json_str: str) -> Any:
        try:
            return json.loads(json_str)
        except json.JSONDecodeError as e:
            self.logger.error(f"Failed to parse JSON string: {e}")
            raise ValueError("Invalid JSON syntax")

    def create_json(self, obj: Any) -> str:
        try:
            return json.dumps(obj)
        except TypeError as e:
            self.logger.error(f"Failed to serialize object: {e}")
            raise ValueError("Type mismatch during object construction")

    def get_factory(self, factory_id: str) -> Type['DynamicJSONParser']:
        if factory_id not in self.factory_registry:
            self.logger.error(f"Factory ID '{factory_id}' not found in registry")
            raise KeyError(f"Unknown factory ID: {factory_id}")
        return self.factory_registry[factory_id]

    def configure_defaults(self, config_dict: Dict[str, Any]):
        self.config_defaults.update(config_dict)

    def validate_json_against_schema(self, json_data: Any) -> Tuple[bool, str]:
        # Integrate with external schema validation service
        pass

    def is_thread_safe(self):
        # Implement thread safety for registry and parsing methods
        pass

    def log_operation(self, operation: str, obj: Any = None):
        self.logger.info(f"{operation}: {obj} ({json.dumps(obj, indent=4)})")

    def __str__(self):
        return f"DynamicJSONParser({len(self.factory_registry)} factories, {len(self.config_defaults)} config defaults)"
