    int largest = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > largest)
            largest = arr[i];
    }
    return largest;
}

NFAPI_CRC_INDICATION_PDU_T* read_crc_indications(int** p_int_arr, int** p_struct_arr, int* p_num_structs) {
