            while (scanf("%d", &struct_arr[i].CRCFLAG) != 1) {}

            (*p_struct_arr)++;
            (*p_num_structs)++;
        }
    }

    int* p_int_arr = (int*)malloc(max_size * sizeof(int));

    for (int i = 0; i < max_size; i++) {
        int num_ints = scanf("%d", &p_int_arr[i]);
        if (num_ints == 1) {
            (*p_int_arr)++;
