                offsets[i] = rand() % 10000000 + 1;
            } else if (j == 1) { // For key array
                // Initialize with random int values
                int *keys = (int *)malloc(1000 * sizeof(int));
                for (int k = 0; k < 1000; k++) {
                    keys[k] = rand() % 10 + 1;
                }
            } else { // For record array
                record *records = (record *)malloc(1000 * sizeof(record));
                for (i = 0; i < 1000; i++) {
                    records[i].value = rand() % 10000 + 1;
                }
            }
        }
    }

    // Allocate memory for client library
    int socket_fd = custom_client_library_init();

    // Establish concurrent connection to remote service
    if (socket_fd == -1) {
        printf("Connection establishment failed.\n");
        return -1;
    }

    // Periodic health checks for the connection
    while (1) {
        if (!custom_client_library_health_check(socket_fd)) {
            printf("Connection dropped unexpectedly. Re-establishing...\n");
            socket_fd = custom_client_library_init();
