#ifndef RANDOM_ENGINE_H
#define RANDOM_ENGINE_H

#include <random>
#include <vector>
#include <atomic>
#include <mutex>

namespace RandomEngine {

class MTGenerator {
public:
    MTGenerator(uint64_t seed) : gen_(std::mt19937_64(seed)), currentSeed_(seed) {}

    std::vector<int> generateRandomNumbers(int quantity) {
        std::vector<int> result;
        for (int i = 0; i < quantity; ++i) {
            result.push_back(gen_.integer() % 10001);
        }
        return result;
    }

    void reset(uint64_t newSeed) {
        currentSeed_ = newSeed;
        gen_ = std::mt19937_64(newSeed);
    }

    uint64_t getCurrentSeed() const {
        return currentSeed_;
    }

private:
    std::mt19937_64 gen_;
    std::atomic<uint64_t> currentSeed_;
};

}

#endif  // RANDOM_ENGINE_H']

