import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class StringToHash {
    public static String computeMd5(String input) throws IOException {
        if (input == null || input.isEmpty()) {
            return null; // or throw an exception, depending on the requirement
        }

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = input.getBytes();
            byte[] hashBytes = md.digest(bytes);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < hashBytes.length; i++) {
                String hex = Integer.toHexString(0xff & hashBytes[i]);
                if (hex.length() == 1) {
                    sb.append('0');
                }
                sb.append(hex);
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IOException("Error computing MD5 hash", e);
        }
    }

    public static void main(String[] args) throws IOException {
        String input = "Hello, World!";
        String md5Hash = computeMd5(input);
        System.out.println(md5Hash);
    }
}
