use reqwest;
use log::{info, error};
use serde_json::json;

#[derive(Debug)]
pub struct HttpClient {
    client: reqwest::blocking::Client,
}

impl HttpClient {
    pub fn new() -> Self {
        let mut client = reqwest::blocking::Client::new();
        client.set_timeout(5000); // 5 seconds
        HttpClient { client }
    }

    pub async fn send_get_request(&self, url: &str) -> Result<String, reqwest::Error> {
        let response = self.client.get(url).send().await?;
        Ok(response.text().await?)
    }

    pub async fn send_get_request_with_hash(&self, url: &str, hash: &str) -> Result<String, reqwest::Error> {
        let response = self.client.get(url).query(&[("hash", hash)]).send().await?;
        Ok(response.text().await?)
    }
}

#[tokio::main]
async fn main() {
    let log_level = "debug";
    env_logger::init_with_level(log_level);
    let client = HttpClient::new();
    let url = "https://example.com/api/endpoint";

    // Send GET request with hash
    let input_string = "Hello, World!";
    let md5_hash = StringToHash::compute_md5(input_string); // assumes the Java component is available
    match client.send_get_request_with_hash(url, &md5_hash) {
        Ok(response) => info!("Response: {}", response),
        Err(err) => error!("Error sending request: {}", err),
    }
}
