#include <string.h>

typedef struct {
    int width;
    int height;
    float compression_quality;
    char color_space[20];
} Metadata;

Metadata* extract_metadata(const unsigned char *jpeg_data, int size) {
    Metadata* metadata = (Metadata*)malloc(sizeof(Metadata));

    // Handle baseline and progressive JPEG profiles
    if (*((unsigned char *)jpeg_data + 1) == 0xFF && *((unsigned char *)jpeg_data + 2) == 0xE0) {
        // Parse image resolution from SOI marker
        metadata->width = *(int32_t*)&jpeg_data[3];
        metadata->height = *(int32_t*)&jpeg_data[7];

        // Parse compression quality from APP1 or APP14 markers
        int16_t *quality = (int16_t*)&jpeg_data[size - 2];
        if (*quality == 0xFF || *quality == 0xF9) {
            metadata->compression_quality = *(float*)&jpeg_data[size - 4];
        } else {
            metadata->compression_quality = 75.0f; // Default compression quality
        }

        // Parse color space from APP1 or APP14 markers
        int16_t *color_space_code = (int16_t*)&jpeg_data[size - 2];
        if (*color_space_code == 0xFF || *color_space_code == 0xF9) {
            char *color_profile = (char*)&jpeg_data[size - 4];
            for (int i = 0; i < 20 && color_profile[i]; i++) {
                metadata->color_space[i] = color_profile[i];
            }
        } else {
            strcpy(metadata->color_space, "sRGB"); // Default color space
        }
    } else {
        metadata->width = -1;
        metadata->height = -1;
        metadata->compression_quality = 75.0f; // Default compression quality
        strcpy(metadata->color_space, "unknown"); // Default color space
    }

    return metadata;
}

void free_metadata(Metadata* metadata) {
    free(metadata);
}
