#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_FILENAME_LENGTH 255
#define MAX_THREADS 32

typedef struct {
    char* original_filename;
    char* new_filename;
} filename_pair;

void* process_filenames(void* arg) {
    filename_pair* pair = (filename_pair*)arg;

    // Step 1: Modify the file extension
    size_t length = strlen(pair->original_filename);
    char* new_name = malloc((length + 12) * sizeof(char));
    strcpy(new_name, pair->original_filename);
    int i = 0;
    for (i = 0; i < length - 1; i++) {
        if (!isalnum(new_name[i])) {
            new_name[i] = '_';
        }
    }
    char* extension = strtok(pair->original_filename, ".");
    char* base = strtok(NULL, ".");
    sprintf(&new_name[length], "%s_%d.%s", base, i, extension);

    // Step 2: Handle multiple filename extensions
    char* temp = strtok(new_name, ".");
    while (temp != NULL) {
        if (strlen(temp) > MAX_FILENAME_LENGTH - 5) {
            size_t new_length = strlen(temp) + 5;
            temp = realloc(temp, new_length * sizeof(char));
            sprintf(temp, "file_%s.txt", temp);
        }
        temp = strtok(NULL, ".");
    }

    // Step 3: Replace invalid characters
    for (i = 0; i < length; i++) {
        if (!isalnum(new_name[i])) {
            new_name[i] = '_';
        }
    }

    // Step 4: Support international filenames
    for (i = 0; i < length; i++) {
        if (!isprint(new_name[i])) {
            new_name[i] = '_';
        }
    }

    // Step 5: Optimize performance
    pthread_mutex_lock();
    pair->new_filename = malloc((strlen(new_name) + 1) * sizeof(char));
    strcpy(pair->new_filename, new_name);
    pthread_mutex_unlock();

    free(new_name);
    return NULL;
}

int rename_files(char** filenames, int num_filenames) {
    pthread_t threads[MAX_THREADS];
    filename_pair* pairs = malloc(num_filenames * sizeof(filename_pair));

    for (int i = 0; i < num_filenames; i++) {
        pairs[i].original_filename = filenames[i];
        pairs[i].new_filename = NULL;
    }

    int thread_index = 0;
    for (int i = 0; i < num_filenames; i += MAX_THREADS) {
        pthread_create(&threads[thread_index], NULL, process_filenames, &pairs[i]);
        thread_index++;
    }

    for (int i = 0; i < thread_index; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < num_filenames; i++) {
        printf("%s -> %s\n", pairs[i].original_filename, pairs[i].new_filename);
    }

    free(pairs);
    return 0;
}

int main() {
    char* filenames[] = {"file.txt", "file.exe", "folder/file.docx", "path/to/file.jpg"};
    int num_filenames = sizeof(filenames) / sizeof(char*);

    rename_files(filenames, num_filenames);
    return 0;
}
