#include <string.h>

void aes_256_cbc_init(const char* password, const char* salt, unsigned char** key,
                       unsigned char** iv, int* key_len) {
    // Derive the encryption key from the password using SHA-256
    unsigned char key_sha[SHA256_DIGEST_LENGTH];
    SHA256(password, strlen(password), key_sha);

    // Derive the encryption key from the salt value
    unsigned char key_derived[AES_KEY_BIT_SIZE / 8];
    HMAC(EVP_md_SHA256(), key_sha, SHA256_DIGEST_LENGTH,
         salt, strlen(salt), key_derived, AES_KEY_BIT_SIZE);

    *key = malloc(AES_KEY_BIT_SIZE);
    memcpy(*key, key_derived, AES_KEY_BIT_SIZE);

    // Generate a unique initialization vector
    unsigned char iv_val[AES_BLOCK_SIZE];
    RAND_bytes(iv_val, AES_BLOCK_SIZE);

    *iv = malloc(AES_BLOCK_SIZE);
    memcpy(*iv, iv_val, AES_BLOCK_SIZE);

    *key_len = AES_KEY_BIT_SIZE;
}

void aes_256_cbc_cleanup(unsigned char* key, unsigned char* iv) {
    if (key != NULL) {
        free(key);
    }
    if (iv != NULL) {
        free(iv);
    }
}
