#define MAX_CONCURRENCY 10
#define MAX_COMMANDS 1024

int execute_commands(char* commands) {
    int i, j, status;
    char** cmd = NULL;
    pid_t pid[MAX_CONCURRENCY];
    int count = 0;

    // Parse commands and store in an array of strings
    cmd = strtok((char*)commands, ";");
    while (cmd && count < MAX_CONCURRENCY) {
        pid[count] = fork();
        if (pid[count] == 0) { // Child process
            execvp(cmd[0], NULL);
            return 0; // Execution failed
        } else { // Parent process
            count++;
        }
        cmd = strtok(NULL, ";");
    }

    // Wait for all child processes to finish
    for (i = 0; i < count; i++) {
        waitpid(pid[i], NULL, 0);
    }

    return 1;
}

int main() {
    char commands[] = "command1; command2; command3";
    int result = execute_commands(commands);
    return result;
}
