void processOAuthAndIntegers(char *oauth_response, int *integers) {
    json_object *oath_obj = json_load_string(oauth_response);
    if (!oath_obj) {
        // Missing or invalid JSON string
        return;
    }

    char *token_type = json_object_get_string(oath_obj, "token_type");
    if (!token_type || strcmp(token_type, "Bearer") != 0) {
        // Invalid token type
        json_object_put(oath_obj);
        return;
    }

    int expires_in = json_object_get_int(oath_obj, "expires_in");
    if (expires_in <= 0) {
        // Invalid expiration time
        json_object_put(oath_obj);
        return;
    }

    char *refresh_token = json_object_get_string(oath_obj, "refresh_token");

    // Process integers
    int num_integers = 0;
    while (1) {
        int integer;
        if (scanf("%d", &integer) != 1 || integer < 0) {
            break; // Invalid input or end of file
        }
        integers[num_integers++] = integer;
    }

    qsort(integers, num_integers, sizeof(int), compare_integers);

    printf("Largest integer: %d\n", integers[0]);

    json_object_put(oath_obj);
}

int compare_integers(const void *a, const void *b) {
    int ia = *(const int *)a;
    int ib = *(const int *)b;
    return (ia > ib) - (ia < ib);
}
