void manage_memory() {
    srand(time(NULL));

    // Step 1: Allocate memory for an array of long integers representing offsets.
    size_t offset_size = 1000; // initial capacity
    long* offsets = (long*)malloc(offset_size * sizeof(long));
    for (size_t i = 0; i < offset_size; i++) {
        offsets[i] = rand() % 2001 - 1000;
    }

    // Step 2: Allocate memory for an array of int keys.
    size_t key_size = 1000;
    int* keys = (int*)malloc(key_size * sizeof(int));
    for (size_t i = 0; i < key_size; i++) {
        keys[i] = rand() % 1000;
    }

    // Step 3: Allocate memory for an array of record structures.
    size_t record_size = offset_size;
    record* records = (record*)malloc(record_size * sizeof(record));
    for (size_t i = 0; i < record_size; i++) {
        int key = keys[i % key_size];
        long hash_value = key % offset_size;
        records[i].ptr = &offsets[hash_value];
    }

    // Step 4: Update the int fields in the record structures.
    for (size_t i = 0; i < record_size; i++) {
        *records[i].ptr += rand() % 4001 + 1000;
    }

    // Step 5: Bounds checking to prevent out-of-bounds access.
    for (size_t i = 0; i < record_size; i++) {
        if (*records[i].ptr < -1000 || *records[i].ptr > 1000) {
            printf("Out-of-bounds access detected!\n");
        }
    }

    // Step 6: Handle edge cases, such as when the number of records exceeds the number of available unique offsets.
    for (size_t i = record_size; i < offset_size; i++) {
        int key = rand() % 1000;
        long hash_value = key % offset_size;
        if (*records[hash_value].ptr == -1) {
            printf("Unique offset collision detected!\n");
        }
    }

    // Step 7: Log memory usage and performance metrics.
    size_t total_bytes_allocated = sizeof(long) * offset_size + sizeof(int) * key_size + sizeof(record) * record_size;
    printf("Total bytes allocated: %zu\n", total_bytes_allocated);

    // Step 8: Free all allocated memory at the end of the function.
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    manage_memory();
    return 0;
}
