#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_NUMBERS 10000
#define BUFFER_SIZE 1024

typedef struct {
    double value;
    int is_valid;
} number_t;

number_t* read_numbers(int* count) {
    FILE* file = stdin;
    *count = 0;
    number_t* numbers = NULL;

    while (1) {
        char buffer[BUFFER_SIZE];
        if (!fgets(buffer, BUFFER_SIZE - 1, file)) {
            break; // end of input
        }

        number_t* current_number = (number_t*)malloc(sizeof(number_t));
        current_number->is_valid = 0;

        char* token = strtok(buffer, " ");
        if (token != NULL) {
            double val;
            if (sscanf(token, "%lf", &val) == 1) {
                current_number->value = val;
                current_number->is_valid = 1;
                numbers = realloc(numbers, (*count + 1) * sizeof(number_t));
                numbers[*count] = *current_number;
                (*count)++;
            } else {
                free(current_number);
            }
        }

        if (ferror(file)) {
            fclose(file);
            return NULL;
        }
    }

    free(file);
    return numbers;
}

void print_top_numbers(number_t* numbers, int count) {
    for (int i = 0; i < 10 && i < count; i++) {
        printf("%lf\n", numbers[count - i - 1].value);
    }
}

double bubble_sort(double* arr, int n) {
    double swapped;
    do {
        swapped = 0;
        for (int i = 0; i < n - 1; i++) {
            if (arr[i] < arr[i + 1]) {
                double temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
                swapped = 1;
            }
        }
    } while (swapped);

    return *arr;
}

number_t* sort_numbers(number_t* numbers, int count) {
    number_t* sorted_numbers = (number_t*)malloc(count * sizeof(number_t));
    for (int i = 0; i < count; i++) {
        if (numbers[i].is_valid) {
            sorted_numbers[i] = numbers[i];
        } else {
            free(sorted_numbers);
            return NULL;
        }
    }

    qsort(sorted_numbers, count - 1, sizeof(number_t), comp);

    for (int i = 0; i < count - 1; i++) {
        if (!sorted_numbers[count - i - 2].is_valid) {
            free(sorted_numbers);
            return NULL;
        }
    }

    return sorted_numbers;
}

int comp(const void* a, const void* b) {
    number_t* na = *(number_t*)a;
    number_t* nb = *(number_t*)b;

    if (na->is_valid && !nb->is_valid) {
        return -1;
    } else if (!na->is_valid && nb->is_valid) {
        return 1;
    } else {
        return na->value > nb->value ? -1 : 1;
    }
}

int main() {
    int count = 0;
    number_t* numbers = read_numbers(&count);

    if (numbers == NULL) {
        printf("Error reading numbers.\n");
        return -1;
    }

    // sort and print top 10 numbers
    number_t* sorted_numbers = sort_numbers(numbers, count);
    if (sorted_numbers == NULL) {
        printf("Error sorting numbers.\n");
        free(numbers);
        return -1;
    }

    print_top_numbers(sorted_numbers, count);

    for (int i = 0; i < count; i++) {
        if (!numbers[i].is_valid) {
            free(&numbers[i]);
        }
    }

    free(sorted_numbers);
    free(numbers);
}
