    // Dynamically allocate memory for integers
    int* integers = (int*)malloc(num_structures * sizeof(int));

    // Read CRC indication structures and integers from standard input
    for (int i = 0; i < num_structures; i++) {
        scanf("%d %d %d", &structures[i].RX_UE_INFORMATION_TAG, &structures[i].RNTI, &structures[i].CRC_INDICATION_REL8_TAG);
