        if(rc) {
            printf("SQL error: %s\n", sqlite3_errmsg(db));
        } else {
            // Bind the network statistics to the SQL query
            rc = sqlite3_bind_int(stmt, 1, num_structures);
            if(rc) {
                printf("Binding error: %s\n", sqlite3_errmsg(db));
            } else {
                // Execute the SQL query and update the database
                rc = sqlite3_step(stmt);
                if(rc != SQLITE_DONE) {
                    printf("Execution error: %s\n", sqlite3_errmsg(db));
                }
            }
        }

        // Release resources and close the database connection
        sqlite3_finalize(stmt);
        sqlite3_close(db);
    }
}

int main() {
