void initAndPopulateLTECellInfoArray(int numEntries, LTE_CELL_INFO_T** cellInfoArray) {
    if (!cellInfoArray || *cellInfoArray) {
        // handle error
    }

    srand(time(NULL));

    for (int i = 0; i < numEntries; i++) {
        LTE_CELL_INFO_T* cellInfo = (LTE_CELL_INFO_T*)malloc(sizeof(LTE_CELL_INFO_T));

        if (!cellInfo) {
            // handle out-of-memory error
        }

        int uniqueCellId;
        do {
            uniqueCellId = rand() % 1000; // generate a random CELL_ID
        } while (*cellInfoArray && !isUniqueCellId(*cellInfoArray, uniqueCellId));

        cellInfo->cellId = (uint16_t)uniqueCellId;
        cellInfo->pci = (uint8_t)(rand() % 2); // generate a random PCI value
        cellInfo->rssi = rand() % 100; // generate a random RSSI value
        cellInfo->txPowerLevel = rand() % 20 - 10; // generate a random TX_POWER_LEVEL value
        cellInfo->sinr = (float)(rand() % 30) / 10.0f; // generate a random SINR value

        *cellInfoArray = realloc(*cellInfoArray, (i + 1) * sizeof(LTE_CELL_INFO_T*));

        if (*cellInfoArray && i > 0) {
            (*cellInfoArray)[i - 1] = cellInfo;
        } else {
            *cellInfoArray = &cellInfo;
        }
    }
}

int isUniqueCellId(LTE_CELL_INFO_T** cellInfoArray, uint16_t cellId) {
    for (int i = 0; i < /*numEntries*/; i++) {
        if ((*cellInfoArray)[i]->cellId == cellId) {
            return 0;
        }
    }
    return 1;
}

