#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* allocateMemory(int numOffsets, int numKeys, int memoryBudget, int minValue, int maxValue) {
    // Calculate the total size of arrays
    size_t totalSize = sizeof(long) * numOffsets + sizeof(int) * numKeys;

    if (totalSize > memoryBudget) {
        // Proportionally reduce the array sizes to fit within budget
        int reducedNumOffsets = numOffsets - (int)((memoryBudget - totalSize) / sizeof(long));
        int reducedNumKeys = numKeys - (int)(((memoryBudget - totalSize) % (sizeof(int) * numKeys)) / sizeof(int));

        numOffsets = reducedNumOffsets;
        numKeys = reducedNumKeys;
    }

    // Allocate arrays
    long* offsets = malloc(sizeof(long) * numOffsets);
    int* keys = malloc(sizeof(int) * numKeys);

    // Initialize arrays
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = i;
    }
    for (int i = 0; i < numKeys; i++) {
        keys[i] = i;
    }

    // Allocate and initialize record array
    record* records = malloc(sizeof(record) * numOffsets);
    srand(time(NULL));
    for (int i = 0; i < numOffsets; i++) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }

    // Serialize data structures
    FILE* file = fopen("data.bin", "wb");
    fwrite(&numOffsets, sizeof(int), 1, file);
    fwrite(&numKeys, sizeof(int), 1, file);
    fwrite(offsets, sizeof(long), numOffsets, file);
    fwrite(keys, sizeof(int), numKeys, file);
    fwrite(records, sizeof(record), numOffsets, file);
    fclose(file);

    // Deallocate memory
    free(offsets);
    free(keys);
    free(records);

    return records;
}
