#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structure for LTE_ENB_RRC_MESSAGE
typedef struct {
    L1_TELEMETRY_DATA* l1_telemetry;
    ENB_RRC_UE_CONTEXT* ue_context;
} LTE_ENB_RRC_MESSAGE;

// Define the library structure to manage dynamic collection of messages
typedef struct {
    pthread_mutex_t lock; // Lock for concurrent access
    size_t capacity; // Initial capacity for message storage
    size_t count; // Current number of stored messages
    LTE_ENB_RRC_MESSAGE** messages; // Array of stored messages
} LTE_ENB_RRC_MESSAGE_LIBRARY;

// Initialize the library structure
LTE_ENB_RRC_MESSAGE_LIBRARY* lte_enb_rrc_message_library_init(size_t initial_capacity) {
    LTE_ENB_RRC_MESSAGE_LIBRARY* lib = (LTE_ENB_RRC_MESSAGE_LIBRARY*)malloc(sizeof(LTE_ENB_RRC_MESSAGE_LIBRARY));
    lib->capacity = initial_capacity;
    lib->count = 0;
    lib->messages = (LTE_ENB_RRC_MESSAGE**)calloc(initial_capacity, sizeof(LTE_ENB_RRC_MESSAGE*));
    pthread_mutex_init(&lib->lock, NULL);
    return lib;
}

// Add a new message to the library
void lte_enb_rrc_message_library_add(LTE_ENB_RRC_MESSAGE_LIBRARY* lib, LTE_ENB_RRC_MESSAGE* message) {
    pthread_mutex_lock(&lib->lock);
    if (lib->count >= lib->capacity) {
        // Reallocate memory for growing capacity
        lib->capacity *= 2;
        lib->messages = (LTE_ENB_RRC_MESSAGE**)realloc(lib->messages, lib->capacity * sizeof(LTE_ENB_RRC_MESSAGE*));
    }
    lib->messages[lib->count] = message;
    lib->count++;
    pthread_mutex_unlock(&lib->lock);
}

// Retrieve a message from the library by ID
LTE_ENB_RRC_MESSAGE* lte_enb_rrc_message_library_get_by_id(LTE_ENB_RRC_MESSAGE_LIBRARY* lib, uint64_t id) {
    pthread_mutex_lock(&lib->lock);
    for (size_t i = 0; i < lib->count; i++) {
        if (messages[i]->id == id) {
            return messages[i];
        }
    }
    pthread_mutex_unlock(&lib->lock);
    return NULL;
}

// Update a message in the library by ID
void lte_enb_rrc_message_library_update_by_id(LTE_ENB_RRC_MESSAGE_LIBRARY* lib, uint64_t id, LTE_ENB_RRC_MESSAGE* updated_message) {
    pthread_mutex_lock(&lib->lock);
    for (size_t i = 0; i < lib->count; i++) {
        if (messages[i]->id == id) {
            messages[i] = updated_message;
            return;
        }
    }
    pthread_mutex_unlock(&lib->lock);
}

// Free the library structure
void lte_enb_rrc_message_library_free(LTE_ENB_RRC_MESSAGE_LIBRARY* lib) {
    pthread_mutex_destroy(&lib->lock);
    free(lib->messages);
    free(lib);
}
