#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

#define RECORDS 1000
#define CONNECTIONS 10
#define PORT 8080

typedef struct {
    int value;
    char status;
} Record;

typedef struct {
    Record* record;
    time_t timestamp;
    int error_count;
} Metadata;

void* allocateMemory(int count) {
    void* ptr = malloc(count * sizeof(Record));
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int main() {
    srand(time(NULL)); // seed random number generator

    Record* records = allocateMemory(RECORDS);
    int* keys = allocateMemory(RECORDS);
    long* offsets = allocateMemory(RECORDS);

    Metadata* metadata = allocateMemory(RECORDS);

    pthread_t connections[CONNECTIONS];

    for (int i = 0; i < RECORDS; i++) {
        records[i].value = rand() % 100;
        records[i].status = 'A'; // initialize status
    }

    for (int i = 0; i < CONNECTIONS; i++) {
        pthread_create(&connections[i], NULL, &handleConnection, NULL);
    }

    for (int i = 0; i < RECORDS; i++) {
        free(records[i].record); // deallocate record memory
    }
    free(records); // deallocate main array of records
    free(keys); // deallocate keys array
    free(offsets); // deallocate offsets array

    for (int i = 0; i < CONNECTIONS; i++) {
        pthread_join(connections[i], NULL);
    }

    return 0;
}

void* handleConnection() {
    int sockfd, connfd;

    struct sockaddr_in servaddr, cliaddr;
    socklen_t clilen;

    // Create a new socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(PORT);

    inet_pton(AF_INET, "127.0.0.1", &servaddr.sin_addr);

    // Bind the socket
    if (bind(sockfd, (struct sockaddr*) &servaddr, sizeof(servaddr)) < 0) {
        perror("Bind failed");
        exit(EXIT_FAILURE);
    }

    // Listen for connections
    listen(sockfd, 3);
    clilen = sizeof(cliaddr);

    while (1) {
        connfd = accept(sockfd, (struct sockaddr*) &cliaddr, &clilen);
        if (connfd < 0) {
            perror("Connection failed");
            exit(EXIT_FAILURE);
        }
        pthread_exit(connfd); // handle the connection
    }

    return NULL;
}
