void* alloc_arrays(size_t offset_size, size_t key_size, int numOffsets, int numKeys, size_t memoryBudget) {
    void* offsets = NULL;
    void* keys = NULL;

    if ((offsets = malloc(numOffsets * sizeof(long))) == NULL || 
        (keys = malloc(numKeys * sizeof(int))) == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize arrays
    long* offset_ptr = offsets;
    int* key_ptr = keys;

    for (int i = 0; i < numOffsets; i++) {
        *offset_ptr++ = i;
    }
    for (int i = 0; i < numKeys; i++) {
        *key_ptr++ = i;
    }

    // Check memory usage
    size_t total_size = sizeof(long) * numOffsets + sizeof(int) * numKeys;
    if (total_size > memoryBudget) {
        printf("Memory budget exceeded.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Return allocated arrays
    return offsets;
}

