record_t* initRecords(int maxRecs, int maxKeySize, int maxOffsetSize, int minVal, int maxVal);
void updateRecord(record_t* records[], int index, int newKey);

int main() {
    // Example usage
    int maxRecs = 100;
    int maxKeySize = 10;
    int maxOffsetSize = 20;
    int minVal = 1;
    int maxVal = 100;

    record_t* records = initRecords(maxRecs, maxKeySize, maxOffsetSize, minVal, maxVal);

    printf("Number of initialized records: %d\n", records[0].key); // Assuming at least one record is initialized

    // Example update
    int indexToUpdate = 5;
    int newKey = 15;
    updateRecord(&records, indexToUpdate, newKey);
}

record_t* initRecords(int maxRecs, int maxKeySize, int maxOffsetSize, int minVal, int maxVal) {
    record_t* records = (record_t*)malloc(maxRecs * sizeof(record_t));
    if (!records) return NULL; // Handle allocation error

    srand(time(NULL)); // Initialize random number generator

    for (int i = 0; i < maxRecs; i++) {
        int key = rand() % (maxVal - minVal + 1) + minVal;
        long offset = rand() % (1 << maxOffsetSize - 1);
        if (i >= maxKeySize || i >= maxOffsetSize) break;

        records[i].key = key;
        records[i].offset = offset;
    }

    return records;
}

void updateRecord(record_t* records[], int index, int newKey) {
    if (!records || index < 0 || index >= sizeof(*records) / sizeof(records[0])) return; // Handle invalid index

    if (index < sizeof(*records) / sizeof(records[0]))
        records[index]->key = newKey;
}
