EVP_CIPHER_CTX* configure_cipher(int algorithm_id, int key_size, const char* mode) {
    EVP_CIPHER_CTX* cipher_ctx;
    unsigned char* block_size = NULL;

    switch (algorithm_id) {
        case 0: // DES
