                cipher_ctx = EVP_CipherInit(EVP_des_ecb(), key_size);
            } else if (!strcmp(mode, "EDE")) {
                cipher_ctx = EVP_CipherInit(EVP_des_ede(), key_size);
            } else if (!strcmp(mode, "EDE3")) {
                cipher_ctx = EVP_CipherInit(EVP_des_ede3(), key_size);
            } else if (!strcmp(mode, "CFB")) {
                block_size = (unsigned char*)malloc(1); // size of block
                *block_size = 8; // default value for DES-CFB
                cipher_ctx = EVP_CipherInit(EVP_des_cfb(), key_size, block_size);
            } else if (!strcmp(mode, "null")) {
                cipher_ctx = EVP_CipherInit(NULL_CIPHER_CTX()); // Null encryption
            } else {
                ERR_error(ERR_VALUE_OUT_OF_RANGE, "Invalid mode");
            }
            break;

        default:
            ERR_error(ERR_VALUE_OUT_OF_RANGE, "Invalid algorithm ID");
            return NULL;
    }

    if (cipher_ctx == NULL) {
        cipher_ctx = EVP_CipherInit(EVP_des_ecb(), 64); // Default to DES-ECB with 64-bit key
    }

    return cipher_ctx;
}
