#define MAX_LIST_SIZE 1000
#define WEB_SERVICE_PORT 8080

typedef struct {
    int rx_ue_info_tag;
    int rnti;
    int crc_ind_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *list = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void* helper_function(void* arg) {
    int max_val = *(int*)arg;
    // find the largest integer in the list
    return (void*)&max_val;
}

void print_max(int* list, int size) {
    pthread_t thread;
    pthread_create(&thread, NULL, helper_function, list);
    pthread_join(thread, NULL);
    printf("Largest value: %d\n", *(int*)list);
}

void update_resource(char* id, char* data) {
    // validate input
    if (strlen(id) > 10 || strlen(data) > 100) {
        printf("Invalid request\n");
        return;
    }

    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        if (!strcmp(list[i].rx_ue_info_tag, id)) {
            // update the resource
            list[i].rnti = atoi(data);
            printf("Updated resource: %s\n", id);
            pthread_mutex_unlock(&list_mutex);
            return;
        }
    }
    printf("Resource not found\n");
    pthread_mutex_unlock(&list_mutex);
}

void delete_resource(char* id) {
    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        if (!strcmp(list[i].rx_ue_info_tag, id)) {
            // remove the resource
            printf("Deleted resource: %s\n", id);
            for (int j = i; j < MAX_LIST_SIZE - 1; j++) {
                list[j] = list[j + 1];
            }
            pthread_mutex_unlock(&list_mutex);
            return;
        }
    }
    printf("Resource not found\n");
    pthread_mutex_unlock(&list_mutex);
}

void handle_http_request(int conn_fd) {
    char buffer[1024];
    read(conn_fd, buffer, 1023);
    char* method = strtok(buffer, " ");
    if (strcmp(method, "PUT") == 0) {
        char* id = strtok(NULL, " ");
        char* data = strtok(NULL, "\r\n");
        update_resource(id, data);
    } else if (strcmp(method, "DELETE") == 0) {
        char* id = strtok(NULL, " ");
        delete_resource(id);
    }
}

int main() {
    pthread_t thread;
    list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    int num_ints;
    scanf("%d", &num_ints);

    for (int i = 0; i < num_ints; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list[i];
        // read integers from standard input and populate the list
        scanf("%d %d %d", &pdu->rx_ue_info_tag, &pdu->rnti, &pdu->crc_ind_rel8_tag);
    }

    print_max(list, num_ints);

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in serv_addr;
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(WEB_SERVICE_PORT);
    inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr);

    bind(server_fd, (struct sockaddr*)&serv_addr, sizeof(serv_addr));
    listen(server_fd, 3);

    while (1) {
        int conn_fd = accept(server_fd, NULL, NULL);
        handle_http_request(conn_fd);
    }

    return 0;
}
