// Define a struct representing UE session state
typedef struct {
    int ueId;
    int bearerId;
    int QoSProfile; // 0: Best Effort, 1: Guaranteed Bitrate, 2: Reserved
} UeSessionState;

// Function to initialize and filter sessions
UeSessionState** initializeAndFilterSessions(int numSessions, int startBearerId, int endBearerId) {
    // Initialize an array of session pointers with size equal to the number of sessions
    UeSessionState** sessions = (UeSessionState**)malloc(numSessions * sizeof(UeSessionState*));

    for (int i = 0; i < numSessions; i++) {
        // Create a new session structure and initialize its fields
        UeSessionState* session = (UeSessionState*)malloc(sizeof(UeSessionState));
        session->ueId = i + 1;
        session->bearerId = rand() % 100; // Randomly generate bearer ID
        session->QoSProfile = rand() % 3; // Randomly generate QoS profile

        // Assign the session structure to its corresponding pointer in the sessions array
        sessions[i] = session;
    }

    // Filter sessions based on the specified bearer ID range
    UeSessionState** filteredSessions = (UeSessionState**)malloc((endBearerId - startBearerId + 1) * sizeof(UeSessionState*));
    int filteredSessionIndex = 0;

    for (int i = 0; i < numSessions; i++) {
        if (sessions[i]->bearerId >= startBearerId && sessions[i]->bearerId <= endBearerId) {
            // Copy the session structure to the filtered sessions array
            filteredSessions[filteredSessionIndex] = sessions[i];
            filteredSessionIndex++;
        }
    }

    // Deallocate unnecessary memory and return the filtered sessions array
    for (int i = 0; i < numSessions - filteredSessionIndex; i++) {
        free(sessions[i]);
    }
    free(sessions);

    return filteredSessions;
}
