    UeSessionState *sessions;
    int capacity;
} UeSessionHashTable;

UeSessionHashTable* create_hash_table(int initial_capacity) {
    UeSessionHashTable* hash_table = (UeSessionHashTable*)malloc(sizeof(UeSessionHashTable));
    hash_table->capacity = initial_capacity;
    hash_table->sessions = (UeSessionState*)calloc(initial_capacity, sizeof(UeSessionState));
    return hash_table;
}

void free_hash_table(UeSessionHashTable* hash_table) {
    if (hash_table == NULL) return;
    free(hash_table->sessions);
    free(hash_table);
}

int insert_session(UeSessionHashTable* hash_table, int ueId, int bearerId, char qosProfile[]) {
    // Find existing session for given ueId
    for (int i = 0; i < hash_table->capacity; i++) {
        if (hash_table->sessions[i].ueId == ueId) {
            // Update existing session
            memcpy(&hash_table->sessions[i], qosProfile, sizeof(UeSessionState));
            return 1;
        }
    }

    // Insert new session
    for (int i = 0; i < hash_table->capacity; i++) {
        if (hash_table->sessions[i].ueId == -1) {
            memcpy(&hash_table->sessions[i], qosProfile, sizeof(UeSessionState));
            return 1;
        }
    }

    // Hash table full, insert new session and remove least-recently-used one
    for (int i = 0; i < hash_table->capacity; i++) {
        if (hash_table->sessions[i].ueId == -1) {
            memcpy(&hash_table->sessions[i], qosProfile, sizeof(UeSessionState));
            return 1;
        }
    }

    return 0;
}

int filter_sessions(UeSessionHashTable* hash_table, int min_bearer_id, int max_bearer_id) {
