// External library for generating random words and numbers
extern void* randlib_init();
extern void randlib_finalize(void*);
extern char* randlib_get_random_word(int max_length);
extern int randlib_get_random_number(int min, int max);

int main() {
    // Initialize the external library
    void* randlib_handle = randlib_init();

    // Set maximum allowed memory allocation in kilobytes
    const size_t MAX_MEMORY_ALLOCATION = 1024 * 16; // 16 MB

    // Prompt user for array sizes and validate input
    int id_array_size;
    printf("Enter the number of identifiers: ");
    if (scanf("%d", &id_array_size) != 1 || id_array_size <= 0) {
        fprintf(stderr, "Invalid input. Exiting.\n");
        randlib_finalize(randlib_handle);
        return -1;
    }

    // Calculate total memory required for arrays
    size_t total_memory_required = sizeof(float) * id_array_size + sizeof(unsigned long) * id_array_size;

    if (total_memory_required > MAX_MEMORY_ALLOCATION) {
        fprintf(stderr, "Memory allocation exceeds maximum allowed. Exiting.\n");
        randlib_finalize(randlib_handle);
        return -1;
    }

    // Allocate memory for identifier and float arrays
    unsigned long* ids = (unsigned long*)malloc(sizeof(unsigned long) * id_array_size);
    float* values = (float*)malloc(sizeof(float) * id_array_size);

    if (!ids || !values) {
        fprintf(stderr, "Memory allocation failed. Exiting.\n");
        free(ids);
        free(values);
        randlib_finalize(randlib_handle);
        return -1;
    }

    // Initialize cache for random word and number generation
    char* cached_word = NULL;
    int cached_max_length = 0;

    // Iterate over identifiers to generate profiles
    for (int i = 0; i < id_array_size; i++) {
        // Generate random float value, ensuring no consecutive duplicates
        float value;
        do {
            int min_range = 1.0f;
            int max_range = 100.0f;

            if (cached_word) {
                // Reuse cached word and adjust range accordingly
                int adjusted_min = randlib_get_random_number(min_range, (int)(min_range + (max_range - min_range) * (255 - strlen(cached_word)) / 255.0f));
                int adjusted_max = randlib_get_random_number(adjusted_min, max_range);
                value = (float)randlib_get_random_number((int)(adjusted_min + (adjusted_max - adjusted_min) * i / id_array_size), adjusted_max);
            } else {
                // Generate new random word and adjust range
                int min_range = 1.0f;
                int max_range = 100.0f;

                char* new_word = randlib_get_random_word(255);

                value = (float)randlib_get_random_number((int)(min_range + (max_range - min_range) * i / id_array_size), max_range);
            }

            // Store generated word in cache
            cached_word = new_word;
            cached_max_length = strlen(new_word);

        } while (value == values[i]);

        // Set profile data
        Profile* profile = (Profile*)malloc(sizeof(Profile));
        if (!profile) {
            fprintf(stderr, "Memory allocation failed. Exiting.\n");
            free(profile);
            randlib_finalize(randlib_handle);
            return -1;
        }

        profile->value = value;
        strcpy(profile->word, cached_word);

        // Set identifier
        profile->id = ids[i];

        // Store profile in cache (if not already allocated)
        // ...

        // Free memory for previous profile (if any)
        free(cached_word);
    }

    // Clean up and exit
    randlib_finalize(randlib_handle);
    free(ids);
    free(values);

    return 0;
}
