    while (1) {
        if ((cell_info_arr = realloc(cell_info_arr, sizeof(NR_CELL_INFORMATION_T *) * (allocated_count + max_allocated))) == NULL || 
            (allocated_cell_ids = realloc(allocated_cell_ids, sizeof(int) * (allocated_count + max_allocated))) == NULL) {
            printf("Memory allocation failed. Freeing previously allocated memory...\n");
            for (int i = 0; i < allocated_count; i++) {
                free(cell_info_arr[i]);
            }
            if (cell_info_arr != NULL) free(cell_info_arr);
            if (allocated_cell_ids != NULL) free(allocated_cell_ids);
            return;
        }

        cell_info_arr[allocated_count] = malloc(sizeof(NR_CELL_INFORMATION_T));
        if (cell_info_arr[allocated_count] == NULL) {
            printf("Memory allocation failed. Freeing previously allocated memory...\n");
            for (int i = 0; i < allocated_count; i++) {
                free(cell_info_arr[i]);
            }
            if (cell_info_arr != NULL) free(cell_info_arr);
            return;
        }

        allocated_cell_ids[allocated_count] = num_cells++;
        allocated_count++;

        if (num_cells >= max_allocated * 2) {
            max_allocated *= 2; // dynamically adjust allocation size
        } else {
            break;
        }
    }

    printf("Allocated %d cell information structures.\n", allocated_count);
}
