    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to initialize the dynamic list
void init_list(Node** head_ref) {
    *head_ref = NULL;
}

// Function to add an element to the dynamic list
void add_element(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T new_data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = new_data;
    new_node->next = *head_ref;
    *head_ref = new_node;
}

// Function to update an existing element based on RNTI
void update_element(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T new_data) {
    Node* current = *head_ref;
    while (current != NULL) {
        if (current->data.rnti == new_data.rnti) {
            current->data = new_data;
            return;
        }
        current = current->next;
    }
}

// Function to remove an element by RNTI
void remove_element(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T data_to_remove) {
    Node* previous = NULL;
    Node* current = *head_ref;
    while (current != NULL) {
        if (current->data.rnti == data_to_remove.rnti) {
            if (previous == NULL) {
                *head_ref = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

// Function to collect real-time performance metrics
void collect_metrics(Node* head, int* num_elements, int* crc_errors) {
    *num_elements = 0;
    *crc_errors = 0;
    Node* current = head;
    while (current != NULL) {
        if (!current->data.crcflag) {
            (*crc_errors)++;
        }
        (*num_elements)++;
        current = current->next;
    }
}

