    // Initialize the dynamic list
    Node* head = NULL;

    // Add elements to the list
    add_element(&head, (NFAPI_CRC_INDICATION_PDU_T){/* Your data here */});
    add_element(&head, (NFAPI_CRC_INDICATION_PDU_T){/* Your data here */});

    // Update an existing element based on RNTI
    update_element(&head, (NFAPI_CRC_INDICATION_PDU_T){/* Your data here */});

    // Remove elements by RNTI
    remove_element(&head, (NFAPI_CRC_INDICATION_PDU_T){/* Your data here */});
    remove_element(&head, (NFAPI_CRC_INDICATION_PDU_T){/* Your data here */});

    // Collect real-time performance metrics
    int num_elements = 0;
    int crc_errors = 0;
    collect_metrics(head, &num_elements, &crc_errors);

    printf("Number of elements: %d\n", num_elements);
    printf("CRC errors detected: %d\n", crc_errors);

