#include <time.h>

typedef struct {
    int value;
} record;

record* createRecord(int index) {
    record* rec = (record*)malloc(sizeof(record));
    if(rec == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    rec->value = rand() % 100; // set random value within range [0, 99]
    return rec;
}

void unionFind(int** offsets, int* keys, record** records, int n, int* disjointPairs, int* timeTaken) {
    int* parent = (int*)malloc(sizeof(int) * n);
    for(int i=0; i<n; i++) {
        parent[i] = i;
    }

    for(int i=0; i<n; i++) {
        int root = i;
        while(parent[root] != root) {
            root = parent[root];
        }
        for(int j=i+1; j<n; j++) {
            if(root == (parent[j]=j)) {
                break;
            }
        }
        for(int j=root; j!=parent[j]; j=parent[j]) {
            int nextRoot = parent[j];
            parent[nextRoot] = root;
        }
    }

    int count = 0;
    clock_t start, end;
    for(int i=0; i<n; i++) {
        for(int j=i+1; j<n; j++) {
            if(parent[i] == parent[j]) {
                disjointPairs[count++] = (i<j)?i:j;
                start = clock();
                // do some operation
                end = clock();
                *timeTaken += 1000*(end-start)/CLOCKS_PER_SEC;
            }
        }
    }

    free(parent);
}

int main() {
    int n = 10; // dynamic input size
    record** records = (record**)malloc(sizeof(record*)*n);
    for(int i=0; i<n; i++) {
        records[i] = createRecord(i);
    }

    int keys[n];
    int offsets[n];

    // implement initialization logic

    int disjointPairs[10]; // dynamic array size
    int timeTaken = 0;
    unionFind(&offsets, &keys, records, n, disjointPairs, &timeTaken);

    printf("Disjoint pairs: ");
    for(int i=0; i<sizeof(disjointPairs)/sizeof(disjointPairs[0]); i++) {
        printf("%d ", disjointPairs[i]);
    }
    printf("\nTime taken: %d ms\n", timeTaken);

    // free memory
    for(int i=0; i<n; i++) {
        free(records[i]);
    }
    free(records);

    return 0;
}
