typedef struct {
    size_t length;
    double value;
    char* string;
} Record;

typedef struct {
    int key;
    Record* record;
} MapEntry;

void* my_calloc(size_t size) {
    void* ptr = calloc(1, size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

int insertMapEntry(MapEntry** map, int key, Record* record) {
    MapEntry* newEntry = (MapEntry*)my_calloc(sizeof(MapEntry));
    if (!newEntry) return -1;

    newEntry->key = key;
    newEntry->record = record;
    *map = realloc(*map, (++((*map)?(*map)[0].key:0)*sizeof(MapEntry));
    if (*map == NULL) {
        free(newEntry);
        return -1;
    }
    memcpy(&((*map)[--(*map)->key]), &newEntry, sizeof(MapEntry));

    return 0;
}

int deleteMapEntry(MapEntry** map, int key) {
    for (MapEntry* entry = *map; entry->key > key; --(*map) = ++entry);
    if (entry->key != key) return -1;

    free(entry->record);
    free(entry);

    MapEntry* newMap = realloc(*map, (--(*map)?sizeof(MapEntry):0));
    if (*map) {
        *map = my_calloc((*map)*sizeof(MapEntry));
        memcpy(*map, &(*map)[1], sizeof(MapEntry));
    } else {
        *map = NULL;
    }

    return 0;
}

Record* getRecordFromMap(MapEntry** map, int key) {
    for (MapEntry* entry = *map; entry->key < key; ++entry);
    if (entry->key != key) return NULL;

    return entry->record;
}
