#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_PDU 1000
#define PDU_LOCK "pdu_lock"

typedef struct {
    uint32_t seq_num;
    MACSDU sdumsg;
} MAC_PDU_T;

typedef struct {
    int count;
    pthread_mutex_t lock;
    MAC_PDU_T* pdus[MAX_PDU];
} pdu_list_t;

pdu_list_t pdu_list = {0};

void add_pdu(uint32_t seq_num, MACSDU sdumsg) {
    pthread_mutex_lock(PDU_LOCK);

    for (int i = 0; i < pdu_list.count; i++) {
        if (pdu_list.pdus[i]->seq_num == seq_num) {
            // Update existing PDU
            pdu_list.pdus[i]->sdumsg = sdumsg;
            pthread_mutex_unlock(PDU_LOCK);
            return;
        }
    }

    // Check if the sequence number is already used
    for (int i = 0; i < pdu_list.count; i++) {
        if (pdu_list.pdus[i]->seq_num == seq_num) {
            printf("Error: PDU with same sequence number already exists.\n");
            pthread_mutex_unlock(PDU_LOCK);
            return;
        }
    }

    // Add new PDU
    if (pdu_list.count >= MAX_PDU) {
        printf("Error: Maximum number of PDUs reached.\n");
        pthread_mutex_unlock(PDU_LOCK);
        return;
    }

    pdu_list.pdus[pdu_list.count] = (MAC_PDU_T*)malloc(sizeof(MAC_PDU_T));
    if (!pdu_list.pdus[pdu_list.count]) {
        printf("Error: Memory allocation failed.\n");
        pthread_mutex_unlock(PDU_LOCK);
        return;
    }

    pdu_list.pdus[pdu_list.count]->seq_num = seq_num;
    pdu_list.pdus[pdu_list.count]->sdumsg = sdumsg;

    pdu_list.count++;

    pthread_mutex_unlock(PDU_LOCK);
}

void remove_pdu(uint32_t seq_num) {
    pthread_mutex_lock(PDU_LOCK);

    for (int i = 0; i < pdu_list.count; i++) {
        if (pdu_list.pdus[i]->seq_num == seq_num) {
            free(pdu_list.pdus[i]);
            memmove(&pdu_list.pdus[i], &pdu_list.pdus[i+1],
                    sizeof(MAC_PDU_T*) * (pdu_list.count - i - 1));
            pdu_list.count--;

            if (i >= pdu_list.count) {
                break;
            }
        }
    }

    pthread_mutex_unlock(PDU_LOCK);
}

void init_pdu_list() {
    pthread_mutex_init(&pdu_list.lock, NULL);
    for (int i = 0; i < MAX_PDU; i++) {
        pdu_list.pdus[i] = NULL;
    }
    pdu_list.count = 0;
}

void free_pdu_list() {
    for (int i = 0; i < pdu_list.count; i++) {
        free(pdu_list.pdus[i]);
    }
    pthread_mutex_destroy(&pdu_list.lock);
}
