#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000000
#define LOG_FILE "operation.log"

typedef struct {
    int key;
    float weight;
    char status;
} Record;

Record* records = NULL;
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_records() {
    if (records != NULL) {
        free(records);
    }
    records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
}

void add_record(int key, float weight, char status) {
    pthread_mutex_lock(&mutex);
    if (record_count >= MAX_RECORDS) {
        MAX_RECORDS *= 2;
        records = (Record*)realloc(records, MAX_RECORDS * sizeof(Record));
    }
    records[record_count].key = key;
    records[record_count].weight = weight;
    records[record_count].status = status;
    record_count++;
    pthread_mutex_unlock(&mutex);
}

void find_disjoint_sets() {
    int* parent = (int*)malloc(record_count * sizeof(int));
    int* rank = (int*)malloc(record_count * sizeof(int));

    for (int i = 0; i < record_count; i++) {
        parent[i] = i;
        rank[i] = 0;
    }

    for (int i = 0; i < record_count; i++) {
        int root = find(parent, records[i].key);
        for (int j = i + 1; j < record_count; j++) {
            if (find(parent, records[j].key) == root) {
                union_sets(parent, rank, root, records[j].key);
            }
        }
    }

    free(parent);
    free(rank);
}

int find(int* parent, int key) {
    if (parent[key] != key) {
        parent[key] = find(parent, parent[key]);
    }
    return parent[key];
}

void union_sets(int* parent, int* rank, int root1, int root2) {
    if (rank[root1] < rank[root2]) {
        parent[root1] = root2;
    } else if (rank[root1] > rank[root2]) {
        parent[root2] = root1;
    } else {
        parent[root2] = root1;
        rank[root1]++;
    }
}

void log_operation(char* operation) {
    FILE* file = fopen(LOG_FILE, "a");
    fprintf(file, "%s\n", operation);
    fclose(file);
}

void update_record(int key, float weight, char status) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < record_count; i++) {
        if (records[i].key == key) {
            records[i].weight = weight;
            records[i].status = status;
            log_operation("Record updated");
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void handle_update_failure(int key, float weight, char status) {
    log_operation("Update failed");
}

int main() {
    init_records();
    // Add records
    add_record(1, 10.0f, 'A');
    add_record(2, 20.0f, 'B');
    add_record(3, 30.0f, 'C');

    // Find disjoint sets
    find_disjoint_sets();

    // Update record
    update_record(2, 25.0f, 'D');

    return 0;
}
