typedef struct {
    int ueId;
    int bearerId;
    char* QoSProfile;
} UeSessionState;

int initializeAndFilterSessions(int* startBearerId, int* endBearerId) {
    // Initialize the session collection and logging framework
    UeSessionState** sessions = (UeSessionState**)malloc(100 * sizeof(UeSessionState*));
    int numSessions = 0;
    FILE* logFile = fopen("sessions.log", "w");

    if (!logFile) {
        return -1; // Error opening the log file
    }

    // Populate the session collection with data representing active UE sessions
    for (int i = 0; i < 100; i++) {
        UeSessionState* session = (UeSessionState*)malloc(sizeof(UeSessionState));
        session->ueId = i;
        session->bearerId = i % 10 + *startBearerId;
        session->QoSProfile = malloc(strlen("ServiceType1") + 1);
        strcpy(session->QoSProfile, "ServiceType1");

        // Add the session to the collection and increment the count
        sessions[numSessions++] = session;
    }

    // Filter sessions based on the specified bearerId range
    for (int i = 0; i < numSessions; i++) {
        if (sessions[i]->bearerId >= *startBearerId && sessions[i]->bearerId <= *endBearerId) {
            // Log information about each filtered session
            fprintf(logFile, "Filtered session: ueId=%d, bearerId=%d, QoSProfile='%s'\n", 
                    sessions[i]->ueId, sessions[i]->bearerId, sessions[i]->QoSProfile);
        } else {
            // Log information about non-filtered sessions
            fprintf(logFile, "Not filtered: ueId=%d, bearerId=%d, QoSProfile='%s'\n", 
                    sessions[i]->ueId, sessions[i]->bearerId, sessions[i]->QoSProfile);

            // Deallocate memory for non-filtered sessions to reduce overhead
            free(sessions[i]->QoSProfile);
            free(sessions[i]);
        }
    }

    // Close the log file and deallocate memory for the session collection
    fclose(logFile);
    for (int i = 0; i < numSessions; i++) {
        free(sessions[i]->QoSProfile);
        free(sessions[i]);
    }
    free(sessions);

    return 0;
}
