#include <string.h>
#include <json-c/json.h>
#include <yaml.h>

typedef struct {
    int value;
} record_t;

record_t* load_config(const char* format, const char* url_or_file) {
    // Initialize arrays and memory
    int num_offsets = 0;
    int num_keys = 0;
    int num_records = 0;
    json_object* config_json = NULL;
    yaml_parser_t parser;
    yaml_event_t event;

    if (strcasecmp(format, "json") == 0) {
        // Load JSON configuration
        FILE* file = fopen(url_or_file, "r");
        if (!file) {
            printf("Error opening file: %s\n", url_or_file);
            return NULL;
        }
        config_json = json_destruct(json_load_file(file));
        fclose(file);

        num_offsets = json_object_get_int_value(config_json, "offsets_count");
        num_keys = json_object_get_int_value(config_json, "keys_count");
        num_records = json_object_get_int_value(config_json, "records_count");

    } else if (strcasecmp(format, "yaml") == 0) {
        // Load YAML configuration
        FILE* file = fopen(url_or_file, "r");
        if (!file) {
            printf("Error opening file: %s\n", url_or_file);
            return NULL;
        }
        yaml_parser_init(&parser);
        yaml_parser_set_input_file(&parser, file);

        while (1) {
            yaml_event_init(&event);
            int event_type = yaml_parser_scan(&parser, &event);

            if (event_type == YAML_NO_EVENT)
                break;

            if (event.type == YAML_SCALAR_NODE && 
                !strcmp(event.data.scalar.s, "offsets_count") &&
                json_object_get_int_value(config_json, "offsets_count")) {
                num_offsets = json_object_get_int_value(config_json, "offsets_count");
            } else if (event.type == YAML_SCALAR_NODE && 
                !strcmp(event.data.scalar.s, "keys_count") &&
                json_object_get_int_value(config_json, "keys_count")) {
                num_keys = json_object_get_int_value(config_json, "keys_count");
            } else if (event.type == YAML_SEQ_START || 
                event.type == YAML_MAP_START) {
                num_records = json_object_get_int_value(config_json, "records_count");
            }

            yaml_event_delete(&event);
        }
        yaml_parser_free(&parser);
        fclose(file);

    } else {
        printf("Unsupported format: %s\n", format);
        return NULL;
    }

    // Initialize arrays
    int* offsets = (int*)malloc((num_offsets + 1) * sizeof(int));
    int* keys = (int*)malloc((num_keys + 1) * sizeof(int));
    record_t* records = (record_t*)malloc((num_records + 1) * sizeof(record_t));

    // Populate arrays
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % 100;
    }

    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % 100;
    }

    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100;
    }

    // Clean up and log
    free(config_json);
    free(offsets);
    free(keys);
    free(records);

    return records;
}
