#include <string.h>

#define MAX_RECORDS 10000
#define MAX_KEY 10
#define TIMESTAMP_SIZE sizeof(double)

typedef struct {
    int value;
    double timestamp;
} record_t;

record_t* records = NULL;
int record_count = 0;
int offset_count = 0;
int key_count = 0;

// Hash table for quick lookups of keys and timestamps
typedef struct {
    int key;
    int offset;
} hash_entry_t;
hash_entry_t* hash_table = NULL;
int hash_table_size = 1000;
int hash_table_count = 0;

FILE *log_file = NULL;

void init_memory() {
    // Initialize record array
    records = (record_t*)calloc(MAX_RECORDS, sizeof(record_t));

    // Initialize offset array
    int* offsets = (int*)calloc(10, sizeof(int));
    offset_count = 1;

    // Initialize key array
    int* keys = (int*)calloc(MAX_KEY, sizeof(int));
    key_count = 0;

    // Initialize hash table
    hash_table = (hash_entry_t*)calloc(hash_table_size, sizeof(hash_entry_t));
}

void free_memory() {
    // Free record array
    if (records) {
        free(records);
        records = NULL;
    }

    // Free offset array
    if (offsets) {
        free(offsets);
        offsets = NULL;
    }

    // Free key array
    if (keys) {
        free(keys);
        keys = NULL;
    }

    // Free hash table
    if (hash_table) {
        free(hash_table);
        hash_table = NULL;
    }
}

void log_error(const char* message) {
    fprintf(log_file, "Error: %s\n", message);
}

int validate_records() {
    int i;
    for (i = 0; i < record_count; i++) {
        if (!records[i].value || !records[i].timestamp) {
            return -1; // Invalid record
        }
    }
    return 1; // All records valid
}
