            case 3:
                // Remove element by RNTI
                int rnti_to_remove;
                scanf("%d", &rnti_to_remove);

                if (rnti_hash[rnti_to_remove] == -1) {
                    printf("RNTI value not found in the list.\n");
                    break;
                }

                NFAPI_CRC_INDICATION_PDU_T *element_to_remove = (*list)[rnti_hash[rnti_to_remove]];
                // Update list and hash table...

