    for (i = 0; i < num_records; i++) {
        records[i].offset = json_object_get_int(config_json, "offsets");
        records[i].key = json_object_get_int(config_json, "keys");
        records[i].temperature = json_object_get_double(config_json, "temperatures");
        records[i].identifier = strdup(json_object_get_string(config_json, "identifiers"));
    }

    // Clean up
    if (config_json) {
        json_object_put(config_json);
    }
    return records;
}

void unload_config(record_t* records, int num_records) {
    int i;

    for (i = 0; i < num_records; i++) {
        free(records[i].identifier);
    }

    free(records);
