// Function to manage memory for three distinct data structures
record** manage_memory(int num_records) {
    // Allocate memory for the arrays
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    record* records = (record*)malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        // Handle memory allocation failure
        printf("Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize the arrays
    for (int i = 0; i < num_records; i++) {
        offsets[i] = i * sizeof(record);
        keys[i] = i;
        records[i].key = keys[i];
        records[i].offset = offsets[i];
        records[i].data = rand() % 100 + 1;
    }

    // Allocate memory for the metadata structure
    struct metadata {
        int num_records;
        long* offset_ptr;
        int* key_ptr;
        record** record_ptr;
    } *metadata = (struct metadata*)malloc(sizeof(struct metadata));

    if (!metadata) {
        printf("Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize the metadata
    metadata->num_records = num_records;
    metadata->offset_ptr = offsets;
    metadata->key_ptr = keys;
    metadata->record_ptr = &records;

    return &metadata;
}
