#include <pthread.h>
#include <time.h>

// Define a structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    // Include RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    int rx_ue_info;
    unsigned char rnti;
    int crc_ind_rel8;
    int crcflag;  // Randomly set CRCFLAG
} NFAPI_CRC_INDICATION_PDU_T;

// Define a structure for the dynamic list of NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t size;
    pthread_mutex_t mutex;  // Mutex for thread-safe operations
} NFAPI_CRC_INDICATION_LIST_T;

// Initialize and return a pointer to the empty dynamic list
NFAPI_CRC_INDICATION_LIST_T* nfa_pi_crc_indication_list_init() {
    NFAPI_CRC_INDICATION_LIST_T* list = (NFAPI_CRC_INDICATION_LIST_T*)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        return NULL;  // Handle memory allocation failure
    }
    list->elements = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Insert a new element into the dynamic list
int nfa_pi_crc_indication_list_insert(NFAPI_CRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list->mutex);

    // Handle memory allocation failure
    if (!element) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    size_t new_size = list->size + 1;
    NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_size);
    if (!new_elements) {
        pthread_mutex_unlock(&list->mutex);
        return -1;  // Handle memory allocation failure
    }
    list->elements = new_elements;
    list->size = new_size;

    list->elements[list->size - 1] = *element;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Delete an element from the dynamic list by its index
int nfa_pi_crc_indication_list_delete(NFAPI_CRC_INDICATION_LIST_T* list, size_t index) {
    pthread_mutex_lock(&list->mutex);

    if (index >= list->size) {
        pthread_mutex_unlock(&list->mutex);
        return -1;  // Index out of bounds
    }

    for (size_t i = index; i < list->size - 1; i++) {
        list->elements[i] = list->elements[i + 1];
    }
    free(list->elements[list->size - 1]);  // Free the deleted element

    list->size--;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Log performance metrics and memory usage
void nfa_pi_crc_indication_list_log_metrics(NFAPI_CRC_INDICATION_LIST_T* list) {
    // Integrate with an external logging service
    printf("Memory Usage: %zu bytes\n", list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    printf("CPU Load: %f%%\n", (double)getrusage().ru_utime.tv_sec / 100.0);
}

// Periodic cleanup of unused elements in the background
void* nfa_pi_crc_indication_list_cleanup(void* arg) {
    NFAPI_CRC_INDICATION_LIST_T* list = (NFAPI_CRC_INDICATION_LIST_T*)arg;

    while (1) {
        pthread_mutex_lock(&list->mutex);

        // Find and delete unused elements
        for (size_t i = 0; i < list->size; i++) {
            if (!list->elements[i].crcflag) {  // Unused element
                free(list->elements[i]);
                break;
            }
        }

        pthread_mutex_unlock(&list->mutex);
        sleep(5);  // Periodically clean up every 5 seconds
    }
}

int main() {
    NFAPI_CRC_INDICATION_LIST_T* list = nfa_pi_crc_indication_list_init();
    pthread_t cleanup_thread;

    pthread_create(&cleanup_thread, NULL, nfa_pi_crc_indication_list_cleanup, (void*)list);

    // Example usage: Insert and delete elements
    NFAPI_CRC_INDICATION_PDU_T element1;
    // ...
    nfa_pi_crc_indication_list_insert(list, &element1);
    // ...

    pthread_join(cleanup_thread, NULL);

    return 0;
}
