#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SIZE 1000000 // in bytes
#define MAX_RECORDS 10000
#define RANDOM_RANGE 100

typedef struct {
    int value;
} record_t;

record_t* allocate_records(int num_records) {
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    if (!records) {
        return NULL;
    }
    for (int i = 0; i < num_records; i++) {
        int random_value = rand() % RANDOM_RANGE;
        // Ensure no two consecutive records have the same value
        while (i > 0 && records[i-1].value == random_value) {
            random_value = rand() % RANDOM_RANGE;
        }
        records[i].value = random_value;
    }
    return records;
}

int main() {
    int num_keys, max_size;
    printf("Enter the number of keys: ");
    scanf("%d", &num_keys);
    printf("Enter the maximum size (in bytes): ");
    scanf("%d", &max_size);

    if (max_size > MAX_SIZE) {
        printf("Error: Maximum size exceeded.\n");
        return 1;
    }

    long* offset_values = NULL;
    int* keys = NULL;

    for (int i = 0; i < num_keys; i++) {
        // Allocate memory for key array
        int new_size = i * sizeof(int) + max_size;
        int* temp_keys = realloc(keys, new_size);
        if (!temp_keys) {
            free(offset_values);
            return 1;
        }
        keys = temp_keys;

        // Allocate memory for offset values array
        long* temp_offset_values = realloc(offset_values, (i+1) * sizeof(long));
        if (!temp_offset_values) {
            free(keys);
            return 1;
        }
        offset_values = temp_offset_values;
    }

    srand(time(NULL)); // Initialize random seed

    record_t* records = allocate_records(num_keys);

    // Free allocated memory
    free(records);
    free(offset_values);
    free(keys);

    return 0;
}
