    NR_UE_MEASUREMENT_RECORD* new_record = (NR_UE_MEASUREMENT_RECORD*)malloc(sizeof(NR_UE_MEASUREMENT_RECORD));
    if (!new_record) return -1; // Handle allocation failure

    new_record->rx_ue_info_tag = ...; // Initialize RX_UE_INFORMATION_TAG
    new_record->RNTI = RNTI;
    new_record->measurement_type_tag = measurement_type_tag;

    NRListNode* node = (NRListNode*)malloc(sizeof(NRListNode));
    if (!node) return -1; // Handle allocation failure

    node->record = new_record;
