typedef enum {
    UNIQUE_SUCCESS,
    UNIQUE_FAILURE,
    RESOURCE_ERROR
} UniqueStatus;

UniqueStatus unique_filename(char *filename, char **new_filename);

int main() {
    // Example usage:
    char filename[] = "path/to/old/file.txt";
    char *new_filename;
    int status = unique_filename(filename, &new_filename);
    if (status == UNIQUE_SUCCESS) {
        printf("New filename: %s\n", new_filename);
    } else if (status == UNIQUE_FAILURE) {
        printf("Failed to generate a unique filename.\n");
    } else {
        printf("Resource error occurred.\n");
    }
    free(new_filename); // Don't forget to clean up!
    return 0;
}

UniqueStatus unique_filename(char *filename, char **new_filename) {
    struct stat file_stat;
    if (stat(filename, &file_stat) == -1) {
        return RESOURCE_ERROR;
    }

    size_t filename_len = strlen(filename);
    size_t dir_len = strcspn(filename, "/");

    // Ensure the directory path is not longer than 256 characters
    char *dir_path = malloc((256 - filename_len + 1) * sizeof(char));
    strncpy(dir_path, filename, (256 - filename_len) + 1);
    dir_path[256 - filename_len] = '\0';

    // Create the new filename without the directory path
    size_t new_filename_len = strlen(dir_path) + 10; // +10 for the identifier and extension
    char *new_filename_ptr = malloc(new_filename_len * sizeof(char));
    strcpy(new_filename_ptr, dir_path);

    // Derive the unique identifier from the original filename
    for (int i = 0; i < 3; i++) {
        new_filename_ptr[strlen(dir_path) + i] = toupper(filename[dirname_len + i]);
    }
    for (int i = 0; i < 3; i++) {
        new_filename_ptr[strlen(dir_path) + i + 3] = tolower(filename[dirname_len + i + 3]);
    }

    // Pad the identifier with zeros
    char *identifier = malloc(8 * sizeof(char));
    strncpy(identifier, &new_filename_ptr[strlen(dir_path)], 8);
    identifier[8] = '\0';

    if (strlen(identifier) < 8) {
        // Append random alphanumeric characters to complete the sequence
        for (int i = strlen(identifier); i < 8; i++) {
            identifier[i] = rand() % 26 + 'a';
        }
    }

    // Ensure the new filename is not longer than 256 characters
    while (strlen(new_filename_ptr) + strlen(extension) > 256) {
        if (dir_len > 0) {
            dir_path[dir_len - 1] = '\0'; // Trim the directory path
            dir_len--;
        } else {
            break; // No more trimming possible
        }
    }

    // Append the identifier and extension to the new filename
    strcat(new_filename_ptr, identifier);
    strcat(new_filename_ptr, extension);

    *new_filename = new_filename_ptr;
    return UNIQUE_SUCCESS;

    // Check if the new filename already exists
    struct stat file_stat;
    int is_unique = 1;
    while (is_unique) {
        if (stat(filename, &file_stat) == -1) {
            return UNIQUE_FAILURE; // Failed to check for uniqueness
        }
        if (file_stat.st_ino != 0) { // File already exists
            filename_len = strlen(filename);
            char *new_filename_ptr = malloc((filename_len + 10) * sizeof(char));
            strcpy(new_filename_ptr, filename);
            int i = 1;
            do {
                sprintf(&new_filename_ptr[filename_len], "_%d", i++);
                filename = new_filename_ptr;
                file_stat.st_ino = 0; // Reset the file's inode number
            } while (stat(filename, &file_stat) == -1);
        }
    }

    return UNIQUE_SUCCESS;
}
