#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int* data;
    pthread_mutex_t lock;
    int ref_count;
} Node;

Node* init_node(int value) {
    Node* node = (Node*) malloc(sizeof(Node));
    node->data = (int*) malloc(sizeof(int));
    *node->data = value;
    node->ref_count = 1;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

void free_node(Node* node) {
    if (--node->ref_count == 0) {
        free(node->data);
        free(node);
    }
}

Node** init_array(size_t initial_size) {
    Node** array = (Node**) calloc(initial_size, sizeof(Node*));
    return array;
}

void add_node(Node** array, size_t capacity, Node* node) {
    if (array[0] == NULL) {
        // Initialize the first element
        array[0] = node;
    } else {
        for (size_t i = 0; i < capacity; i++) {
            if (array[i] == NULL) {
                array[i] = node;
                return;
            }
        }
        // Resize the array if it's full
        array = realloc(array, sizeof(Node*) * (capacity + initial_size));
        for (size_t i = 0; i < capacity; i++) {
            if (array[i] == NULL) {
                array[i] = node;
                return;
            }
        }
    }
}

void remove_node(Node** array, size_t capacity, Node* node) {
    for (size_t i = 0; i < capacity; i++) {
        if (array[i] == node) {
            array[i] = NULL;
            return;
        }
    }
}

void increment_ref_count(Node* node) {
    pthread_mutex_lock(&node->lock);
    node->ref_count++;
    pthread_mutex_unlock(&node->lock);
}

void decrement_ref_count(Node* node) {
    pthread_mutex_lock(&node->lock);
    node->ref_count--;
    pthread_mutex_unlock(&node->lock);
}
