```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* manage_array(void* arg) {
    int* num_elements = (int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        pthread_exit(NULL);
    }

    srand(time(NULL));  // seed the random number generator

    for (int i = 0; i < *num_elements; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100;
        array[i].RNTI = rand() % 100;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        array[i].CRCFLAG = (rand() % 2) ? 1 : 0;  // randomly set CRCFLAG
    }

    free(array);
    pthread_exit(NULL);
}

int main(int argc, char* argv[]) {
    int N = atoi(argv[1]);  // get the number of elements from command line argument

    pthread_t threads[N];

    for (int i = 0; i < N; i++) {
        int* num_elements = &N;
        pthread_create(&threads[i], NULL, manage_array, (void*)num_elements);
    }

    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
