#define MAX_STRUCTURES_PER_THREAD 100
#define TOTAL_MAX_STRUCTURES 10000
#define FILE_NAME "log.txt"

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file;

NFAPI_CRC_INDICATION_PDU_T** structures;

void* manage_structures(void* arg) {
    int batch_size = *(int*)arg;
    int num_structures_allocated = 0;

    for (int i = 0; i < batch_size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (structure == NULL) {
            // Handle memory allocation error
            fprintf(log_file, "Memory allocation failed for batch size %d.\n", batch_size);
            exit(1);
        }

        structure->RX_UE_INFORMATION_TAG = rand();
        structure->RNTI = rand();
        structure->CRC_INDICATION_REL8_TAG = rand();
        structure->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        pthread_mutex_lock(&mutex);
        {
            if (num_structures_allocated + batch_size > TOTAL_MAX_STRUCTURES) {
                // Handle total structures exceeded limit
                fprintf(log_file, "Total number of structures (%d) exceeds the allowed limit.\n", num_structures_allocated + batch_size);
                exit(1);
            }

            for (int j = 0; j < batch_size; j++) {
                if (num_structures_allocated >= MAX_STRUCTURES_PER_THREAD) {
                    // Handle structures per thread exceeded limit
                    fprintf(log_file, "Structures per thread (%d) exceeds the allowed limit.\n", num_structures_allocated);
                    exit(1);
                }

                structures[num_structures_allocated][j] = structure;
                num_structures_allocated++;
            }
        }
        pthread_mutex_unlock(&mutex);
    }

    free(structure); // Free allocated memory
}

int main() {
    log_file = fopen(FILE_NAME, "a");

    if (log_file == NULL) {
        // Handle file opening error
        fprintf(stderr, "Error opening log file.\n");
        exit(1);
    }

    pthread_t threads[10]; // Initialize 10 threads for testing

    for (int i = 0; i < 10; i++) {
        int batch_size = rand() % 101; // Randomly set batch size
        *(int*)(&batch_size) = batch_size;

        pthread_create(&threads[i], NULL, manage_structures, &batch_size);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL); // Wait for threads to finish
    }

    fclose(log_file);

    return 0;
}

