// Function to initialize and return a new custom hash table with a given size
CUSTOM_HASH_TABLE* create_hash_table(int size) {
    CUSTOM_HASH_TABLE* hash_table = (CUSTOM_HASH_TABLE*)malloc(sizeof(CUSTOM_HASH_TABLE));
    hash_table->size = size;
    hash_table->num_entries = 0;
    hash_table->table = (LTE_UPLINK_NAS_TRANSPORT**)calloc(size, sizeof(LTE_UPLINK_NAS_TRANSPORT*));
    pthread_mutex_init(&hash_table->lock, NULL);
    return hash_table;
}

// Function to insert an LTE_UPLINK_NAS_TRANSPORT structure into the hash table
void insert_into_hash_table(CUSTOM_HASH_TABLE* hash_table, LTE_UPLINK_NAS_TRANSPORT* entry) {
    int index = entry->ue_identity % hash_table->size;
    pthread_mutex_lock(&hash_table->lock);
    if (hash_table->table[index] == NULL) {
        hash_table->table[index] = entry;
        hash_table->num_entries++;
    } else {
        // Rebalance the hash table when it becomes imbalanced
        rebalance_hash_table(hash_table);
    }
    pthread_mutex_unlock(&hash_table->lock);
}

// Function to remove an LTE_UPLINK_NAS_TRANSPORT structure from the hash table
void remove_from_hash_table(CUSTOM_HASH_TABLE* hash_table, LTE_UPLINK_NAS_TRANSPORT* entry) {
    int index = entry->ue_identity % hash_table->size;
    pthread_mutex_lock(&hash_table->lock);
    if (hash_table->table[index] == entry) {
        hash_table->table[index] = NULL;
        hash_table->num_entries--;
    }
    pthread_mutex_unlock(&hash_table->lock);
}

// Function to rebalance the hash table when it becomes imbalanced
void rebalance_hash_table(CUSTOM_HASH_TABLE* hash_table) {
    // Implement rebalancing strategy here
    printf("Rebalancing hash table...\n");
}

// Function to free memory allocated for the custom hash table
void destroy_hash_table(CUSTOM_HASH_TABLE* hash_table) {
    pthread_mutex_lock(&hash_table->lock);
    for (int i = 0; i < hash_table->size; i++) {
        if (hash_table->table[i] != NULL) {
            free(hash_table->table[i]);
        }
    }
    free(hash_table->table);
    free(hash_table);
    pthread_mutex_unlock(&hash_table->lock);
}

