        // fields of each NFAPI_CRC_INDICATION_PDU_T structure...

        pdu->CRCFLAG = (rand() % 2) ? 0x01 : 0x00; // Randomly set CRCFLAG with no adjacent duplicates
        crcflag_sum ^= pdu->CRCFLAG;

        if (!list) {
            list = pdu;
        } else {
            list = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (i + 1));
            if (!list) {
                printf("Error: Could not reallocate memory for structure %u.\n", i);
                while (--i >= 0) {
                    free(list[i]);
                }
                free(list);
                return NULL;
            }
            list[i] = pdu;
        }
    }

    // Perform integrity checks
    if (list && crcflag_sum != 0) {
        printf("Error: CRCFLAG checksum mismatch.\n");
        while (i-- > 0) {
            free(list[i]);
        }
        free(list);
        return NULL;
    }

    return list;
