#define MAX_LOGS 1000 // max number of log entries in the list
#define LOG_EVENT_RECORD_SIZE sizeof(struct LogEventRecord)

struct LogEventRecord {
    int64_t log_id;
    time_t log_timestamp;
    char *log_message; // dynamically allocated memory for message
};

// dynamically allocated list of log event records
typedef struct {
    struct LogEventRecord **logs;
    pthread_mutex_t lock;
    int num_logs;
} LogList;

// function to manage the log list
LogList* init_log_list() {
    LogList *log_list = (LogList*)malloc(sizeof(LogList));
    log_list->logs = (struct LogEventRecord**)calloc(MAX_LOGS, sizeof(struct LogEventRecord*));
    pthread_mutex_init(&log_list->lock, NULL);
    log_list->num_logs = 0;
    return log_list;
}

// add a new log event to the list
void add_log_event(LogList *log_list, struct LogEventRecord *event) {
    pthread_mutex_lock(&log_list->lock);

    // check if the list is full
    if (log_list->num_logs >= MAX_LOGS) {
        // reallocate memory for more log events
        log_list->logs = realloc(log_list->logs, (MAX_LOGS + 100) * sizeof(struct LogEventRecord*));
    }

    // add the new event to the list
    log_list->logs[log_list->num_logs] = event;
    log_list->num_logs++;

    pthread_mutex_unlock(&log_list->lock);
}

// print all logs in the list
void print_logs(LogList *log_list) {
    pthread_mutex_lock(&log_list->lock);

    for (int i = 0; i < log_list->num_logs; i++) {
        printf("Log ID: %ld, Timestamp: %ld, Message: %s\n",
               log_list->logs[i]->log_id, log_list->logs[i]->log_timestamp,
               log_list->logs[i]->log_message);
    }

    pthread_mutex_unlock(&log_list->lock);
}

int main() {
    LogList *log_list = init_log_list();

    // add some log events
    struct LogEventRecord event1;
    event1.log_id = 1;
    event1.log_timestamp = time(NULL);
    event1.log_message = (char*)malloc(50); // dynamically allocate memory for message
    strcpy(event1.log_message, "This is the first log entry");
    add_log_event(log_list, &event1);

    struct LogEventRecord event2;
    event2.log_id = 2;
    event2.log_timestamp = time(NULL);
    event2.log_message = (char*)malloc(50); // dynamically allocate memory for message
    strcpy(event2.log_message, "This is the second log entry");
    add_log_event(log_list, &event2);

    // print all logs in the list
    print_logs(log_list);

    return 0;
}
```

The code provided includes:

- `LogList` structure to manage a dynamically allocated list of `LOG_EVENT_RECORD` structures.
- `init_log_list()` function to initialize a new log list.
- `add_log_event()` function to add a new log event to the list.
- `print_logs()` function to print all logs in the list.

In this code, we use a mutex to lock and unlock the log list when adding or printing events.']

