#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define a struct to represent products
typedef struct {
    char* name;
    int quantity;
    float price;
} Product;

// Function to manage memory for an array of product structures
Product** manageMemory(int initialCapacity) {
    // Allocate memory for the array of pointers
    Product** products = (Product**)malloc(initialCapacity * sizeof(Product*));

    // Initialize the first element with a null pointer
    products[0] = NULL;

    return products;
}

// Function to resize the dynamic array of product structures
void resizeArray(Product** products, int newSize) {
    // Allocate new memory for the array
    Product** newProducts = (Product**)realloc(products, newSize * sizeof(Product*));

    // If allocation fails, handle error and exit
    if (!newProducts) {
        printf("Memory allocation failed. Exiting.\n");
        return;
    }

    // Initialize the first element with a null pointer
    newProducts[0] = NULL;

    // Update the products array to point to the newly allocated memory
    products = newProducts;
}

// Function to sort products based on quantity in ascending order and secondary criterion (price)
void sortProducts(Product** products, int size) {
    // Use a stable sorting algorithm like radix sort or timsort
    qsort(products, size, sizeof(Product*), compareProducts);
}

int compareProducts(const void* p1, const void* p2) {
    Product* product1 = *(Product**)p1;
    Product* product2 = *(Product**)p2;

    // Sort based on quantity in ascending order
    if (product1->quantity < product2->quantity) return -1;
    if (product1->quantity > product2->quantity) return 1;

    // If quantities are equal, sort based on price
    if (product1->price < product2->price) return -1;
    if (product1->price > product2->price) return 1;

    return 0;
}

// Function to update the price of all products by a given percentage
void updatePrices(Product** products, int size, float percentage) {
    // Iterate through the array and update prices
    for (int i = 0; i < size; i++) {
        Product* product = products[i];
        product->price *= (1 + percentage);
    }
}

// Function to free memory allocated for the dynamic array of product structures
void freeMemory(Product** products, int size) {
    // Free individual products
    for (int i = 0; i < size; i++) {
        Product* product = products[i];
        if (product->name) free(product->name);
        free(product);
    }

    // Free the array of pointers
    free(products);
}
