#include <stdlib.h>
#include <stdio.h>

struct record {
    char *buffer;
    int key;
    long offset;
    bool valid;
};

int manageMemory(int numRecords) {
    if (numRecords <= 0) {
        return -1; // Invalid input: number of records must be positive
    }

    int *keys = malloc(sizeof(int) * (numRecords + 1));
    long *offsets = malloc(sizeof(long) * (numRecords + 1));

    if (!keys || !offsets) {
        free(keys);
        free(offsets);
        return -2; // Memory allocation failed
    }

    for (int i = 0; i <= numRecords; i++) {
        keys[i] = i % 256; // Fill key array with ASCII values
    }

    for (int i = 0; i <= numRecords; i++) {
        offsets[i] = i * 1024; // Fill offset array with increments of 1024
    }

    struct record *records = malloc(sizeof(struct record) * numRecords);

    if (!records) {
        free(keys);
        free(offsets);
        return -3; // Memory allocation failed
    }

    for (int i = 0; i < numRecords; i++) {
        records[i].buffer = malloc(1024); // Allocate buffers
        records[i].key = keys[i];
        records[i].offset = offsets[i];
        records[i].valid = true;
    }

    free(keys);
    free(offsets);

    return 0; // Successful memory management
}
