#define LOG_INTERVAL 10 // seconds
#define MEMORY_POOL_SIZE 65536

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    uint16_t RNTI;
    MEASUREMENT_RESULT_REL16_TAG measurement_result;
} NR_UeMeasurementReportT;

void *memory_pool = NULL;
size_t memory_pool_size = 0;

void init_memory_pool() {
    memory_pool = malloc(MEMORY_POOL_SIZE);
    memory_pool_size = MEMORY_POOL_SIZE;
}

void *allocate_from_memory_pool(size_t size) {
    if (memory_pool_size < size) {
        // Out of memory, handle gracefully
        return NULL;
    }
    void *ptr = memory_pool;
    memory_pool = (char *)memory_pool + size;
    memory_pool_size -= size;
    return ptr;
}

void deallocate_from_memory_pool(void *ptr, size_t size) {
    if (!ptr)
        return; // Nothing to deallocate
    memory_pool = (char *)ptr - size;
    memory_pool_size += size;
}

int process_reports(int rate) {
    NR_UeMeasurementReportT *reports = NULL;
    int num_reports = 0;

    while ((num_reports < rate || reports) && (reports = (NR_UeMeasurementReportT *)allocate_from_memory_pool(sizeof(NR_UeMeasurementReportT))) != NULL) {
        // Initialize report structure
        reports->rx_ue_info.tag = RX_UE_INFORMATION_TAG_INITIALIZER;
        reports->RNTI = 0;
        reports->measurement_result.tag = MEASUREMENT_RESULT_REL16_TAG_INITIALIZER;

        num_reports++;
    }

    if (num_reports >= REPORT_PROCESSING_THRESHOLD) {
        // Log and trigger alert for network congestion
        printf("Reports processed: %d\n", num_reports);
    } else {
        printf("Reports processed: %d within threshold\n", num_reports);
    }

    time_t end_time = time(NULL);
    int elapsed_seconds = (int)(time(NULL) - end_time);
    if (elapsed_seconds >= LOG_INTERVAL) {
        // Log and reset timer
        printf("Elapsed seconds: %d, Reports processed per second: %f\n",
               (int)(time(NULL) - end_time),
               (float)num_reports / elapsed_seconds);

        end_time = time(NULL);
        elapsed_seconds = 0;
    }

    deallocate_from_memory_pool(reports, sizeof(NR_UeMeasurementReportT) * num_reports);

    return num_reports;
}
