product** manageProductArray(int* size, product*** arr) {
    if (*size == 0) {
        *arr = malloc(sizeof(product*));
        if (!(*arr)) {
            printf("Memory allocation failed\n");
            return NULL;
        }
        return *arr;
    }

    int newSize = *size * 2;
    product** newArr = realloc(*arr, sizeof(product*) * newSize);
    if (!newArr) {
        printf("Memory reallocation failed\n");
        return NULL;
    }
    *arr = newArr;
    *size = newSize;
    return *arr;
}

void addProduct(int* size, product*** arr, const char* name, int quantity, float price) {
    (*arr)[*size] = (product){malloc(strlen(name) + 1), quantity, price};
    strcpy((*arr)[*size]->name, name);
    (*size)++;
    manageProductArray(size, arr);
}

void sortProducts(product** arr, int size) {
    qsort(arr, size, sizeof(product*), compareProductsByQuantity);
}

int compareProductsByQuantity(const void* a, const void* b) {
    product* prodA = *(product**)a;
    product* prodB = *(product**)b;
    if (prodA->quantity < prodB->quantity)
        return -1;
    else if (prodA->quantity > prodB->quantity)
        return 1;
    return 0;
}

void freeProductArray(int size, product** arr) {
    for (int i = 0; i < size; i++) {
        free(arr[i]->name);
        free(arr[i]);
    }
    free(arr);
}
