typedef struct {
    char* name;
    int quantity;
    float price;
} product_t;

product_t* products = NULL;
int product_count = 0;
int cache_index = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int cached_products = 0;

void* cache[CACHE_SIZE];
int cache_timestamps[CACHE_SIZE];

void sort_products(int (*compare)(const void*, const void*)) {
    qsort(products, product_count, sizeof(product_t), compare);
}

int name_compare(const void* a, const void* b) {
    product_t* prod1 = (product_t*)a;
    product_t* prod2 = (product_t*)b;
    return strcmp(prod1->name, prod2->name);
}

int quantity_price_compare(const void* a, const void* b) {
    product_t* prod1 = (product_t*)a;
    product_t* prod2 = (product_t*)b;
    if (prod1->quantity == prod2->quantity)
        return (int)((prod1->price - prod2->price) * 1000000);
    else
        return prod1->quantity - prod2->quantity;
}

void update_prices(float percentage) {
    for (int i = 0; i < product_count; i++) {
        product_t* prod = &products[i];
        pthread_mutex_lock(&lock);
        float new_price = prod->price + (prod->price * percentage / 100);
        pthread_mutex_unlock(&lock);
    }
}

void* thread_function(void* arg) {
    int tid = *(int*)arg;
    for (int i = tid; i < product_count; i += CACHE_SIZE) {
        product_t* prod = &products[i];
        pthread_mutex_lock(&lock);
        if (!cached_products || cache_timestamps[cached_products] != tid) {
            // Update cache
            cache[cached_products] = malloc(sizeof(product_t));
            strcpy(cache[cached_products]->name, prod->name);
            cache[cached_products]->quantity = prod->quantity;
            cache[cached_products]->price = prod->price;
            cache_timestamps[cached_products] = tid;
            cached_products++;
        }
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

int main() {
    // Initialize products array
    products = (product_t*)malloc(MAX_PRODUCTS * sizeof(product_t));
    product_count = 0;

    // Create threads for caching
    int thread_count = (product_count + CACHE_SIZE - 1) / CACHE_SIZE;
    pthread_t threads[thread_count];
    for (int i = 0; i < thread_count; i++) {
        int* tid = malloc(sizeof(int));
        *tid = i;
        pthread_create(&threads[i], NULL, thread_function, tid);
    }
    // ... Handle threads

    return 0;
}
