import json
from flask import Flask, request, jsonify
from flask_caching import Cache

app = Flask(__name__)
cache = Cache(app, config={'CACHE_TYPE': 'SimpleCache'})

# Versioning mechanism using timestamps
version_counter = 0
versions = {}

@app.before_request
def versioning():
    global version_counter
    if not request.json:
        return jsonify({'message': 'No JSON payload provided'}), 400

    request_json = json.loads(request.get_data())
    version_id = f'V{str(version_counter)}'
    versions[version_id] = {'timestamp': str(version_counter)}
    version_counter += 1
    request.version_id = version_id

@app.route('/resources/<resource_id>', methods=['PUT'])
def update_resource(resource_id):
    if not cache.get(f'resource:{resource_id}'):
        return jsonify({'message': 'Resource not found'}), 404

    cached_resource = cache.get(f'resource:{resource_id}')
    updated_resource = request_json['data']

    # Handle partial updates
    if 'partial' in request_json:
        updated_resource.update(request_json['partial'])

    # Ensure version consistency and prevent race conditions
    if versions[request.version_id]['timestamp'] != str(versions.get(resource_id, 0)):
        return jsonify({'message': 'Version mismatch'}), 409

    # Update the resource and cache
    updated_resource['version'] = request.version_id
    cache.set(f'resource:{resource_id}', updated_resource)
    return jsonify(updated_resource), 200

@app.route('/resources/<resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    if not cache.get(f'resource:{resource_id}'):
        return jsonify({'message': 'Resource not found'}), 404

    cached_resource = cache.get(f'resource:{resource_id}')
    associated_entities = ['entity1', 'entity2']  # Example entities to clean up
    for entity in associated_entities:
        if cache.get(f'{entity}:{resource_id}'):
            cache.delete(f'{entity}:{resource_id}')

    # Logging mechanism
    app.logger.info(f'Resource {resource_id} deleted')

    return jsonify({'message': 'Resource deleted'}), 200

@app.errorhandler(400)
def invalid_request(e):
    return jsonify({'error': 'Invalid request'}), 400

if __name__ == '__main__':
    app.run(debug=True, use_reloader=True)
```"]

