#define HASH_SIZE 16
#define LIST_CAPACITY 1000

typedef struct {
    int id;
    char pdu[256];
} LTE_UPLINK_NAS_TRANSPORT;

typedef struct {
    LTE_UPLINK_NAS_TRANSPORT* data;
    pthread_mutex_t mutex;
} HashEntry;

HashEntry hash_table[HASH_SIZE];

void init_hash_table() {
    for (int i = 0; i < HASH_SIZE; i++) {
        hash_table[i].data = NULL;
        pthread_mutex_init(&hash_table[i].mutex, NULL);
    }
}

void add_ue_to_hash(int id, char* pdu) {
    int index = id % HASH_SIZE;
    HashEntry* entry = &hash_table[index];
    LTE_UPLINK_NAS_TRANSPORT new_entry;

    // Create a new entry and set its data
    new_entry.id = id;
    strcpy(new_entry.pdu, pdu);

    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&entry->mutex);
    if (entry->data == NULL) {
        entry->data = &new_entry;
    } else {
        // If the slot is already occupied, resize the hash table and rehash the UE identity
        if (rehash_needed(id)) {
            int new_hash_size = 2 * HASH_SIZE;
            HashEntry* new_table = (HashEntry*)malloc(new_hash_size * sizeof(HashEntry));
            for (int i = 0; i < HASH_SIZE; i++) {
                if (hash_table[i].data != NULL) {
                    // Rehash the UE identity and add it to the new table
                    int new_index = hash_function(id, new_hash_size);
                    new_table[new_index].data = &new_entry;
                }
            }
            free(hash_table);
            hash_table = new_table;
        } else {
            // The slot is not occupied, so just insert the new entry
            if (entry->data != NULL) {
                // If there are multiple UEs with the same identity, detect and handle this situation
                int collision_count = 0;
                for (int i = 0; i < HASH_SIZE; i++) {
                    if (hash_table[i].data && hash_function(id, HASH_SIZE) == i) {
                        collision_count++;
                    }
                }
                if (collision_count > 1) {
                    // Handle the collision
                    // ...
                }
            } else {
                entry->data = &new_entry;
            }
        }
    }

    pthread_mutex_unlock(&entry->mutex);
}

int main() {
    init_hash_table();
    add_ue_to_hash(123, "some_pdu");
    return 0;
}
