CellStatusRecord* insert_record(int cell_id, int pci, float channel_quality_indicator) {
    pthread_mutex_lock(&lock);

    if (list_length >= NR_CELL_STATUS_RECORD) {
        printf("Dynamic list is full. Cannot insert more records.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    CellStatusRecord* new_record = (CellStatusRecord*)malloc(sizeof(CellStatusRecord));
    if (!new_record) {
        printf("Memory allocation failed. Cannot insert record.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    new_record->CELL_ID = cell_id;
    new_record->PCI = pci;
    new_record->CHANNEL_QUALITY_INDICATOR = channel_quality_indicator;

    if (list_length > 0) {
        CellStatusRecord* current_record = (CellStatusRecord*)dynamic_list;
        for (int i = 0; i < list_length; i++) {
            dynamic_list += sizeof(CellStatusRecord);
        }
        *dynamic_list = *new_record;
    } else {
        dynamic_list = new_record;
    }

    list_length++;
    pthread_mutex_unlock(&lock);

    return new_record;
}

void remove_record(int cell_id) {
    pthread_mutex_lock(&lock);

    if (list_length == 0) {
        printf("Dynamic list is empty. Cannot remove records.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    CellStatusRecord* current_record = (CellStatusRecord*)dynamic_list;
    for (int i = 0; i < list_length; i++) {
        if (current_record->CELL_ID == cell_id) {
            dynamic_list += sizeof(CellStatusRecord);
            free(current_record);
            list_length--;
            break;
        }
        dynamic_list += sizeof(CellStatusRecord);
        current_record = dynamic_list;
    }

    pthread_mutex_unlock(&lock);
}

void check_channel_quality() {
