        strcpy(records[i].description, "");
    }
}

void start_service() {
    // Simulate service start
    printf("Service started.\n");
    sleep(rand() % 5 + 1);
}

void stop_service(int service_id) {
    // Simulate service stop and send message to messaging system
    printf("Stopping service ID %d...\n", service_id);
    sleep(rand() % 5 + 1);

    FILE *fp = fopen("/dev/messaging_system", "w");
    if (fp) {
        fprintf(fp, "Service stopped: ID %d, timestamp: %ld\n", service_id, time(NULL));
        fclose(fp);
    }
}

void add_record(int key, char *description) {
    // Add record to the end of the array
    record new_rec;
    new_rec.key = key;
    strcpy(new_rec.description, description);

    records = (record *)realloc(records, sizeof(record) * (RECORDS + 1));
    offsets = (long *)realloc(offsets, sizeof(long) * (RECORDS + 1));
    keys = (int *)realloc(keys, sizeof(int) * (RECORDS + 1));

    int idx = RECORDS++;
    records[idx].key = key;
    strcpy(records[idx].description, description);
}

record *get_record_by_key(int key) {
    for (int i = 0; i < RECORDS; i++) {
        if (records[i].key == key) {
            return &records[i];
        }
    }
    return NULL;
}

void update_record(int key, char *new_description) {
    // Find record by key and update description
    record *rec = get_record_by_key(key);
    if (rec) {
        strcpy(rec->description, new_description);
    }
}

int main() {
    initialize_system(RECORDS);
    start_service();

    for (int i = 0; i < 10; i++) {
        add_record(rand() % KEY_RANGE, "New record");
    }

    stop_service(1);

    update_record(5, "Updated description");

    return 0;
}
