#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    int sourceID;
    int destinationID;
    char* payload;
} DataPacket;

typedef struct {
    DataPacket* head;
    DataPacket* tail;
    pthread_mutex_t mutex;
} PacketList;

void packet_list_init(PacketList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

DataPacket* packet_list_insert(PacketList* list, int timestamp, int sourceID, int destinationID, char* payload) {
    DataPacket* new_packet = (DataPacket*)malloc(sizeof(DataPacket));
    new_packet->timestamp = timestamp;
    new_packet->sourceID = sourceID;
    new_packet->destinationID = destinationID;
    new_packet->payload = payload;

    if(list->head == NULL) {
        list->head = new_packet;
        list->tail = new_packet;
    } else {
        new_packet->next = list->head;
        list->head = new_packet;
    }

    return new_packet;
}

DataPacket* packet_list_get(PacketList* list, int sourceID) {
    pthread_mutex_lock(&list->mutex);
    DataPacket* current = list->head;
    while(current != NULL && current->sourceID != sourceID) {
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);

    return current;
}

void packet_list_remove(PacketList* list, int destinationID) {
    pthread_mutex_lock(&list->mutex);
    DataPacket* current = list->head;
    DataPacket* previous = NULL;

    while(current != NULL && current->destinationID != destinationID) {
        previous = current;
        current = current->next;
    }

    if(current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    if(previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);

    if(list->tail == current) {
        list->tail = previous;
    }

    pthread_mutex_unlock(&list->mutex);
}

void packet_list_free(PacketList* list) {
    pthread_mutex_lock(&list->mutex);
    DataPacket* current = list->head;

    while(current != NULL) {
        DataPacket* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->mutex);

    packet_list_init(list);
}
