    if (n > MAX_ALLOCATED_STRUCTURES) {
        // Error: Too many structures to allocate
        return NULL;
    }

    if ((ptr = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T))) == NULL) {
        // Memory allocation failed
        free(ptr);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* p = (NFAPI_CRC_INDICATION_PDU_T*) ptr;

    for (int i = 0; i < n; i++) {
