            p[i].metadata.source_identifier = getSourceIdentifier();
        }
    }

    if (compress) {
        // Compress the allocated structures
        uint8_t* compressed_data = NULL;
        int compression_level = Z_DEFAULT_COMPRESSION;
        int compress_result = compressData((char*) ptr, n * sizeof(NFAPI_CRC_INDICATION_PDU_T), &compressed_data, compression_level);
        if (compress_result != Z_OK) {
            // Compression failed
            free(ptr);
            return NULL;
        }
    }

    if (log_enabled && n > MIN_LOGGING_THRESHOLD) {
        // Log the allocation operation
        logAllocateStructures(n);
    }

    return ptr;
}

void nfaapi_crc_indication_pdu_free(void* ptr, int compress) {
    if (ptr == NULL) {
        return;
    }

    if (compress) {
        // Decompress and free the allocated structures
        uint8_t* decompressed_data = malloc((int) strlen((char*) ptr));
        int decompression_result = decompressData((char*) ptr, &decompressed_data);
        if (decompression_result != Z_OK) {
            // Decompression failed
            return;
        }
    }

    free(ptr);
}
