void allocate_and_init_memory(long numOffsets, int numKeys, long memoryBudget, int minValue, int maxValue, const char* dataSource) {
    // Allocate memory for offset and key arrays
    size_t totalBytes = (numOffsets + numKeys) * sizeof(int);
    size_t remainingMemory = memoryBudget - totalBytes;

    if(remainingMemory < 0) {
        // Reduce array sizes to fit within budget
        int reducedNumOffsets = (int)((float)numOffsets / ((float)memoryBudget / totalBytes));
        int reducedNumKeys = numKeys - (reducedNumOffsets * 2);

        // Reallocate memory with reduced sizes
        long* offsets = (long*)malloc(reducedNumOffsets * sizeof(long));
        int* keys = (int*)malloc((reducedNumKeys + numOffsets) * sizeof(int));

        // Initialize offset values and keys
        for(int i = 0; i < reducedNumOffsets; i++) {
            offsets[i] = rand() % (maxValue - minValue + 1) + minValue;
        }
        for(int i = 0; i < reducedNumKeys; i++) {
            if(i >= numOffsets) {
                keys[i] = rand() % (maxValue - minValue + 1) + minValue;
            } else {
                keys[i] = dataSource[i];
            }
        }

        // Initialize remaining offset values and keys
        for(int i = reducedNumOffsets; i < numOffsets; i++) {
            offsets[i] = rand() % (maxValue - minValue + 1) + minValue;
        }
        for(int i = reducedNumKeys; i < numKeys; i++) {
            if(i >= numOffsets) {
                keys[i] = rand() % (maxValue - minValue + 1) + minValue;
            } else {
                keys[i] = dataSource[i];
            }
        }

    } else {
        // Allocate memory with full sizes
        long* offsets = (long*)malloc(numOffsets * sizeof(long));
        int* keys = (int*)malloc(numKeys * sizeof(int));

        // Initialize offset values and keys
        for(int i = 0; i < numOffsets; i++) {
            offsets[i] = rand() % (maxValue - minValue + 1) + minValue;
        }
        for(int i = 0; i < numKeys; i++) {
            if(i >= numOffsets) {
                keys[i] = rand() % (maxValue - minValue + 1) + minValue;
            } else {
                keys[i] = dataSource[i];
            }
        }
    }

    // Serialize initialized data structures into a binary file format
    FILE* file = fopen("data.bin", "wb");
    fwrite(offsets, sizeof(long), numOffsets, file);
    fwrite(keys, sizeof(int), numKeys, file);
    fclose(file);
}
