    // Initialize the 'int' keys array
    int* keys = malloc(sizeof(int) * numRecords);

    // Create an array of record structures and initialize their 'int' values
    record_t* records = malloc(sizeof(record_t) * numRecords);

    for (int i = 0; i < numRecords; i++) {
