char* generateUniqueIdentifier(const char* filename) {
    // Extract the first three uppercase letters and last three lowercase letters of the original filename
    char* identifier = malloc(9);
    strncpy(identifier, filename, 3);
    identifier[3] = '\0';
    for (int i = 6; i >= 3; i--) {
        identifier[i] = filename[i];
    }
    identifier[8] = '\0';

    // Pad with zeros to form an 8-character sequence
    for (int i = 3; i < 6; i++) {
        identifier[i] = '0';
    }

    // If the sequence is incomplete, complete it with random alphanumeric characters
    int len = strlen(identifier);
    char* remaining = malloc(9 - len);
    srand(time(NULL));
    for (int i = 0; i < 5 - len; i++) {
        identifier[len + i] = ((rand() % 26) + 'a');
    }
    free(remaining);

    // Append the generated identifier to the existing filename extension
    char* newFilename = malloc(strlen(filename) + 9);
    strcpy(newFilename, filename);
    strcat(newFilename, ".");
    strcat(newFilename, identifier);

    return newFilename;
}

char* ensureUniqueName(const char* directory, const char* filename) {
    // Verify the uniqueness of the new filename within the specified directory
    if (fileExists(directory, filename)) {
        int i = 1;
        do {
            // Append a numeric suffix starting from 1 and incrementing until a unique filename is created
            char* tempName = malloc(strlen(filename) + 10);
            strcpy(tempName, filename);
            strcat(tempName, "(%d)", i);
            if (!fileExists(directory, tempName)) {
                free(filename);
                return tempName;
            }
            free(tempName);
            i++;
        } while (1);
    }

    return filename;
}

