    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(minRange, maxRange);

    record* records = new record[list.size()];
    size_t* offsets = new size_t[list.size()];

    bool found = false;
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == key) {
            found = true;
            break;
        }
        ++it;
    }

    if (!found) {
        list.insert_after(list.end(), value);
    } else {
        size_t index = 0;
        it = list.begin();
        while (it != list.end()) {
            records[index].value = dis(gen);
            offsets[index] = distance(list.begin(), it);
            ++index;
            ++it;
        }

