void process_integers(int** arr, int size, int sum_threshold) {
    int max = 0;
    for (int i = 0; i < size; i++) {
        if ((*arr)[i] > max)
            max = (*arr)[i];
    }

    int non_zero_count = 0;
    for (int i = 0; i < size; i++) {
        if ((*arr)[i] != 0) 
            non_zero_count++;
    }

    int total_sum = 0;
    for (int i = 0; i < size; i++) {
        total_sum += (*arr)[i];
    }

    printf("Largest integer: %d\n", max);
    printf("Sum of integers: %d\n", total_sum);
    printf("Count of non-zero integers: %d\n", non_zero_count);
}

int main() {
    int max_size = 10000;
    int sum_threshold = 0;

    printf("Enter the maximum size of the input list (default is 10,000): ");
    scanf("%d", &max_size);

    if (max_size > 10000) {
        printf("Error: Maximum size exceeds the default limit. Using default value.\n");
        max_size = 10000;
    }

    printf("Enter the sum threshold (default is 0): ");
    scanf("%d", &sum_threshold);

    int** arr = NULL;
    int size = 0;

    while (1) {
        int num;
        if ((size >= max_size) || ((arr != NULL) && (size > 0))) {
            break;
        }

        printf("Enter an integer (or -1 to stop): ");
        scanf("%d", &num);

        if (num == -1)
            break;

        size++;

        arr = realloc(arr, (size + 1) * sizeof(int*));
        (*arr)[size - 1] = num;
    }

    process_integers(&arr, size, sum_threshold);

    for (int i = 0; i < size; i++) {
        free((*(arr))[i]);
    }

    free(arr);
    return 0;
}
