#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define the maximum number of retries before throwing an error
#define MAX_RETRIES 5

// Define the semaphore structure with initialization value and timeout
typedef struct {
    sem_t semaphore;
    int initial_value;
    int timeout;
} Semaphore;

// Function to initialize the semaphore with a given initial value and timeout
Semaphore* init_semaphore(int initial_value, int timeout) {
    Semaphore* semaphore = (Semaphore*)malloc(sizeof(Semaphore));
    if (semaphore == NULL) {
        return NULL;
    }
    semaphore->initial_value = initial_value;
    sem_init(&semaphore->semaphore, 0, initial_value);
    semaphore->timeout = timeout;
    return semaphore;
}

// Function to acquire the semaphore with a specified timeout
int wait_semaphore(Semaphore* semaphore) {
    int retries = 0;
    while (1) {
        if (sem_wait(&semaphore->semaphore) == 0) {
            break; // Semaphore acquired successfully
        }
        retries++;
        if (retries >= MAX_RETRIES || clock_gettime(CLOCK_REALTIME, &semaphore->timeout)) {
            printf("Semaphore timeout exceeded. Process will wait for further instructions.\n");
            return -1; // Timeout exceeded
        }
    }
    return 0;
}

// Function to release the semaphore after acquiring it
void release_semaphore(Semaphore* semaphore) {
    sem_post(&semaphore->semaphore);
}

// Function to destroy the semaphore when no longer needed
void free_semaphore(Semaphore* semaphore) {
    sem_destroy(&semaphore->semaphore);
    free(semaphore);
}

int main() {
    // Example usage: Initialize and use a semaphore with an initial value of 5 and timeout of 2 seconds
    Semaphore* semaphore = init_semaphore(5, 2000000); // 2000000 microseconds = 2 seconds
    if (semaphore == NULL) {
        printf("Failed to initialize semaphore.\n");
        return -1;
    }

    // Acquire the semaphore and wait for up to 2 seconds
    int result = wait_semaphore(semaphore);
    if (result < 0) {
        printf("Semaphore timeout exceeded. Process will exit.\n");
        free_semaphore(semaphore);
        return -1;
    }

    // Release the semaphore after acquiring it
    release_semaphore(semaphore);

    // Destroy the semaphore when no longer needed
    free_semaphore(semaphore);

    return 0;
}
