import java.nio.file.attribute.BasicFileAttributes;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.Level;
import java.util.logging.Logger;

public class FileHashService {
    private final Map<String, String> fileMap = new HashMap<>();
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final Logger logger = Logger.getLogger(FileHashService.class.getName());
    private int concurrencyLevel = 10; // configurable concurrency level
    private boolean includeExtensionInHash = true; // configurable option to include extension in hash

    public void processDirectory(String directoryPath) {
        Path path = Paths.get(directoryPath);
        try (Files.walk(path)) {
            Files.walk(path).forEach(filePath -> {
                if (!filePath.toFile().isDirectory()) {
                    processFile(filePath, filePath.getFileName().toString());
                }
            });
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error processing directory", e);
        }
    }

    private void processFile(Path filePath, String fileName) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] buffer = new byte[4096]; // adjust to your needs
            FileInputStream fis = new FileInputStream(filePath.toFile());
            try (MD5Hasher hasher = new MD5Hasher(md)) {
                int bytesRead;
                while ((bytesRead = fis.read(buffer)) != -1) {
                    hasher.update(buffer, 0, bytesRead);
                }
                String hash = hasher.digest().toString();
                if (includeExtensionInHash) {
                    fileName += "." + filePath.getFileName().toString().substring(filePath.getNameCount() - 1).toString();
                }
                fileMap.put(fileName, hash);
            } finally {
                fis.close();
            }
        } catch (IOException | NoSuchAlgorithmException e) {
            logger.log(Level.SEVERE, "Error processing file: " + fileName, e);
        }
    }

    public Map<String, String> getFileMap() {
        return fileMap;
    }

    public void setConcurrencyLevel(int concurrencyLevel) {
        this.concurrencyLevel = concurrencyLevel;
    }

    public void setIncludeExtensionInHash(boolean includeExtensionInHash) {
        this.includeExtensionInHash = includeExtensionInHash;
    }
}

class MD5Hasher extends DigestInputStream {
    private final MessageDigest md;

    public MD5Hasher(MessageDigest md) throws IOException {
        super(md);
        this.md = md;
    }

    @Override
    protected void processBytes(byte[] buffer, int offset, int len) throws IOException {
        md.update(buffer, offset, len);
    }
}
