// Custom structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Data structure to manage pool of structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* arr;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} NFAPI_CRC_POOL_T;

NFAPI_CRC_POOL_T crc_pool;

// Function to initialize the CRC pool
void init_crc_pool(int initial_capacity) {
    crc_pool.size = 0;
    crc_pool.capacity = initial_capacity;
    crc_pool.arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(crc_pool.capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&crc_pool.mutex, NULL);
}

// Function to add a structure to the CRC pool
void add_to_crc_pool(int RX_UE_INFORMATION_TAG, int RNTI) {
    if (crc_pool.size >= crc_pool.capacity) {
        // Reallocate memory with increased capacity
        crc_pool.capacity *= 2;
        crc_pool.arr = (NFAPI_CRC_INDICATION_PDU_T*)realloc(crc_pool.arr, crc_pool.capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    NFAPI_CRC_INDICATION_PDU_T* new_struct = &crc_pool.arr[crc_pool.size++];
    new_struct->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_struct->RNTI = RNTI;
    new_struct->CRC_INDICATION_REL8_TAG = rand() % 100; // Randomly set CRCFLAG
}

// Function to remove a structure from the CRC pool
void remove_from_crc_pool(int index) {
    pthread_mutex_lock(&crc_pool.mutex);

    if (index < crc_pool.size) {
        memmove(&crc_pool.arr[index], &crc_pool.arr[index + 1], (crc_pool.size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        crc_pool.size--;

        // Reclaim memory
        NFAPI_CRC_INDICATION_PDU_T* temp_arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc((crc_pool.capacity / 2) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(temp_arr, crc_pool.arr, (crc_pool.size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(crc_pool.arr);
        crc_pool.arr = temp_arr;

        crc_pool.capacity /= 2;
    }

    pthread_mutex_unlock(&crc_pool.mutex);
}

