public static class XmlParser
{
    public static XElement GetFirstXmlElementByName(string xml, string elementName)
    {
        try
        {
            XmlDocument doc = new XmlDocument();
            doc.LoadXml(xml);
            XmlNodeList nodes = doc.SelectNodes($"//{elementName}");
            return nodes != null && nodes.Count > 0 ? nodes[0].SelectSingleNode("//text()") : null;
