// Function to rename files based on their current extension and content
void renameFiles(char* path) {
    // Open the file for reading
    FILE* file = fopen(path, "r");

    if(file == NULL) {
        printf("Error opening file: %s\n", path);
        return;
    }

    // Get the current filename without extension
    char currentFilename[255];
    fgets(currentFilename, 256, file);
    fclose(file);
    int dotIndex = strlen(currentFilename) - 1;
    while(dotIndex > 0 && currentFilename[dotIndex] != '.') {
        dotIndex--;
    }

    // Get the original filename without extension
    char originalName[255];
    strncpy(originalName, currentFilename, dotIndex);
    originalName[dotIndex] = '\0';

    // Initialize a counter for new filenames
    int i = 1;

    do {
        // Create the new filename by appending "_renamed" to the original name and incrementing the number
        char newFilename[255];
        sprintf(newFilename, "%s_%d", originalName, i);

        // Open the file with the new name for writing
        FILE* newFile = fopen(strcat(path, ".txt"), "w");

        if(newFile != NULL) {
            // Write the content to the new file
            fwrite(currentFilename, 1, strlen(currentFilename), newFile);
            fclose(newFile);
            break;
        }
    } while(i++ < 1000);

    if(i >= 1000) {
        printf("Renaming failed: %s\n", path);
    }
}

int main() {
    initMemory();
    renameFiles("path/to/file.txt");
    return 0;
}
