// Function to load a resource bundle from a specified file path
int load_resource_bundle(const char* file_path) {
    FILE* file = fopen(file_path, "rb");

    if (file == NULL) {
        // Handle error: unable to open the file
        return -1;
    }

    // Read the number of items in the bundle
    int num_items;
    fread(&num_items, sizeof(int), 1, file);

    // Allocate memory for the bundle and its items
    int* bundle = (int*)malloc((num_items + 1) * sizeof(int));

    for (int i = 0; i < num_items; i++) {
        fread(&bundle[i], sizeof(int), 1, file);
    }

    fclose(file);

    return num_items;
}

