Record** findPrimes(long* offsets, int* keys, int numRecords) {
    // Create arrays to store pointers to prime records
    Record** primes = (Record**)malloc(sizeof(Record*) * numRecords);
    if (!primes) return NULL;

    for (int i = 0; i < numRecords; ++i) {
        // Check if key is a prime number within the range [2, sqrt(maxKey)]
        int maxKey = keys[i];
        int isPrime = 1;
        for (int j = 2; j * j <= maxKey && isPrime; ++j)
            if (maxKey % j == 0) isPrime = 0;

        if (isPrime) {
            primes[i] = &((Record){.offset = offsets[i], .key = keys[i]});
        } else {
            primes[i] = NULL;
        }
    }

    return primes;
}
