// Define custom error codes
#define ERROR_OUT_OF_MEMORY 1
#define ERROR_INVALID_PARAMETERS 2
#define ERROR_CONCURRENCY_FAILURE 3

// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Function to allocate and initialize arrays
int allocateArrays(int array_size, int memory_limit, int num_records, int min_value, int max_value, Record** records, int** keys, long** offsets) {
    // Calculate the total size of memory required in bytes
    int total_memory_required = (array_size * sizeof(long)) + (num_records * sizeof(Record));

    // Check if the requested memory exceeds the limit
    if ((total_memory_required / 1024) > memory_limit) {
        return ERROR_OUT_OF_MEMORY;
    }

    // Dynamically allocate memory for arrays
    *keys = (int*)malloc(array_size * sizeof(int));
    *offsets = (long*)malloc(array_size * sizeof(long));
    *records = (Record*)malloc(num_records * sizeof(Record));

    if (!(*keys || *offsets || *records)) {
        return ERROR_OUT_OF_MEMORY;
    }

    // Initialize the arrays
    srand(time(NULL)); // seed for random number generation

    for (int i = 0; i < num_records; i++) {
        Record record = ({ .key = rand() % (max_value - min_value + 1) + min_value, .offset = rand() % array_size });
        (*records)[i] = record;
    }

    return 0;
}

// Function to free allocated memory
void freeMemory(int* keys, long* offsets, Record* records, int size) {
    if (keys) {
        free(keys);
    }
    if (offsets) {
        free(offsets);
    }
    if (records) {
        free(records);
    }
}

// Example usage:
int main() {
    int array_size = 1000;
    int memory_limit = 1024; // in kilobytes
    int num_records = 500;
    int min_value = 1;
    int max_value = 100;

    Record* records;
    int* keys;
    long* offsets;

    int error_code = allocateArrays(array_size, memory_limit, num_records, min_value, max_value, &records, &keys, &offsets);

    if (error_code != 0) {
        printf("Error code: %d\n", error_code);
    } else {
        // Use the allocated arrays
    }

    freeMemory(keys, offsets, records, array_size);

    return 0;
}
