#include <stdlib.h>
#include <stdio.h>
#include <math.h>

// Define struct point
typedef struct {
    int x;
    int y;
} Point;

// Define struct shape
typedef enum {CIRCLE, RECTANGLE, TRIANGLE} ShapeType;
typedef struct {
    int type;
    union {
        double radius;
        struct {
            int width;
            int height;
        } rect;
        struct {
            int base;
            int height;
        } tri;
    } shapeData;
} Shape;

// Function to calculate Euclidean distance between two points
double euclideanDistance(Point p1, Point p2) {
    return sqrt(pow((p2.x - p1.x), 2) + pow((p2.y - p1.y), 2));
}

// Function to compute area and perimeter of a shape
void computeShapeProperties(Shape* shape, double* areas, double* perimeters) {
    switch (shape->type) {
        case CIRCLE:
            *areas = M_PI * shape->shapeData.radius * shape->shapeData.radius;
            *perimeters = 2 * M_PI * shape->shapeData.radius;
            break;
        case RECTANGLE:
            *areas = shape->shapeData.rect.width * shape->shapeData.rect.height;
            *perimeters = 2 * (shape->shapeData.rect.width + shape->shapeData.rect.height);
            break;
        case TRIANGLE:
            *areas = 0.5 * shape->shapeData.tri.base * shape->shapeData.tri.height;
            *perimeters = shape->shapeData.tri.base + shape->shapeData.tri.height + sqrt(pow(shape->shapeData.tri.base, 2) + pow(shape->shapeData.tri.height, 2));
            break;
    }
}

int main() {
    // Initialize arrays
    double* distances;
    Shape* shapes;
    int numPoints = 10;
    int numShapes = 5;

    // Allocate memory for arrays
    Point* points = malloc(numPoints * sizeof(Point));
    distances = malloc(numPoints * numPoints * sizeof(double));
    shapes = malloc(numShapes * sizeof(Shape));

    // Initialize point array
    for (int i = 0; i < numPoints; i++) {
        points[i].x = i;
        points[i].y = i;
    }

    // Initialize shape array
    for (int i = 0; i < numShapes; i++) {
        switch (i % 3) { // CIRCLE, RECTANGLE, TRIANGLE
            case 0:
                shapes[i].type = CIRCLE;
                shapes[i].shapeData.radius = (double)i;
                break;
            case 1:
                shapes[i].type = RECTANGLE;
                shapes[i].shapeData.rect.width = i;
                shapes[i].shapeData.rect.height = i;
                break;
            case 2:
                shapes[i].type = TRIANGLE;
                shapes[i].shapeData.tri.base = i;
                shapes[i].shapeData.tri.height = i;
                break;
        }
    }

    // Calculate distances and shape properties
    for (int i = 0; i < numPoints; i++) {
        for (int j = i; j < numPoints; j++) {
            distances[numPoints * i + j] = euclideanDistance(points[i], points[j]);
        }
    }

    for (int i = 0; i < numShapes; i++) {
        double area, perimeter;
        computeShapeProperties(&shapes[i], &area, &perimeter);
        printf("Shape %d: Area = %.2f, Perimeter = %.2f\n", i, area, perimeter);
    }

    // Deallocate memory
    free(points);
    free(distances);
    free(shapes);

    return 0;
}
