        for (int i = 0; i < n; i++) {
            // Your external HTTP service URL
            char url[256];
            sprintf(url, "http://your-service.com/update-html-content?section-id=%s&element-id=%s&RNTI=%d&CRCFLAG=%d", pageSectionID, elementID, packet[i].RNTI, packet[i].CRCFLAG);

            // Add request headers and parameters
            curl_easy_setopt(curl, CURLOPT_URL, url);
            headers = curl_slist_append(headers, "Content-Type: application/json");
            headers = curl_slist_append(headers, "X-Custom-Header: Your-HTTP-Headers");
            headers = curl_slist_append(headers, "param1=value1&param2=value2"); // Add parameters

            do {
                res = curl_easy_perform(headers, NULL);
            } while ((res == CURLE_RETRY_AFTER) && (retryCount < 3));

            if (res != CURLE_OK) {
                break;
            }
        }

        // Handle any errors
        if (res != CURLE_OK) {
            *status = 1; // Set status to indicate failure
            return 0;
        }
    }

    curl_easy_cleanup(curl);
    curl_global_cleanup();

    free(packet);
    return 1; // Indicate success
