import java.io.*;
import java.util.*;

public class AppConfigLoader {
    private static Map<File, AppConfig> configCache = new HashMap<>();
    private static final int MAX_CACHE_SIZE = 100;

    public static AppConfig loadConfig(File file) throws IOException {
        AppConfig config = configCache.get(file);
        if (config != null) {
            return config;
        }

        try (FileInputStream fis = new FileInputStream(file)) {
            ObjectInputStream ois = new ObjectInputStream(fis);
            config = (AppConfig) ois.readObject();
            configCache.put(file, config);

            // Cache invalidation strategy
            if (configCache.size() > MAX_CACHE_SIZE) {
                configCache.clear();
            }
        } catch (ClassNotFoundException e) {
            return null;
        } catch (IOException e) {
            throw new UncheckedIOException("Error reading configuration file: " + file, e);
        }

        return config;
    }
}
