#include <forward_list>
#include <string>
#include <mutex>
#include <thread>
#include <chrono>
#include <fstream>

std::ofstream logFile;

void initLogger() {
    time_t now = time(0);
    char* dt = ctime(&now);

    std::string filename = "logs-" + dt;
    logFile.open(filename, std::ios_base::app);
}

class MessageBuffer {
public:
    MessageBuffer(int capacity) : buffer_, maxCapacity_(capacity), loggingEnabled_(true) {}

    void insertAfter(const std::string& target, const std::string& message) {
        if (!loggingEnabled_) {
            buffer_.insert_after(buffer_.cbegin(), message);
            return;
        }

        auto start = std::chrono::high_resolution_clock::now();

        std::unique_lock<std::mutex> lock(mutex_);
        if (buffer_.size() >= maxCapacity_ - 1) {
            buffer_.pop_front();
        }
        auto it = buffer_.begin();
        while (it != buffer_.end()) {
            if (it->compare(target)) {
                break;
            }
            ++it;
        }

        if (it == buffer_.end()) {
            buffer_.insert_after(it, message);
        } else {
            buffer_.insert_after(it++, message);
        }

        auto end = std::chrono::high_resolution_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);

        logMessage("INSERT_AFTER", target, message, buffer_.size(), duration.count());
    }

private:
    void logMessage(const std::string& action, const std::string& target, const std::string& message,
                     int size, long long duration) {
        if (!loggingEnabled_) return;

        logFile << "[";
        auto now = std::chrono::high_resolution_clock::now();
        char* dt = ctime(&now);
        logFile << dt;
        logFile << "] " << action << ": ";
        logFile << target << " -> " << message;
        logFile << ", Buffer size: " << size << ", Duration: " << duration << " us\n";
    }

    std::forward_list<std::string> buffer_;
    int maxCapacity_;
    bool loggingEnabled_;
    mutable std::mutex mutex_;
};

int main() {
    initLogger();
    MessageBuffer buffer(10);

    // Example usage
    buffer.insertAfter("message1", "new message");
    return 0;
}
