function testModule(label, f, max_execution_time) {
  require('unittest').reset();
  const start = Date.now();
  const tests = [];

  async function executeTest() {
    for (let i = 0; i < 10000; i++) {
      await f();
    }
    return 'Test completed';
  }

  async function runTests() {
    let current_time = Date.now() - start;

    while (current_time < max_execution_time) {
      try {
        const test_name = label + '_' + tests.length;
        console.log(`Executing test: ${test_name}`);

        await executeTest();

        console.log(`Test: ${test_name} completed`);
        current_time = Date.now() - start;
      } catch (error) {
        console.error(`Error in test: ${test_name}`, error);
      }
    }
  }

  runTests().then(() => {
    require('unittest').finalize();
  });
}
