function processOldTestamentReferences(text) {
  const regexPatterns = [
    { pattern: /\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1Samuel|2Samuel|1Kings|2Kings|1Chronicles|2Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|SongofSolomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Zephaniah|Haggai|Zechariah|Malachi)\b/i, type: 'book' },
    { pattern: /\b([1-3]?[0-9]{1,2}|1[0-2][0-9]|10-12)(-[1-3]?[0-9]{1,2}|-(1[0-2][0-9]|10-12))?/i, type: 'chapter' },
    { pattern: /\b([1-3]?[0-9]{1,2}|1[0-2][0-9]|10-12)(\s*:|-|--|\.|\(.*\))?(,[1-3]?[0-9]{1,2}|,(1[0-2][0-9]|10-12))?/i, type: 'verse' }
  ];

  const references = {};
  let currentReference;

  for (const match of text.matchAll(new RegExp(regexPatterns.map(p => p.pattern).join('|'), 'gi'))) {
    switch (match.groups.type) {
      case 'book':
        currentReference = { book: match.groups[0].trim().replace(/[^\w\s]/, '') };
        break;
      case 'chapter':
        if (!currentReference.book) throw new Error('Missing book reference');
        currentReference.chapter = parseInt(match.groups[0], 10);
        break;
      case 'verse':
        if (!currentReference.book || !currentReference.chapter) throw new Error('Missing chapter or verse reference');
        let verse = match.groups[0].trim().replace(/[^\w\s]/, '');
        verse = verse.replace(/^([1-3]?[0-9]{1,2}|1[0-2][0-9]|10-12)\s*:$/i, '$1');
        currentReference.verse = parseInt(verse.split('-').join('-').split(',').join(','), 10);
        break;
    }

    if (currentReference.book && currentReference.chapter && currentReference.verse) {
      const referenceKey = `${currentReference.book} ${currentReference.chapter}:${currentReference.verse}`;
      references[referenceKey] = (references[referenceKey] || 0) + 1;
      currentReference = {};
    }
  }

  return references;
}
