import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicLong;

import org.apache.commons.lang3.StringUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class RemoteConnectionManager {
    private static final Logger LOG = LoggerFactory.getLogger(RemoteConnectionManager.class);

    private final ExecutorService connectionThreadPool;
    private final Selector selector;
    private final List<RemoteAddress> remoteAddresses;
    private final int maxConnectionsPerAddress;
    private final int retryAttempts;
    private final long connectionTimeoutMs;

    public RemoteConnectionManager(int numThreads, int maxConnectionsPerAddress, int retryAttempts, long connectionTimeoutMs) {
        this.connectionThreadPool = Executors.newFixedThreadPool(numThreads);
        this.selector = Selector.open();
        this.remoteAddresses = new ArrayList<>();
        this.maxConnectionsPerAddress = maxConnectionsPerAddress;
        this.retryAttempts = retryAttempts;
        this.connectionTimeoutMs = connectionTimeoutMs;
    }

    public void addRemoteAddress(InetSocketAddress address) {
        remoteAddresses.add(new RemoteAddress(address, selector, maxConnectionsPerAddress));
    }

    public void start() {
        for (RemoteAddress remoteAddress : remoteAddresses) {
            remoteAddress.startConnectionHandler();
        }
    }

    private class RemoteAddress {
        private final InetSocketAddress address;
        private final Selector selector;
        private final int maxConnections;

        public RemoteAddress(InetSocketAddress address, Selector selector, int maxConnections) {
            this.address = address;
            this.selector = selector;
            this.maxConnections = maxConnections;
        }

        public void startConnectionHandler() {
            connectionThreadPool.submit(() -> {
                try {
                    while (true) {
                        SelectionKey key = selector.select(1000); // 1-second timeout
                        if (key != null && key.isValid()) {
                            for (SelectionKey k : key.keysRemoved()) {
                                k.cancel();
                            }
                            for (int i = 0; i < maxConnections; i++) {
                                try {
                                    connectAndHandle(address);
                                } catch (IOException e) {
                                    LOG.error("Failed to establish connection to {}: {}", address, e.getMessage());
                                    // Requeue the connection attempt
                                    selector.wakeup();
                                }
                            }
                        }
                    }
                } catch (IOException e) {
                    LOG.error("Error handling connections: {}", e.getMessage());
                }
            });
        }

        private void connectAndHandle(InetSocketAddress address) throws IOException {
            try (SocketChannel channel = SocketChannel.open()) {
                channel.configureBlocking(false);
                channel.connect(address);
                channel.setOption(StandardSocketOptions.SO_KEEPALIVE, true);

                // Handle connection success/failure
                if (channel.finishConnect() && channel.isConnected()) {
                    LOG.info("Connected to {}: {}", address, StringUtils.EMPTY);
                } else {
                    LOG.error("Failed to establish connection to {}: {}", address, StringUtils.EMPTY);
                }
            }
        }
    }

    public static class Metrics {
        private final AtomicLong totalConnectionsMade = new AtomicLong();
        private final AtomicLong connectionsFailed = new AtomicLong();
        private final AtomicLong connectionLatencyMs = new AtomicLong();

        public void updateMetrics(long bytesRead, long bytesWritten) {
            // Calculate metrics here
        }

        public long getTotalConnectionsMade() {
            return totalConnectionsMade.get();
        }

        public long getConnectionsFailed() {
            return connectionsFailed.get();
        }

        public long getConnectionLatencyMs() {
            return connectionLatencyMs.get();
        }
    }
}
