    double value;
    char buffer[20];
} data_t;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

int init_resources(int data_size, float* arr_float, char** arr_char, data_t*** arr_data, size_t memory_limit) {
    size_t total_allocated = 0;

    // Initialize arrays
    *arr_float = (float*)my_malloc(data_size * sizeof(float));
    if (!*arr_float) return -1;
    total_allocated += data_size * sizeof(float);

    *arr_char = (char**)my_malloc((data_size + 1) * sizeof(char*));
    if (!*arr_char) return -2;
    total_allocated += (data_size + 1) * sizeof(char*);

    *arr_data = (data_t***)my_malloc(data_size * sizeof(data_t*));
    if (!*arr_data) return -3;
    total_allocated += data_size * sizeof(data_t*);

    // Initialize struct array
    for (int i = 0; i < data_size; ++i) {
        (*arr_data)[i] = my_malloc(sizeof(data_t));
        if (!(*arr_data)[i]) return -4;
        total_allocated += sizeof(data_t);

        // Initialize struct members
        (*arr_data)[i]->index = i;
        (*arr_data)[i]->value = (double)i * 2.0 + 3.5;
        strcpy((*arr_data)[i]->buffer, "Hello, world!");
    }

    if (total_allocated > memory_limit) {
        my_free(*arr_float);
        my_free(*arr_char);
        for (int i = 0; i < data_size; ++i) {
            my_free((*arr_data)[i]);
        }
        my_free(*arr_data);
        return -5;
    }

    return 0;
}

