    if (arr_float && sizeof(float) * strlen(arr_char) > memory_limit) {
        // Handle error
    } else {
        my_free(arr_float);
    }

    if (arr_char && sizeof(char*) * strlen(*arr_char) > memory_limit) {
        // Handle error
    } else {
        for (int i = 0; i < data_size; ++i) {
            my_free((*arr_data)[i]);
        }
        my_free(arr_data);
    }
}

void log_memory_usage(size_t allocated, size_t limit) {
    printf("Memory usage: %zu KB / %zu KB (limit)\n", allocated / 1024, limit / 1024);
}
