use reqwest::blocking::{get, put};
use reqwest::header;
use tokio::time;
use log::info;

pub struct HttpClient {
    timeout: time::Duration,
    max_concurrent_requests: usize,
}

impl HttpClient {
    pub fn new(timeout: time::Duration, max_concurrent_requests: usize) -> Self {
        HttpClient { timeout, max_concurrent_requests }
    }

    pub fn request(&self, url: &str, method: &str, headers: &[(String, String)]) -> reqwest::blocking::RequestBuilder {
        let mut builder = match method.to_lowercase().as_str() {
            "get" => get(url),
            "put" => put(url),
            _ => panic!("Invalid HTTP method"),
        };

        for (key, value) in headers.iter() {
            builder.header(key.clone(), value.clone());
        }

        builder.timeout(self.timeout).timeout_read(self.timeout)
    }
}

async fn send_request(builder: reqwest::blocking::RequestBuilder) -> Result<String, reqwest::Error> {
    let response = builder.send().await?;
    let body = response.text().await?;

    Ok(body)
}

#[tokio::main]
async fn main() {
    env_logger::init();
    info!("HTTP client started");

    let mut http_client = HttpClient::new(time::Duration::from_secs(10), 5);

    let url = "https://example.com";
    let method = "GET";
    let headers = vec![("Accept".to_string(), "application/json".to_string())];

    let builder = http_client.request(url, method, &headers);

    match send_request(builder) {
        Ok(response) => println!("Response: {}", response),
        Err(error) => eprintln!("Error: {}", error),
    }
}
