#define MAX_LIST_SIZE 1000
#define FILE_LOGGING_ENABLED 1

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfaapi_crc_indication_pdu_list = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *fp = fopen("log.txt", "w");

void initialize_list(int size) {
    nfaapi_crc_indication_pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    if (!nfaapi_crc_indication_pdu_list) {
        fprintf(fp, "Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < size; i++) {
        nfaapi_crc_indication_pdu_list[i].RX_UE_INFORMATION_TAG = -1;
        nfaapi_crc_indication_pdu_list[i].RNTI = -1;
        nfaapi_crc_indication_pdu_list[i].CRC_INDICATION_REL8_TAG = 0;
    }
}

void add_entry(int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        if (nfaapi_crc_indication_pdu_list[i].RX_UE_INFORMATION_TAG == -1) {
            nfaapi_crc_indication_pdu_list[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            nfaapi_crc_indication_pdu_list[i].RNTI = RNTI;
            nfaapi_crc_indication_pdu_list[i].CRC_INDICATION_REL8_TAG = 0;
            break;
        }
    }
    pthread_mutex_unlock(&list_mutex);
}

void update_crc(int RX_UE_INFORMATION_TAG, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        if (nfaapi_crc_indication_pdu_list[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            nfaapi_crc_indication_pdu_list[i].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
            break;
        }
    }
    pthread_mutex_unlock(&list_mutex);
}

void log_list() {
    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        fprintf(fp, "RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
                nfaapi_crc_indication_pdu_list[i].RX_UE_INFORMATION_TAG,
                nfaapi_crc_indication_pdu_list[i].RNTI,
