#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void create_crc_indication_pdu(int max_size, int* pdu_array, int* size) {
    srand(time(NULL));
    for (int i = 0; i < max_size; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 100 + 1;
        pdu.RNTI = rand() % 500 + 1;
        pdu.CRCFLAG = (rand() % 2) ? true : false;

        // Check for duplicate RX_UE_INFORMATION_TAG entries
        bool duplicate = false;
        for (int j = 0; j < *size; j++) {
            if (pdu_array[j].RX_UE_INFORMATION_TAG == pdu.RX_UE_INFORMATION_TAG) {
                duplicate = true;
                break;
