#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the memory management library
#include "mem_manager.h"

// Define the custom serialization protocol
#include "serialization_protocol.h"

// Define the grid structure
typedef struct {
    int xSize;
    int ySize;
    int zSize;
    float* data;
} Grid;

// Allocate and initialize a 3D grid of float values
Grid* createGrid(int xSize, int ySize, int zSize, float defaultValue) {
    Grid* grid = (Grid*)malloc(sizeof(Grid));
    grid->xSize = xSize;
    grid->ySize = ySize;
    grid->zSize = zSize;

    // Calculate the memory requirement
    int totalBytes = xSize * ySize * zSize * sizeof(float);

    // Check if the initial allocation exceeds the memory limit
    if (totalBytes > MEM_LIMIT) {
        // Reduce each dimension by a factor of two until the memory requirement is within the allowed limit
        while (totalBytes > MEM_LIMIT) {
            xSize /= 2;
            ySize /= 2;
            zSize /= 2;
            totalBytes = xSize * ySize * zSize * sizeof(float);
        }
    }

    // Allocate and initialize the grid data
    grid->data = (float*)malloc(totalBytes);
    for (int i = 0; i < xSize * ySize * zSize; i++) {
        grid->data[i] = defaultValue;
    }

    return grid;
}

// Update individual grid elements based on a user-defined function
void updateGrid(Grid* grid, int xCoord, int yCoord, int zCoord, float (*updateFunc)(int, int, int, float)) {
    pthread_mutex_lock(&grid->mutex);
    for (int i = 0; i < grid->xSize * grid->ySize * grid->zSize; i++) {
        // Apply the update function in parallel across multiple threads
        if (i == (xCoord * grid->xSize + yCoord) * grid->zSize + zCoord) {
            grid->data[i] = (*updateFunc)(xCoord, yCoord, zCoord, grid->data[i]);
        }
    }
    pthread_mutex_unlock(&grid->mutex);
}

// Serialize the entire grid into a binary file format
void serializeGrid(Grid* grid, FILE* file) {
    // Compress the grid data using a custom protocol
    serialization_protocol_compress(grid->data, xSize * ySize * zSize, &file);

    // Write additional metadata to the file (e.g., grid dimensions)
    fwrite(&grid->xSize, sizeof(int), 1, file);
    fwrite(&grid->ySize, sizeof(int), 1, file);
    fwrite(&grid->zSize, sizeof(int), 1, file);
}

// Deserialize a binary file format into the original grid
void deserializeGrid(Grid* grid, FILE* file) {
    // Read the metadata from the file (e.g., grid dimensions)
    fread(&grid->xSize, sizeof(int), 1, file);
    fread(&grid->ySize, sizeof(int), 1, file);
    fread(&grid->zSize, sizeof(int), 1, file);

    // Decompress the grid data using a custom protocol
    serialization_protocol_decompress(file, &grid->data, xSize * ySize * zSize);
}
