NFAPI_CRC_INDICATION_LIST_T nfapi_crc_indication_list_init(size_t initial_capacity) {
    NFAPI_CRC_INDICATION_LIST_T list = (NFAPI_CRC_INDICATION_LIST_T)malloc(sizeof(struct));
    if (!list) return NULL; // Handle memory allocation failure
    list->count = 0;
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL; // Handle memory allocation failure
    }
    pthread_mutex_init(&list->mutex, NULL); // Initialize mutex for thread safety
    return list;
}

void nfapi_crc_indication_list_free(NFAPI_CRC_INDICATION_LIST_T* list) {
    if (!list || !(*list)) return; // Check for null or uninitialized list
    pthread_mutex_unlock(&((*list)->mutex)); // Unlock the mutex to avoid deadlocks during destruction
    free((*list)->data); // Free dynamically allocated memory
    free(*list); // Free the list structure itself
}

