void insert_node(Node* node) {
    int index = custom_hash_function(node->key, NULL);

    if (hash_table[index] == NULL) {
        // Handle the case when there is no collision
        hash_table[index] = node;
        metadata.num_entries++;
    } else {
        // Handle the case of a collision
        Node* temp = hash_table[index];
        while (temp != NULL && temp->key != node->key) {
            temp = temp->next;
        }

        if (temp == NULL) {
            // New entry, add to the end of the linked list
            node->next = NULL;
            temp = hash_table[index];
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = node;
            metadata.num_entries++;
        } else if (temp->key == node->key) {
            // Update the existing entry
            temp->value = node->value;
        } else {
            // Handle the case where there is a collision but the keys are different
            // This should not be possible with our custom hash function
        }
    }
}

int check_load_factor() {
    return (double)metadata.num_entries / (double)hash_table_size();
}

void resize_hash_table(int new_size) {
