#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    uint8_t src_addr[6];
    uint8_t dst_addr[6];
    uint16_t len;
} MAC_HEADER;

typedef struct {
    uint32_t timestamp;
    uint8_t flags;
} TIMESTAMP;

void process_mac_frames(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Error opening file\n");
        return;
    }

    int frame_count = 0;
    MAC_HEADER* mac_headers = NULL;
    TIMESTAMP* timestamps = NULL;
    size_t* payload_sizes = NULL;

    while (1) {
        MAC_HEADER mac_header;
        TIMESTAMP timestamp;
        uint8_t* payload = NULL;

        if (fread(&mac_header, sizeof(MAC_HEADER), 1, file) != 1 || 
            fread(&timestamp, sizeof(TIMESTAMP), 1, file) != 1) {
            break;
        }

        int payload_size = *(int*)malloc(sizeof(int));
        if (!payload_size) {
            printf("Error allocating memory for payload size\n");
            return;
        }
        fread(payload_size, sizeof(int), 1, file);

        uint8_t* temp_payload = (uint8_t*)malloc(*payload_size);
        if (!temp_payload) {
            printf("Error allocating memory for payload\n");
            free(payload_size);
            return;
        }

        if (fread(temp_payload, *payload_size, 1, file) != 1) {
            free(temp_payload);
            free(payload_size);
            break;
        }

        // Process the frame here
        printf("Frame %d: MAC header = %02x:%02x:%02x:%02x:%02x:%02x, "
               "Timestamp = %u, Payload size = %zu bytes\n",
               ++frame_count, mac_header.src_addr[0], mac_header.src_addr[1],
               mac_header.src_addr[2], mac_header.src_addr[3], mac_header.src_addr[4],
               mac_header.src_addr[5], timestamp.timestamp, *payload_size);

        // Deallocate memory
        free(temp_payload);
        free(payload_size);

        // Allocate memory for next frame
        if (frame_count % 1000 == 0) {
            MAC_HEADER* new_mac_headers = 
                realloc(mac_headers, sizeof(MAC_HEADER) * (frame_count + 1));
            TIMESTAMP* new_timestamps = 
                realloc(timestamps, sizeof(TIMESTAMP) * (frame_count + 1));
            size_t* new_payload_sizes = 
                realloc(payload_sizes, sizeof(size_t) * (frame_count + 1));

            if (!new_mac_headers || !new_timestamps || !new_payload_sizes) {
                printf("Error allocating memory for frame buffer\n");
                return;
            }

            mac_headers = new_mac_headers;
            timestamps = new_timestamps;
            payload_sizes = new_payload_sizes;
        }
    }

    fclose(file);
}
