}

int isDuplicate(NFAPI_CRC_INDICATION_PDU_T **nfaPduList, int length, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    for (int i = 0; i < length - 1; i++) {
        if (pdu->RX_UE_INFORMATION_TAG == nfaPduList[i]->RX_UE_INFORMATION_TAG && 
            pdu->RNTI == nfaPduList[i]->RNTI) {
            printf("Duplicate detected! Skipping this entry...\n");
            free(pdu);
            return 1;
        }
    }
    return 0;
}
