<?php

class DAO {

    private $conn;

    public function __construct($host, $username, $password, $database) {
        try {
            $this->conn = new mysqli($host, $username, $password, $database);
            if ($this->conn->connect_error) {
                throw new Exception("Database connection failed: " . $this->conn->connect_error);
            }
        } catch (Exception $e) {
            echo "Error connecting to database: " . $e->getMessage();
            exit;
        }
    }

    public function updateUserPassword($username, $old_password, $new_password) {
        if (!$this->conn) {
            echo "Connection failed";
            return false;
        }

        // Check password strength
        if (!validatePasswordStrength($new_password)) {
            echo "New password does not meet minimum requirements";
            return false;
        }

        // Update user password
        $query = "UPDATE users SET password = ? WHERE username = ?";
        if (!$stmt = $this->conn->prepare($query)) {
            echo "Prepare failed: (" . $this->conn->errno . ") " . $this->conn->error;
            return false;
        }

        $stmt->bind_param("ss", $new_password, $username);

        if (!$stmt->execute()) {
            echo "Execute failed: (" . $stmt->errno . ") " . $stmt->error;
            return false;
        }

        $stmt->close();
        $this->conn->close();

        // Handle user lockout or other post-password update actions
    }
}

function validatePasswordStrength($password) {
    if (strlen($password) < 8) {
        return false;
    }

    $uppercase = preg_match('/[A-Z]/', $password);
    $lowercase = preg_match('/[a-z]/', $password);
    $numbers = preg_match('/\d/', $password);
    $special_chars = preg_match('/[^a-zA-Z0-9]/', $password);

    return ($uppercase && $lowercase && $numbers && $special_chars);
}
