#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>

typedef struct {
    int value;
    pthread_mutex_t lock;
    int ref_count;
} record;

record* allocate_records(int count) {
    record *records = (record*)malloc(count * sizeof(record));
    if (!records) return NULL;

    for (int i = 0; i < count; i++) {
        records[i].value = -1;
        pthread_mutex_init(&records[i].lock, NULL);
        records[i].ref_count = 0;
    }

    return records;
}

void free_records(record* records) {
    if (!records) return;

    for (int i = 0; i < records[0]->value; i++) {
        pthread_mutex_destroy(&records[i].lock);
        free(records + i);
    }
    free(records);
}

record* deserialize_records(const char *filename, int count) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    record *records = allocate_records(count);
    if (!records) {
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        fread(&records[i].value, sizeof(int), 1, file);
        pthread_mutex_lock(&records[i].lock);
        records[i].ref_count = -1; // Initialize ref count
        pthread_mutex_unlock(&records[i].lock);
    }

    fclose(file);

    return records;
}

void serialize_records(const char *filename, record* records) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    for (int i = 0; i < records[0]->value; i++) {
        fwrite(&records[i].value, sizeof(int), 1, file);
    }

    fclose(file);
}

int main() {
    // Example usage
    record* records = allocate_records(100);
    if (!records) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    for (int i = 0; i < records[0]->value; i++) {
        // Initialize or update records...
    }

    serialize_records("records.bin", records);

    record* deserialized_records = deserialize_records("records.bin", 100);
    if (!deserialized_records) {
        printf("Deserialization failed.\n");
        return -1;
    }

    for (int i = 0; i < deserialized_records[0]->value; i++) {
        // Verify or process the deserialized records...
    }

    free_records(deserialized_records);

    return 0;
}
