typedef struct {
    long *long_ptr;
    int *int_ptr;
} record;

record* manage_memory_allocation(long n, long m, long p) {
    if (n < 0 || m < 0 || p < 0) {
        return NULL; // Invalid input
    }

    // Allocate memory for 'n' 'long' offset values and 'm' 'int' keys
    long *offsets = (long*)malloc((size_t)n * sizeof(long));
    int *keys = (int*)malloc((size_t)m * sizeof(int));

    if (!offsets || !keys) {
        free(offsets);
        return NULL; // Memory allocation failed
    }

    // Initialize each record structure
    record* records = (record*)malloc((size_t)p * sizeof(record));
    for (long i = 0; i < p; ++i) {
        records[i].long_ptr = &offsets[(int)(rand() % n)];
        records[i].int_ptr = &keys[(int)(rand() % m)];
    }

    // Populate the 'int' keys array with unique values
    for (int i = 0; i < m; ++i) {
        int val = rand() % 1000;
        while (val >= m || records[0].int_ptr != &keys[val]) {
            val = rand() % 1000;
        }
        keys[i] = val;
    }

    return records;
}
