#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* key;
    void* value;
    int ref_count;
} Entry;

Entry** entries = NULL;
int entry_count = 0;
int max_entries = 0;

// Function to initialize and allocate memory for an array of 'entries'
void init_entries(int count) {
    if (entry_count > 0) {
        // Re-allocate memory to accommodate the new count
        Entry** temp_entries = realloc(entries, sizeof(Entry*) * (count + max_entries));
        if (!temp_entries) {
            printf("Memory allocation failed!\n");
            exit(EXIT_FAILURE);
        }
        entries = temp_entries;
    } else {
        // Initialize and allocate memory for the first time
        entries = malloc(sizeof(Entry*) * count);
        if (!entries) {
            printf("Memory allocation failed!\n");
            exit(EXIT_FAILURE);
        }
    }
    max_entries = count;
    entry_count = 0;
}

// Function to add a new entry to the array
void add_entry(char* key, void* value) {
    Entry* new_entry = malloc(sizeof(Entry));
    if (!new_entry) {
        printf("Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
    new_entry->key = strdup(key);
    new_entry->value = value;
    new_entry->ref_count = 1;

    // Insert the new entry at the end of the array
    entries[entry_count++] = new_entry;
}

// Function to update and validate the state of entries after deserialization
void verify_entries() {
    for (int i = 0; i < entry_count; i++) {
        Entry* current_entry = entries[i];
        // Validate the integrity of each entry and its reference count
        if (!current_entry || !current_entry->key || current_entry->ref_count < 1) {
            printf("Invalid or corrupted entry found!\n");
            exit(EXIT_FAILURE);
        }
    }
}

// Function to serialize the entire data structure to a persistent storage medium
void serialize_entries() {
    // Serialize each entry and its reference count to disk
    FILE* file = fopen("data.txt", "wb");
    if (!file) {
        printf("Serialization failed!\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < entry_count; i++) {
        Entry* current_entry = entries[i];
        fwrite(&current_entry->key, sizeof(char), strlen(current_entry->key), file);
        fwrite(&current_entry->value, sizeof(void*), 1, file);
        fwrite(&current_entry->ref_count, sizeof(int), 1, file);
    }
    fclose(file);
}

// Function to deserialize the entire data structure from a persistent storage medium
void deserialize_entries() {
    // Deserialize each entry and its reference count from disk
    FILE* file = fopen("data.txt", "rb");
    if (!file) {
        printf("Deserialization failed!\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < max_entries; i++) {
        Entry* new_entry = malloc(sizeof(Entry));
        if (!new_entry) {
            printf("Memory allocation failed!\n");
            exit(EXIT_FAILURE);
        }
        fread(&new_entry->key, sizeof(char), strlen(new_entry->key), file);
        fread(&new_entry->value, sizeof(void*), 1, file);
        fread(&new_entry->ref_count, sizeof(int), 1, file);

        // Update and validate the state of entries
        verify_entries();

        // Insert the deserialized entry at the end of the array
        entries[entry_count++] = new_entry;
    }
    fclose(file);
}

int main() {
    init_entries(10); // Initialize with a starting count of 10 entries

    add_entry("key1", "value1");
    add_entry("key2", "value2");

    serialize_entries(); // Serialize the data structure to disk

    deserialize_entries(); // Deserialize the data structure from disk

    return 0;
}
