function processAndStoreData(data, storageSystem) {
  const buffers = [];
  let bufferIndex = 0;

  async function processBuffer(buffer) {
    try {
      // Validate and preprocess data
      const preprocessedData = await validateAndPreprocessData(buffer);

      // Store data in distributed storage system
      await storeInStorageSystem(preprocessedData, storageSystem);
    } catch (error) {
      // Handle errors
      console.error(`Error processing buffer: ${error}`);
    }
  }

  async function processBatch() {
    const batch = buffers.splice(0, BUFFER_SIZE);
    try {
      // Process and store data in parallel
      await Promise.all(batch.map(processBuffer));
    } catch (error) {
      // Handle errors
      console.error(`Error processing batch: ${error}`);
    }
  }

  async function run() {
    while (true) {
      // Pause if requested or if buffer is full
      if (shouldPause || buffers.length >= BUFFER_SIZE) {
        await pauseAndResume();
        continue;
      }

      // Process available data in the buffer
      await processBatch();
    }
  }

  async function pauseAndResume() {
    try {
      // Pause operation
      await pauseOperation();
    } catch (error) {
      console.error(`Error pausing: ${error}`);
    } finally {
      // Resume operation after a configurable timeout
      setTimeout(() => {
        run();
      }, PAUSE_TIMEOUT);
    }
  }

  async function validateAndPreprocessData(data) {
    // Validate and preprocess data
    return await preprocessData(data);
  }

  async function storeInStorageSystem(data, storageSystem) {
    // Store data in distributed storage system
    return await storeData(data, storageSystem);
  }

  run();
}
