from psycopg2.extras import DictCursor

def get_employee_details(supervisor_id):
    db_config = {'dbname': 'mydatabase', 'user': 'myuser', 'password': 'mypassword'}

    try:
        conn = psycopg2.connect(**db_config)
        cur = conn.cursor(cursor_factory=DictCursor)

        if not isinstance(supervisor_id, int) or supervisor_id <= 0:
            raise ValueError("Invalid supervisor ID")

        query = "SELECT name, city, address FROM Employees WHERE supervisor_id = %s"
        cur.execute(query, (supervisor_id,))

        employees = [dict(row) for row in cur.fetchall()]

        conn.close()
        return employees

    except psycopg2.Error as e:
        if 'timeout' in str(e):
            print(f"Database timeout: {str(e)}")
            # retry after 5 seconds
            time.sleep(5)
            return get_employee_details(supervisor_id)
        elif 'connection refused' in str(e):
            print(f"Database connection refused: {str(e)}")
            raise e

    except ValueError as e:
        print(f"Invalid supervisor ID: {str(e)}")
        raise e

    except Exception as e:
        # log the error
        logging.error("An unknown error occurred", exc_info=True)
        raise e

