```php
class PasswordManager {
    private $config;
    private $hashAlgorithms;
    private $saltRounds;

    public function __construct($config) {
        $this->config = $config;
        $this->hashAlgorithms = ['md5', 'sha256', 'bcrypt'];
        $this->saltRounds = 10;
    }

    public function generatePassword($role, $length) {
        // Generate random string based on role
        if ($role == 'admin') {
            $chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+~';
        } elseif ($role == 'standard_user') {
            $chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
        }

        // Validate character set strength
        if (!preg_match('/[A-Z]/', $chars) || !preg_match('/[a-z]/', $chars) || !preg_match('/\d/', $chars) || !preg_match('/[^A-Za-z0-9]/', $chars)) {
            throw new Exception('Invalid character set strength');
        }

        // Generate password
        $password = '';
        for ($i = 0; $i < $length; $i++) {
            $password .= substr(str_shuffle($chars), 0, 1);
        }

        return $password;
    }

    public function hashPassword($password) {
        // Get salt and algorithm based on role
        if ($this->config['role'] == 'admin') {
            $salt = uniqid('adm_');
            $algorithm = 'sha256';
        } elseif ($this->config['role'] == 'standard_user') {
            $salt = uniqid('std_');
            $algorithm = 'md5';
        }

        // Hash password with salt
        return hash($algorithm, $password . $salt);
    }

    public function verifyPassword($storedHash, $inputPassword) {
        // Get algorithm from stored hash
        list($algorithm, $salt) = explode(':', $storedHash);

        if ($algorithm == 'sha256') {
            $hashFunction = 'sha256';
        } elseif ($algorithm == 'md5') {
            $hashFunction = 'md5';
        }

        return hash_equals($storedHash, $hashFunction . (strval($inputPassword) . $salt));
    }
}
