} TransactionStream;

// Function to process transactions and filter based on criteria
void process_transactions(TransactionStream* stream, int threshold) {
    pthread_mutex_lock(&stream->lock);

    // Loop through transactions in the stream
    for (size_t i = 0; i < stream->size; i++) {
        Transaction transaction = stream->transactions[i];

        // Filter based on age: only consider transactions from the past 5 seconds
        if (time(NULL) - transaction.timestamp > 5) continue;

        // Filter based on number of transactions in the past 5 seconds: only consider if threshold is reached
        int num_transactions = 0;
        for (size_t j = i; j < stream->size; j++) {
            if (time(NULL) - stream->transactions[j].timestamp > 5) break;
            num_transactions++;
        }
        if (num_transactions < threshold) continue;

        // Filter based on weighted sum: only consider if exceeds a certain threshold
        double sum = 0;
        for (size_t j = i; j < stream->size; j++) {
            sum += stream->transactions[j].weight;
            if (sum > 10.0) break;
        }
        if (sum <= 10.0) continue;

        // Log transaction details based on outcome
        if (num_transactions >= threshold && sum > 10.0)
            printf("DEBUG: Transaction %d with weight %.2f and age %lds accepted.\n", transaction.id, transaction.weight, time(NULL) - transaction.timestamp);
        else if (num_transactions < threshold || sum <= 10.0)
            printf("INFO: Transaction %d with weight %.2f and age %lds rejected.\n", transaction.id, transaction.weight, time(NULL) - transaction.timestamp);

        // Send aggregated metrics and logs to external analytics service
        // ...
    }

    pthread_mutex_unlock(&stream->lock);
}
