};

void manageGameCharacterActions(int actionCount, std::function<float()> randomFloatGenerator, std::function<std::string(int)> identifierGenerator) {
    std::vector<ActionData*> actionVector;

    // Initialize cooldown timer
    auto lastActionTime = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < actionCount; ++i) {
        float parameter = randomFloatGenerator();
        ActionData* action = new ActionData(parameter, i);

        // Check if enough time has passed since the last action
        if (std::chrono::high_resolution_clock::now() - lastActionTime >= std::chrono::duration<float>(9.0f)) {
            actionVector.push_back(action);
            lastActionTime = std::chrono::high_resolution_clock::now();
        }
    }

    // Clean up allocated memory when done
    for (auto action : actionVector) {
        delete action;
    }
}
