void populateNfaPduList(NFAPI_CRC_INDICATION_PDU_T **pduList, size_t numPDUs) {
    srand(time(NULL));
    *pduList = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numPDUs * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (size_t i = 0; i < numPDUs; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        do {
            // Generate random RX_UE_INFORMATION_TAG and RNTI
            sprintf(pdu.RX_UE_INFORMATION_TAG, "%06x", rand() % 65536);
            pdu.RNTI = rand() % 65535;

            // Check for uniqueness
            int found = 0;
            for (size_t j = 0; j < i; j++) {
                if (strcmp(pdu.RX_UE_INFORMATION_TAG, (*pduList)[j].RX_UE_INFORMATION_TAG) == 0 &&
                    pdu.RNTI == (*pduList)[j].RNTI) {
                    found = 1;
                    break;
                }
            }

            // If duplicate found, retry with different values
            if (found) {
                if (i < numPDUs - 1) {
                    i--; // retry with the same index
                } else {
                    printf("Error: Duplicate entry detected. Aborting.\n");
                    exit(1);
                }
            }
        } while (found);

        (*pduList)[i] = pdu;
    }

    return;
}
