function updateUserPassword($username, $newPassword, $dao) {
    if (!preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*#?&])[A-Za-z\d@$!#%*?&]{8,}$/', $newPassword)) {
        return false; // Invalid password strength
    }

    try {
        $dao->updatePassword($username, $newPassword);
        return true;
    } catch (Exception $e) {
        if ($e instanceof PDOException) {
            // Handle database connection failure
            if (isset($dao->dbConnection)) {
                unset($dao->dbConnection); // Release connection
            }
            sleep(1); // retry after 1 second
            try {
                $dao->updatePassword($username, $newPassword);
                return true;
            } catch (Exception $e) {
                // Handle failed query execution with exponential backoff
                for ($i = 0; $i < 10; $i++) {
                    sleep(pow(2, $i)); // retry after increasing delay
                    try {
                        $dao->updatePassword($username, $newPassword);
                        return true;
                    } catch (Exception $e) {
                        break; // failed to update password
                    }
                }
            }
        } else {
            // Handle other error types (invalid user credentials, etc.)
            return false;
        }
    }
}
