typedef struct {
    char RX_UE_INFORMATION_TAG[64];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[32];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe dynamic collection of NFAPI_CRC_INDICATION_PDU_T structures
struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T** entries;
    int count;
    int max_entries;
    int stale_threshold; // time interval in seconds
} NFAPICollection;

void NFAPICollection_init(NFAPICollection* collection, int max_entries) {
    collection->max_entries = max_entries;
    collection->entries = (NFAPI_CRC_INDICATION_PDU_T**)malloc(max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < max_entries; i++) {
        collection->entries[i] = NULL;
    }
    collection->count = 0;
    pthread_mutex_init(&collection->mutex, NULL);
}

void NFAPICollection_add_entry(NFAPICollection* collection, NFAPI_CRC_INDICATION_PDU_T* entry) {
    pthread_mutex_lock(&collection->mutex);
    for (int i = 0; i < collection->count; i++) {
        if (!collection->entries[i]) {
            collection->entries[i] = entry;
            collection->count++;
            break;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}

void NFAPICollection_remove_entry(NFAPICollection* collection, int RNTI) {
    pthread_mutex_lock(&collection->mutex);
    for (int i = 0; i < collection->count; i++) {
        if (collection->entries[i]->RNTI == RNTI) {
            free(collection->entries[i]);
            for (int j = i + 1; j < collection->count; j++) {
                collection->entries[j - 1] = collection->entries[j];
            }
            collection->count--;
            break;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}

void NFAPICollection_cleanup_stale_entries(NFAPICollection* collection, int timeout) {
    pthread_mutex_lock(&collection->mutex);
    for (int i = 0; i < collection->count; i++) {
        if (gettimeofday(NULL, NULL)) {
            // Handle errors
        }
        NFAPI_CRC_INDICATION_PDU_T* entry = collection->entries[i];
        if (entry && (time(NULL) - entry->last_updated > timeout * 1000)) {
            free(entry);
            for (int j = i + 1; j < collection->count; j++) {
                collection->entries[j - 1] = collection->entries[j];
            }
            collection->count--;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}

void NFAPICollection_log(NFAPICollection* collection, const char* message) {
    // Integrate with external logging framework
}

