// Function to initialize and configure dynamic list of LTE UE contexts
lte_ue_context_list* init_lte_ue_context_list() {
    lte_ue_context_list* list = (lte_ue_context_list*)malloc(sizeof(lte_ue_context_list));
    list->data = (lte_ue_context*)malloc(1 * sizeof(lte_ue_context));
    list->capacity = 1;
    list->size = 0;
    return list;
}

// Function to add a new LTE UE context to the dynamic list
int add_lte_ue_context(lte_ue_context_list* list, int ue_id) {
    if (list->size >= list->capacity) {
        list->data = (lte_ue_context*)realloc(list->data, (list->capacity * 2 + 1) * sizeof(lte_ue_context));
        list->capacity *= 2;
    }
    lte_ue_context* new_ue = &list->data[list->size];
    new_ue->ue_id = ue_id;
    srand(time(NULL));
    for (int i = 0; i < 10; i++) {
        new_ue->rssi[i] = (double)rand() / RAND_MAX;
        new_ue->snr[i] = (double)rand() / RAND_MAX;
    }
    strcpy(new_ue->cell_status_report, "Initial Cell Status Report");
    list->size++;
    return 0;
}

// Function to synchronize with external network management system
