    for (size_t i = 0; i < list->size; i++) {
        lte_ue_context* ue = &list->data[i];
        printf("UE ID: %d, Cell ID: %d, Timestamp: %ld, RSSI: %.2f, SNR: %.2f, Cell Status Report: %s\n", 
               ue->ue_id, ue->cell_id, ue->timestamp, ue->rssi[0], ue->snr[0], ue->cell_status_report);
    }
}

int main() {
