typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void populateNfaPduList(NFAPI_CRC_INDICATION_PDU_T **pduList, int *size) {
    srand(time(NULL));
    for (int i = 0; i < *size; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        do {
            pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
            pdu.RNTI = rand() % 10000;
            pdu.CRCFLAG = (pdu.RX_UE_INFORMATION_TAG + pdu.RNTI) % 2;
        } while (findDuplicate(pduList, i, &pdu));
        *pduList = realloc(*pduList, (++*size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        (*pduList)[i] = pdu;
    }
}

int findDuplicate(NFAPI_CRC_INDICATION_PDU_T **pduList, int index, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    for (int i = 0; i < index; i++) {
        if ((pdu->RX_UE_INFORMATION_TAG == (*pduList)[i].RX_UE_INFORMATION_TAG &&
             pdu->RNTI == (*pduList)[i].RNTI) ||
            (pdu->RX_UE_INFORMATION_TAG == (*pduList)[i].RX_UE_INFORMATION_TAG &&
             pdu->RNTI == (*pduList)[i].RX_UE_INFORMATION_TAG)) {
            // Log the error
            printf("Duplicate found: RX_UE_INFORMATION_TAG = %d, RNTI = %d\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
            return 1;
        }
    }
    return 0;
}
