#include <iostream>
#include <fstream>
#include <thread>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <string>
#include <chrono>

using namespace std;

int main(int argc, char** argv) {
    vector<string> args(argv + 1, argv + argc);
    string filePath = "";
    bool loggingEnabled = true;
    bool streamingOutput = false;

    for (auto& arg : args) {
        if (arg == "--help") {
            cout << "Usage: " << argv[0] << " [file_path]" << endl
                 << "Options:" << endl
                 << "  --help: Display this help message" << endl
                 << "  -l: Log detailed process information to a file" << endl
                 << "  -s: Stream the file contents to standard output" << endl
                 << "  -d: Disable logging" << endl;
            return 0;
        }
        else if (arg == "-l") {
            loggingEnabled = true;
        }
        else if (arg == "-s") {
            streamingOutput = true;
        }
        else if (arg == "-d") {
            loggingEnabled = false;
        }
        else {
            filePath = arg;
        }
    }

    mutex mtx;
    condition_variable cv;

    thread reader([&](string fp) {
        ifstream file(fp, ios::in);
        if (!file) {
            cerr << "Error: File not found or inaccessible." << endl;
            return;
        }

        char buffer[4096];
        int bytesRead = 0;
        while (file.read(buffer, sizeof(buffer))) {
            bytesRead += file.gcount();
            if (loggingEnabled) {
                lock_guard<mutex> lock(mtx);
                cout << "Reading: ";
                for (int i = 0; i < bytesRead; ++i) {
                    cout << buffer[i];
                }
                cout << endl;
            }

            if (streamingOutput) {
                cout.write(buffer, file.gcount());
                cout.flush();
            }

            unique_lock<mutex> lock(mtx);
            cv.notify_all();
        }

        if (loggingEnabled) {
            lock_guard<mutex> lock(mtx);
            cout << "Completed reading." << endl;
        }
    }, filePath);

    reader.join();

    return 0;
}
