    (*(*array + array_size))->CRCFLAG = (uint8_t)rand() % CRCFLAG_RANGE;
    array_size++;
    pthread_mutex_unlock(mutex);
}

void free_array(pthread_mutex_t *mutex, NFAPI_CRC_INDICATION_PDU_T **array) {
    pthread_mutex_lock(mutex);
    if (array_size > 0) {
        for (int i = 0; i < array_size; i++) {
            if ((*array)[i] != NULL)
                free((*array)[i]);
        }
    }
    free_entries(0, array_size);
    *array = NULL;
    array_size = 0;
    pthread_mutex_unlock(mutex);
}
