#include "custom_allocator.h"

void* record_array_alloc(int num_records) {
    if (num_records <= 0) return NULL;

    // Allocate arrays for offsets and keys
    void* offset_ptr = custom_malloc(num_records * sizeof(long));
    void* key_ptr = custom_malloc(num_records * sizeof(int));

    if (!offset_ptr || !key_ptr) {
        // Free any partially allocated memory to avoid leaks
        if (offset_ptr) custom_free(offset_ptr);
        if (key_ptr) custom_free(key_ptr);
        return NULL;
    }

    // Allocate array of record structures
    void* records_ptr = custom_malloc(num_records * sizeof(record));
    if (!records_ptr) {
        // Free any partially allocated memory to avoid leaks
        custom_free(offset_ptr);
        custom_free(key_ptr);
        return NULL;
    }

    // Initialize record structures and store offset and key pointers
    for (int i = 0; i < num_records; i++) {
        record* r = records_ptr + i * sizeof(record);
        r->offset = offset_ptr + i * sizeof(long);
        r->key = key_ptr + i * sizeof(int);
        r->status = 0;
    }

    return records_ptr;
}
