function renderScripts(scripts) {
  const footer = document.getElementById('footer');
  scripts.forEach(script => {
    const scriptTag = document.createElement('script');
    scriptTag.src = `data:text/javascript;charset=utf-8;base64,${btoa(JSON.stringify({ key: script.key, code: script.code }))}`;
    scriptTag.onload = function() {
      this.parentNode.removeChild(this);
    };
    footer.appendChild(scriptTag);
  });
}

// Example usage:
const scripts = [
  { key: 'script1', code: 'console.log("Hello from script 1");' },
  { key: 'script2', code: 'console.log("Hello from script 2");' },
  // ...
];
renderScripts(scripts);
