#define NR_CELL_STATS_T 1000
#define BUFFER_SIZE 1024

typedef struct {
    int CELL_ID;
    float RX_POWER;
    float TX_POWER;
    float LINK_QUALITY;
} CellStats;

void processAndAggregateTrafficData(json_object *config) {
    // Initialize variables
    json_object *interval_obj = json_object_object_get(config, "aggregation_interval");
    int aggregation_interval = atoi(json_object_get_string(interval_obj));

    json_object *logging_level_obj = json_object_object_get(config, "logging_level");
    char logging_level[32];
    strcpy(logging_level, json_object_get_string(logging_level_obj));

    // Process traffic data
    CellStats cell_stats[NR_CELL_STATS_T];
    // ... process traffic data ...

    // Aggregate data by cell ID
    int num_cells = 0;
    float avg_rx_power_sum = 0.0;
    float avg_link_quality_sum = 0.0;

    for (int i = 0; i < NR_CELL_STATS_T; i++) {
        if (cell_stats[i].CELL_ID != -1) {
            if (num_cells == 0 || cell_stats[i].CELL_ID != cell_stats[num_cells-1].CELL_ID) {
                // New cell
                num_cells++;
                avg_rx_power_sum = cell_stats[i].RX_POWER;
                avg_link_quality_sum = cell_stats[i].LINK_QUALITY;
            } else {
                // Same cell, aggregate data
                avg_rx_power_sum += (cell_stats[i].RX_POWER - avg_rx_power_sum) / (num_cells);
                avg_link_quality_sum += (cell_stats[i].LINK_QUALITY - avg_link_quality_sum) / (num_cells);
            }
        }
    }

    // Print aggregated data
    printf("Average RX Power: %.2f\n", avg_rx_power_sum / num_cells);
    printf("Average Link Quality: %.2f\n", avg_link_quality_sum / num_cells);

    return;
}

int main() {
    json_object *config = NULL;

    // Load JSON configuration file
    FILE *fp = fopen("config.json", "r");
    if (fp != NULL) {
        fseek(fp, 0, SEEK_END);
        size_t len = ftell(fp);
        char buffer[len+1];
        rewind(fp);
        fread(buffer, 1, len, fp);
        buffer[len] = '\0';
        fclose(fp);

        // Parse JSON configuration file
        config = json_object_from_json_string(buffer);
    }

    if (config != NULL) {
        processAndAggregateTrafficData(config);
    } else {
        printf("Error parsing JSON configuration file.\n");
    }

    return 0;
}
