// Define maximum allowed size for memory allocation
#define MAX_ALLOC_SIZE (1024 * 1024)

// Structure to represent data point with label and weight
typedef struct {
    float value;
    char label[10];
    double weight;
} DataPoint;

// Comparator function for sorting based on weights
int compare(const void* a, const void* b) {
    DataPoint* p1 = (DataPoint*)a;
    DataPoint* p2 = (DataPoint*)b;
    return (p1->weight > p2->weight) ? -1 : 1;
}

// C function to process data
void process_data(float** float_array, char*** char_array, double** double_array, int num_points, int precision) {
    // Initialize arrays with user input size
    *float_array = (float*)calloc(num_points, sizeof(float));
    if (*float_array == NULL) {
        fprintf(stderr, "Error: Float array allocation failed.\n");
        return;
    }

    *char_array = (char**)calloc(num_points, sizeof(char*));
    if (*char_array == NULL) {
        free(*float_array);
        fprintf(stderr, "Error: Char array allocation failed.\n");
        return;
    }

    for (int i = 0; i < num_points; i++) {
        (*char_array)[i] = (char*)calloc(10, sizeof(char));
        if ((*char_array)[i] == NULL) {
            free(*float_array);
            free(*char_array);
            fprintf(stderr, "Error: Char array allocation failed.\n");
            return;
        }
    }

    *double_array = (double*)calloc(num_points, sizeof(double));
    if (*double_array == NULL) {
        free(*float_array);
        free(*char_array);
        fprintf(stderr, "Error: Double array allocation failed.\n");
        return;
    }

    // Perform mathematical computations with the external library
    // ...

    // Sort data points based on weights using comparator function
    qsort((void*)*double_array, num_points, sizeof(double), compare);

    // Release allocated resources upon exit
    for (int i = 0; i < num_points; i++) {
        free((*char_array)[i]);
    }
    free(*char_array);
    free(*float_array);
}

// Companion Python function to read and write files
import numpy as np

def process_file(input_file_path, output_file_path):
    try:
        # Read dataset from file
        data = np.loadtxt(input_file_path)

        # Split data into labels, values, and weights
        num_points = len(data)
        float_array = np.empty(num_points, dtype=np.float32)
        char_array = np.empty(num_points, dtype=object)
        double_array = np.empty(num_points, dtype=np.float64)

        for i in range(num_points):
            float_array[i] = data[i][0]
            char_array[i] = str(data[i][1])
            double_array[i] = data[i][2]

        # Process data using C function
        num_points = int(num_points)
        precision = 5
        process_data(&float_array, &char_array, &double_array, num_points, precision)

        # Write processed data back to file
        np.savetxt(output_file_path, zip(*[x for x in [float_array, char_array, double_array]]), delimiter=' ')

    except FileNotFoundError:
        print("Error: Input file not found.")
    except Exception as e:
        print(f"Error: {str(e)}")
