#include "memory_manager.h"
#include "node.h"

void* allocate_memory(size_t textSize, size_t numValues) {
    memory_budget = textSize + (numValues * sizeof(float)) + (sizeof(node) * textSize);

    if (memory_budget > total_available_memory()) {
        // Proportionally reduce the sizes to meet the budget constraint
        textSize *= total_available_memory() / memory_budget;
        numValues *= total_available_memory() / memory_budget;

        // Re-allocate the necessary components
        char* buffer = allocate_block(textSize);
        float* values = allocate_block(numValues * sizeof(float));
        node** list = allocate_block(textSize * sizeof(node*));

        return (void*)malloc(sizeof(struct allocation) + textSize + numValues * sizeof(float) + textSize * sizeof(node*));
    }

    // Allocate the necessary components
    char* buffer = allocate_block(textSize);
    float* values = allocate_block(numValues * sizeof(float));
    node** list = allocate_block(textSize * sizeof(node*));

    return (void*)malloc(sizeof(struct allocation) + textSize + numValues * sizeof(float) + textSize * sizeof(node*));
}

int serialize_allocation(void* allocation, FILE* file) {
    struct allocation* a = (struct allocation*)allocation;

    // Serialize the buffer
    fwrite(a->buffer, 1, a->textSize, file);

    // Serialize the values array
    fwrite(&a->values, sizeof(float), a->numValues, file);

    // Serialize the linked list of nodes
    node* current = a->list;
    while (current) {
        fwrite(&current->value, sizeof(double), 1, file);
        fwrite(&current->next, sizeof(void*), 1, file);
        current = current->next;
    }

    return 0;
}

int deserialize_allocation(FILE* file, void** allocation) {
    struct allocation* a = (struct allocation*)malloc(sizeof(struct allocation));

    // Deserialize the buffer
    fread(a->buffer, 1, a->textSize, file);

    // Deserialize the values array
    fread(&a->values, sizeof(float), a->numValues, file);

    // Deserialize the linked list of nodes
    node* current = NULL;
    for (int i = 0; i < a->textSize; i++) {
        node* new_node = malloc(sizeof(node));
        fread(&new_node->value, sizeof(double), 1, file);
        fread(&new_node->next, sizeof(void*), 1, file);

        if (!current) {
            current = new_node;
        } else {
            new_node->next = current;
            current = new_node;
        }
    }

    *allocation = a;
    return 0;
}
