typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int key;
    long offset[10];
} record;

void populateNFAPIList(int n, int max_size, int* records, NFAPI_CRC_INDICATION_PDU_T** list) {
    int i;
    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*list == NULL || !(*list)) {
        printf("Memory allocation failed.\n");
        return;
    }

    for (i = 0; i < n; i++) {
        (*list)[i].RX_UE_INFORMATION_TAG = records[i];
        (*list)[i].RNTI = rand() % 100 + 1;
        (*list)[i].CRCFLAG = rand() % 2; // random value between 0 and 1

        if ((i+1) * sizeof(NFAPI_CRC_INDICATION_PDU_T) > max_size) {
            printf("Memory exceeded.\n");
            free(*list);
            *list = NULL;
            return;
        }
    }
}

void generateRecords(int n, int range_start, int range_end, record** records) {
    int i;
    *records = (record*)malloc(n * sizeof(record));

    if (*records == NULL || !(*records)) {
        printf("Memory allocation failed.\n");
        return;
    }

    for (i = 0; i < n; i++) {
        (*records)[i].key = rand() % range_end + range_start;

        // Ensure no two consecutive records share the same value
        while (1) {
            if (i > 0 && (*records)[i] == (*records)[i-1]) {
                (*records)[i].key = rand() % range_end + range_start;
            } else break;
        }
    }
}

int main() {
    int n = 100; // number of records
    int max_size = 1024 * 1024; // maximum memory size (in bytes)
    int range_start = 1, range_end = 100; // record key range

    srand(time(NULL)); // seed for reproducibility

    record* rec_list;
    NFAPI_CRC_INDICATION_PDU_T* list;

    generateRecords(n, range_start, range_end, &rec_list);

    if (n * sizeof(record) > max_size) {
        printf("Memory exceeded.\n");
    } else {
        populateNFAPIList(n, max_size, rec_list, &list);

        // free allocated memory
        free(rec_list);
        free(list);
    }

    return 0;
}
