// Shape structure definition
typedef struct {
    double x, y; // point coordinates
    char color[16]; // shape color (max 15 characters)
    int ref_count; // reference count for memory management
} Shape;

// Array of shapes
Shape* shapes = NULL;
int num_shapes = 0;

// Load shapes from external data source
void load_shapes(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return;

    // Read shape data from file (e.g., CSV, JSON)
    // ...

    fclose(file);
}

// Add a new shape to the collection
int add_shape(double x, double y, const char* color) {
    Shape* new_shape = (Shape*)malloc(sizeof(Shape));
    if (!new_shape) return -1; // allocation failed

    new_shape->x = x;
    new_shape->y = y;
    strcpy(new_shape->color, color);
    new_shape->ref_count = 1;

    shapes = realloc(shapes, (num_shapes + 1) * sizeof(Shape));
    if (!shapes) {
        free(new_shape);
        return -1; // allocation failed
    }

    shapes[num_shapes] = new_shape;
    num_shapes++;

    return num_shapes - 1;
}

// Remove a shape from the collection
void remove_shape(int index) {
    assert(index >= 0 && index < num_shapes);

    Shape* shape = &shapes[index];
    if (shape->ref_count > 1) {
        // Decrement reference count, but don't free yet
        shape->ref_count--;
    } else {
        // Free the shape and update the array
        free(shape);
        memmove(&shapes[index], &shapes[index + 1], (num_shapes - index - 1) * sizeof(Shape));
        num_shapes--;
    }
}

// Release all shapes from memory
void release_shapes() {
    for (int i = 0; i < num_shapes; i++) {
        Shape* shape = &shapes[i];
        if (shape->ref_count > 1) {
            // Decrement reference counts before freeing
            shape->ref_count--;
        } else {
            free(shape);
        }
    }

    free(shapes);
    shapes = NULL;
    num_shapes = 0;
}

// Test function to demonstrate usage
int main() {
    load_shapes("shapes.txt");
    int new_shape_index = add_shape(1.5, 2.3, "blue");
    printf("Added shape at index %d\n", new_shape_index);

    // ... test cases and error handling ...

    release_shapes();

    return 0;
}
