    if (!bundle->loader->path) {
        // Handle error
    } else {
        result = bundle->loader->load(bundle->loader, file);
    }
    return result;
}

void bundle_free(Bundle* bundle) {
    if (bundle->data != NULL) {
        free(bundle->data);
        bundle->data = NULL;
    }
}

int resource_load(char* path, FILE* file) {
    int numItems = 0;

    // Check file and parse accordingly
    char buffer[MAX_BUNDLE_SIZE];
    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    if (fileSize > MAX_BUNDLE_SIZE) {
        printf("File size exceeds maximum allowed bundle size.\n");
        return -1;
    }

    fread(buffer, sizeof(char), fileSize, file);
    buffer[fileSize] = '\0';

