#include <zlib.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_COMPRESSION_LEVELS 3
#define LOW_COMPRESSION_LEVEL 1
#define MEDIUM_COMPRESSION_LEVEL 6
#define HIGH_COMPRESSION_LEVEL 9

typedef enum {
    LOW,
    MEDIUM,
    HIGH
} CompressionLevel;

void *compress_file(void *args) {
    // Extract file path and compression level from the passed arguments
    struct {
        char *file_path;
        CompressionLevel compression_level;
    } *task = args;

    // Initialize ZLib compression context
    z_stream stream;
    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;
    stream.opaque = Z_NULL;
    deflateInit2(&stream, (int)task->compression_level, Z_DEFLATED,
                  31, 8, Z_DEFAULT_STRATEGY);

    // Open file for reading and writing
    FILE *file = fopen(task->file_path, "rb+");
    if (!file) {
        return NULL;
    }

    // Initialize memory to store compressed data
    size_t buffer_size = 1024 * 1024; // 1MB buffer
    uint8_t *buffer = (uint8_t *)malloc(buffer_size);

    // Compress file in chunks and write to temporary file
    char temp_file_path[256];
    sprintf(temp_file_path, "%s.zlib", task->file_path);
    FILE *temp_file = fopen(temp_file_path, "wb+");
    if (!temp_file) {
        fclose(file);
        free(buffer);
        return NULL;
    }

    int bytes_written = 0;
    z_ulong total_in;
    while (1) {
        // Read file chunk
        size_t read_size = fread(buffer, 1, buffer_size, file);
        if (read_size == 0) {
            break; // File end reached
        }
        total_in = read_size;

        // Compress and write to temporary file
        stream.avail_in = read_size;
        stream.next_in = buffer;
        do {
            int have;
            stream.avail_out = buffer_size - bytes_written;
            stream.next_out = &buffer[bytes_written];
            deflate(&stream, Z_NO_FLUSH, &have);
            bytes_written += have;
        } while (stream.avail_out == 0);

        // Write compressed chunk to temporary file
        fwrite(buffer, 1, bytes_written, temp_file);
    }

    // Flush and close the compression stream
    stream.avail_in = 0;
    stream.next_in = Z_NULL;
    deflate(&stream, Z_FINISH, &have);
    fclose(temp_file);
    deflateEnd(&stream);

    // Replace original file with temporary compressed file
    rename(temp_file_path, task->file_path);

    free(buffer);
    fclose(file);
    return NULL;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <file_path> <compression_level>\n", argv[0]);
        return -1;
    }

    CompressionLevel compression_level = LOW;
    switch (atoi(argv[2])) {
        case 1:
            compression_level = LOW;
            break;
        case 6:
            compression_level = MEDIUM;
            break;
        case 9:
            compression_level = HIGH;
            break;
        default:
            fprintf(stderr, "Invalid compression level. Using low compression by default.\n");
    }

    pthread_t threads[MAX_COMPRESSION_LEVELS];
    for (int i = 0; i < MAX_COMPRESSION_LEVELS; i++) {
        struct {
            char *file_path;
            CompressionLevel compression_level;
        } task = {argv[1], compression_level};
        pthread_create(&threads[i], NULL, compress_file, &task);
        // Handle potential race conditions by blocking until tasks complete
        pthread_join(threads[i], NULL);
    }

    return 0;
}
