#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int ue_id;
    int cell_id;
    double *snr_values;
    int snr_values_count;
} UE_Context;

UE_Context *ue_contexts = NULL;
int num_ue_contexts = 0;

void add_ue_context(int ue_id, int cell_id, double *snr_values, int snr_values_count) {
    UE_Context *new_ue_context = (UE_Context *)malloc(sizeof(UE_Context));
    new_ue_context->ue_id = ue_id;
    new_ue_context->cell_id = cell_id;
    new_ue_context->snr_values = (double *)malloc(snr_values_count * sizeof(double));
    memcpy(new_ue_context->snr_values, snr_values, snr_values_count * sizeof(double));
    new_ue_context->snr_values_count = snr_values_count;

    if (num_ue_contexts == 0) {
        ue_contexts = new_ue_context;
    } else {
        UE_Context *last_ue_context = &ue_contexts[num_ue_contexts - 1];
        new_ue_context->next = NULL;
        last_ue_context->next = new_ue_context;
    }

    num_ue_contexts++;
}

double calculate_average_snr(int ue_id) {
    int i;
    double sum = 0.0;
    UE_Context *current_ue_context = &ue_contexts[0];

    while (num_ue_contexts > 0 && current_ue_context->next != NULL) {
        if (current_ue_context->ue_id == ue_id) {
            for (i = 0; i < current_ue_context->snr_values_count; i++) {
                sum += current_ue_context->snr_values[i];
            }
            break;
        }
        current_ue_context = current_ue_context->next;
    }

    if (num_ue_contexts == 0 || current_ue_context->ue_id != ue_id) {
        return -1.0;
    } else {
        return sum / (double)current_ue_context->snr_values_count;
    }
}

int main() {
    // Example usage:
    int ue_id = 1234;
    int cell_id = 4567;
    double snr_values[] = {1.2, 3.4, 5.6};
    int snr_values_count = sizeof(snr_values) / sizeof(snr_values[0]);

    add_ue_context(ue_id, cell_id, snr_values, snr_values_count);

    double average_snr = calculate_average_snr(ue_id);
    printf("Average SNR for UE %d: %f\n", ue_id, average_snr);

    return 0;
}
