    srand(time(NULL));

    // Set initial size of UE list
    *size = MIN_UES;

    // Allocate memory for the UE list
    *ues = (lte_ue_context **)malloc(*size * sizeof(lte_ue_context *));
    if (*ues == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

