}

// Function to add a UE context
int add_ue(lte_ue_context **ues, int *size, int cell_id, time_t timestamp) {
    lte_ue_context *new_ue = (lte_ue_context *)malloc(sizeof(lte_ue_context));
    if (new_ue == NULL) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    // Initialize UE attributes
    new_ue->ue_id = rand() % 1000000; // Random UE ID within range [0, 999,999]
    new_ue->rssi = (double)(rand() % (MAX_SIGNAL_QUALITY - MIN_SIGNAL_QUALITY + 1)) + MIN_SIGNAL_QUALITY;
    new_ue->snr = (double)(rand() % (MAX_SIGNAL_QUALITY - MIN_SIGNAL_QUALITY + 1)) + MIN_SIGNAL_QUALITY;
    new_ue->cell_id = cell_id; // Set cell ID to the provided value
    new_ue->timestamp = timestamp;

    if (*size >= MAX_UES) {
        printf("Maximum number of UE contexts reached.\n");
        return -1;
    }

    // Check for memory allocation failure
    if ((*ues) == NULL) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    // Add the new UE context to the list and increment size
    (*ues)[*size] = new_ue;
    (*size)++;

    return 0;
}

// Function to remove inactive UEs
void remove_inactive_ues(lte_ue_context **ues, int *size) {
    for (int i = 0; i < *size; i++) {
        // Check if the UE is inactive (i.e., has not reported a measurement within the specified timeout period)
        // Implement logic to handle inactive UEs
        // For this example, assume that inactive UEs are simply removed from the list
        free((*ues)[i]);
    }

    *size = 0;
}

// Function to export UE contexts to JSON file
int export_uess_to_json(const lte_ue_context *ues, int size, char *filename) {
    // Create a JSON object
    json_object *json_data = json_object_new_object();

    if (json_data == NULL) {
        printf("Failed to create JSON object.\n");
        return -1;
    }

    for (int i = 0; i < size; i++) {
        json_object *ue_json = json_object_new_object();
        if (ue_json == NULL) {
            printf("Failed to create UE JSON object.\n");
            return -1;
        }

        // Serialize UE attributes
        json_object_object_add(ue_json, "ue_id", json_object_new_int(ues[i]->ue_id));
        json_object_object_add(ue_json, "rssi", json_object_new_double(ues[i]->rssi));
        json_object_object_add(ue_json, "snr", json_object_new_double(ues[i]->snr));
        json_object_object_add(ue_json, "cell_id", json_object_new_int(ues[i]->cell_id));
        json_object_object_add(ue_json, "timestamp", json_object_new_int((int)ues[i]->timestamp));

        // Add UE JSON object to the main JSON object
        json_object_object_add(json_data, "UE", ue_json);
    }

    // Write the JSON data to the file
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        printf("Failed to open file.\n");
        return -1;
    }

    json_object_to_file(file, json_data);

    fclose(file);
    json_object_free(json_data);

    return 0;
}
