        printf("Error: File not found\n");
        return 1;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        char* token = strtok(line, ",");

        if (!token) continue; // invalid data

        float val = atof(token);

        int numFields = 0;
        for (token = strtok(NULL, ","); token; token = strtok(NULL, ",")) {
            numFields++;

            if (numFields == 3) break; // last two numerical fields

            if (!atof(token)) continue; // invalid data

            val += atof(token);
        }

        printf("%s%f\n", line, val / (float)(numFields - 2));
    }

    fclose(file);

    return 0;
}
