int convert_jpeg_to_pdf(char *file_name, char *output_dir, int min_range, int max_range) {
    // Allocate memory for arrays
    long *offsets = (long *)malloc(1000 * sizeof(long));
    int *keys = (int *)malloc(1000 * sizeof(int));
    record *records = (record *)malloc(1000 * sizeof(record));

    // Initialize arrays with random values
    srand(time(NULL));
    for (int i = 0; i < 1000; i++) {
        offsets[i] = rand() % (max_range - min_range + 1) + min_range;
        keys[i] = rand();
        records[i].value = rand() % (max_range - min_range + 1) + min_range;
    }

    // Convert JPEG to PDF
    FILE *jpeg_file = fopen(file_name, "rb");
    if (!jpeg_file) {
        printf("Error opening JPEG file: %s\n", strerror(errno));
        return 1;
    }

    FILE *pdf_file = fopen(strcat(output_dir, "/output.pdf"), "wb");
    if (!pdf_file) {
        printf("Error creating PDF file: %s\n", strerror(errno));
        fclose(jpeg_file);
        return 1;
    }

    // Write data to PDF file
    fwrite(&records[0], sizeof(record), 1000, pdf_file);

    fclose(pdf_file);
    fclose(jpeg_file);

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
