#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define RECORD_FILE "record_file.bin"
#define OFFSET_ARRAY_SIZE 1024
#define KEY_ARRAY_SIZE 1024
#define RANDOM_RECORD_RANGE 1000

// Structure to represent a record
typedef struct {
    int key;
    long offset;
} Record;

// Function prototypes
Record* load_records(const char* filename, int* total_records);
int save_records(const char* filename, int total_records);

// Global variables for thread-safety
static pthread_mutex_t file_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;

int main() {
    // Initialize arrays and load existing data from file
    Record* records = load_records(RECORD_FILE, &total_records);

    // Process records...

    // Save changes back to the file
    save_records(RECORD_FILE, total_records);

    // Release resources
    free(records);

    return 0;
}

// Load existing data from a binary file into record arrays
Record* load_records(const char* filename, int* total_records) {
    Record* records = (Record*)malloc(KEY_ARRAY_SIZE * sizeof(Record));
    long* offsets = (long*)malloc(OFFSET_ARRAY_SIZE * sizeof(long));

    FILE* file = fopen(filename, "rb");
    if (!file) {
        // Handle file read error
        return NULL;
    }

    pthread_mutex_lock(&file_lock);

    // Initialize arrays with random values
    for (int i = 0; i < KEY_ARRAY_SIZE; i++) {
        records[i].key = rand() % RANDOM_RECORD_RANGE;
        offsets[i] = -1;  // Initialize offset array with invalid values
    }

    pthread_mutex_unlock(&file_lock);

    int count = 0;
    while (fread(&records[count], sizeof(Record), 1, file) == 1) {
        if (offsets[records[count].key] != -1) {
            // Handle duplicate key by updating the corresponding offset
            pthread_mutex_lock(&record_lock);
            offsets[records[count].key]++;
            pthread_mutex_unlock(&record_lock);
        } else {
            count++;
        }
    }

    fclose(file);

    *total_records = count;
    return records;
}

// Save changes back to the file
int save_records(const char* filename, int total_records) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        // Handle file write error
        return 1;
    }

    pthread_mutex_lock(&record_lock);

