    DATA_TYPE,
    CHAR_ARRAY_TYPE
} data_type_t;

typedef struct {
    void* ptr;
    data_type_t type;
} offset_t;

void* allocate_memory(size_t size, data_type_t type) {
    // Allocate memory based on the specified size and type
    void* mem = malloc(size);
    if (mem == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    switch (type) {
        case LONG_TYPE:
            memset(mem, 0x00, size);
            break;
        case INT_TYPE:
            memset(mem, 0x00, size);
            break;
        case DATA_TYPE:
            memset(mem, 0x00, size);
            break;
        case CHAR_ARRAY_TYPE:
            // Initialize the char array with random non-null ASCII characters
            for (size_t i = 0; i < size; i++) {
                ((char*)mem)[i] = (rand() % 26) + 'a';
            }
            break;
    }
    return mem;
}

void initialize_offset_array(size_t num_records, offset_t* offsets) {
    // Initialize the offset array with correctly mapped pointers
    for (size_t i = 0; i < num_records; i++) {
        size_t size = rand() % MAX_STRING_SIZE + 1;
        data_type_t type = (data_type_t)(rand() % 4);
        void* ptr = allocate_memory(size, type);
        offsets[i].ptr = ptr;
        offsets[i].type = type;
    }
}

