                for (size_t j = 0; j < MAX_STRING_SIZE; j++) {
                    ((char*)offsets[i].ptr)[j] = (rand() % 26) + 'a';
                }
                break;
            case CHAR_ARRAY_TYPE:
                // Populate each element of the char array with random non-null ASCII characters
                for (size_t j = 0; j < MAX_STRING_SIZE; j++) {
                    ((char*)offsets[i].ptr)[j] = (rand() % 26) + 'a';
                }
                break;
        }
    }
}

