#define MAX_SIZE 1024

// Structure for item
typedef struct {
    double value;
    char name[255];
    int id;
} item_t;

// Function to manage dynamic memory allocation and initialization
int manage_memory(int num_double, int num_int, int num_item, int cache_size) {
    // Check if total memory usage exceeds the maximum allowed size
    if ((num_double + 8 * (num_int + num_item)) / (1024 * 1024) > MAX_SIZE) {
        printf("Error: Memory allocation would exceed the maximum allowed size.\n");
        return -1;
    }

    // Mutex for thread safety
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Dynamic memory allocation and initialization
    double* arr_double = (double*)malloc(num_double * sizeof(double));
    int* arr_int = (int*)malloc(num_int * sizeof(int));
    item_t** arr_item = (item_t**)malloc(num_item * sizeof(item_t*));

    for (int i = 0; i < num_item; i++) {
        // Initialize each struct with unique values
        arr_item[i] = (item_t*)malloc(sizeof(item_t));
        item_t* p = arr_item[i];
        p->value = i;
        strcpy(p->name, "Item ");
        p->id = i;

        // Lock for thread safety during initialization
        pthread_mutex_lock(&mutex);
        {
            // Initialize with random values within a specified range
            for (int j = 0; j < num_double; j++) {
                arr_double[j] = (double)rand() / RAND_MAX;
            }
            for (int j = 0; j < num_int; j++) {
                arr_int[j] = rand();
            }
        }
        pthread_mutex_unlock(&mutex);
    }

    // Initialize the LRU cache
    item_t** cache = (item_t**)malloc(cache_size * sizeof(item_t*));
    for (int i = 0; i < cache_size; i++) {
        cache[i] = NULL;
    }

    return 0;
}

