    fwrite(&numOffsets, sizeof(long), 1, file);
    fwrite(&numKeys, sizeof(int), 1, file);

    for (int i = 0; i < numRecords; i++) {
        fwrite(&records[i], RECORD_SIZE, 1, file);
    }
}

void deserialize_data(FILE* file, record** records, long** offsets, int** keys) {
    int numRecords;
    fread(&numRecords, sizeof(int), 1, file);

    int numOffsets;
    fread(&numOffsets, sizeof(long), 1, file);

