    *offsets = my_malloc(numOffsets * sizeof(long));
    *keys = my_malloc(numKeys * sizeof(int));

    for (int i = 0; i < numRecords; i++) {
        fread(&((*records)[i]), RECORD_SIZE, 1, file);
    }
}

