void* dynamic_array(int min_size, int max_size) {
    size_t total_memory = (max_size > min_size ? max_size : min_size) * sizeof(long);
    void* offset_array = mmap(NULL, total_memory, PROT_READ | PROT_WRITE,
            MAP_SHARED | MAP_ANONYMOUS, -1, 0);

    if (offset_array == MAP_FAILED) {
        printf("Memory allocation failed.\n");
        return NULL;
