void init_offset_array(long** offset_array, int size) {
    *offset_array = (long*)malloc(size * sizeof(long));

    for (int i = 0; i < size; i++) {
        (*offset_array)[i] = i;
    }
}

int random_value(int min, int max) {
    static unsigned seed = time(NULL);
    srand(seed);

    return rand() % ((max + 1) - min) + min;
}

