void* distribute_data(size_t max_memory, size_t batch_size, int seed, int* key_array, record_t** records) {
    // Initialize random number generator with custom seed (if provided)
    srand(seed);

    // Calculate maximum number of 'record' structures based on allocated memory and batch size
    size_t num_records = min(max_memory / sizeof(record_t), batch_size);

    // Allocate memory for key array, ensuring it's at least as large as the total number of records
    int* keys = malloc(num_records * sizeof(int));
    if (!keys) {
        return NULL;  // Handle out-of-memory error (OOM)
    }

    // Initialize key array with sequential values starting from 0
    for (size_t i = 0; i < num_records; i++) {
        keys[i] = i;
    }

    // Allocate memory for 'record' structures and initialize with random data
    records = malloc(num_records * sizeof(record_t*));
    if (!records) {
        free(keys);
        return NULL;  // Handle OOM
    }

    for (size_t i = 0; i < num_records; i++) {
        record_t* rec = malloc(sizeof(record_t));
        if (!rec) {
            // Free previously allocated resources and handle OOM
            free(keys);
            free(records);
            return NULL;
        }

        // Initialize 'record' structure with random integer value and null-terminated character array
        rec->value = rand() % 100;  // Random integer within a specified range (e.g., [0, 100])
        strcpy(rec->data, "Record Data");  // Initialize with a default string

        records[i] = rec;
    }

    return keys;
}

// Free allocated memory and close logging mechanism
void close_distributed_data(int* keys, record_t** records) {
    if (keys) {
        free(keys);
    }

    for (size_t i = 0; i < num_records; i++) {
        if (records[i]) {
            free(records[i]);
        }
    }

