typedef struct measurement {
    double value;
    char unit;
} measurement;

int manage_memory(int max_size, int* int_keys_max_size) {
    int* int_keys = (int*)malloc(*int_keys_max_size * sizeof(int));
    if (!int_keys) {
        fprintf(stderr, "Error: Memory allocation for int keys failed.\n");
        return 1;
    }

    double* temps = (double*)malloc(max_size * sizeof(double));
    if (!temps) {
        free(int_keys);
        fprintf(stderr, "Error: Memory allocation for temperatures failed.\n");
        return 2;
    }

    char* units = (char*)malloc(max_size * sizeof(char));
    if (!units) {
        free(int_keys);
        free(temps);
        fprintf(stderr, "Error: Memory allocation for units failed.\n");
        return 3;
    }

    // Initialize random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<double> dist(0.0, 100.0);

    measurement* measurements = (measurement*)malloc(max_size * sizeof(measurement));
    if (!measurements) {
        free(int_keys);
        free(temps);
        free(units);
        fprintf(stderr, "Error: Memory allocation for measurements failed.\n");
        return 4;
    }

    int count = 0;
    for (int i = 0; i < max_size; i++) {
        double temp = dist(gen);
        if (count > 0) {
            while (units[i] == units[i - 1]) {
                temp = dist(gen);
            }
        }
        measurements[i].value = temp;
        measurements[i].unit = 'F'; // Default unit

        int_keys[count++] = i + 1;

        if (count >= *int_keys_max_size) {
            break;
        }
    }

    free(int_keys);
    free(temps);
    free(units);

    return count;
}
