#include <time.h>

typedef struct {
    int ueId;
    int bearerId;
    char qosProfile[20];
} UeSessionState;

typedef struct {
    int value;
    char status;
} Record;

typedef struct {
    Record* record;
    time_t timestamp;
    int errorCount;
} Metadata;

void manageAndFilterSessions(int numSessions, int minBearerId, int maxBearerId) {
    // Initialize arrays
    UeSessionState** sessions = (UeSessionState**)malloc(numSessions * sizeof(UeSessionState*));
    for (int i = 0; i < numSessions; i++) {
        sessions[i] = (UeSessionState*)malloc(sizeof(UeSessionState));
    }

    int* offsets = (int*)malloc(numSessions * sizeof(int));
    int* keys = (int*)malloc(numSessions * sizeof(int));
    Record* records = (Record*)malloc(numSessions * sizeof(Record));
    Metadata* metadata = (Metadata*)malloc(numSessions * sizeof(Metadata));

    // Populate sessions, records and metadata
    srand(time(NULL));  // Initialize random seed
    for (int i = 0; i < numSessions; i++) {
        sessions[i]->ueId = i;
        sessions[i]->bearerId = rand() % (maxBearerId - minBearerId + 1) + minBearerId;
        strcpy(sessions[i]->qosProfile, "SomeQoSProfile");

        records[i].value = rand() % 100;
        records[i].status = 'A' + i;

        metadata[i].record = &records[i];
        metadata[i].timestamp = time(NULL);
        metadata[i].errorCount = 0;
    }

    // Filter sessions based on bearerId range
    for (int i = 0; i < numSessions; i++) {
        if (sessions[i]->bearerId >= minBearerId && sessions[i]->bearerId <= maxBearerId) {
            // Log session addition
            printf("Session added: ueId=%d, bearerId=%d\n", sessions[i]->ueId, sessions[i]->bearerId);
        } else {
            // Log session filtering
            printf("Session filtered out: ueId=%d, bearerId=%d\n", sessions[i]->ueId, sessions[i]->bearerId);
        }
    }

    // Clean up unused records and metadata periodically
    for (int i = 0; i < numSessions; i++) {
        if (metadata[i].timestamp + 60 * 60 < time(NULL)) {  // Inactivity threshold (1 hour)
            free(metadata[i].record);
            free(&metadata[i]);
            // Log record cleanup
            printf("Record cleaned up: ueId=%d\n", sessions[i]->ueId);
        }
    }

    // Free memory
    for (int i = 0; i < numSessions; i++) {
        free(sessions[i]);
    }
    free(sessions);
    free(offsets);
    free(keys);
    free(records);
    free(metadata);
}
