} record;

record* manage_memory_allocation(int num_records) {
    if (num_records <= 0) return NULL;

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) return NULL; // allocation failed, free partially allocated resources and return error

    int* keys = (int*)calloc(num_records, sizeof(int));
    long* offsets = (long*)calloc(num_records, sizeof(long));

    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    free(keys);
    free(offsets);

    return records;
}

void manage_memory_release(record* records) {
    if (!records) return;

    free(records);
}
