#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the maximum size of each array (in bytes)
#define MAX_ARRAY_SIZE 1024

// Define the maximum number of retries for memory allocation
#define MAX_RETRIES 5

// Define the struct node type
typedef struct {
    double value;
    char identifier;
    struct node* next;
} Node;

// Function to allocate and initialize arrays and linked list
int allocate_and_initialize(int max_size, int max_id_count, int* retries) {
    // Calculate the actual size of each array (in bytes)
    int array_size = min(max_size / sizeof(double), MAX_ARRAY_SIZE);
    int id_array_size = min(array_size, max_id_count);
    int node_array_size = id_array_size;

    // Allocate memory for arrays
    double* values = malloc(array_size * sizeof(double));
    char* identifiers = malloc(id_array_size * sizeof(char));
    Node* nodes = malloc(node_array_size * sizeof(Node));

    if (!values || !identifiers || !nodes) {
        // Memory allocation failed, try again (up to max_retries times)
        for (int i = 0; i < *retries && !values || !identifiers || !nodes; i++) {
            free(values);
            free(identifiers);
            free(nodes);

            array_size -= sizeof(double);
            id_array_size--;
            node_array_size--;

            values = malloc(array_size * sizeof(double));
            identifiers = malloc(id_array_size * sizeof(char));
            nodes = malloc(node_array_size * sizeof(Node));

            if (!values || !identifiers || !nodes) {
                printf("Memory allocation failed after %d retries.\n", i + 1);
                return -1;
            }
        }

        // If max_retries is reached and memory allocation still fails, exit
        if (*retries == MAX_RETRIES) {
            printf("Memory allocation failed after %d retries. Aborting.\n", MAX_RETRIES);
            return -1;
        }
    }

    // Initialize arrays and linked list
    for (int i = 0; i < id_array_size; i++) {
        values[i] = rand() / (double)RAND_MAX;
        identifiers[i] = 'A' + (rand() % 26);
        nodes[i].value = values[i];
        nodes[i].identifier = identifiers[i];
        nodes[i].next = &nodes[i + 1];
    }

    return 0;
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    int max_size = 2048; // Set the maximum size for arrays (in bytes)
    int max_id_count = 10; // Set the maximum count of identifiers

    int retries = MAX_RETRIES;

    allocate_and_initialize(max_size, max_id_count, &retries);

    return 0;
}
```

