#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
#include <memory>

using namespace std;

class Node {
public:
    char* key;
    int value;
};

class MemoryManagementSystem {
private:
    unordered_map<string, shared_ptr<Node>> nodeTable;
    mutex nodeMutex;

public:
    void addNode(const string& key, int value) {
        unique_lock<mutex> lock(nodeMutex);
        if (!nodeTable.count(key)) {
            shared_ptr<Node> newNode = make_shared<Node>();
            newNode->key = new char[key.length() + 1];
            strcpy(newNode->key, key.c_str());
            newNode->value = value;
            nodeTable.emplace(key, newNode);
        }
    }

    void removeNode(const string& key) {
        unique_lock<mutex> lock(nodeMutex);
        if (nodeTable.count(key)) {
            auto it = nodeTable.find(key);
            delete[] it->second->key;
            nodeTable.erase(it);
        }
    }

    int getNodeValue(const string& key) {
        unique_lock<mutex> lock(nodeMutex);
        if (nodeTable.count(key)) {
            return nodeTable.at(key)->value;
        } else {
            return -1; // Node not found
        }
    }

    void updateNodeValue(const string& key, int value) {
        unique_lock<mutex> lock(nodeMutex);
        if (nodeTable.count(key)) {
            nodeTable.at(key)->value = value;
        }
    }

    vector<pair<string, int>> getAllNodes() {
        vector<pair<string, int>> result;

        unique_lock<mutex> lock(nodeMutex);

        for (const auto& pair : nodeTable) {
            result.emplace_back(pair.first, pair.second->value);
        }

        return result;
    }
};

int main() {
    MemoryManagementSystem system;

    // Example usage
    system.addNode("key1", 10);
    system.addNode("key2", 20);

    cout << "Value for key 'key1': " << system.getNodeValue("key1") << endl;
    cout << "Value for key 'key2': " << system.getNodeValue("key2") << endl;

    system.updateNodeValue("key1", 30);
    cout << "Updated value for key 'key1': " << system.getNodeValue("key1") << endl;

    vector<pair<string, int>> allNodes = system.getAllNodes();
    for (const auto& pair : allNodes) {
        cout << "Key: " << pair.first << ", Value: " << pair.second << endl;
    }

    return 0;
}
