#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int value;
    long offset;
    int key;
} record;

record* allocate_records(int num_records) {
    // Allocate memory for arrays
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    record* records = (record*)malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        // Handle allocation failure
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize arrays with deterministic sequence generator values
    int seed = 12345; // Custom seed for sequence generator
    for (int i = 0; i < num_records; i++) {
        offsets[i] = ((seed * 1103515245 + 12345) % (1L << 31)) >> 5;
        keys[i] = (seed * 1103515245 + 12345) % (1 << 16);
    }

    // Initialize record values with random integers within specified range
    int min_value = 0, max_value = 100; // Custom range for random integer generation
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % ((max_value - min_value) + 1) + min_value;
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    return records;
}

void free_allocated_memory(record* records, long* offsets, int* keys) {
    // Free allocated memory
    if (records) free(records);
    if (offsets) free(offsets);
    if (keys) free(keys);
}

int main() {
    int num_records = 1000; // Custom number of records for testing
    record* records = allocate_records(num_records);

    if (!records) {
        printf("Memory allocation failed.\n");
    } else {
        // Use allocated memory for processing
        free_allocated_memory(records, NULL, NULL);
    }

    return 0;
}
