#define DATA_RECORD_T struct {
    int timestamp;
    int sensor_id;
    float value;
};
typedef DATA_RECORD_T data_record_t;

#define CACHE_SIZE 1000
int cache[CACHE_SIZE];
int cache_index = 0;
int least_recently_used = -1;

void processAndTransformData(const char *input_file, const char *output_file) {
    FILE *fp_in = fopen(input_file, "rb");
    if (!fp_in) {
        printf("Error opening input file.\n");
        return;
    }

    FILE *fp_out = fopen(output_file, "wb");
    if (!fp_out) {
        printf("Error opening output file.\n");
        fclose(fp_in);
        return;
    }

    data_record_t record;
    float moving_average = 0.0f;
    int count = 0;

    while (fread(&record, sizeof(data_record_t), 1, fp_in)) {
        if (count > 0) {
            moving_average = (moving_average * (count - 1) + record.value) / count;
        }

        // Apply moving average filter
        record.value = moving_average;

        // Cache and evict least recently used entry
        cache[cache_index] = record.timestamp;
        if (++cache_index >= CACHE_SIZE) {
            int min_timestamp = INT_MAX;
            for (int i = 0; i < CACHE_SIZE; ++i) {
                if (min_timestamp > cache[i]) {
                    min_timestamp = cache[i];
                    least_recently_used = i;
                }
            }
            cache_index -= least_recently_used + 1;
        }

        // Write transformed record to output file
        fwrite(&record, sizeof(data_record_t), 1, fp_out);
    }

    fclose(fp_in);
    fclose(fp_out);
}

int main() {
    processAndTransformData("input.bin", "output.bin");
    return 0;
}
```']

