#include <libpq-fe.h>
#include <stdio.h>
#include <stdlib.h>

int configureDatabaseConnection(const char *host, int port, const char *username, const char *password, const char *dbname, void (*callback)(const char *message), void (*errorCallback)(const char *message)) {
    PGconn *conn = PQconnectdbf("host=%s port=%d username=%s password=%s dbname=%s", host, port, username, password, dbname);

    if (PQstatus(conn) == CONNECTION_BAD) {
        errorCallback("Connection failed");
        PQfinish(conn);
        return 1;
    }

    PGresult *res = PQexec(conn, "SELECT 1");

    if (PQresultStatus(res) != PGRES_COMMAND_OK) {
        errorCallback("Query execution failed");
        PQclear(res);
        PQfinish(conn);
        return 1;
    }

    callback("Connection established successfully");
    PQclear(res);
    PQfinish(conn);
    return 0;
}
