    for (int i = 0; i < n; i++) {
        if (xCoordCount >= array_sizes[0]) {
            printf("Error: Too many points requested.\n");
            exit(1);
        }
        double x = doubles[xCoordCount++];
        for (int j = 0; j < array_sizes[2]; j++) {
            if (j % 2 == 0) {
                currentPoint->x = x;
            } else {
                currentPoint->y = rand() / (double)RAND_MAX;
            }
            currentPoint++;
        }
    }

