    int value;
} record_t;

// Caching strategy for random numbers
typedef struct {
    int* cache;
    pthread_mutex_t mutex;
    int cache_size;
    int cache_head;
} rand_cache_t;

rand_cache_t rand_cache;

record_t* create_records(int size) {
    return (record_t*)malloc(size * sizeof(record_t));
}

void init_rand_cache() {
    rand_cache.cache = NULL;
    rand_cache.cache_size = 1000; // Initial cache size
    rand_cache.cache_head = 0;
    pthread_mutex_init(&rand_cache.mutex, NULL);
}

void* generate_random(int min_value, int max_value) {
    if (rand_cache.cache && rand_cache.cache_head > 0) {
        int idx = rand() % rand_cache.cache_head;
        return &rand_cache.cache[idx];
    }

    srand(time(NULL)); // Initialize random seed
    int num = rand() % (max_value - min_value + 1) + min_value;

    pthread_mutex_lock(&rand_cache.mutex);
    if (rand_cache.cache_head >= rand_cache.cache_size) {
        rand_cache.cache_size += 1000;
        rand_cache.cache = realloc(rand_cache.cache, rand_cache.cache_size * sizeof(int));
    }
    rand_cache.cache[rand_cache.cache_head++] = num;
    pthread_mutex_unlock(&rand_cache.mutex);

    return &num;
}

void create_arrays(int size, long* offset_values, int* keys) {
    if (size > MAX_SIZE) {
        printf("Error: Size exceeds maximum allowed value.\n");
        return;
    }

    offset_values = (long*)malloc(size * sizeof(long));
    keys = (int*)malloc(size * sizeof(int));

