#include <stdlib.h>
#include <time.h>

#define MAX_SIZE 1024
#define RAND_RANGE 1000
#define LOG_LEVEL 1 // 0 for error only, 1 for warning and error, 2 for info, warning, and error

typedef struct {
    int key;
    long offset;
} record_t;

record_t* create_records(int num_records) {
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    if (!records) {
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        int val = rand() % RAND_RANGE;
        while (i > 0 && val == ((record_t*)malloc(sizeof(record_t)))->key) {
            val = rand() % RAND_RANGE;
        }
        records[i].key = val;
        records[i].offset = (long)i * sizeof(record_t);
    }
    return records;
}

void free_records(record_t* records, int num_records) {
    if (!records) {
        return;
    }
    for (int i = 0; i < num_records; i++) {
        free(&records[i]);
    }
    free(records);
}

int main() {
    int max_size;
    printf("Enter the maximum size: ");
    scanf("%d", &max_size);

    if (max_size > MAX_SIZE) {
        LOG_ERROR("Maximum size exceeds the limit");
        return -1;
    }

    int num_keys;
    printf("Enter the number of keys: ");
    scanf("%d", &num_keys);

    long* offsets = (long*)malloc(num_keys * sizeof(long));
    if (!offsets) {
        LOG_ERROR("Failed to allocate memory for offset values");
        return -1;
    }

    int* keys = (int*)malloc(num_keys * sizeof(int));
    if (!keys) {
        LOG_ERROR("Failed to allocate memory for key values");
        free(offsets);
        return -1;
    }

    // Initialize and use the external library
    srand(time(NULL));

    record_t* records = create_records(num_keys);

    free_records(records, num_keys);

    return 0;
}
