void manage_cell_list(NR_CELL_INFORMATION_T** cell_list, int* list_size, int threshold) {
    int i, j, new_size = *list_size;
    for (i = 0; i < new_size; i++) {
        if (cell_list[i]->rf_signal_strength > threshold) {
            // purge cells with outdated signal strength
            memmove(cell_list + i, cell_list + i + 1, sizeof(NR_CELL_INFORMATION_T*) * (new_size - i));
            new_size--;
            i--;
        }
    }

    // check for available slots and populate default values if needed
    for (i = new_size; i < *list_size; i++) {
        NR_CELL_INFORMATION_T* cell = malloc(sizeof(NR_CELL_INFORMATION_T));
        cell->cell_id = -1;
        cell->pci = -1;
        cell->rf_signal_strength = 0.0f;
        memmove(cell_list + i, cell_list + new_size, sizeof(NR_CELL_INFORMATION_T*) * (new_size - i));
    }

    for (i = 0; i < new_size; i++) {
        if (!isValidCellInfo(cell_list[i])) {
            // log invalid structure and attempt recovery by populating default values
            printf("Invalid cell information: %d, %d, %.2f\n", cell_list[i]->cell_id, cell_list[i]->pci, cell_list[i]->rf_signal_strength);
            cell_list[i] = malloc(sizeof(NR_CELL_INFORMATION_T));
            cell_list[i]->cell_id = -1;
            cell_list[i]->pci = -1;
            cell_list[i]->rf_signal_strength = 0.0f;
        }
    }

    // query the list for cells within a specified PCI range
    void* find_cells(int start_pci, int end_pci) {
        for (i = 0; i < new_size; i++) {
            if (cell_list[i]->pci >= start_pci && cell_list[i]->pci <= end_pci) {
                // return the found cells
                NR_CELL_INFORMATION_T* result = malloc(sizeof(NR_CELL_INFORMATION_T));
                *result = *cell_list[i];
                free(cell_list[i]);
                return result;
            }
        }
        return NULL;
    }

    *list_size = new_size;
}

// helper function to check if a cell info structure is valid
int isValidCellInfo(NR_CELL_INFORMATION_T* cell) {
    // implement your logic here
    // for example, you can check if the PCI value is within a certain range
    return (cell->pci >= 0 && cell->pci <= 100);
}

