typedef struct {
    float value;
    char word[256];
    unsigned long id;
} profile_t;

// Function to generate random words and numbers using an external library
void* rand_gen_init() {
    // Initialize the random number generator library
    return (void*)randinit();
}

void rand_gen_exit(void* lib) {
    // Clean up resources used by the random number generator library
    exitlib(lib);
}

int profile_array_alloc(int num_profiles, float* values, unsigned long** ids, char*** words, void* lib) {
    if (!values || !ids || !words) return -1;  // Validate input

    // Allocate memory for the arrays and initialize structures
    *values = (float*)malloc(num_profiles * sizeof(float));
    *ids = (unsigned long*)malloc(num_profiles * sizeof(unsigned long));
    *words = (char**)malloc(num_profiles * sizeof(char*));

    if (!(*values) || !(*ids) || !(*words)) {
        // Handle memory allocation error
        free(*values);
        free(*ids);
        for (int i = 0; i < num_profiles; i++) {
            free((*words)[i]);
        }
        free(*words);

        return -1;
    }

    // Initialize arrays and structures
    for (int i = 0; i < num_profiles; i++) {
        (*values)[i] = (float)rand() / RAND_MAX;  // Generate random float values
        (*ids)[i] = rand_ulong(lib);  // Generate random unsigned long identifiers

        char* word = malloc(256 * sizeof(char));
        strcpy(word, rand_word(lib));  // Generate random words using the external library
        (*words)[i] = word;
    }

    return 0;  // Successful allocation and initialization
}

int main() {
    int num_profiles;
    printf("Enter the number of profiles: ");
    scanf("%d", &num_profiles);

    float* values;
    unsigned long* ids;
    char** words;
    void* lib = rand_gen_init();

    if (profile_array_alloc(num_profiles, &values, &ids, &words, lib) == -1) {
        // Handle allocation error
        free(values);
        for (int i = 0; i < num_profiles; i++) {
            free(words[i]);
        }
        free(words);

        rand_gen_exit(lib);  // Clean up resources used by the random number generator library

        return -1;
    }

    // Use the allocated arrays and structures
    printf("Allocated arrays and initialized profiles.\n");

    // Release memory and exit
    for (int i = 0; i < num_profiles; i++) {
        free(words[i]);
    }
    free(words);
    free(ids);
    free(values);

    rand_gen_exit(lib);  // Clean up resources used by the random number generator library

    return 0;
}

