    int seed = 0; // default seed
    int mode = CRYPTO_MODE_NONDETERMINISTIC; // default mode

    // Initialize the random number generator
    if (crypto_random_init(&ctx, seed, mode) != CRYPTO_SUCCESS) {
        printf("Error initializing random number generator!\n");
        return NULL;
    }

    // Allocate memory for records and keys
    record_t* records = my_malloc(sizeof(record_t));
    int* keys = my_malloc(sizeof(int));

    // Validate input to prevent overflow/underflow
    if (max_memory < 0 || min_key > max_key) {
        printf("Invalid input! Memory size must be positive, and min_key <= max_key.\n");
        return NULL;
    }

    // Allocate memory for offset values
    long* offsets = my_malloc(sizeof(long));

    // Generate records based on user-defined parameters
    int num_generated = 0;
    *total_size = 0;

    while (true) {
        record_t rec;
        int key = crypto_random_int(&ctx, range_min, range_max);
        rec.key = key;
        rec.offset = (long)rand() % max_memory; // generate random offset
        records[num_generated] = rec;
        keys[num_generated] = key;

        if (++num_generated >= max_memory / sizeof(record_t)) {
            break;
        }
    }

    *num_records = num_generated;
    return records;
}

