#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Define a struct for each message
typedef struct {
    int timestamp;
    int msgid;
    size_t payload_size;
} Message;

// Define a struct to represent the collection of messages
typedef struct {
    Message *messages; // Array of all messages
    int num_messages;   // Number of messages in the collection
    int capacity;       // Maximum number of messages allowed
} MsgCollection;

// Function to add a new message into the collection
void msg_collection_add(MsgCollection *collection, Message new_message) {
    if (collection->num_messages >= collection->capacity) {
        // Reallocate memory for more messages if necessary
        collection->messages = realloc(collection->messages, sizeof(Message) * (collection->capacity + 10));
        collection->capacity += 10;
    }
    collection->messages[collection->num_messages++] = new_message;
}

// Function to update the payload size of a message using its ID
void msg_collection_update(MsgCollection *collection, int msgid, size_t new_payload_size) {
    for (int i = 0; i < collection->num_messages; i++) {
        if (collection->messages[i].msgid == msgid) {
            collection->messages[i].payload_size = new_payload_size;
            return;
        }
    }
}

// Function to retrieve a message from the collection by its ID
Message* msg_collection_get(MsgCollection *collection, int msgid) {
    for (int i = 0; i < collection->num_messages; i++) {
        if (collection->messages[i].msgid == msgid)
            return &collection->messages[i];
    }
    return NULL;
}

// Function to clean up the message collection
void msg_collection_free(MsgCollection *collection) {
    free(collection->messages);
    memset(collection, 0, sizeof(MsgCollection));
}

// Example usage of the library:
int main() {
    MsgCollection collection = {NULL, 0, 10}; // Initialize a new message collection

    Message message1 = {12345, 1, 1024};
    Message message2 = {67890, 2, 512};
    Message message3 = {11111, 3, 2048};

    msg_collection_add(&collection, message1);
    msg_collection_add(&collection, message2);
    msg_collection_add(&collection, message3);

    Message* retrieved_message = msg_collection_get(&collection, 2);
    printf("Retrieved message ID: %d, Payload size: %zu\n", retrieved_message->msgid, retrieved_message->payload_size);

    msg_collection_update(&collection, 1, 2048);
    retrieved_message = msg_collection_get(&collection, 1);
    printf("Updated message ID: %d, New Payload size: %zu\n", retrieved_message->msgid, retrieved_message->payload_size);

    msg_collection_free(&collection);

    return 0;
}
