// Define the structure for each message
typedef struct {
    int timestamp;
    int id;
    int payload_size;
    int priority; // 0 or 1, where 1 is high priority
} Message;

// Function to initialize the message array
Message **init_messages(int capacity) {
    return (Message **)malloc(sizeof(Message *) * capacity);
}

// Function to add a new message
void add_message(Message ***messages, int capacity, Message *new_msg) {
    if (*messages == NULL || (*messages)[0] != NULL) {
        // Reallocate memory if the array is empty or has no free slots
        *messages = (Message **)realloc(*messages, sizeof(Message *) * (capacity * 2));
        capacity *= 2;
    }
    (*messages)[new_msg->id] = new_msg;
}

// Function to update an existing message
void update_message(Message ***messages, int id, Message *updated_msg) {
    if ((*messages)[id] != NULL) {
        // Update the timestamp and payload size only
        (*messages)[id]->timestamp = updated_msg->timestamp;
        (*messages)[id]->payload_size = updated_msg->payload_size;
    } else {
        printf("Error: Message ID not found.\n");
    }
}

// Function to retrieve a message by its ID
Message *get_message(Message ***messages, int id) {
    return (*messages)[id];
}

// Function to sort messages based on their timestamps in ascending order
void sort_messages(Message **messages, int capacity) {
    Message temp;
    for (int i = 0; i < capacity - 1; i++) {
        for (int j = i + 1; j < capacity; j++) {
            if ((*messages)[i]->timestamp > (*messages)[j]->timestamp) {
                // Swap messages
                temp = (*messages)[i];
                (*messages)[i] = (*messages)[j];
                (*messages)[j] = temp;
            }
        }
    }
}

// Function to clean up allocated resources when the program terminates
void cleanup_messages(Message **messages, int capacity) {
    for (int i = 0; i < capacity; i++) {
        free(messages[i]);
    }
    free(messages);
}
