typedef struct {
    int priority;
    bool status;
    long deadline;
    char description[MAX_DESCRIPTION_LENGTH];
} Project;

void* allocateProject() {
    return malloc(sizeof(Project));
}

void deallocateProject(void* project) {
    free(project);
}

void initializeProjects(int numProjects, void** projects) {
    for (int i = 0; i < numProjects; i++) {
        Project* project = (Project*) allocateProject();
        // Initialize random deadline within range [0, 10000]
        srand(time(NULL));
        project->deadline = rand() % 10001;
        // Set default status to false
        project->status = false;
        projects[i] = project;
    }
}

void updateStatus(void** projects, int index) {
    Project* project = (Project*) projects[index];
    if (project->priority > 5 && !project->status) {
        project->status = true;
    }
}

bool resizeCollection(int numProjects, void*** projects) {
    // Resize only when the number of projects exceeds the threshold
    if (numProjects > PROJECT_CAPACITY) {
        int newSize = PROJECT_CAPACITY * 2;
        *projects = realloc(*projects, newSize * sizeof(void*));
        return true;
    }
    return false;
}

void serializeProjects(int numProjects, void** projects, FILE* file) {
    for (int i = 0; i < numProjects; i++) {
        Project* project = (Project*) projects[i];
        fwrite(&project->priority, sizeof(int), 1, file);
        fwrite(&project->status, sizeof(bool), 1, file);
        fwrite(&project->deadline, sizeof(long), 1, file);
        fwrite(project->description, sizeof(char), strlen(project->description) + 1, file);
    }
}

void deserializeProjects(int* numProjects, void*** projects, FILE* file) {
    *numProjects = 0;
    while (fread(&project, sizeof(Project), 1, file)) {
        (*projects)[(*numProjects)++] = project;
    }
}
