// Structure to represent a record
typedef struct {
    int value;
} Record;

// Function to initialize and manage random number generation
void srandManager(int seed) {
    srand(seed);
}

// Function to generate a random integer within a specified range
int randRange(int min, int max) {
    return (rand() % ((max + 1) - min)) + min;
}

// Function to dynamically allocate memory for and initialize arrays
void* initArrays(const char* configFile, size_t* offsetCount, size_t* keyCount, int** offsets, int** keys) {
    FILE* configFilePtr = fopen(configFile, "r");
    if (configFilePtr == NULL) {
        printf("Failed to open configuration file\n");
        return NULL;
    }

    // Initialize variables based on the content of the configuration file
    fscanf(configFilePtr, "%zu %zu", offsetCount, keyCount);

    // Allocate memory for arrays
    *offsets = (int*)malloc(*keyCount * sizeof(int));
    *keys = (int*)malloc(*keyCount * sizeof(int));

    if (*offsets == NULL || *keys == NULL) {
        printf("Failed to allocate memory for arrays\n");
        fclose(configFilePtr);
        return NULL;
    }

    // Initialize arrays
    for (size_t i = 0; i < *keyCount; i++) {
        fscanf(configFilePtr, "%d", &(*offsets)[i]);
        (*keys)[i] = i;
    }

    fclose(configFilePtr);
    return NULL;
}

// Function to generate and initialize record array
void* initRecords(int** records, int** lastValue, size_t keyCount) {
    // Allocate memory for record array
    *records = (Record*)malloc(keyCount * sizeof(Record));

    if (*records == NULL) {
        printf("Failed to allocate memory for record array\n");
        return NULL;
    }

    // Initialize records
    int lastValueSet = 0;
    for (size_t i = 0; i < keyCount; i++) {
        Record* record = &(*records)[i];
        if (!lastValueSet) {
            *lastValue = &record->value;
            lastValueSet = 1;
        } else {
            do {
                record->value = randRange(1, INT_MAX);
            } while (record->value == (*lastValue));
        }
    }

    return NULL;
}

int main() {
    // Initialize random number generation
    srandManager(time(NULL));

    // Dynamically allocate memory for and initialize arrays
    size_t offsetCount, keyCount;
    int* offsets, *keys;

    initArrays("config.txt", &offsetCount, &keyCount, &offsets, &keys);

    // Generate and initialize record array
    int* lastValue = NULL;
    Record* records;

    initRecords(&records, &lastValue, keyCount);

    return 0;
}
