NFAPI_CRC_INDICATION_PDU_T* initialize_list(int n) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int allocated_count = 0;
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;

    while (n > 0) {
        if (list == NULL && (list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T))) == NULL) {
            // Handle memory allocation failure
            printf("Memory allocation failed. Reducing list size.\n");
            break;
        }

        pthread_mutex_lock(&lock);
        if (list != NULL && allocated_count < n) {
            for (int i = 0; i < TAG_SIZE; i++) {
                ((uint8_t*)list)[i] = (uint8_t)(allocated_count + i);
            }
            list->RX_UE_INFORMATION_TAG = allocated_count;
            list->RNTI = allocated_count % 2 ? 1 : 0;
            list->CRC_INDICATION_REL8_TAG = allocated_count & 1 ? 0x01 : 0x02;
            allocated_count++;
        }
        pthread_mutex_unlock(&lock);
    }

    return list;
}
