def execute_shell_command(command):
    try:
        result = subprocess.check_output(command, shell=True)
        return result.decode('utf-8')
    except subprocess.CalledProcessError as e:
        print(f"Shell command '{command}' failed: {e}")
        return None

def main():
    config = read_config('config.json')
    remote_data = get_remote_data(config['api_url'])
    database_records = process_database_records(remote_data)

    uf = UnionFind(len(database_records))
    disjoint_pairs = set()
    timing_info = {}

    start_time = datetime.now().timestamp() * 1000

    for i in range(len(database_records)):
        for j in range(i + 1, len(database_records)):
            if uf.find(i) == uf.find(j):
                disjoint_pairs.add((i, j))

    end_time = datetime.now().timestamp() * 1000 - start_time
    print(f"Disjoint pairs: {disjoint_pairs}")
    print(f"Time taken for disjointness check: {end_time} milliseconds")

if __name__ == "__main__":
