typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_nfapi_crc_indication_pdu_t(int n) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDATION_PDU_T));
        if (new_node == NULL) {
            // Handle memory allocation error
            printf("Memory allocation failed\n");
            return head;
        }
        new_node->RX_UE_INFORMATION_TAG = rand() % 1000;
        new_node->RNTI = rand() % 500;
        while (!(rand() % 2)) {
            // Ensure CRCFLAG value falls within valid range
            new_node->CRC_INDICATION_REL8_TAG = rand() % 10 + 1;
        }
        if (head == NULL) {
            head = new_node;
        } else {
            NFAPI_CRC_INDATION_PDU_T* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
        }
    }
    return head;
}
