#include <string.h>

struct Cipher {
    EVP_CIPHER_CTX* ctx;
    int is_password_based;
};

Cipher* initialize_cipher(const char* config_file_path, const char* mode, const char* password) {
    Cipher* cipher = malloc(sizeof(struct Cipher));
    if (!cipher) return NULL;

    // Initialize the cipher context
    switch (strncasecmp(mode, "ecb", 3)) {
        case 0:
            cipher->ctx = EVP_CIPHER_CTX_new();
            break;
        case -7: // CBC mode
            cipher->ctx = EVP_CIPHER_CTX_new_bytype_name("AES-128-CBC");
            break;
        case -5: // GCM mode
            cipher->ctx = EVP_CIPHER_CTX_new_bytype_name("AES-128-GCM");
            break;
        default:
            free(cipher);
            return NULL; // unsupported mode
    }

    if (!cipher->ctx) {
        free(cipher);
        return NULL; // initialization failure
    }

    // Handle password-based encryption
    if (password && !strncasecmp(mode, "ecb", 3)) {
        cipher->is_password_based = 1;
        EVP_CIPHER_CTX_set_key_length(cipher->ctx, strlen(password));
        EVP_EncryptInit_ex(cipher->ctx, EVP_aes_128_ecb(), NULL, password, NULL);
    } else {
        cipher->is_password_based = 0;
    }

    return cipher;
}

void cleanup_cipher(Cipher* cipher) {
    if (!cipher) return;
    EVP_CIPHER_CTX_free(cipher->ctx);
    free(cipher);
}
