// Structure to hold RX_UE_INFORMATION_TAG, RNTI and CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
typedef struct {
    char rx_ue_info_tag[16];
    int rnti;
    uint8_t crc_ind_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Structure to hold 'long' offset values, 'int' keys and 'record' structures
typedef struct {
    long offset;
    int key;
    int value;
} record;

void* client_library(void*) {
    // Initialize the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_CONCURRENT_CONNECTIONS * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize concurrently an array of 'long' offset values, an array of 'int' keys and an array of 'record' structures
    record* records = (record*)malloc(MAX_CONCURRENT_CONNECTIONS * sizeof(record));
    pthread_t* threads = (pthread_t*)malloc(MAX_CONCURRENT_CONNECTIONS * sizeof(pthread_t));

    // Initialize the arrays with random data
    srand(time(NULL));
    for(int i = 0; i < MAX_CONCURRENT_CONNECTIONS; i++) {
        crc_indications[i].rx_ue_info_tag[16] = '\0';
        crc_indications[i].rnti = rand() % 100;
        crc_indications[i].crc_ind_rel8_tag = (uint8_t)rand();

        records[i].offset = (long)rand();
        records[i].key = rand() % 100;
        records[i].value = rand() % 100;
    }

    // Initialize the threads
    for(int i = 0; i < MAX_CONCURRENT_CONNECTIONS; i++) {
        pthread_create(&threads[i], NULL, client_thread, &records[i]);
    }

    // Wait for all threads to finish
    for(int i = 0; i < MAX_CONCURRENT_CONNECTIONS; i++) {
