using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace UserDefinedResources
{
    [ApiController]
    [Route("api/[controller]")]
    public class ResourcesController : ControllerBase
    {
        private readonly ResourceDbContext _context;
        private readonly IResourceConfigService _configService;
        private readonly IExternalDataStorageService _dataStorageService;
        private readonly IRateLimiter _rateLimiter;

        public ResourcesController(ResourceDbContext context, IResourceConfigService configService, IExternalDataStorageService dataStorageService, IRateLimiter rateLimiter)
        {
            _context = context;
            _configService = configService;
            _dataStorageService = dataStorageService;
            _rateLimiter = rateLimiter;
        }

        // GET: api/Resource
        [HttpGet]
        public async Task<ActionResult<IEnumerable<Resource>>> GetResources()
        {
            return await _context.Resources.ToListAsync();
        }

        // GET: api/Resource/5
        [HttpGet("{id}")]
        public async Task<ActionResult<Resource>> GetResource(int id)
        {
            var resource = await _context.Resources.FindAsync(id);
            if (resource == null) return NotFound();

            return resource;
        }

        // POST: api/Resource
        [HttpPost]
        public async Task<IActionResult> PostResource([FromBody]Resource resource)
        {
            _rateLimiter.Wait();
            try
            {
                await _dataStorageService.SaveResource(resource);
                return CreatedAtAction(nameof(GetResource), new { id = resource.Id }, resource);
            }
            catch (Exception ex)
            {
                return StatusCode(500, $"Error saving resource: {ex.Message}");
            }
        }

        // PUT: api/Resource/5
        [HttpPut("{id}")]
        public async Task<IActionResult> PutResource(int id, [FromBody]Resource resource)
        {
            _rateLimiter.Wait();
            try
            {
                var existingResource = await _context.Resources.FindAsync(id);
                if (existingResource == null) return NotFound();

                // Optimistic locking: Check for conflicts before updating
                if (!await IsUpdateAllowed(existingResource))
                    return Conflict("Resource has been updated concurrently");

                resource.UpdatedTimestamp = DateTime.UtcNow;
                _dataStorageService.SaveResource(resource);

                return Ok();
            }
            catch (Exception ex)
            {
                return StatusCode(500, $"Error updating resource: {ex.Message}");
            }
        }

        // DELETE: api/Resource/5
        [HttpDelete("{id}")]
        public async Task<IActionResult> DeleteResource(int id)
        {
            _rateLimiter.Wait();
            try
            {
                var resource = await _context.Resources.FindAsync(id);
                if (resource == null) return NotFound();

                _dataStorageService.DeleteResource(resource);

                return NoContent();
            }
            catch (Exception ex)
            {
                return StatusCode(500, $"Error deleting resource: {ex.Message}");
            }
        }

        private async Task<bool> IsUpdateAllowed(Resource existingResource)
        {
            // Check for conflicts by comparing the updated timestamp with the stored version
            if (!existingResource.UpdatedTimestamp.SequenceEqual(resource.UpdatedTimestamp))
                return false;

            return true;
        }
    }
}
