    float value;
    item_state state;
    char* string;
} item;

void init_item_array(item** items, int size) {
    for (int i = 0; i < size; i++) {
        items[i] = malloc(sizeof(item));
        if (!items[i]) {
            // Handle out-of-memory error
            printf("Memory allocation failed.\n");
            return;
        }
        items[i]->value = 0.0f;
        items[i]->state = STATE_INITIALIZED;
        items[i]->string = NULL;

        // Dynamically allocate and initialize the string buffer
        int str_len = 16; // Default length for new strings
        items[i]->string = malloc(str_len * sizeof(char));
        if (!items[i]->string) {
            // Handle out-of-memory error
            printf("Memory allocation failed.\n");
            return;
        }
        memset(items[i]->string, '\0', str_len);
    }
}

void resize_string(item* item_ptr, int new_length) {
    char* old_str = item_ptr->string;
    int new_capacity = new_length * sizeof(char);

    // Reallocate the string buffer with the new capacity
    item_ptr->string = realloc(old_str, new_capacity);
    if (!item_ptr->string) {
        // Handle out-of-memory error
        printf("Memory allocation failed.\n");
        return;
    }

    // Update the length of the string to match the new capacity
    item_ptr->state = STATE_MODIFIED;
}

void free_item_array(item** items, int size) {
    for (int i = 0; i < size; i++) {
        if (items[i]->string) {
            free(items[i]->string);
            items[i]->string = NULL;
        }
        free(items[i]);
    }
}
