int network_communication_and_memory_management(int port, const char* hostname) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock == -1) {
        return -1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    inet_pton(AF_INET, hostname, &(server_addr.sin_addr));
    server_addr.sin_port = htons(port);

    if (connect(sock, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        close(sock);
        return -1;
    }

    int bytes_read = 0;
    char *buffer = (char*)malloc(1024);
    while ((bytes_read = read(sock, buffer, 1024)) > 0) {
        buffer[bytes_read] = '\0';
    }

    if (close(sock) < 0) {
        free(buffer);
        return -1;
    }

    free(buffer);

    double *doubles = (double*)malloc(10000 * sizeof(double));
    short *shorts = (short*)malloc(10000 * sizeof(short));

    for (int i = 0; i < 10000; i++) {
        doubles[i] = rand() / (double)RAND_MAX;
