#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define HASH_TABLE_SIZE 128
#define OFFSET_BASE 0x100000000L

typedef struct {
    int key;
    long offset;
} Record;

Record *records = NULL;
size_t records_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* hash_table[HASH_TABLE_SIZE] = {NULL};

void init_record(Record* record, int key) {
    record->key = key;
    record->offset = OFFSET_BASE + (long)(key * sizeof(Record));
}

int hash_function(int key) {
    return key % HASH_TABLE_SIZE;
}

int is_key_in_hash_table(int key) {
    for (size_t i = 0; i < HASH_TABLE_SIZE; i++) {
        if (hash_table[i] && ((Record*)hash_table[i])->key == key)
            return 1;
    }
    return 0;
}

void add_to_hash_table(Record* record) {
    int index = hash_function(record->key);
    pthread_mutex_lock(&mutex);
    if (!hash_table[index]) {
        hash_table[index] = record;
    } else {
        Record* existing_record = (Record*)hash_table[index];
        // collision resolution strategy: linear probing
        while (((Record*)hash_table[(index + 1) % HASH_TABLE_SIZE])->key != -1) {
            index = (index + 1) % HASH_TABLE_SIZE;
        }
        hash_table[index] = record;
    }
    pthread_mutex_unlock(&mutex);
}

void* allocate_record() {
    Record* new_record = realloc(NULL, sizeof(Record));
    if (!new_record) {
        return NULL;
    }
    init_record(new_record, records_size++);
    add_to_hash_table(new_record);
    return new_record;
}

int get_offset(int key) {
    int index = hash_function(key);
    pthread_mutex_lock(&mutex);
    Record* record = (Record*)hash_table[index];
    if (!record || record->key != key) {
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&mutex);
        return -1; // key not found
    }
    pthread_mutex_unlock(&mutex);
    return record->offset;
}

void free_record(Record* record) {
    int index = hash_function(record->key);
    pthread_mutex_lock(&mutex);
    if (hash_table[index] == record) {
        hash_table[index] = NULL;
    }
    pthread_mutex_unlock(&mutex);
    free(record);
}

int manage_memory(size_t max_memory_limit) {
    size_t total_allocated = 0;
    for (size_t i = 0; i < records_size; i++) {
        Record* record = &records[i];
        total_allocated += sizeof(Record);
        if (total_allocated > max_memory_limit) {
            // reclamation strategy: free unused records
            for (int j = 0; j < i - 1; j++) {
                free_record(&records[j]);
            }
            return -1; // memory limit exceeded, but at least one record remains
        }
    }
    return 0;
}

void* concurrent_access(void* arg) {
    int key = *(int*)arg;
    long offset = get_offset(key);
    if (offset == -1) {
        printf("Key not found: %d\n", key);
        return NULL;
    }
    printf("Accessed record with offset 0x%lx for key %d\n", offset, key);
    return NULL;
}

int main() {
    pthread_t threads[MAX_RECORDS];
    int keys[] = {1, 2, 3, ..., MAX_RECORDS};

    // initialize records from the list of keys
    for (size_t i = 0; i < MAX_RECORDS; i++) {
        Record* record = allocate_record();
        if (!record) {
            printf("Memory allocation failure\n");
            return -1;
        }
    }

    // manage memory dynamically based on the number of records
    size_t max_memory_limit = ...; // specify the maximum allowed memory usage
    while (manage_memory(max_memory_limit)) {
        printf("Memory limit exceeded, freeing unused records...\n");
        // reclamation strategy: free unused records and try again
    }

    // concurrently access and modify records using multiple threads
    for (size_t i = 0; i < MAX_RECORDS; i++) {
        pthread_create(&threads[i], NULL, concurrent_access, &keys[i]);
    }
    for (size_t i = 0; i < MAX_RECORDS; i++) {
        pthread_join(threads[i], NULL);
    }

    // ensure all allocated memory is freed
    for (size_t i = 0; i < records_size; i++) {
        free_record(&records[i]);
    }
    return 0;
}
