    list.size = initial_size;
    list.elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list.size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list.mutex, NULL);
    pthread_cond_init(&list.cond, NULL);
    return list;
}

void crc_list_free(NFAPI_CRC_LIST* list) {
