#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a record structure containing int value and long offset
typedef struct {
    int value;
    long offset;
} record_t;

// Define a hash table structure with collision resolution strategy
typedef struct {
    size_t capacity;
    size_t size;
    record_t** records;
    pthread_mutex_t lock;
} hashtable_t;

// Function to create a new record and initialize its offset based on the record's index
record_t* new_record(size_t idx) {
    record_t* record = (record_t*)malloc(sizeof(record_t));
    if (!record) return NULL; // Handle memory allocation failure

    record->value = idx;
    record->offset = (long)idx * sizeof(int); // Initialize offset based on the record's index
    return record;
}

// Function to create and initialize a new hash table with the given capacity
hashtable_t* new_hashtable(size_t capacity) {
    hashtable_t* table = (hashtable_t*)malloc(sizeof(hashtable_t));
    if (!table) return NULL; // Handle memory allocation failure

    table->capacity = capacity;
    table->size = 0;
    table->records = (record_t**)calloc(capacity, sizeof(record_t*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

// Function to insert a record into the hash table using chaining for collision resolution
void insert_hashtable(hashtable_t* table, record_t* record) {
    size_t idx = record->value % table->capacity; // Hash function

    pthread_mutex_lock(&table->lock); // Lock access to the table

    if (table->records[idx] == NULL) { // Create a new bucket if empty
        table->records[idx] = (record_t*)malloc(sizeof(record_t));
        table->size++;
    }

    // Insert the record into the existing bucket or create a new one if necessary
    record_t* current = table->records[idx];
    while (current) {
        if (current->value == record->value) break; // Find the record with the same value
        current = current->next;
    }

    if (!current) { // Insert the record as a new node in the bucket
        record_t* next = current ? current->next : NULL;
        record->next = next;
        current->next = record;
        table->size++;
    }

    pthread_mutex_unlock(&table->lock); // Unlock access to the table
}

// Function to retrieve a record from the hash table using chaining for collision resolution
record_t* lookup_hashtable(hashtable_t* table, int key) {
    size_t idx = key % table->capacity; // Hash function

    pthread_mutex_lock(&table->lock); // Lock access to the table

    if (table->records[idx]) { // Start searching from the bucket
        record_t* current = table->records[idx];
        while (current) {
            if (current->value == key) break; // Find the record with the same value
            current = current->next;
        }
    }

    pthread_mutex_unlock(&table->lock); // Unlock access to the table

    return current ? current : NULL;
}

// Function to free all allocated memory in the hash table and records
void free_hashtable(hashtable_t* table) {
    if (!table) return;

    for (size_t i = 0; i < table->capacity; i++) {
        record_t* current = table->records[i];
        while (current) {
            record_t* next = current->next;
            free(current);
            current = next;
        }
    }

    free(table->records);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

// Example usage of the function
int main() {
    size_t capacity = 1000; // Set the initial hash table capacity

    hashtable_t* table = new_hashtable(capacity);

    // Insert records into the hash table
    for (size_t i = 0; i < 500; i++) {
        record_t* record = new_record(i);
        if (!record) break; // Handle memory allocation failure
        insert_hashtable(table, record);
    }

    // Perform lookups and operations on the records in the hash table

    free_hashtable(table);

    return 0;
}

