// Custom memory pool structure
typedef struct {
    void* ptr;
    size_t size;
} MemoryPool;

// Record structure containing integer key, long offset value, and statistical metadata
typedef struct {
    int key;
    long offset;
    unsigned int usage_count;
} Record;

// Shared, lock-free data structure to store records
pthread_rwlock_t record_list_lock = PTHREAD_RWLOCK_INITIALIZER;
Record* record_list = NULL;
size_t record_list_size = 0;

// Custom memory pool management function
void* my_malloc(size_t size) {
    // Initialize custom memory pool if not already created
    static pthread_once_t once = PTHREAD_ONCE_INIT;
    pthread_once(&once, init_memory_pool);

    // Allocate memory from custom memory pool or system allocator
    MemoryPool* mp = get_memory_pool();
    void* ptr = mp->ptr;
    size_t mem_size = mp->size;

    if (ptr && size <= mem_size) {
        mp->ptr += size;
        mp->size -= size;
        return ptr;
    }

    // Fallback to system allocator for large allocations or memory pool exhaustion
    return malloc(size);
}

// Release all allocated resources when data processing session ends
void release_resources() {
    // Destroy custom memory pool and free any remaining memory
    destroy_memory_pool();

    // Free system-allocated memory
    free(record_list);

    // Reset shared, lock-free data structure
    pthread_rwlock_destroy(&record_list_lock);
}

// Initialize custom memory pool for efficient memory management
void init_memory_pool() {
    // Create a large initial block of contiguous memory
    size_t initial_size = 1024 * 1024; // 1MB
    void* initial_ptr = malloc(initial_size);

    if (!initial_ptr) {
        printf("Error: Unable to allocate initial memory pool.\n");
        exit(EXIT_FAILURE);
    }

    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->ptr = initial_ptr;
    mp->size = initial_size;

    // Initialize custom memory pool management functions
    my_malloc = &my_malloc;
}

// Prune infrequently accessed records to reduce memory consumption
void prune_records() {
    // Iterate over shared, lock-free data structure
    Record* current = record_list;
    while (current) {
        if (current->usage_count < 5) { // Adjust threshold as needed
            // Remove and free infrequently accessed record
            Record* next = current->next;
            pthread_rwlock_wrlock(&record_list_lock);
            if (!record_list_size--) {
                record_list = next;
            } else {
                current->next = next;
            }
            pthread_rwlock_unlock(&record_list_lock);
            free(current);
        } else {
            current = current->next;
        }
    }
}

// Periodically compact shared, lock-free data structure to mitigate memory fragmentation
void compact_records() {
    // Iterate over shared, lock-free data structure and coalesce adjacent freed memory blocks
    Record* current = record_list;
    while (current) {
        if (!current->next) break;
        size_t block_size = current->next - current;
        if (block_size > 0x10000) { // Adjust threshold as needed
            // Coalesce and free adjacent freed memory blocks
            Record* next = current->next;
            pthread_rwlock_wrlock(&record_list_lock);
            record_list_size -= block_size;
            current->next = NULL;
            pthread_rwlock_unlock(&record_list_lock);
            free(next);
        } else {
            current = current->next;
        }
    }
}
