        int* new_slots = (int*)realloc(ue->downlink_grant_slots, (ue->num_downlink_grants + 1) * sizeof(int));
        double* new_power_levels = (double*)realloc(ue->downlink_grant_power_levels, (ue->num_downlink_grants + 1) * sizeof(double));

        ue->downlink_grant_frames = new_frames;
        ue->downlink_grant_slots = new_slots;
        ue->downlink_grant_power_levels = new_power_levels;
    }

    ue->downlink_grant_frames[ue->num_downlink_grants] = frame_number;
    ue->downlink_grant_slots[ue->num_downlink_grants] = slot_index;
    ue->downlink_grant_power_levels[ue->num_downlink_grants] = power_level;

    ue->num_downlink_grants++;
}

void add_uplink_indicator(UE* ue, time_t timestamp, int flag) {
