record* initRecords(int count) {
    // Generate random key values within a specified range to avoid collisions
    srand(time(NULL));
    int minKey = 1, maxKey = 100;
    record* records = (record*)malloc(count * sizeof(record));

    for (int i = 0; i < count; i++) {
        int key = rand() % (maxKey - minKey) + minKey;
        if (i > 0 && key == records[i-1].key) {
            // Ensure no consecutive records have the same key value
            while (records[i-1].key == key) {
                key = rand() % (maxKey - minKey) + minKey;
            }
        }
        records[i].offset = i;
        records[i].key = key;
        records[i].data = 0.0; // Initialize data value
    }

    return records;
}

void freeRecords(record* records, int count) {
    free(records);
}

int main() {
    int recordCount = 10000;
    record* records = initRecords(recordCount);

    // Now you can use the records array for your application

    freeRecords(records, recordCount);
    return 0;
