// Function to generate a unique filename from an original filename
char* generate_unique_filename(const char* dir_path, const char* original_filename) {
    // Calculate the length of the original filename
    size_t len = strlen(original_filename);

    // Initialize variables for extracting letters and appending random characters
    int i;
    char first_three_uppercase[4];
    char last_three_lowercase[4];
    char identifier[8];
    srand(time(NULL));  // Seed the random number generator

    // Extract the first three uppercase letters and last three lowercase letters from the original filename
    for (i = 0; i < 3; i++) {
        first_three_uppercase[i] = toupper(original_filename[i]);
    }
    for (i = len - 4; i < len; i++) {
        last_three_lowercase[i - len + 4] = tolower(original_filename[i]);
    }

    // Initialize the identifier
    strncpy(identifier, first_three_uppercase, 3);
    identifier[3] = '\0';
    for (i = 0; i < 5; i++) {
        identifier[3 + i] = (char)('a' + rand() % 26);
    }
    identifier[8] = '\0';

    // Initialize the new filename
    char* new_filename = malloc(strlen(dir_path) + strlen(identifier) + 2);
    strcpy(new_filename, dir_path);
    strcat(new_filename, "/");
    strcat(new_filename, identifier);

    return new_filename;
}

// Function to verify the uniqueness of a filename and generate a unique one if necessary
char* generate_unique_filename_in_directory(const char* dir_path, const char* original_filename) {
    // Calculate the length of the original filename
    size_t len = strlen(original_filename);

    // Initialize variables for appending numeric suffixes
    int i;
    char* new_filename = malloc(strlen(dir_path) + 8);
    strcpy(new_filename, dir_path);
    strcat(new_filename, "/");

    // Initialize the filename and its length
    size_t file_len = 0;

    // Verify the uniqueness of the original filename and generate a unique one if necessary
    for (i = 1; ; i++) {
        char* temp_filename = malloc(strlen(new_filename) + 8);
        strcpy(temp_filename, new_filename);
        sprintf(temp_filename + strlen(temp_filename), "%d", i);

        // Check if the generated filename is already in use
        struct stat sb;
        if (stat(temp_filename, &sb) == -1) {
            file_len = strlen(temp_filename);
            break;
        }
        free(temp_filename);
    }

    return new_filename;
}

int main() {
    // Example usage
    const char* dir_path = "path/to/directory";
    const char* original_filename = "example.txt";

    char* new_filename = generate_unique_filename(dir_path, original_filename);
    printf("New filename: %s\n", new_filename);

    return 0;
}
