void init_device(Device* dev, const char* id) {
    strcpy(dev->id, id);
    dev->timestamp = time(NULL);
    dev->packet_loss_rate = (float)rand() / RAND_MAX;
    dev->throughput = (float)rand() / RAND_MAX;
    dev->latency = (float)rand() / RAND_MAX;
}

void* allocate_device(void) {
    Device* new_dev = (Device*)malloc(sizeof(Device));
    if (!new_dev) {
        return NULL; // handle memory allocation failure
    }
    init_device(new_dev, "device_");
    return new_dev;
}

void resize_device_list(int threshold) {
    int old_capacity = capacity;
    capacity += threshold;
    Device* new_list = (Device*)realloc(device_list, sizeof(Device) * capacity);
    if (!new_list) {
        device_count = old_capacity; // handle memory allocation failure
    } else {
        device_list = new_list;
    }
}

void check_device_health() {
    for (int i = 0; i < device_count; i++) {
        Device* dev = &device_list[i];
        if (dev->packet_loss_rate > 0.1 || dev->throughput < 100) { // threshold
            printf("Alert: %s - Packet loss rate %.2f, Throughput %.2f\n", dev->id, dev->packet_loss_rate, dev->throughput);
        }
    }
}

void filter_devices(float packet_loss_threshold) {
    for (int i = 0; i < device_count; i++) {
        Device* dev = &device_list[i];
        if (dev->packet_loss_rate > packet_loss_threshold) {
            printf("Warning: %s - Packet loss rate %.2f\n", dev->id, dev->packet_loss_rate);
        }
    }
}

int main() {
    srand(time(NULL)); // seed random number generator

    for (int i = 0; i < capacity; i++) {
        device_list[i] = *allocate_device();
    }
    device_count = capacity;

    while (1) {
        check_device_health();
        sleep(10); // simulate monitoring interval
    }

    return 0;
}

