void manageFrames(struct NFAPI_UL_RX_FRAME_PDU_T** frames, size_t* frame_count, size_t max_frames) {
    if (*frame_count >= max_frames) {
        return; // Array is full
    }

    *frames = realloc(*frames, sizeof(NFAPI_UL_RX_FRAME_PDU_T*) * (max_frames + 1));
    if (!*frames) {
        printf("Memory allocation failed\n");
        return;
    }

    (*frames)[*frame_count] = malloc(sizeof(NFAPI_UL_RX_FRAME_PDU_T));
    if (!(*frames)[*frame_count]) {
        printf("Memory allocation failed\n");
        free(*frames);
        *frames = NULL;
        return;
    }

    (*frames)[*frame_count]->RX_FRAME_INDICATION_TAG = 0; // Initialize tag
    (*frames)[*frame_count]->UE_ID = 0; // Initialize UE ID
    (*frames)[*frame_count]->buffer = malloc(1024); // Allocate buffer for frame data

    if (!(*frames)[*frame_count]->buffer) {
        printf("Memory allocation failed\n");
        free((*frames)[*frame_count]);
        (*frames)[*frame_count] = NULL;
        return;
    }

    (*frame_count)++;
}

void updateFrame(struct NFAPI_UL_RX_FRAME_PDU_T** frames, size_t frame_index, uint8_t new_tag, uint32_t new_ue_id) {
    if (frame_index >= *frames) {
        printf("Invalid frame index\n");
        return;
    }

    frames[frame_index]->RX_FRAME_INDICATION_TAG = new_tag;
    frames[frame_index]->UE_ID = new_ue_id;
}

void freeFrame(struct NFAPI_UL_RX_FRAME_PDU_T** frames, size_t frame_index) {
    if (frame_index >= *frames) {
        printf("Invalid frame index\n");
        return;
    }

    free(frames[frame_index]->buffer);
    free(frames[frame_index]);
}

int main() {
    struct NFAPI_UL_RX_FRAME_PDU_T* frames = NULL;
    size_t frame_count = 0;
    size_t max_frames = 10;

    manageFrames(&frames, &frame_count, max_frames);

    updateFrame(&frames, 0, 1, 2);
    freeFrame(&frames, 0);

    return 0;
}
