```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MEMORY_LIMIT 1024 * 1024 * 10
#define GRACE_PERIOD 30 // seconds

typedef struct {
    int key;
    int value;
    time_t last_accessed;
} Record;

typedef struct node {
    Record record;
    struct node* next;
} Node;

typedef struct {
    size_t size;
    void** keys;
    Record** records;
    Node** deleted_records;
    pthread_mutex_t lock;
} HashTable;

HashTable* hash_table_init(size_t initial_size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = initial_size;
    table->keys = (void**)malloc(initial_size * sizeof(void*));
    table->records = (Record**)malloc(initial_size * sizeof(Record*));
    table->deleted_records = (Node*)malloc(initial_size * sizeof(Node));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

int hash_function(size_t key, size_t table_size) {
    return key % table_size;
}

void resize_hash_table(HashTable* table) {
    HashTable* new_table = hash_table_init(table->size * 2);
    for (size_t i = 0; i < table->size; i++) {
        if (table->keys[i]) {
            size_t index = hash_function(*(int*)table->keys[i], new_table->size);
            Node* node = &new_table->deleted_records[index];
            while (node) {
                Record record = node->record;
                node = node->next;
                insert_record(new_table, *(int*)table->keys[i], record.value);
            }
        }
    }
    free(table->keys);
    free(table->records);
    free(table->deleted_records);
    *table = *new_table;
}

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr && size > 0) {
        // Handle memory allocation failure
        return NULL;
    }
    return ptr;
}

int insert_record(HashTable* table, int key, int value) {
    size_t index = hash_function(key, table->size);
    Record record = {key, value, time(NULL)};
    if (table->records[index]) {
        // Handle collision
        Node* node = &table->deleted_records[index];
        while (node->next) {
            node = node->next;
        }
        node->record = record;
    } else {
        table->keys[index] = &key;
        table->records[index] = &record;
    }
    return 0;
}

void free_records(HashTable* table, time_t current_time) {
    for (size_t i = 0; i < table->size; i++) {
        if (table->records[i]) {
            Record record = *table->records[i];
            if (record.last_accessed + GRACE_PERIOD < current_time) {
                // Free record
                Node* node = &table->deleted_records[i];
                while (node) {
                    Record deleted_record = node->record;
                    node = node->next;
                    free(deleted_record.value);
                    free((void*)table->keys[i]);
                    table->keys[i] = NULL;
                    table->records[i] = NULL;
                }
            }
        }
    }
}

int main() {
    // Initialize data structures
    HashTable* table = hash_table_init(16);

    // Insert records and handle memory allocation failures
    for (size_t i = 0; i < MAX_RECORDS; i++) {
        int key = rand();
        int value = rand();
        if (!insert_record(table, key, value)) {
            printf("Record inserted successfully!\n");
        } else {
            // Handle memory allocation failure
            printf("Memory allocation failed! Aborting...\n");
            return 1;
        }
    }

    // Resize hash table as necessary
    while (table->size < MAX_RECORDS) {
        resize_hash_table(table);
    }

    // Free records that have not been accessed in the specified grace period
    time_t current_time = time(NULL);
    free_records(table, current_time);

    return 0;
}
