    // Add more states as needed
};

// Define structure for item
typedef struct {
    float floating_value;
    enum state state_value;
    char* string_value;
} item;

// Function to manage dynamic memory allocation for array of item structures
void* (*item_array_manager)(int, size_t);

void* item_array_manager_allocate(int n, size_t size) {
    // Initialize logging module
    log_memory_allocation(n * size);

    // Dynamically allocate memory for array
    void* arr = malloc(n * size);
    if (arr == NULL) {
        log_error("Out-of-memory condition");
        return NULL;
    }

    // Initialize each item in the array with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < n; i++) {
        item* item_ptr = arr + i * size;
        item_ptr->floating_value = (float)rand() / RAND_MAX;
        item_ptr->state_value = rand() % (STATE_1 + STATE_2 - STATE_1);

        // Dynamically allocate memory for string
        size_t string_size = 16; // Initial buffer size for strings
        char* string_ptr = malloc(string_size * sizeof(char));
        if (string_ptr == NULL) {
            log_error("Out-of-memory condition");
            return NULL;
        }

        sprintf(string_ptr, "CRC_FLAG_%d", rand() % (STATE_1 + STATE_2 - STATE_1));
        item_ptr->string_value = string_ptr;
    }

    // Update logging module with array allocated
    log_memory_allocation(n * size);

    return arr;
