#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for a TrafficEvent
typedef struct {
    time_t timestamp;
    int type;
    char *payload;
} TrafficEvent;

// Define a structure to represent the traffic management system
typedef struct {
    TrafficEvent **events; // dynamic array of events
    size_t capacity; // current capacity of the event list
    pthread_mutex_t lock; // mutex for concurrent access
    FILE *log_file; // file pointer for logging
} TrafficSystem;

// Initialize the traffic management system
TrafficSystem* init_traffic_system(size_t initial_capacity) {
    TrafficSystem* system = (TrafficSystem*) malloc(sizeof(TrafficSystem));
    system->events = (TrafficEvent**) calloc(initial_capacity, sizeof(TrafficEvent*));
    system->capacity = initial_capacity;
    pthread_mutex_init(&system->lock, NULL);
    system->log_file = fopen("traffic.log", "a");
    return system;
}

// Insert a new TrafficEvent into the system
void insert_traffic_event(TrafficSystem* system, TrafficEvent* event) {
    pthread_mutex_lock(&system->lock);

    // Check if the system needs to resize its capacity
    if (system->capacity == system->events[0]->count + 1) {
        system->events = (TrafficEvent**) realloc(system->events,
            sizeof(TrafficEvent*) * (2 * system->capacity));
        system->capacity *= 2;
    }

    // Insert the event at the end of the array
    system->events[system->events[0]->count] = event;

    pthread_mutex_unlock(&system->lock);

    // Log the insertion action
    fprintf(system->log_file, "Inserted event {%ld, %d, %s} at timestamp {%ld}\n",
        event->timestamp, event->type, event->payload, event->timestamp);
}

// Delete a TrafficEvent from the system
void delete_traffic_event(TrafficSystem* system, size_t index) {
    pthread_mutex_lock(&system->lock);

    // Shift all events after the deleted one down
    for (size_t i = index; i < system->events[0]->count - 1; i++) {
        system->events[i] = system->events[i + 1];
    }

    // Decrement the count of events
    system->events[0]->count--;

    pthread_mutex_unlock(&system->lock);

    // Log the deletion action
    fprintf(system->log_file, "Deleted event at index %zu\n", index);
}

// Print all TrafficEvents in the system
void print_traffic_events(TrafficSystem* system) {
    pthread_mutex_lock(&system->lock);

    for (size_t i = 0; i < system->events[0]->count; i++) {
        printf("Event {%ld, %d, %s}\n", system->events[i]->timestamp,
            system->events[i]->type, system->events[i]->payload);
    }

    pthread_mutex_unlock(&system->lock);
}

// Free memory allocated by the traffic management system
void free_traffic_system(TrafficSystem* system) {
    pthread_mutex_lock(&system->lock);

    for (size_t i = 0; i < system->events[0]->count; i++) {
        free(system->events[i]->payload);
        free(system->events[i]);
    }

    free(system->events);
    fclose(system->log_file);
    pthread_mutex_unlock(&system->lock);
}

int main() {
    // Initialize the traffic management system with an initial capacity of 10
    TrafficSystem* system = init_traffic_system(10);

    // Simulate concurrent insertions and deletions from multiple threads
    pthread_t threads[5];
    for (size_t i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, thread_func, system);
    }

    // Wait for all threads to finish
    for (size_t i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    // Print all TrafficEvents in the system
    print_traffic_events(system);

    // Free memory allocated by the traffic management system
    free_traffic_system(system);

    return 0;
}

// Define a thread function to simulate concurrent operations
void* thread_func(void* arg) {
    TrafficSystem* system = (TrafficSystem*) arg;

    for (size_t i = 0; i < 5; i++) {
        // Insert random events into the system
        insert_traffic_event(system, create_random_event());

        // Delete random events from the system
        delete_traffic_event(system, rand() % system->events[0]->count);
    }

    return NULL;
}

// Define a function to create a random TrafficEvent
TrafficEvent* create_random_event() {
    TrafficEvent* event = (TrafficEvent*) malloc(sizeof(TrafficEvent));
    event->timestamp = time(NULL);
    event->type = rand() % 2; // Randomly generate event type (0 or 1)
    event->payload = (char*) malloc(rand() % 10 + 1); // Randomly generate payload
    for (size_t i = 0; i < rand() % 10 + 1; i++) {
        event->payload[i] = (char) ('a' + rand() % 26); // Generate random characters
    }
    event->payload[rand() % 10 + 1] = '\0'; // Terminate the payload string

    return event;
}

// Define a function to clean up memory allocation failures
void handle_memory_allocation_failure() {
    printf("Memory allocation failure! Terminating.\n");
    exit(1);
}
