        printf("Error serializing measurement reports to file!\n");
    }

    fclose(filePtr);

    // Handle cases where measurement results exceed predefined limits by validating and logging
    for (i = 0; i < numReports; i++) {
        if (ueMeasurementReports[i].MEASUREMENT_RESULT_REL16_TAG.resultValue > MAX_MEASUREMENT_RESULT_VALUE) {
            fprintf(stderr, "Invalid measurement result value: %d\n", ueMeasurementReports[i].MEASUREMENT_RESULT_REL16_TAG.resultValue);
        }
    }

    // Clean up allocated resources
    free(ueMeasurementReports);
}
