char* generate_unique_id(const char* filename, int length) {
    // extract first three uppercase letters and last three lowercase letters
    char* id = (char*)malloc((length + 1) * sizeof(char));
    strncpy(id, &filename[0], 3);
    for (int i = 0; i < 3; i++) {
        if (!isupper(filename[i])) {
            // handle error: non-uppercase character in filename
            return NULL;
        }
    }
    for (int i = strlen(filename) - 4; i >= strlen(filename) - 6; i--) {
        id[3 + i] = filename[i];
    }
    // pad with zeros and random alphanumeric characters if necessary
    for (int i = 0; i < length - 6; i++) {
        id[3 + i] = 'a' + rand() % 26;
    }
    return id;
}

char* generate_unique_filename(const char* directory, const char* filename) {
    // generate unique ID
    int length = strlen(filename);
    if (length > 8) {
        length -= 4; // truncate ID and append random characters
    } else {
        length += 3 + rand() % 10;
    }
    char* id = generate_unique_id(filename, length);
    if (!id) {
        return NULL;
    }

    // construct new filename
    char* new_filename = (char*)malloc((strlen(directory) + length + 1) * sizeof(char));
    strcpy(new_filename, directory);
    strcat(new_filename, "/");
    strcat(new_filename, id);
    free(id); // release ID memory

    // ensure new filename does not exceed 256 characters
    if (strlen(new_filename) > 256) {
        char* trimmed_directory = (char*)malloc((256 - length - 1) * sizeof(char));
        strncpy(trimmed_directory, new_filename + strlen(directory), 256 - length);
        free(new_filename); // release original filename memory
        return trimmed_directory;
    }

    return new_filename;
}

int main() {
    srand(time(NULL)); // seed random number generator
    int num_records = 1000; // adjust as necessary
    record_t* records = allocate_records(num_records);
    if (!records) {
        // handle memory allocation failure
        return -1;
    }

    char* directory = "/path/to/directory";
    const char* filename = "original_filename.txt"; // adjust as necessary
    char* new_filename = generate_unique_filename(directory, filename);
    if (!new_filename) {
        // handle error: unique filename generation failure
        return -1;
    }

    free(records); // release record memory
    free(new_filename); // release new filename memory

    return 0;
}
