NR CELL_HEALTH_REPORT_T* populate_reports(int num_reports) {
    NR_CELL_HEALTH_REPORT_T *reports = NULL;
    srand(time(NULL));

    // Create a hash table to manage unique cell_id values
    int *unique_cell_ids = (int *)malloc(sizeof(int) * 100);
    int unique_cell_id_count = 0;

    for (int i = 0; i < num_reports; i++) {
        NR_CELL_HEALTH_REPORT_T report;

        // Generate a unique cell_id
        while (1) {
            report.cell_id = rand() % 1000 + 1;
            int exists = 0;
            for (int j = 0; j < unique_cell_id_count; j++) {
                if (report.cell_id == unique_cell_ids[j]) {
                    exists = 1;
                    break;
                }
            }
            if (!exists) {
                break;
            }
        }

        // Fill in other report fields
        report.rx_quality = rand() % 100 / 100.0f;
        sprintf(report.channel_usage_pattern, "Pattern_%d", i);
        report.power_level = (rand() % 30 + 1) / 10.0f;
        report.timestamp = time(NULL);

        // Add the report to the array
        if (i == 0) {
            reports = (NR_CELL_HEALTH_REPORT_T *)malloc(sizeof(NR_CELL_HEALTH_REPORT_T) * num_reports);
        }
        reports[i].cell_id = report.cell_id;
        reports[i].rx_quality = report.rx_quality;
        strcpy(reports[i].channel_usage_pattern, report.channel_usage_pattern);
        reports[i].power_level = report.power_level;
        reports[i].timestamp = report.timestamp;

        // Update the unique_cell_ids hash table
        if (unique_cell_id_count < 100) {
            unique_cell_ids[unique_cell_id_count] = report.cell_id;
            unique_cell_id_count++;
        }
    }

    free(unique_cell_ids);

    return reports;
}
