typedef struct node {
    char* str;
    int timestamp;
    int ref_count;
} Node;

Node* create_node(char* dir, char* filename) {
    Node* node = (Node*)malloc(sizeof(Node));

    // Generate unique identifier
    time_t t = time(NULL);
    char id[5];
    sprintf(id, "%02x%02x", (t / 10000) % 256, (t % 10000) % 256);
    while (strlen(id) < 4) {
        strcat(id, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789");
    }

    // Trim filename if it exceeds limit
    char path[128];
    int len = strlen(dir);
    if (len + strlen(filename) + strlen(id) > 127) {
        len -= 1;
        while (dir[len] != '/') {
            len--;
        }
        strcpy(path, dir);
        path[len] = '\0';
    } else {
        strcpy(path, dir);
    }

    // Generate new filename
    char* new_filename = (char*)malloc(strlen(path) + strlen(id) + 2);
    sprintf(new_filename, "%s/%s%s", path, id, "");
    int i = 1;
    while (access(new_filename, F_OK) == 0) {
        free(new_filename);
        sprintf(new_filename, "%s/%s%02d", path, id, i++);
    }

    node->str = new_filename;
    node->timestamp = t;
    node->ref_count = 1;

    return node;
}

int main() {
    // Example usage
    Node* nodes[10];
    DIR* dir = opendir("/path/to/directory");
    struct dirent* ent;
    int i = 0;
    while ((ent = readdir(dir))) {
        if (ent->d_type == DT_REG) { // Check for regular file
            char filename[1024] = ent->d_name;
            nodes[i++] = create_node("/path/to/directory", filename);
        }
    }

    closedir(dir);

    return 0;
}
