    if (!array) return NULL;

    for (int i = 0; i < size; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand() % 65535;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        array[i].CRCFLAG = rand() & 1;

        // Validate uniqueness of RX_UE_INFORMATION_TAG and RNTI
        for (int j = 0; j < i; j++) {
            if (array[i].RX_UE_INFORMATION_TAG == array[j].RX_UE_INFORMATION_TAG || 
                array[i].RNTI == array[j].RNTI) {
                printf("Duplicate found: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", array[i].RX_UE_INFORMATION_TAG, array[i].RNTI);
                return NULL;
            }
        }
    }

    // Sort the array by RX_UE_INFORMATION_TAG
    qsort(array, size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_tags);

    if (size > max_size) {
        printf("Memory usage exceeds configured limit: %d/%d\n", size, max_size);
    } else {
        printf("Memory usage within limit: %d/%d\n", size, max_size);
    }

