// Define a custom record structure
typedef struct {
    long offset;
    int key;
    float data;
} record_t;

// Define an external memory management library
extern void* my_malloc(size_t size);
extern void my_free(void* ptr);

// Function to manage memory allocation and initialization
int manage_memory_allocation(int numOffsets, int numKeys, int numDataPoints, long minOffset, long maxOffset, int minKey, int maxKey, float minData, float maxData) {
    // Calculate total memory required for arrays
    size_t totalBytes = sizeof(long) * numOffsets + sizeof(int) * numKeys + sizeof(float) * numDataPoints;

    // Check if total memory exceeds the budget
    if (totalBytes > 1024*1024*10) { // Assuming a 10MB budget
        // Reduce array sizes proportionally to meet budget constraint
        int reducedNumOffsets = numOffsets - (numOffsets / 2);
        int reducedNumKeys = numKeys - (numKeys / 2);
        int reducedNumDataPoints = numDataPoints - (numDataPoints / 2);

        totalBytes = sizeof(long) * reducedNumOffsets + sizeof(int) * reducedNumKeys + sizeof(float) * reducedNumDataPoints;
    }

    // Allocate and initialize arrays
    long* offsets = my_malloc(totalBytes);
    int* keys = my_malloc(sizeof(int) * numKeys);
    float* dataPoints = my_malloc(sizeof(float) * numDataPoints);

    for (int i = 0; i < reducedNumOffsets; i++) {
        offsets[i] = (rand() % (maxOffset - minOffset)) + minOffset;
    }

    for (int i = 0; i < reducedNumKeys; i++) {
        keys[i] = (rand() % (maxKey - minKey)) + minKey;
    }

    for (int i = 0; i < reducedNumDataPoints; i++) {
        dataPoints[i] = (float)(rand() / (double)RAND_MAX * (maxData - minData) + minData);
    }

    // Initialize array of record structures
    record_t* records = my_malloc(sizeof(record_t) * numOffsets);

    for (int i = 0; i < numOffsets; i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i % reducedNumKeys];
        records[i].data = dataPoints[i % reducedNumDataPoints];
    }

    // Serialize initialized data structures into a binary file
    FILE* file = fopen("data.bin", "wb");
    fwrite(&records, sizeof(record_t), numOffsets, file);
    fclose(file);

    return 0;
}
