                size_t new_cache_size = cache_size + 16;
                void** new_cache = (void**)realloc(cache, new_cache_size * sizeof(void*));
                if (!new_cache) return; // Handle memory allocation failure

                for (size_t j = cache_size; j < new_cache_size; j++) {
                    new_cache[j] = NULL;
