typedef struct {
    int timestamp;
    char status;
    double priority;
} TaskIdentifier;

void* allocate_and_initialize_tasks(size_t max_memory, size_t* count) {
    void* memory = NULL;
    size_t total_size = 0;

    // Initialize random seed
    srand(time(NULL));

    while (total_size < max_memory) {
        size_t array_size = rand() % 10 + 1; // Randomly generated array size
        double* doubles_array = (double*)malloc(array_size * sizeof(double));
        TaskIdentifier* tasks_array = (TaskIdentifier*)malloc(array_size * sizeof(TaskIdentifier));

        for (size_t i = 0; i < array_size; i++) {
            // Generate random job description and timestamp
            char job_description[10];
            int timestamp = rand() % 100000 + 1;
            int status = 'N'; // New task
            double priority = ((double)rand()) / RAND_MAX;

            // Ensure no two consecutive tasks share the same job description or timestamp
            while (i > 0 && memcmp(job_description, &tasks_array[i-1].status, sizeof(char)) == 0)
                timestamp++;

            strcpy(job_description, "Task ");
            itoa(timestamp, job_description + 6, 10);

            // Populate TaskIdentifier structs
            tasks_array[i].timestamp = timestamp;
            tasks_array[i].status = status;
            tasks_array[i].priority = priority;

            if (i > 0 && memcmp(&job_description[0], &tasks_array[i-1].status, sizeof(char)) == 0)
                tasks_array[i].status = 'R'; // Running task
        }

        total_size += array_size * sizeof(double) + array_size * sizeof(TaskIdentifier);
        memory = realloc(memory, total_size);

        if (memory == NULL || total_size > max_memory) {
            free(memory);
            return NULL;
        }

        // Update count and reset arrays
        for (size_t i = 0; i < array_size; i++) {
            doubles_array[i] = ((double)i); // Initialize with incremental values
            tasks_array[i].timestamp += i; // Ensure timestamps are unique
        }
    }

    *count = total_size / sizeof(double);
    return memory;
}
