#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    long offset;
    int key;
} record_t;

record_t* records = NULL;
long* offsets = NULL;
int* keys = NULL;
int num_records = 0;
int max_records = 10;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = fopen("log.txt", "w");

void* allocate(int size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(log_file, "Memory allocation failed\n");
        return NULL;
    }
    return ptr;
}

void deallocate(void* ptr) {
    free(ptr);
}

int init_records() {
    records = (record_t*)allocate(sizeof(record_t) * max_records);
    offsets = (long*)allocate(sizeof(long) * max_records);
    keys = (int*)allocate(sizeof(int) * max_records);
    for (int i = 0; i < max_records; i++) {
        records[i].value = rand() % 100;
        records[i].offset = i;
        records[i].key = i;
    }
    num_records = max_records;
    return 0;
}

void free_records() {
    deallocate(records);
    deallocate(offsets);
    deallocate(keys);
    records = NULL;
    offsets = NULL;
    keys = NULL;
    num_records = 0;
}

int add_record(int value, long offset, int key) {
    pthread_mutex_lock(&lock);
    if (num_records >= max_records) {
        fprintf(log_file, "Record list is full\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }
    records[num_records].value = value;
    records[num_records].offset = offset;
    records[num_records].key = key;
    offsets[num_records] = offset;
    keys[num_records] = key;
    num_records++;
    pthread_mutex_unlock(&lock);
    return 0;
}

int main() {
    srand(time(NULL));
    init_records();
    // Add records
    add_record(10, 1, 2);
    add_record(20, 3, 4);
    // Periodic updates from external data source
    pthread_t thread;
    pthread_create(&thread, NULL, update_thread, NULL);
    return 0;
}

void* update_thread(void*) {
    while (1) {
        // Update records
        for (int i = 0; i < num_records; i++) {
            if (records[i].value % 2 == 0) {
                records[i].value++;
            }
        }
        sleep(5); // Periodic update interval
    }
    return NULL;
}

void log_error(char* message) {
    fprintf(log_file, "%s\n", message);
}
