    for (int i = 0; i < *size; i++) {
        if ((*list)[i].RNTI == rnti) {
            memmove(&(*list)[i], &(*list)[i + 1], (*size - i - 1) * sizeof(NFAPI_CRC_INDATION_PDU_T));
            (*size]--;
            return;
        }
