```c
#include <stdlib.h>
#include <stdio.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

typedef struct {
    int value;
} record;

typedef struct {
    int* keys;
    long* offsets;
    record** data;
} collection;

collection* init_collection(size_t initial_size) {
    collection* coll = (collection*)malloc(sizeof(collection));
    coll->keys = (int*)calloc(initial_size, sizeof(int));
    coll->offsets = (long*)calloc(initial_size, sizeof(long));
    coll->data = (record**)calloc(initial_size, sizeof(record*));
    return coll;
}

void resize_collection(collection* coll, size_t new_size) {
    coll->keys = (int*)realloc(coll->keys, new_size * sizeof(int));
    coll->offsets = (long*)realloc(coll->offsets, new_size * sizeof(long));
    coll->data = (record**)realloc(coll->data, new_size * sizeof(record*));
}

void add_record(collection* coll, int key, long offset, record* rec) {
    for (size_t i = 0; i < coll->keys[0]; ++i) {
        if (coll->keys[i] == key && coll->offsets[i] == offset) {
            printf("Error: Record already exists.\n");
            return;
        }
    }
    coll->keys[coll->keys[0]] = key;
    coll->offsets[coll->keys[0]] = offset;
    coll->data[coll->keys[0]] = rec;
}

record* get_record(collection* coll, int key, long offset) {
    for (size_t i = 0; i < coll->keys[0]; ++i) {
        if (coll->keys[i] == key && coll->offsets[i] == offset) {
            return coll->data[i];
        }
    }
    printf("Error: Record not found.\n");
    return NULL;
}

int main() {
    collection* coll = init_collection(10);
    for (size_t i = 0; i < coll->keys[0]; ++i) {
        record* rec = (record*)malloc(sizeof(record));
        rec->value = rand() % 100 + 1;
        add_record(coll, rand() % 100 + 1, rand(), rec);
    }
    for (size_t i = 0; i < coll->keys[0]; ++i) {
        record* rec = get_record(coll, rand() % 100 + 1, rand());
        if (rec != NULL) {
            printf("Record value: %d\n", rec->value);
        }
    }
    return 0;
}
