// Module initialization function
NFAPICRCList* NFAPICRCList_init(int initial_capacity) {
    NFAPICRCList* list = (NFAPICRCList*)malloc(sizeof(NFAPICRCList));
    list->size = 0;
    list->capacity = initial_capacity;
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(list->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return list;
}

// Add new element to the list
int NFAPICRCList_add(NFAPICRCList* list, NFAPI_CRC_INDICATION_PDU_T new_element) {
    if (list->size >= list->capacity) {
        // Resize the list with increased capacity
        int new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            return -1; // Allocation failure
        }
        list->capacity = new_capacity;
        list->elements = new_elements;
    }
    list->elements[list->size] = new_element;
    list->size++;
    return 0; // Success
}

// Remove element by RNTI from the list
int NFAPICRCList_remove_by_RNTI(NFAPICRCList* list, char target_RNTI[6]) {
    for (int i = 0; i < list->size; i++) {
        if (strcmp(list->elements[i].RNTI, target_RNTI) == 0) {
            // Shift elements to fill the gap
            memmove(&list->elements[i], &list->elements[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->size--;
            return 0; // Success
        }
    }
    return -1; // Element not found
}

// Update CRCFLAG value by index
int NFAPICRCList_update_CRCFLAG(NFAPICRCList* list, int index, int new_CRCFLAG) {
    if (index >= 0 && index < list->size) {
        list->elements[index].CRCFLAG = new_CRCFLAG;
        return 0; // Success
