#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    double temperature;
    char timestamp[64];
} TemperatureRecord;

typedef struct {
    int size;
    int capacity;
    TemperatureRecord** records;
    pthread_mutex_t mutex;
} DynamicList;

void* dynamic_list_init(int capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->size = 0;
    list->capacity = capacity;
    list->records = (TemperatureRecord**)calloc(capacity, sizeof(TemperatureRecord*));
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void dynamic_list_add_record(void* list, double temperature, const char* timestamp) {
    DynamicList* dl = (DynamicList*)list;
    pthread_mutex_lock(&dl->mutex);
    if (dl->size >= dl->capacity) {
        // reallocate memory
        int new_capacity = dl->capacity * 2;
        TemperatureRecord** new_records = (TemperatureRecord**)realloc(dl->records, new_capacity * sizeof(TemperatureRecord*));
        dl->capacity = new_capacity;
        dl->records = new_records;
    }
    TemperatureRecord* record = (TemperatureRecord*)malloc(sizeof(TemperatureRecord));
    record->temperature = temperature;
    strncpy(record->timestamp, timestamp, 64);
    dl->records[dl->size] = record;
    dl->size++;
    pthread_mutex_unlock(&dl->mutex);
}

void dynamic_list_get_latest_records(void* list, int count, TemperatureRecord** result) {
    DynamicList* dl = (DynamicList*)list;
    pthread_mutex_lock(&dl->mutex);
    for (int i = 0; i < count && i < dl->size; i++) {
        result[i] = dl->records[dl->size - i - 1];
    }
    pthread_mutex_unlock(&dl->mutex);
}

void dynamic_list_log_operation(void* list, const char* operation) {
    DynamicList* dl = (DynamicList*)list;
    pthread_mutex_lock(&dl->mutex);
    // log operation
    pthread_mutex_unlock(&dl->mutex);
}
