void init_populate_measurement_reports(int num_reports, char* session_id) {
    NR_UE_MEASUREMENT_REPORT_T* report_array = (NR_UE_MEASUREMENT_REPORT_T*)malloc(num_reports * sizeof(NR_UE_MEASUREMENT_REPORT_T));
    if (!report_array) {
        printf("Memory allocation failed.\n");
        return;
    }

    for (int i = 0; i < num_reports; i++) {
        NR_UE_MEASUREMENT_REPORT_T report;
        // Initialize the RX_UE_INFORMATION_TAG
        // Initialize the RNTI
        report.measurement_result.rssi = 20; // Set a default value
        report.measurement_result.snr = 30; // Set a default value

        // Check if the structure is valid before adding it to the array
        if (!validate_structure(&report)) {
            log_error("Invalid measurement report");
            continue;
        }

        // Add the report to the array
        report_array[i] = report;
    }

    free(report_array);
}

void clear_old_reports(int threshold) {
    // Clear old reports older than the specified threshold
    for (int i = 0; i < num_reports; i++) {
        NR_UE_MEASUREMENT_REPORT_T* report = &report_array[i];
        if (report->timestamp <= threshold) {
            // Clear the report
            memset(report, 0, sizeof(NR_UE_MEASUREMENT_REPORT_T));
        }
    }
}

int get_num_active_reports() {
    int count = 0;
    for (int i = 0; i < num_reports; i++) {
        NR_UE_MEASUREMENT_REPORT_T* report = &report_array[i];
        if (report->valid) {
            count++;
        }
    }
    return count;
}

void trigger_alert(int threshold) {
    int num_active_reports = get_num_active_reports();
    if (num_active_reports > threshold) {
        // Trigger an alert
        printf("Number of active reports exceeds threshold: %d\n", num_active_reports);
    }
}

int main() {
    int num_reports = 10;
    char* session_id = "session1";
    init_populate_measurement_reports(num_reports, session_id);

    // Periodically clear old reports and trigger alerts
    while (1) {
        clear_old_reports(1000); // Clear reports older than 1 second
        trigger_alert(5); // Trigger an alert if more than 5 active reports
    }

    return 0;
}

