#include <iostream>
#include <filesystem>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <deque>
#include <chrono>
#include "imageConversionLibrary.h"
#include "cachingMechanism.h"

class ThreadPool {
public:
    ThreadPool(size_t numThreads) : stopped(false), threads(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            threads.emplace_back([this] {
                while (true) {
                    std::unique_lock<std::mutex> lock(queue_mutex);
                    queue.wait_until(lock, [this] { return stopped || !tasks.empty(); });
                    if (stopped && tasks.empty()) {
                        return;
                    }
                    auto task = std::move(tasks.front());
                    tasks.pop();
                    lock.unlock();
                    task();
                }
            });
        }
    }

    template<typename Function>
    void enqueue(Function f) {
        std::unique_lock<std::mutex> lock(queue_mutex);
        tasks.emplace_front(f);
        queue.notify_one();
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stopped = true;
        }
        queue.notify_all();
        for (auto &thread : threads) {
            thread.join();
        }
    }

private:
    std::vector<std::thread> threads;
    std::deque<Function> tasks;
    mutable std::mutex queue_mutex;
    std::condition_variable queue;

};

void processImages(const std::string& directoryPath, const std::string& outputPDF) {
    ThreadPool pool(std::thread::hardware_concurrency());

    for (const auto &entry : std::filesystem::directory_iterator(directoryPath)) {
        if (!std::filesystem::is_regular_file(entry.path())) continue;

        try {
            std::this_thread::sleep_for(std::chrono::milliseconds(50));

            // Process image using the conversion library
            ImageConversionLibrary::convertImage(entry.path(), outputPDF);

            // Cache frequently accessed images in memory
            cachingMechanism().storeInMemory(entry.path());

        } catch (const std::exception &e) {
            // Log error with timestamp and error code
            std::cerr << "[ERROR] " << e.what() << " at " << std::chrono::system_clock::now() << std::endl;
        }
    }
}
