```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int cell_id;
    int pci;
    float rsrp;
    float sinr;
} NR_CELL_INFORMATION_T;

// Function to initialize and manage a dynamic list of NR_cell_information_t structures
NR_CELL_INFORMATION_T* cell_info_list = NULL;
int cell_info_list_size = 0;
int cell_info_list_max_size = 10; // Initial capacity

void update_cell_info_list(NR_CELL_INFORMATION_T* new_cell_info) {
    if (cell_info_list == NULL || cell_info_list_size >= cell_info_list_max_size) {
        // Dynamically allocate memory for the list and handle potential out-of-memory errors
        NR CELL_INFORMATION_T** temp = realloc(cell_info_list, sizeof(NR CELL INFORMATION_T*) * (cell_info_list_size + 1));
        if (temp == NULL) {
            printf("Error: Out of memory\n");
            return;
        }
        cell_info_list = temp;

        // Initialize the new capacity
        cell_info_list_max_size += cell_info_list_max_size / 2; // Double the current size for performance

        // Add the new cell information to the list, keeping it sorted by CELL_ID
        for (int i = 0; i < cell_info_list_size; i++) {
            if (new_cell_info->cell_id <= cell_info_list[i]->cell_id) {
                // Shift all existing entries down and add the new one at the correct position
                memmove(&cell_info_list[i + 1], &cell_info_list[i], sizeof(NR CELL INFORMATION_T*) * (cell_info_list_size - i));
                cell_info_list[i] = new_cell_info;
                return;
            }
        }
    }

    // Add the new cell information to the list, keeping it sorted by CELL_ID
    NR_CELL_INFORMATION_T* temp = malloc(sizeof(NR CELL INFORMATION_T));
    if (temp == NULL) {
        printf("Error: Out of memory\n");
        return;
    }
    *temp = *new_cell_info;
    cell_info_list[cell_info_list_size++] = temp;
}

void print_cell_info_list() {
    for (int i = 0; i < cell_info_list_size; i++) {
        printf("Cell ID: %d, PCI: %d, RSRP: %.2f, SINR: %.2f\n", 
               cell_info_list[i]->cell_id, cell_info_list[i]->pci, cell_info_list[i]->rsrp, cell_info_list[i]->sinr);
    }
}

int main() {
    NR_CELL_INFORMATION_T new_cell_info = {1, 10, 20.0, 30.0};
    update_cell_info_list(&new_cell_info);

    NR_CELL_INFORMATION_T new_cell_info2 = {3, 20, 40.0, 50.0};
    update_cell_info_list(&new_cell_info2);

    print_cell_info_list();

    return 0;
}

