    TrafficFlow* traffic_flows = (TrafficFlow*)malloc(num_entries * sizeof(TrafficFlow));

    for (int i = 0; i < num_entries; i++) {
        TrafficFlow* flow = &traffic_flows[i];

        // Validate IP addresses
        if (!validate_ip_address(flow->SourceIP) || !validate_ip_address(flow->DestinationIP)) {
            printf("Invalid IP address at entry %d. Skipping.\n", i);
            continue;
        }

        // Initialize flow details
        flow->FlowID = i + 1; // assuming FlowID starts from 1

        // Validate and set FlowID (you can adjust this validation as per your requirement)
        if (flow->FlowID < 1) {
            printf("Invalid FlowID at entry %d. Setting to default.\n", i);
            flow->FlowID = 1;
        }
    }

    return traffic_flows;
}

// Validate IP address
int validate_ip_address(char* ip) {
    // implement your IP validation logic here
    // For simplicity, assume a valid IP address is any string with 15 characters or less that contains exactly one dot (.)
    int len = strlen(ip);
    if (len > 15 || !strchr(ip, '.')) {
        return 0; // invalid IP address
    }
    return 1; // valid IP address
}

// Free allocated memory
void free_traffic_flow_array(TrafficFlow* traffic_flows, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        free(traffic_flows[i].SourceIP);
        free(traffic_flows[i].DestinationIP);
    }
    free(traffic_flows);
}
