        *userIds = realloc(*userIds, (*numUsers) * sizeof(int));
        *pucchConfigs = realloc(*pucchConfigs, (*numUsers) * sizeof(LTE_PUCCH_CONFIG_SRS_T *));
        (*userIds)[*numUsers - 1] = userId;
        (*pucchConfigs)[*numUsers - 1]->srs_info = srsConfig;
    }
    fclose(fp);
}

// Helper function to calculate and print the average of user IDs
void printAverageUserIDs(int *numUsers, int **userIds) {
    if (*numUsers > 0) {
        double sum = 0.0;
        for (int i = 0; i < *numUsers; i++) {
            sum += (*userIds)[i];
        }
        printf("Average user ID: %.2f\n", sum / *numUsers);
    } else {
        printf("No user IDs found.\n");
    }
}

int main() {
    int numUsers = 0;
    int *userIds = NULL;
    LTE_PUCCH_CONFIG_SRS_T **pucchConfigs = NULL;

    managePUCCHConfigArray(&numUsers, &userIds, &pucchConfigs);

    // Read user IDs and SRS configurations from standard input
    readUserIdsAndSRSConfigs(&numUsers, &userIds, &pucchConfigs);

    // Print average of user IDs
    printAverageUserIDs(&numUsers, &userIds);

    return 0;
}

