    try {
        if (N <= 0) {
            printf("Invalid input: Number of entries should be greater than zero.\n");
            return NULL;
        }

        array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (array == NULL) {
            printf("Memory allocation failed.\n");
            return NULL;
        }

        int seq_num = 1;
        for (int i = 0; i < N; i++) {
            array[i].RX_UE_INFORMATION_TAG = seq_num++;
            array[i].RNTI = rand() % 100 + 1;
            array[i].CRC_INDICATION_REL8_TAG = rand() % 100 + 1;
            array[i].CRCFLAG = rand() % 2; // Randomly set CRC flag
        }

        printf("Array of size %d successfully allocated.\n", N);
    } catch (int e) {
        if (array != NULL) {
            free(array);
        }
        return NULL;
    } finally {
        if (array != NULL) {
            free(array);
        }
    }

    return array;
}

