NFAPI_CRC_LIST_T* nfapi_crc_list_create() {
    NFAPI_CRC_LIST_T* list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    list->data = NULL;
    list->size = 0;
    list->capacity = 1;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Function to add a new NFAPI_CRC_INDICATION_PDU_T structure to the dynamic list
int nfapi_crc_list_add(NFAPI_CRC_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (list->size >= list->capacity) {
        // Double capacity when full
        list->data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (list->capacity *= 2));
    }
    list->data[list->size++] = pdu;
    return 0;
}

// Function to update an existing NFAPI_CRC_INDICATION_PDU_T structure in the dynamic list
int nfapi_crc_list_update(NFAPI_CRC_LIST_T* list, int index, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);
    if (index < 0 || index >= list->size) {
        // Index out of bounds
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    list->data[index] = *pdu;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

