// Allocate memory for all arrays and initialize the key array
void init_memory() {
    // Allocate memory for long offset values
    void* long_offsets = malloc(MAX_LONG_OFFSET * sizeof(long));

    // Allocate memory for int keys
    void* int_keys = malloc(MAX_INT_KEY * sizeof(int));
    int i;
    for (i = 0; i < MAX_INT_KEY; i++) {
        int_keys[i] = i;
    }

    // Allocate memory for record structures
    void* records = malloc(MAX_RECORDS * sizeof(record_t));

    // Initialize the key array with sequential values starting from 0
    int* keys = (int*) int_keys;

    // Populate the record array with int values randomly generated within a specified range
