        printf("Error opening file.\n");
        return;
    }

    // Write the long offset values
    fwrite(long_offsets, sizeof(long), MAX_LONG_OFFSET, file);

    // Write the int keys
    fwrite(int_keys, sizeof(int), MAX_INT_KEY, file);

    // Write the record structures
    fwrite(records, sizeof(record_t), MAX_RECORDS, file);

    // Close the file
    fclose(file);
}

// Deserialize the managed data structures from a binary file
void deserialize() {
    FILE* file = fopen("data.bin", "rb");
    if (file == NULL) {
        printf("Error opening file.\n");
        return;
    }

    // Read the long offset values
    fread(long_offsets, sizeof(long), MAX_LONG_OFFSET, file);

    // Read the int keys
    fread(int_keys, sizeof(int), MAX_INT_KEY, file);

    // Read the record structures
    fread(records, sizeof(record_t), MAX_RECORDS, file);

    // Close the file
