        if (rand() % 2 == 1) {
            report_array[i].tx_power_level = rand() % 100.0 / 10.0f;
        } else {
            report_array[i].tx_power_level = -80.0f;
        }
    }

    // process text file
    FILE* file = fopen("data.txt", "r");
    if (file == NULL) {
        printf("Error opening file.\n");
        return 1;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // convert each line into a comma-separated string
        char* token = strtok(line, ",");
        char result[1024];
        int count = 0;
        while (token != NULL) {
            if (count > 1) {
                float avg = (atof(token) + atof(token)) / 2.0f;
                sprintf(result + strlen(result), "%f,", avg);
            } else {
                sprintf(result + strlen(result), "%s,", token);
            }
            token = strtok(NULL, ",");
            count++;
        }

        // process result
        printf("%s\n", result);

        free(line); // dynamic memory allocation for each line
    }

    fclose(file);

    // theme cache management
    char* theme_dir = getenv("THEME_DIR");
    if (theme_dir == NULL) {
        theme_dir = "/path/to/default/theme";
    }
    DIR* dir = opendir(theme_dir);
    if (dir != NULL) {
        struct dirent* ent;
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
                continue;

            char file_path[1024];
            sprintf(file_path, "%s/%s", theme_dir, ent->d_name);
            FILE* f = fopen(file_path, "rb");
            if (f != NULL) {
                // parse PNG file from cache root directory
                unsigned char* buffer = malloc(1024 * 1024); // adjust memory allocation
                fread(buffer, 1, 1024 * 1024, f);
                fclose(f);

                // store it in the theme cache
                // ... (omitted for brevity)
            }
        }
        closedir(dir);
    }

    return 0;
}
