#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the maximum number of records
#define MAX_RECORDS 1000

// Define the maximum length of metadata strings
#define MAX_METADATA_LENGTH 256

typedef struct {
    int key;
    int value;
    char* metadata;
} Record;

Record* record_list = NULL;
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* generate_random_string(int len) {
    char* str = (char*)malloc(len + 1);
    if (!str) return NULL; // Handle memory allocation failure

    for (int i = 0; i < len; i++) {
        str[i] = (rand() % 26) + 'a';
    }
    str[len] = '\0';

    return str;
}

Record* add_record(int key, int value) {
    pthread_mutex_lock(&mutex);

    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    new_record->key = key;
    new_record->value = value;

    int metadata_len = (rand() % MAX_METADATA_LENGTH) + 1;
    char* metadata = generate_random_string(metadata_len);
    if (!metadata) {
        // Handle metadata generation failure
        free(new_record);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    new_record->metadata = metadata;

    record_list = (Record*)realloc(record_list, sizeof(Record) * (record_count + 1));
    if (!record_list) {
        // Handle memory allocation failure
        free(metadata);
        free(new_record);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    record_list[record_count] = *new_record;
    record_count++;

    pthread_mutex_unlock(&mutex);

    return new_record;
}

void remove_record(int key) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < record_count; i++) {
        if (record_list[i].key == key) {
            free(record_list[i].metadata);
            free(&record_list[i]);
            memmove(&record_list[i], &record_list[i + 1], sizeof(Record) * (record_count - i - 1));
            record_count--;
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
}

void clean_up() {
    for (int i = 0; i < record_count; i++) {
        free(record_list[i].metadata);
        free(&record_list[i]);
    }
    free(record_list);
}

int main() {
    // Initialize random number generator
    srand(time(NULL));

    // Initialize the collection with a specified number of records
    for (int i = 0; i < MAX_RECORDS; i++) {
        add_record(i, rand() % 100); // Generate random integer value within range [0, 99]
    }

    // Example usage: Remove record with key 5
    remove_record(5);

    clean_up();
    return 0;
}
