NFAPI_CRC_INDICATION_PDU_T* read_data(int* n) {
    FILE* fp = fopen("input.txt", "r");
    if (fp == NULL) {
        printf("Error opening file\n");
        return NULL;
    }

    *n = 0;
    NFAPI_CRC_INDICATION_PDU_T* data = malloc(sizeof(NFAPI_CRC_INDATION_PDU_T)*100);
    for(int i=0; ;i++) {
        if(fscanf(fp, "%d %d %c\n", &data[i].RX_UE_INFORMATION_TAG, &data[i].RNTI, &data[i].CRCFLAG) != 3)
            break;
        data[i].CRC_INDICATION_REL8_TAG = rand();
        (*n)++;
    }
    fclose(fp);
    return data;
}

int validate_data(NFAPI_CRC_INDICATION_PDU_T* data, int n) {
    for(int i=0; i<n; i++) {
        if(data[i].RX_UE_INFORMATION_TAG < 1 || data[i].RNTI < 1)
            return -1;
    }
    return 1;
}

NFAPI_CRC_INDICATION_PDU_T* validate_input(NFAPI_CRC_INDICATION_PDU_T* data, int n) {
    if(validate_data(data,n)<0) {
        printf("Invalid input\n");
        return NULL;
    } else
        return data;
}

void log_critical_error() {
    //integrate with external logging service here
    printf("Critical error occurred\n");
}

int main() {
    srand(time(NULL));
    int n;
    NFAPI_CRC_INDICATION_PDU_T* data = read_data(&n);
    data = validate_input(data, n);
    if(data == NULL) {
        log_critical_error();
        return 0;
    }
    //identify and print the largest integer in the array
    int max = data[0].RX_UE_INFORMATION_TAG;
    for(int i=1; i<n; i++) {
        if(data[i].RX_UE_INFORMATION_TAG > max)
            max = data[i].RX_UE_INFORMATION_TAG;
    }
    printf("Largest integer: %d\n", max);
    //log this operation to the external logging service
    log_critical_error();
    free(data);
    return 0;
}

