        item temp;
        temp.f = (float)i;
        temp.s = (enum state)i % 2;
        temp.str = malloc(1024); // allocate a string buffer
        sprintf(temp.str, "Item %zu", i);

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.crc = crc32(temp.str);
        pdu.ptr = temp.str;
        temp.f = (float)pdu.crc;

        arr[i] = temp;
    }

    return arr;
}

void free_item_array(item* arr, size_t n) {
    for (size_t i = 0; i < n; i++) {
        if (arr[i].str) {
            free(arr[i].str);
            arr[i].str = NULL;
        }
    }
