    item->status = DISCONNECTED;
    size_t metadata_len = strlen(metadata);
    item->metadata = (char*)my_malloc(metadata_len + 1);
    strcpy(item->metadata, metadata);
    return item;
}

void radio_item_free(radioItem* item) {
    if (!item) return;

    my_free(item->metadata);
    my_free(item);
}

int radio_items_init(size_t initial_capacity) {
    radio_items = (radioItem**)my_malloc(initial_capacity * sizeof(radioItem*));
    num_items = 0;
    cache_size = 0;
    return 0;
}

void radio_items_destroy() {
    for (size_t i = 0; i < num_items; i++) {
        radio_item_free(radio_items[i]);
    }

    my_free(cache);
    my_free(radio_items);
}

int enqueue_radio_item(radioItem* item) {
    pthread_mutex_lock(&lock);

    if (!item) {
        pthread_mutex_unlock(&lock);
        return -1;  // Error: invalid item
    }

    // Add the item to the array and cache (if necessary)
    if (num_items >= sizeof(radio_items[0]) * 2) {
        size_t new_capacity = num_items + num_items / 2;
        radio_items = (radioItem**)my_realloc(radio_items, new_capacity * sizeof(radioItem*));
    }

    radio_items[num_items++] = item;

    // Cache the item if it fits within our cache size
    if (cache_size < num_items) {
        cache = my_malloc(sizeof(radio_item_new(0.0f, "")));
        cache_size = 1;  // Start with a single cached item
    }

    pthread_mutex_unlock(&lock);
    return 0;
}

int dequeue_radio_item() {
    pthread_mutex_lock(&lock);

    if (num_items == 0) {
        pthread_mutex_unlock(&lock);
        return -1;  // Error: empty queue
    }

    radioItem* item = radio_items[--num_items];

    if (cache_size > 1) {
        cache_size--;
        if (!cache) my_free(cache);
        cache = item;
    } else {
        radio_item_free(item);
    }

    pthread_mutex_unlock(&lock);
    return 0;
}

int process_radio_item(radioItem* item) {
    // Process the item (e.g., send it to a logging framework)
    printf("Processing signal strength: %f, metadata: '%s'\n", item->signal_strength, item->metadata);

    return 0;
}
