void initialize_and_serialize_data(double startValue, int stepSize, int numReports, size_t memoryBudget) {
    // Calculate total required memory
    size_t totalMemoryRequired = (sizeof(double) * 3 + sizeof(struct report) * numReports);

    if (totalMemoryRequired > memoryBudget) {
        // Scale down sizes proportionally to fit within allocated memory
        double scaleFactor = (double)memoryBudget / totalMemoryRequired;
        int scaledNumReports = (int)(numReports * scaleFactor);
        startValue *= scaleFactor;
        stepSize /= scaleFactor;

        numReports = scaledNumReports;
    }

    // Initialize and allocate arrays
    double* doublesArray = malloc(sizeof(double) * 3);
    char** stringsArray = malloc(sizeof(char*) * numReports);
    struct report* reportsArray = malloc(sizeof(struct report) * numReports);

    for (int i = 0; i < numReports; i++) {
        // Initialize report structure
        reportsArray[i].value = startValue + stepSize * i;
        reportsArray[i].label = stringsArray[i] = malloc(10);
        strcpy(stringsArray[i], "Report ");
        reportsArray[i].flag = (i % 2) ? enum_type_FLAG1 : enum_type_FLAG2;

        // Check available memory and reallocate if necessary
        if (memory_left() < totalMemoryRequired) {
            // Fallback mechanism: scale down sizes again to fit within allocated memory
            scaleFactor = (double)memory_budget / totalMemoryRequired;
            scaledNumReports = (int)(numReports * scaleFactor);
            startValue *= scaleFactor;
            stepSize /= scaleFactor;

            numReports = scaledNumReports;

            // Reallocate arrays with updated sizes
            free(doublesArray);
            doublesArray = malloc(sizeof(double) * 3);

            for (int j = 0; j < numReports; j++) {
                // Initialize report structure again
                reportsArray[j].value = startValue + stepSize * j;
                reportsArray[j].label = stringsArray[j] = malloc(10);
                strcpy(stringsArray[j], "Report ");
                reportsArray[j].flag = (j % 2) ? enum_type_FLAG1 : enum_type_FLAG2;

            }
        }
    }

    // Serialize initialized data structures
    FILE* file = fopen("data.bin", "wb");

    if (file != NULL) {
        fwrite(doublesArray, sizeof(double), 3, file);
        fwrite(stringsArray, sizeof(char*), numReports, file);

        for (int i = 0; i < numReports; i++) {
            // Serialize report structure
            fwrite(&reportsArray[i], sizeof(struct report), 1, file);
        }

        fclose(file);
    } else {
        // Handle memory allocation failure and ensure resources are properly released
        free(doublesArray);
        for (int i = 0; i < numReports; i++) {
            free(stringsArray[i]);
        }
        free(stringsArray);
        free(reportsArray);

        printf("Memory allocation failed. Exiting...\n");
    }

    // Thread-safe mechanism: use locking to ensure data integrity
    pthread_mutex_lock();
    // Serialize initialized data structures in a thread-safe manner
    pthread_mutex_unlock();

}
