        connections[max_connections] = new_connection;
    } else {
        // Handle buffer overflow
        printf("Connection buffer full. Cannot add more connections.\n");
        return -1; // Error: connection buffer full
    }

    max_connections++;
    return 0; // Success
}

int purge_stale_connections(int threshold) {
    int i, j = 0;
    for (i = 0; i < max_connections; i++) {
        TCP_CONNECTION_RECORD *connection = connections[i];
        if (connection->flag_status == 1 && time(NULL) - connection->timestamp > threshold) { // ESTABLISHED connection stale
            free(connection);
            connections[i] = NULL;
        } else {
            j++;
        }
    }
    max_connections = j;
    return 0; // Success
}

