typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDATION_PDU_T* data;
    struct Node* next;
} Node;

Node* head = NULL;

void add_node(Node** head, NFAPI_CRC_INDICATION_PDU_T* new_data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    new_node->data = new_data;
    new_node->next = (*head);
    (*head) = new_node;
}

void remove_duplicate_tags(Node** head) {
    Node* current = *head;
    Node* next = NULL;
    while (current && current->next) {
        if (!strcmp(current->data->RX_UE_INFORMATION_TAG, current->next->data->RX_UE_INFORMATION_TAG)) {
            Node* temp = current->next;
            current->next = current->next->next;
            free(temp);
        } else {
            next = current->next;
            current = current->next;
        }
    }
}

void print_list(Node* head) {
    while (head) {
        printf("RX_UE_INFORMATION_TAG: %s, RNTI: %d, CRC_INDICATION_REL8_TAG: %s, CRCFLAG: %d\n", 
               head->data->RX_UE_INFORMATION_TAG, head->data->RNTI, head->data->CRC_INDICATION_REL8_TAG, 
               head->data->CRCFLAG);
        head = head->next;
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* new_data1 = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    strcpy(new_data1->RX_UE_INFORMATION_TAG, "TAG1");
    new_data1->RNTI = 123;
    strcpy(new_data1->CRC_INDICATION_REL8_TAG, "REL8TAG1");
    new_data1->CRCFLAG = rand() % 2;

    NFAPI_CRC_INDICATION_PDU_T* new_data2 = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    strcpy(new_data2->RX_UE_INFORMATION_TAG, "TAG2");
    new_data2->RNTI = 456;
    strcpy(new_data2->CRC_INDICATION_REL8_TAG, "REL8TAG2");
    new_data2->CRCFLAG = rand() % 2;

    NFAPI_CRC_INDICATION_PDU_T* new_data3 = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    strcpy(new_data3->RX_UE_INFORMATION_TAG, "TAG1"); // Duplicate TAG
    new_data3->RNTI = 789;
    strcpy(new_data3->CRC_INDICATION_REL8_TAG, "REL8TAG3");
    new_data3->CRCFLAG = rand() % 2;

    add_node(&head, new_data1);
    add_node(&head, new_data2);
    add_node(&head, new_data3);

    remove_duplicate_tags(&head);

    print_list(head);

    return 0;
}

