    for (size_t i = 0; i < arraySize; ++i) {
        LTE_PDCP_RX_PDU* pdu = (LTE_PDCP_RX_PDU*)malloc(sizeof(LTE_PDCP_RX_PDU));

        if (!pdu) {
            // Handle memory allocation failure
            printf("Error: Failed to allocate memory for PDU %zu.\n", i);
            for (size_t j = 0; j < i; ++j) {
                free(pduArray[j]);
            }
            free(pduArray);
            return NULL;
        }

        pdu->RX_UE_INFORMATION_TAG = rand() % 100;
        pdu->RNTI = rand() % 200 + 1;
