#include "NFAPI_CRC_INDICATION_PDU_T.h"

void nfapi_crc_indication_pdu_array_mgmt(NFAPI_CRC_INDICATION_PDU_T** arr, int* len, int idx, NFAPI_CRC_INDICATION_PDU_T* elem) {
    if (!arr || !len) {
        printf("Error: Invalid input - array or length pointer is NULL.\n");
        return;
    }

    // Allocate and reallocate as needed
    int new_len = *len + 1;
    NFAPI_CRC_INDICATION_PDU_T** new_arr = realloc(*arr, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * new_len);
    if (!new_arr) {
        printf("Error: Memory allocation failed.\n");
        return;
    }
    *arr = new_arr;

    // Insert or remove at arbitrary position
    if (idx < 0 || idx >= *len) {
        printf("Error: Invalid index - out of bounds.\n");
        return;
    }

    if (idx == *len) {  // Add at the end
        (*arr)[*len] = elem;
    } else {  // Remove and shift elements after removal point
        for (int i = idx; i < *len; i++) {
            (*arr)[i] = (*arr)[i + 1];
        }
        free(elem);
    }

    // Update array length
    *len = new_len;
}
