#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct data {
    int id;
    double value;
} data_t;

typedef struct event {
    data_t* measurement;
    char status;
    time_t timestamp;
} event_t;

void manageMemory(int numSensors, int numEvents) {
    // Allocate memory for sensor readings
    float** sensorReadings = (float**)malloc(numSensors * sizeof(float*));
    for (int i = 0; i < numSensors; i++) {
        sensorReadings[i] = (float*)malloc(1 * sizeof(float));
    }

    // Allocate memory for flags
    char** qualityFlags = (char**)malloc(numSensors * sizeof(char*));
    for (int i = 0; i < numSensors; i++) {
        qualityFlags[i] = (char*)malloc(1 * sizeof(char));
    }

    // Allocate memory for data structures
    data_t** measurements = (data_t**)malloc(numEvents * sizeof(data_t*));
    for (int i = 0; i < numEvents; i++) {
        measurements[i] = (data_t*)malloc(sizeof(data_t));
    }

    // Allocate memory for events
    event_t** events = (event_t**)malloc(numEvents * sizeof(event_t*));
    for (int i = 0; i < numEvents; i++) {
        events[i] = (event_t*)malloc(sizeof(event_t));

        // Initialize event with current timestamp and measurement
        time_t currentTime = time(NULL);
        events[i]->timestamp = currentTime;
        events[i]->measurement = measurements[i];
    }

    // Handle potential memory allocation failures gracefully
    if (!sensorReadings || !qualityFlags || !measurements || !events) {
        printf("Memory allocation failed.\n");
        // Free allocated memory in reverse order of allocation to avoid dangling pointers
        for (int i = 0; i < numEvents; i++) {
            free(events[i]);
        }
        for (int i = 0; i < numSensors; i++) {
            free(qualityFlags[i]);
            free(sensorReadings[i]);
        }
        free(measurements);
        free(qualityFlags);
        free(sensorReadings);
    } else {
        // Perform necessary operations with allocated memory
        printf("Memory allocation successful.\n");
