Node* node_table = NULL;
int table_size = 0;
int num_nodes = 0;

// Function to add a new node to the table
void add_node(char* key, int value) {
    // Create a new node and allocate memory for it
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->key = strdup(key);
    new_node->value = value;

    // Rehash the table if necessary
    if (num_nodes >= table_size) {
        table_size *= 2;
        node_table = (Node**)realloc(node_table, table_size * sizeof(Node*));
    }

    // Insert the new node into the table
    int index = hash_function(key) % table_size;
    Node** current_bucket = &node_table[index];
    while (*current_bucket != NULL) {
        if (strcmp((*current_bucket)->key, key) == 0) {
            free(new_node->key);
            free(new_node);
            return;
        }
        current_bucket = &(*current_bucket + 1);
    }

    *current_bucket = new_node;
    num_nodes++;
}

// Function to remove a node from the table
void remove_node(char* key) {
    int index = hash_function(key) % table_size;
    Node** current_bucket = &node_table[index];
    while (*current_bucket != NULL) {
        if (strcmp((*current_bucket)->key, key) == 0) {
            free((*current_bucket)->key);
            free(*current_bucket);
            *current_bucket = NULL;
            return;
        }
        current_bucket = &(*current_bucket + 1);
    }
}

// Function to update the value of a node
void update_node(char* key, int new_value) {
    int index = hash_function(key) % table_size;
    Node** current_bucket = &node_table[index];
    while (*current_bucket != NULL) {
        if (strcmp((*current_bucket)->key, key) == 0) {
            (*current_bucket)->value = new_value;
            return;
        }
        current_bucket = &(*current_bucket + 1);
    }
}

// Function to perform a bulk operation on the table
void bulk_operation(int num_bulk_nodes) {
    // Allocate memory for the new nodes
    Node* new_nodes = (Node*)malloc(num_bulk_nodes * sizeof(Node));

    // Insert the new nodes into the table
    for (int i = 0; i < num_bulk_nodes; i++) {
        add_node("bulk_node_key", 1); // Replace with actual key and value

        // Update statistics or perform other bulk operation tasks here
    }

    free(new_nodes);
}

// Function to get the number of nodes in the table
int get_num_nodes() {
    return num_nodes;
}

// Hash function used for node table lookups
unsigned int hash_function(char* key) {
    unsigned int hash = 0;
    while (*key != '\0') {
        hash = (hash * 31 + *key) % table_size;
        key++;
    }
    return hash;
}
