typedef struct {
    int type;
    unsigned char header[14];
    unsigned long statistics[3];
} MAC_PDU_T;

// Function to calculate checksum
unsigned int calculate_checksum(int type, unsigned char header[14]) {
    // Implement your checksum calculation logic here
}

// Structure to represent the dynamic array of MAC_PDU_T structures
typedef struct {
    MAC_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

// Function to create a new dynamic array with initial capacity
DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!arr) return NULL; // Handle memory allocation failure

    arr->data = (MAC_PDU_T*)calloc(initial_capacity, sizeof(MAC_PDU_T));
    if (!arr->data) {
        free(arr);
        return NULL;
    }

    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);

    return arr;
}

// Function to add an element to the dynamic array
int add_element(DynamicArray* arr, MAC_PDU_T new_element) {
    if (arr->size == arr->capacity) {
        // Double the capacity and re-allocate memory
        size_t new_capacity = arr->capacity * 2;
        MAC_PDU_T* new_data = (MAC_PDU_T*)realloc(arr->data, new_capacity * sizeof(MAC_PDU_T));
        if (!new_data) return -1; // Handle memory allocation failure

        arr->data = new_data;
        arr->capacity = new_capacity;
    }

    pthread_mutex_lock(&arr->mutex);
    arr->data[arr->size++] = new_element;

    // Validate the new element's checksum
    for (int i = 0; i < arr->size; i++) {
        MAC_PDU_T* current_pdu = &arr->data[i];
        if (calculate_checksum(current_pdu->type, current_pdu->header) != current_pdu->statistics[2]) {
            // Handle invalid checksum
            arr->size--;
            pthread_mutex_unlock(&arr->mutex);
            return -1;
        }
    }

    pthread_mutex_unlock(&arr->mutex);

    return 0; // Success
}

// Function to remove an element from the dynamic array
int remove_element(DynamicArray* arr, size_t index) {
    if (index >= arr->size) return -1; // Index out of bounds

    pthread_mutex_lock(&arr->mutex);
    memmove(&arr->data[index], &arr->data[index + 1], (arr->size - index - 1) * sizeof(MAC_PDU_T));
    arr->size--;

    pthread_mutex_unlock(&arr->mutex);

    return 0; // Success
}

// Function to log changes to the dynamic array
void log_changes(DynamicArray* arr, const char* message) {
    static char log_buffer[LOG_BUFFER_SIZE];
    sprintf(log_buffer, "%s: Added/Removed %d elements from index %zu.\n", message, (arr->size == 0 ? -1 : 1), (arr->size == 0 ? -1 : arr->size - 1));
    printf("%s", log_buffer);
}

// Example usage
int main() {
    DynamicArray* arr = create_dynamic_array(100);
    for (int i = 0; i < 10; i++) {
        MAC_PDU_T new_element;
        // Initialize new_element...
        add_element(arr, new_element);
    }
    remove_element(arr, 5);

    return 0;
}
