// Function to create a new node
NFAPI_CRC_INDICATION_PDU_T* new_node(int tag, int rnti, int crc) {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->RX_UE_INFORMATION_TAG = tag;
    node->RNTI = rnti;
    node->CRC_INDICATION_REL8_TAG = crc;
    node->timestamp = time(NULL);
    return node;
}

// Function to calculate checksum
int checksum(int tag, int rnti) {
    // Simple example checksum calculation using XOR operation
    return tag ^ rnti;
}

// Function to insert a new node into the linked list
void insert_node(NFAPI_CRC_INDICATION_PDU_T** head, NFAPI_CRC_INDICATION_PDU_T* node) {
    if (*head == NULL || (*head)->RX_UE_INFORMATION_TAG > node->RX_UE_INFORMATION_TAG) {
        node->next = *head;
        *head = node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = *head;
        while (current->next && current->next->RX_UE_INFORMATION_TAG <= node->RX_UE_INFORMATION_TAG)
            current = current->next;
        node->next = current->next;
        current->next = node;
    }
}

// Function to print the linked list
void print_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current) {
        printf("(%d, %d, %d) - timestamp: %ld\n", current->RX_UE_INFORMATION_TAG, current->RNTI, current->CRC_INDICATION_REL8_TAG, current->timestamp);
        current = current->next;
    }
}

// Function to detect and handle cyclic dependencies
void check_cycle(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDINATION_PDU_T* visited[10000];
    int i;

    for (i = 0; i < 10000; i++) {
        visited[i] = NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current) {
        if (visited[current->RX_UE_INFORMATION_TAG] != NULL)
            // Cycle detected, handle it accordingly
        else
            visited[current->RX_UE_INFORMATION_TAG] = current;

        current = current->next;
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    int i;

    for (i = 0; i < 10000; i++) {
        int tag = i % 10;
        int rnti = i % 20;
        int crc = checksum(tag, rnti);
        NFAPI_CRC_INDICATION_PDU_T* node = new_node(tag, rnti, crc);

        // Check for cyclic dependencies
        check_cycle(head);

        // Insert the node into the linked list
        insert_node(&head, node);
    }

    print_list(head);

    return 0;
}
