    // Allocate and initialize temperature readings array
    float *temperatureReadings = (float *)malloc(numReadings * sizeof(float));
    if (!temperatureReadings) {
        // Handle memory allocation failure
        printf("Memory allocation failed for temperature readings.\n");
        return;
    }

    // Initialize sensor identifiers array
    char *sensorIdentifiers = (char *)malloc(numSensors * sizeof(char));
    if (!sensorIdentifiers) {
