    // Allocate and initialize struct reading records array
    struct reading **readingRecords = (struct reading **)malloc(numReadings * sizeof(struct reading *));
    if (!readingRecords) {
        // Handle memory allocation failure
        printf("Memory allocation failed for reading records.\n");
        free(temperatureReadings);
        free(sensorIdentifiers);
        return;
    }

    // Initialize sensor objects array
    struct sensor *sensors = (struct sensor *)malloc(numSensors * sizeof(struct sensor));
    if (!sensors) {
        // Handle memory allocation failure
        printf("Memory allocation failed for sensors.\n");
        free(temperatureReadings);
        free(sensorIdentifiers);
        free(readingRecords);
        return;
    }

    // Initialize historical temperature readings array
    float **historicalTemperatureReadings = (float **)malloc(numSensors * sizeof(float *));
    if (!historicalTemperatureReadings) {
        // Handle memory allocation failure
        printf("Memory allocation failed for historical temperature readings.\n");
        free(temperatureReadings);
        free(sensorIdentifiers);
        free(readingRecords);
        free(sensors);
        return;
    }

    // Populate sensor objects with historical data
