        memcpy(sensors[i].temperatureReadings, historicalData[i], numReadings * sizeof(float));
    }

    // Ensure memory usage does not exceed budget
    int totalBytesUsed = (numReadings + numSensors) * sizeof(float) + numSensors * sizeof(char) + numReadings * sizeof(struct reading *) + numSensors * sizeof(struct sensor) + numSensors * sizeof(float *);
    if (totalBytesUsed > memoryBudget) {
        // Adjust array sizes to meet budget
