                    // Handle memory allocation failure
                    printf("Memory allocation failed for sensor %c.\n", sensorIdentifiers[i]);
                    free(temperatureReadings);
                    free(sensorIdentifiers);
                    free(readingRecords);
                    free(sensors);
                    return;
                }
            }
        }
    }

    // Initialize external memory management library and monitor usage
