#define MAX_SIZE 1000
#define MEMORY_THRESHOLD (MAX_SIZE * sizeof(NFAPI_LTE_UE_STATS) + (MAX_SIZE * 2) * sizeof(double))

void manage_nfa_lte_ue_stats(int num_entries, double* temperatures, char** keys, NFAPI_LTE_UE_STATS** stats_array) {
    if(num_entries > MAX_SIZE || !stats_array) {
        printf("Invalid input. Maximum size exceeded.\n");
        return;
    }

    // Initialize arrays
    *stats_array = (NFAPI_LTE_UE_STATS*)malloc(MAX_SIZE * sizeof(NFAPI_LTE_UE_STATS));
    double* temp_array = (double*)malloc(MAX_SIZE * 2 * sizeof(double));
    char** key_array = (char**)malloc(MAX_SIZE * sizeof(char*));

    // Initialize random seed
    srand(time(NULL));

    for(int i = 0; i < num_entries; i++) {
        // Generate random temperature
        double temp = temperature_generate();

        // Check if memory usage exceeds threshold
        size_t current_memory_usage = (num_entries * sizeof(NFAPI_LTE_UE_STATS) + (2 * num_entries) * sizeof(double));
        if(current_memory_usage > MEMORY_THRESHOLD) {
            printf("Memory usage exceeded. Cleaning up.\n");
            for(int j = 0; j < i; j++) {
                // Clear memory
                free(key_array[j]);
            }
            free(temp_array);
            free(*stats_array);

            // Re-allocate arrays with reduced size
            num_entries /= 2;
            *stats_array = (NFAPI_LTE_UE_STATS*)malloc(num_entries * sizeof(NFAPI_LTE_UE_STATS));
            temp_array = (double*)malloc(num_entries * 2 * sizeof(double));
            key_array = (char**)malloc(num_entries * sizeof(char*));

            // Re-generate temperatures and keys
            for(int j = 0; j < num_entries; j++) {
                double new_temp = temperature_generate();
                char* new_key = random_string(10);

                temp_array[2*j] = new_temp;
                key_array[j] = new_key;

                // Update stats array
                (*stats_array)[j].temperature = new_temp;
                strcpy((*stats_array)[j].key, new_key);
            }
        } else {
            // Generate random keys and temperatures
            char* temp_key = random_string(10);
            temp_array[2*i] = temperature_generate();
            key_array[i] = temp_key;

            (*stats_array)[i].temperature = temperature_generate();
            strcpy((*stats_array)[i].key, temp_key);
        }
    }

    // Free allocated memory
    free(temp_array);
    for(int i = 0; i < num_entries; i++) {
        free(key_array[i]);
    }
    free(key_array);

    logging_log("NFAPI LTE UE Stats managed successfully.");
}
