struct MemoryPool {
    int size;
    int used;
    NFAPI_CRC_INDICATION_PDU_T* pool;
};

struct LinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct LinkedListNode* next;
    pthread_mutex_t lock;
};

void initMemoryPool(struct MemoryPool* pool) {
    pool->size = MAX_POOL_SIZE;
    pool->used = 0;
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(pool->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

int getMemoryFromPool(struct MemoryPool* pool) {
    if (pool->used >= pool->size / 2) {
        // Trigger garbage collection
        int i = 0;
        NFAPI_CRC_INDICATION_PDU_T* current = pool->pool;
        while (i < pool->used) {
            free(current);
            current++;
            i++;
        }
        pool->used = 0;
    }
    return (pool->used)++;
}

void releaseMemoryToPool(struct MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (data != NULL) {
        // Update memory pool statistics
        int i = 0;
        NFAPI_CRC_INDICATION_PDU_T* current = pool->pool;
        while (i < pool->used) {
            if (current == data) {
                memmove(current, (current + 1), (pool->size - pool->used - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                pool->used--;
                return;
            }
            current++;
            i++;
        }
    }
}

void logStatistics() {
