#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int UE_ID;
    int test_type_id;
    int status_flag;
} LTE_PHY_TEST_PDU_T;

struct dynamic_array {
    LTE_PHY_TEST_PDU_T* data;
    size_t capacity;
    size_t used;
    pthread_mutex_t mutex;
};

LTE_PHY_TEST_PDU_T* dynamic_array_create(size_t initial_capacity) {
    struct dynamic_array* arr = (struct dynamic_array*)malloc(sizeof(struct dynamic_array));
    arr->data = (LTE_PHY_TEST_PDU_T*)calloc(initial_capacity, sizeof(LTE_PHY_TEST_PDU_T));
    arr->capacity = initial_capacity;
    arr->used = 0;
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

void dynamic_array_destroy(struct dynamic_array* arr) {
    free(arr->data);
    free(arr);
}

int dynamic_array_add_entry(struct dynamic_array* arr, int UE_ID, int test_type_id, int status_flag) {
    if (arr->used == arr->capacity) {
        // Double capacity and reallocate memory
        arr->data = (LTE_PHY_TEST_PDU_T*)realloc(arr->data, sizeof(LTE_PHY_TEST_PDU_T) * (arr->capacity *= 2));
    }
    LTE_PHY_TEST_PDU_T* entry = &arr->data[arr->used++];
    entry->UE_ID = UE_ID;
    entry->test_type_id = test_type_id;
    entry->status_flag = status_flag;
    return 0;
}

int dynamic_array_update_entry(struct dynamic_array* arr, int UE_ID, int test_type_id, int status_flag) {
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = 0; i < arr->used; i++) {
        if (arr->data[i].UE_ID == UE_ID) {
            arr->data[i].test_type_id = test_type_id;
            arr->data[i].status_flag = status_flag;
            pthread_mutex_unlock(&arr->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&arr->mutex);
    return -1; // Not found
}

int dynamic_array_get_entry(struct dynamic_array* arr, int UE_ID, LTE_PHY_TEST_PDU_T* entry) {
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = 0; i < arr->used; i++) {
        if (arr->data[i].UE_ID == UE_ID) {
            *entry = arr->data[i];
            pthread_mutex_unlock(&arr->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&arr->mutex);
    return -1; // Not found
}

int main() {
    struct dynamic_array* arr = dynamic_array_create(10);
    LTE_PHY_TEST_PDU_T test_entry;
    int ret = dynamic_array_add_entry(arr, 123, 456, 789);
    ret = dynamic_array_update_entry(arr, 123, 111, 222);
    ret = dynamic_array_get_entry(arr, 123, &test_entry);
    // ...
    return 0;
}
