typedef struct {
    double temperature;
    char key[20];
} NFAPI_LTE_UE_STATS;

void manage_dynamic_lists(int max_size, int* num_crc_indications, NFAPI_CRC_INDICATION_PDU_T** crcindications, int* num_ue_stats, NFAPI_LTE_UE_STATS** ue_stats, double* temperatures, char** temperature_keys) {
    // Initialize the random number generator
    srand(time(NULL));

    // Define the threshold for memory usage
    const size_t max_memory_usage = 1024 * 1024; // 1MB

    while (*num_crc_indications < max_size && (size_t)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)) <= max_memory_usage) {
        NFAPI_CRC_INDICATION_PDU_T* new_crc_indication = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_crc_indication) {
            LOG_ERROR("Memory allocation failed");
            break;
        }

        // Generate a random CRC flag
        new_crc_indication->crc_indication_rel8.crcflag = (uint32_t)rand();

        // Store the new NFAPI_CRC_INDICATION_PDU_T structure
        *num_crc_indications += 1;
        crcindications[*num_crc_indications - 1] = &new_crc_indication;

        // Initialize a dynamic array for temperatures and keys
        if (*num_ue_stats < max_size) {
            NFAPI_LTE_UE_STATS* new_ue_stat = (NFAPI_LTE_UE_STATS*)malloc(sizeof(NFAPI_LTE_UE_STATS));

            if (!new_ue_stat) {
                LOG_ERROR("Memory allocation failed");
                break;
            }

            // Generate a random temperature and key
            new_ue_stat->temperature = (double)rand() / RAND_MAX;
            strcpy(new_ue_stat->key, "Key");

            // Store the new NFAPI_LTE_UE_STATS structure
            *num_ue_stats += 1;
            ue_stats[*num_ue_stats - 1] = &new_ue_stat;

            // Update the temperature and key arrays
            temperatures[*num_ue_stats - 1] = new_ue_stat->temperature;
            strcpy(temperature_keys[*num_ue_stats - 1], new_ue_stat->key);
        }
    }

    // Release memory for any unused structures
    for (int i = 0; i < *num_crc_indications; i++) {
        free(crcindications[i]);
    }
    for (int i = 0; i < *num_ue_stats; i++) {
        free(ue_stats[i]);
    }
}
