// Dynamic array of UESessions with caching mechanism
UESession **ueSessions = NULL;
size_t cacheSize = 0;
size_t cacheHitCount = 0;
pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;

void ueSessionArrayInit(size_t initialCapacity) {
    pthread_mutex_lock(&cacheMutex);
    if (ueSessions == NULL || ueSessions[0] == NULL) {
        ueSessions = (UESession **)malloc((initialCapacity + 1) * sizeof(UESession *));
        if (!ueSessions) {
            // Handle allocation failure
            fprintf(stderr, "Error allocating initial session array.\n");
            exit(EXIT_FAILURE);
        }
    }
    pthread_mutex_unlock(&cacheMutex);
}

void ueSessionArrayAdd(int ueId) {
    pthread_mutex_lock(&cacheMutex);
    for (size_t i = 0; i < cacheSize; i++) {
        if (ueSessions[i]->ueId == ueId) {
            // Cache hit, do not reallocate
            cacheHitCount++;
            break;
        }
    }

    if (i >= cacheSize) {
        // Allocate new session
        size_t newSize = cacheSize + 1;
        UESession **newArray = (UESession **)realloc(ueSessions, (newSize + 1) * sizeof(UESession *));
        if (!newArray) {
            // Handle allocation failure
            fprintf(stderr, "Error allocating additional session.\n");
            exit(EXIT_FAILURE);
        }
        cacheSize = newSize;
        ueSessions = newArray;
    }

    UESession *session = &ueSessions[cacheSize - 1];
    session->ueId = ueId;
    // Initialize radio resources and other fields as needed
    pthread_mutex_unlock(&cacheMutex);
}

void ueSessionArrayRelease() {
    pthread_mutex_lock(&cacheMutex);
    if (ueSessions) {
        for (size_t i = 0; i < cacheSize; i++) {
            free(ueSessions[i]->radioResources);
        }
        free(ueSessions);
    }
    pthread_mutex_unlock(&cacheMutex);
}
