void largestInteger(NFAPI_CRC_INDICATION_PDU_T* array, int size) {
    int max = array[0].RX_UE_INFORMATION_TAG;
    for (int i = 1; i < size; i++) {
        if (array[i].RX_UE_INFORMATION_TAG > max)
            max = array[i].RX_UE_INFORMATION_TAG;
