NFAPI_CRC_INDICATION_PDU_T* readAndProcess(int maxAllocSize) {
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    int size = 0, maxRecordNum = 0;
    srand(time(NULL));

    while (1) {
        int recordNum = rand() % maxAllocSize;
        if (recordNum > maxAllocSize)
            break;

        NFAPI_CRC_INDICATION_PDU_T* newArray = realloc(array, (size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
