#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ENTRIES 1000
#define LOG_ENABLED 1 // set to 0 to disable logging

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG[CRC_FLAG_SIZE]; // assuming CRC_FLAG_SIZE is a constant
} NFAPI_CRC_INDICATION_PDU_T;

int generateUniqueRNTI() {
    static int rnti = 0;
    return rnti++;
}

void createNFAPI_CRC_INDICATION_PDU_T_list(int maxEntries, NFAPI_CRC_INDICATION_PDU_T **list) {
    if (*list != NULL) {
        for (int i = 0; i < *maxEntries; i++) {
            free((*list)[i].CRC_INDICATION_REL8_TAG);
        }
        free(*list);
    }

    *maxEntries = MAX_ENTRIES;
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * (*maxEntries));

    for (int i = 0; i < *maxEntries; i++) {
        (*list)[i].RX_UE_INFORMATION_TAG = i;
        (*list)[i].RNTI = generateUniqueRNTI();
        // randomly set CRCFLAG
        srand(time(NULL));
        int crcFlag = rand() % (1 << CRC_FLAG_SIZE);
        memcpy((*list)[i].CRC_INDICATION_REL8_TAG, &crcFlag, sizeof(crcFlag));

        if (LOG_ENABLED) {
            printf("Created NFAPI_CRC_INDICATION_PDU_T with RNTI=%d and CRCFLAG=0x%x\n", (*list)[i].RNTI, crcFlag);
        }
    }
}

void printNFAPI_CRC_INDICATION_PDU_T_list(NFAPI_CRC_INDICATION_PDU_T *list, int size) {
    for (int i = 0; i < size; i++) {
        printf("RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=0x%x\n", list[i].RX_UE_INFORMATION_TAG, list[i].RNTI, *(int *)list[i].CRC_INDICATION_REL8_TAG);
    }
}

int main() {
    int maxEntries = 10;
    NFAPI_CRC_INDICATION_PDU_T *list;

    createNFAPI_CRC_INDICATION_PDU_T_list(&maxEntries, &list);

    printNFAPI_CRC_INDICATION_PDU_T_list(list, maxEntries);

    // dynamically adjust maximum entries
    maxEntries += 5;
    createNFAPI_CRC_INDICATION_PDU_T_list(&maxEntries, &list);
    printNFAPI_CRC_INDICATION_PDU_T_list(list, maxEntries);

    return 0;
}
