    UE_Context_List* list = (UE_Context_List*)malloc(sizeof(UE_Context_List));
    list->contexts = (UE_Context*)calloc(initial_size, sizeof(UE_Context));
    list->size = initial_size;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add a new UE context to the list
int ue_context_list_add(UE_Context_List* list, UE_Context* ctx) {
    pthread_mutex_lock(&list->lock);
    if (list->size == 0) {
        // Dynamically resize the array if necessary
        list->contexts = (UE_Context*)realloc(list->contexts, sizeof(UE_Context) * (list->size + 1));
        list->size++;
    }
    list->contexts[list->size - 1] = ctx;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to remove a UE context from the list
int ue_context_list_remove(UE_Context_List* list, int idx) {
    pthread_mutex_lock(&list->lock);
    if (idx < list->size) {
        // Move all subsequent contexts down one position
        memmove(&list->contexts[idx], &list->contexts[idx + 1], sizeof(UE_Context) * (list->size - idx - 1));
        list->size--;
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}

