int ue_context_update_srs_config_concurrently(UE_Context_List* list) {
    pthread_mutex_lock(&list->lock);
    // Create a priority queue to resolve conflicts and prioritize UE contexts with higher latency requirements
    struct {
        int idx;
        int priority;
    } pq[10]; // Temporary array for priority queue

    int i = 0;
    for (int j = 0; j < list->size; j++) {
        if (list->contexts[j].info.srs_config[0] > pq[i].priority) {
            pq[i].idx = j;
            pq[i].priority = list->contexts[j].info.srs_config[0];
            i++;
        }
    }

    // Update SRS configurations for UE contexts in priority order
    for (int k = 0; k < i; k++) {
        int idx = pq[k].idx;
        ue_context_update_srs_config(list, idx, list->contexts[idx].info.srs_config);
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
