#define RECORD_SIZE sizeof(struct Record)

struct Record {
    int value;
    long* offset;
    int* key;
};

void init_records(int array_size, int min_value, int max_value) {
    struct Record* records = (struct Record*)malloc(array_size * RECORD_SIZE);
    long* offsets = (long*)malloc(array_size * sizeof(long));
    int* keys = (int*)malloc(array_size * sizeof(int));

    for (int i = 0; i < array_size; i++) {
        records[i].value = rand() % ((max_value - min_value) + 1) + min_value;
        offsets[i] = i * 10; // initialize offset values
        keys[i] = i % 100; // initialize key values
    }

    printf("Records initialized: %d\n", array_size);
    printf("Random values assigned: ");
    for (int i = 0; i < array_size; i++) {
        printf("%d ", records[i].value);
    }
    printf("\n");

    free(offsets);
    free(keys);

    // Handle resource leaks
    void* temp;
    pthread_exit(&temp); // prevent compiler warning
}

void free_records(struct Record* records, int array_size) {
    free(records);
}
