function copyDataChunks(dataChunks, numBytes) {
    const copyBuffer = Buffer.allocUnsafe(numBytes);

    for (let i = 0; i < dataChunks.length && i * numBytes <= dataChunks.byteLength; i++) {
        try {
            const chunk = dataChunks.slice(i * numBytes, (i + 1) * numBytes);
            if (!chunk.copy(copyBuffer)) {
                throw new Error('Failed to copy data');
