#define MAX_CAPACITY 1024
#define DEFAULT_CRCFLAG 0x00

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[8];
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *nfaPiList = NULL;
int nfaPiListSize = 0;
int maxCapacity = MAX_CAPACITY;

void resetCrcFlags() {
    pthread_mutex_lock(&list_lock);
    for (int i = 0; i < nfaPiListSize; i++) {
        nfaPiList[i].CRCFLAG = DEFAULT_CRCFLAG;
    }
    pthread_mutex_unlock(&list_lock);
}

int addNFAPI_CRC_INDICATION_PDU_T(int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list_lock);
    if (nfaPiListSize >= maxCapacity) {
        pthread_mutex_unlock(&list_lock);
        return -1; // List is full
    }

    NFAPI_CRC_INDICATION_PDU_T *newElement = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newElement->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newElement->RNTI = RNTI;
    for (int i = 0; i < 8; i++) {
        newElement->CRC_INDICATION_REL8_TAG[i] = rand() % 256;
    }
    newElement->CRCFLAG = DEFAULT_CRCFLAG;

    if (nfaPiListSize == 0) {
        nfaPiList = newElement;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *currentLastElement = nfaPiList;
        while (currentLastElement->RNTI != RNTI && currentLastElement->RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
            currentLastElement = currentLastElement + 1;
        }
        if (currentLastElement->RNTI == RNTI && currentLastElement->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            // Element already exists
            free(newElement);
            pthread_mutex_unlock(&list_lock);
            return -2; // Element already exists
        } else {
            NFAPI_CRC_INDICATION_PDU_T *newList = (NFAPI_CRC_INDICATION_PDU_T *)malloc((nfaPiListSize + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(newList, nfaPiList, nfaPiListSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            free(nfaPiList);
            nfaPiList = newList;
        }
    }

    pthread_mutex_unlock(&list_lock);
    return 0; // Element added
}

int removeNFAPI_CRC_INDICATION_PDU_T(int RNTI) {
    pthread_mutex_lock(&list_lock);
    NFAPI_CRC_INDICATION_PDU_T *currentElement = nfaPiList;
    for (int i = 0; i < nfaPiListSize; i++) {
        if (currentElement->RNTI == RNTI) {
            if (i != nfaPiListSize - 1) {
                NFAPI_CRC_INDICATION_PDU_T *newLastElement = currentElement;
                while (newLastElement + 1 < &nfaPiList[nfaPiListSize]) {
                    newLastElement++;
                }
                memcpy(currentElement, newLastElement + 1, (nfaPiListSize - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }
            free(currentElement);
            nfaPiList = &currentElement[1];
            nfaPiListSize--;
        } else {
            currentElement++;
        }
    }
    pthread_mutex_unlock(&list_lock);
    return 0; // Element removed
}

NFAPI_CRC_INDICATION_PDU_T *getIterator() {
    NFAPI_CRC_INDICATION_PDU_T *iterator = NULL;
    pthread_mutex_lock(&list_lock);
    iterator = nfaPiList;
    pthread_mutex_unlock(&list_lock);
    return iterator;
}

int getNFAPI_CRC_INDICATION_PDU_TSize() {
    int size = 0;
    pthread_mutex_lock(&list_lock);
    size = nfaPiListSize;
    pthread_mutex_unlock(&list_lock);
    return size;
}
