// Memory allocation and initialization
void* allocate_memory(size_t size) {
    // Use a single allocation strategy for similar data types (e.g., 'int' and 'long')
    void* mem = malloc(size);
    if (!mem) {
        printf("Memory allocation failed!\n");
        exit(1);
    }
    return mem;
}

// Handle cases where the allocated size is not a multiple of the data type size
void align_memory(void* mem, size_t size) {
    // Calculate the remaining bytes that need to be filled with zeros
    size_t remaining = (size_t)mem % sizeof(long);
    if (remaining != 0) {
        char* aligned_mem = (char*)mem + remaining;
        // Fill the remaining bytes with zeros
        memset(aligned_mem, '\0', sizeof(long) - remaining);
    }
}

// Initialize key array with sequential values starting from 0
void init_key_array(int** key_array, size_t size) {
    for (size_t i = 0; i < size; i++) {
        (*key_array)[i] = i;
    }
}

// Populate record array with random 'int' values and initialize 'char' arrays
void populate_record_array(record*** records, size_t size, int min_val, int max_val) {
    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < size; i++) {
        record* rec = (*records)[i] = allocate_memory(sizeof(record));
        rec->value = rand() % (max_val - min_val + 1) + min_val;
        rec->char_array = allocate_memory(strlen("Hello") + 1);
        strcpy((char*)rec->char_array, "Hello");
        rec->char_array[sizeof("Hello")] = '\0'; // Null terminate
    }
}

// Dynamic resizing mechanism for the 'record' array
void* resize_record_array(record*** records, size_t* size, size_t new_size) {
    record** new_records = allocate_memory(sizeof(record*) * new_size);
    for (size_t i = 0; i < *size && i < new_size; i++) {
        new_records[i] = (*records)[i];
    }
    for (size_t i = *size; i < new_size; i++) {
        new_records[i] = allocate_memory(sizeof(record));
        new_records[i]->value = 0;
        new_records[i]->char_array = allocate_memory(strlen("Hello") + 1);
        strcpy((char*)new_records[i]->char_array, "Hello");
        new_records[i]->char_array[sizeof("Hello")] = '\0'; // Null terminate
    }
    free(*records);
    *records = new_records;
    *size = new_size;
}

// Structure definition for the 'record' array
typedef struct {
    int value;
    char* char_array;
} record;

int main() {
    size_t offset_sizes[] = {1024, 2048};
    size_t key_size = sizeof(int);
