    // Allocate memory for each array based on provided sizes
    long** offset_arrays = (long**)malloc(sizeof(long*) * sizeof(offset_sizes) / sizeof(size_t));
    int* keys = allocate_memory(key_size * 5);
    record** records = allocate_memory(sizeof(record*) * 10);
    float* floats = allocate_memory(sizeof(float) * 5);
    char** chars = allocate_memory(sizeof(char*) * 5);

    // Initialize key array with sequential values starting from 0
    init_key_array(&keys, 5);

    // Populate record array with random 'int' values and initialize 'char' arrays
    populate_record_array(&records, 10, 0, 100);

    // Dynamic resizing mechanism for the 'record' array
    resize_record_array(&records, &size, 20);

    return 0;
}
