#include <time.h>
#include <string.h>

typedef struct {
    int priority;
    time_t deadline;
    char* status;
} task;

typedef struct {
    time_t timestamp;
    const char* message;
    struct log_entry* next;
} log_entry;

task* tasks = NULL;
log_entry* log_head = NULL;
log_entry* log_tail = NULL;

void create_task(int priority_min, int priority_max, long deadline_start, long deadline_end) {
    task* new_task = (task*)malloc(sizeof(task));
    if (!new_task) {
        fprintf(stderr, "Memory allocation failed for task structure.\n");
        return;
    }

    new_task->priority = rand() % (priority_max - priority_min + 1) + priority_min;
    new_task->deadline = (rand() % (deadline_end - deadline_start)) + deadline_start;

    char* status = (char*)malloc(strlen("New Task") + 1);
    if (!status) {
        fprintf(stderr, "Memory allocation failed for task status.\n");
        free(new_task);
        return;
    }

    strcpy(status, "New Task");
    new_task->status = status;

    log_entry* new_log_entry = (log_entry*)malloc(sizeof(log_entry));
    if (!new_log_entry) {
        fprintf(stderr, "Memory allocation failed for log entry.\n");
        free(new_task);
        return;
    }

    time_t timestamp = time(NULL);
    char* message = (char*)malloc(strlen("Task created") + 1);
    if (!message) {
        fprintf(stderr, "Memory allocation failed for log message.\n");
        free(new_task);
        free(new_log_entry);
        return;
    }

    strcpy(message, "Task created");
    new_log_entry->timestamp = timestamp;
    new_log_entry->message = message;
    new_log_entry->next = NULL;

    if (!log_head) {
        log_head = log_tail = new_log_entry;
    } else {
        log_tail->next = new_log_entry;
        log_tail = new_log_entry;
    }

    // Add the task to the array
    tasks = (task*)realloc(tasks, sizeof(task) * (tasks ? strlen(tasks) + 1 : 0));
    if (!tasks) {
        fprintf(stderr, "Memory allocation failed for task array.\n");
        free(new_task);
        return;
    }

    tasks[ strlen(tasks)++ ] = *new_task;
}

void destroy_tasks() {
    task* current_task = tasks;
    while (current_task) {
        task* next_task = current_task->next;
        free(current_task->status);
        free(current_task);
        current_task = next_task;
    }

    log_entry* current_log_entry = log_head;
    while (current_log_entry) {
        log_entry* next_log_entry = current_log_entry->next;
        free(current_log_entry->message);
        free(current_log_entry);
        current_log_entry = next_log_entry;
    }
}
