#include <string.h>
#include <time.h>

// Structure for NetworkEventLogEntry
typedef struct {
    long timestamp;
    int eventType;
    char* metadata;
} NetworkEventLogEntry;

// Function to initialize and manage dynamic array of NetworkEventLogEntry structures
NetworkEventLogEntry** networkEventLogCreate(int initialSize) {
    NetworkEventLogEntry** log = (NetworkEventLogEntry**)malloc(initialSize * sizeof(NetworkEventLogEntry*));
    for (int i = 0; i < initialSize; i++) {
        log[i] = NULL;
    }
    return log;
}

// Function to add a new event entry
void networkEventLogAdd(NetworkEventLogEntry** log, int index, long timestamp, int eventType, char* metadata) {
    if (!log[index]) {
        log[index] = (NetworkEventLogEntry*)malloc(sizeof(NetworkEventLogEntry));
        log[index]->timestamp = timestamp;
        log[index]->eventType = eventType;
        log[index]->metadata = strdup(metadata);
    }
}

// Function to update an existing event entry based on unique identifier
void networkEventLogUpdate(NetworkEventLogEntry** log, int index, long timestamp, int eventType, char* metadata) {
    if (log[index]) {
        free(log[index]->metadata);
        log[index]->timestamp = timestamp;
        log[index]->eventType = eventType;
        log[index]->metadata = strdup(metadata);
    }
}

// Function to retrieve entries by timestamp range
NetworkEventLogEntry** networkEventLogGetRange(NetworkEventLogEntry** log, long startTimestamp, long endTimestamp) {
    int size = 0;
    for (int i = 0; i < log[0]; i++) {
        if (log[i]->timestamp >= startTimestamp && log[i]->timestamp <= endTimestamp)
            size++;
    }
    NetworkEventLogEntry** result = (NetworkEventLogEntry**)malloc(size * sizeof(NetworkEventLogEntry*));
    int j = 0;
    for (int i = 0; i < log[0]; i++) {
        if (log[i]->timestamp >= startTimestamp && log[i]->timestamp <= endTimestamp) {
            result[j] = log[i];
            j++;
        }
    }
    return result;
}

// Function to filter events based on predefined event types and metadata fields
NetworkEventLogEntry** networkEventLogFilter(NetworkEventLogEntry** log, int eventTypeMask, char* metadataFilter) {
    int size = 0;
    for (int i = 0; i < log[0]; i++) {
        if ((log[i]->eventType & eventTypeMask) && strstr(log[i]->metadata, metadataFilter))
            size++;
    }
