    }
    fclose(fp);

    // Initialize a random number generator
    srand(time(NULL));

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T* arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (arr == NULL) {
        printf("Error allocating memory.\n");
        return NULL;
    }

    // Populate the array with unique RNTI and valid RX_UE_INFORMATION_TAG
    for (int i = 0; i < N; i++) {
        arr[i].RX_UE_INFORMATION_TAG = uInfoTags[i];
        do {
            arr[i].RNTI = rand() % 100;
        } while (arr[i].RNTI != uInfoTags[(i+1)%N]);
        arr[i].CRC_INDICATION_REL8_TAG = rand() % 10;
        if (rand() % 2) {
