                if (/* condition for update */) {
                    // Update UE information tag and reset CRC flag
                    nfa_api_array[j].rx_ue_info = ...; // update RX_UE_INFORMATION_TAG
                    nfa_api_array[j].crcflag = 0x00; // reset CRC flag
                }
            }
        }

        // Periodic reset of all CRC flags to default state
        for (int i = 0; i < current_size / sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
            nfa_api_array[i].crcflag = 0x00;
        }

        // Check if the array needs to be reallocated
        if (current_size >= allocated_size) {
            int new_allocated_size = current_size + 100;
            NFAPI_CRC_INDICATION_PDU_T* new_nfa_api_array = NULL;

            new_nfa_api_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(nfa_api_array, new_allocated_size);
