    data_t* data = (data_t*)malloc(num_elements * sizeof(data_t));
    data_t** pointers = (data_t**)malloc(num_elements * sizeof(data_t*));

    // Initialize linked list
    struct node {
        data_t* data;
        struct node* next;
    };
    struct node* head = NULL;
    struct node* current = NULL;

    for(int i = 0; i < num_elements; i++) {
        // Generate random float value and integer length
        float fvalue = (float)rand() / RAND_MAX * 100.0 + 1.0;
        int length = rand() % 10 + 5;
        char* string = (char*)malloc((length+1)*sizeof(char));
        for(int j = 0; j < length; j++) {
            string[j] = 'a' + (rand() % 26);
        }
        string[length] = '\0';

        // Initialize data structure
        data[i].index = i;
        data[i].value = fvalue;
        data[i].length = length;
        data[i].string = string;

        // Add to linked list
        if(head == NULL) {
            head = (struct node*)malloc(sizeof(struct node));
            current = head;
        } else {
            struct node* temp = (struct node*)malloc(sizeof(struct node));
            current->next = temp;
            current = temp;
        }
        current->data = &data[i];
        current->next = NULL;
    }

    // Add pointers to linked list
    for(int i = 0; i < num_elements; i++) {
        struct node* temp = (struct node*)malloc(sizeof(struct node));
        temp->data = &data[i];
        temp->next = NULL;
        if(head == NULL) {
            head = temp;
            current = temp;
        } else {
            current->next = temp;
            current = temp;
        }
    }

    // Deallocate memory
    for(int i = 0; i < num_elements; i++) {
        free(strings[i]);
        free(data[i].string);
    }
    free(doubles);
    free(strings);
    free(data);
    free(pointers);

    // Free linked list
    struct node* temp = head;
    while(temp != NULL) {
        struct node* next = temp->next;
        free(temp);
        temp = next;
    }
}

int main() {
    manage_memory(10);
    return 0;
}
