typedef struct {
    long offset;
    int key;
} record;

void manage_memory(int n) {
    if (n <= 0 || n > 10000) {
        printf("Invalid size %d. Size must be within [1, 10000].\n", n);
        return;
    }

    // Step 2: Allocate memory for offsets array
    long* offsets = malloc(n * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Insufficient memory for offsets.\n");
        exit(1);
    }

    // Step 3: Allocate memory for keys array
    int* keys = malloc(n * sizeof(int));
    if (!keys) {
        free(offsets);  // Free previously allocated memory
        fprintf(stderr, "Error: Insufficient memory for keys.\n");
        exit(1);
    }

    // Step 4: Define and allocate memory for records array
    record* records = malloc(n * sizeof(record));
    if (!records) {
        free(offsets);  // Free previously allocated memory
        free(keys);      // Free previously allocated memory
        fprintf(stderr, "Error: Insufficient memory for records.\n");
        exit(1);
    }

    // Step 5: Initialize offsets array with random values and unique keys
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        offsets[i] = rand() % 1001;
        int key = (rand() % 1000) + 1;  // Ensure all keys are within [1, 1000]
        while (i > 0 && (keys[i - 1] == key)) {  // Maintain data integrity by ensuring unique offsets
            key = (rand() % 1000) + 1;
        }
        keys[i] = key;
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    // Free allocated memory upon exit
    free(records);
    free(keys);
    free(offsets);
}

int main() {
    int n = 5000;  // Example size, can be changed to test different scenarios
    manage_memory(n);
    return 0;
}
