    long* offsets = (long*)malloc(max_records * sizeof(long));
    int* keys = (int*)malloc(max_records * sizeof(int));
    record_t** records = (record_t**)malloc(max_records * sizeof(record_t*));

    for (int i = 0; i < max_records; i++) {
        record_t* record = create_record(time(NULL) + i);
        record->value = (rand() % RANDOM_RANGE) + 1;
        while (record->value == (records[i-1]->value) - 1) { // ensure no two consecutive records share the same value
            record->value = (rand() % RANDOM_RANGE) + 1;
        }
        cache_invalidate();
        offsets[i] = i * sizeof(record_t);
        keys[i] = i;
        records[i] = record;
    }

    free(offsets);
    for (int i = 0; i < max_records; i++) {
        free(records[i]);
    }
