```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;

public class DataProcessor {
    public static void establishConnection(InetSocketAddress address) throws IOException {
        // Create a selector and socket channel
        Selector selector = Selector.open();
        SocketChannel channel = SocketChannel.open();

        // Establish connection
        channel.configureBlocking(false);
        channel.connect(address);

        // Handle connection state changes
        while (true) {
            SelectionKey key = channel.keyFor(selector);
            if (key != null && key.isReadable()) {
                readFromChannel(channel);
            } else if (key != null && key.isWritable()) {
                writeToChannel(channel);
            }
        }
    }

    private static void readFromChannel(SocketChannel channel) throws IOException {
        // Read from the channel
        byte[] buffer = new byte[1024];
        int bytesRead = channel.read(buffer);

        // Process incoming data
        processIncomingData(buffer, bytesRead);
    }

    private static void writeToChannel(SocketChannel channel) throws IOException {
        // Write to the channel
        byte[] buffer = new byte[1024];
        channel.write(buffer);

        // Send outgoing data
        sendOutgoingData(buffer);
    }
}
