    while (fscanf(file, "%lld %x %x %x %x %c\n", &current->timestamp, &current->pdu.valid, &current->pdu.RNTI, &current->pdu.PDCP_PDU_TAG[0], &current->pdu.PDCP_PDU_TAG[1], &current->pdu.PDCP_PDU_TAG[2], &current->pdu.PDCP_PDU_TAG[3]) == 7) {
        current = current->next;
    }

    fclose(file);
    return 0;
}

void print_timestamp_info() {
    timestamp_node* current = head;
    int unique_count = 0;

    while (current != NULL) {
        printf("Timestamp: %lld, Count: %d, Last seen sequence number: %x\n", current->timestamp, unique_count++, current->pdu.PDCP_PDU_TAG[3]);
        current = current->next;
    }
}

