    UESession** ueSessions = (UESession**)malloc(numUes * sizeof(UESession*));
    for (int i = 0; i < numUes; i++) {
        ueSessions[i] = createUESession(i + 1);
    }

    // Populate UE sessions with resources and traffic data
    for (int i = 0; i < numUes; i++) {
        RadioResourceBlock* resource = malloc(sizeof(RadioResourceBlock));
        resource->startFrequency = 100 + i;
        resource->endFrequency = 200 + i;
        ueSessions[i]->resources = resource;

        // Monitor and adjust resource allocation based on network load
        int trafficVolume = getTrafficVolume(ueSessions[i]);
        ueSessions[i]->trafficVolume += trafficVolume;
