#include <pthread.h>

#define MAX_ITEM_STR 256
#define MAX_LOG_ENTRY_MSG 1024

typedef enum { NEW, MODIFIED, DELETED } state;

struct item {
    float value;
    state status;
    char* str;
};

struct log_entry {
    time_t timestamp;
    int ref_count;
    char* message;
};

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void resize_message(struct log_entry* entry, int new_len) {
    char* old_message = entry->message;
    int old_len = strlen(old_message);

    // Calculate the required size for a new message
    int new_size = (new_len + 1) * sizeof(char);

    // Reallocate memory and copy the old message
    char* new_message = allocate_memory(new_size);
    strncpy(new_message, old_message, old_len);
    free(old_message);

    entry->message = new_message;
}

void item_init(struct item* item, float val, const char* str) {
    item->value = val;
    item->status = NEW;
    item->str = allocate_memory(strlen(str) + 1);
    strcpy(item->str, str);
}

void log_entry_init(struct log_entry* entry, time_t timestamp, int ref_count) {
    entry->timestamp = timestamp;
    entry->ref_count = ref_count;
    entry->message = allocate_memory(MAX_LOG_ENTRY_MSG * sizeof(char));
    // Initialize message with random alphanumeric characters
    srand(time(NULL));
    char* p = entry->message;
    for (int i = 0; i < MAX_LOG_ENTRY_MSG; ++i) {
        *p++ = (char)(rand() % 26 + 'a');
    }
    *p = '\0';
}

void log_entry_acquire(struct log_entry* entry) {
    pthread_mutex_lock(&entry->mutex);
    entry->ref_count++;
    pthread_mutex_unlock(&entry->mutex);
}

void log_entry_release(struct log_entry* entry) {
    pthread_mutex_lock(&entry->mutex);
    if (--entry->ref_count == 0) {
        free(entry->message);
        free(entry);
    }
    pthread_mutex_unlock(&entry->mutex);
}

void item_free(struct item* item) {
    free(item->str);
    free(item);
}

void log_entry_free(struct log_entry* entry) {
    log_entry_release(entry);
}
