void *malloc_aligned(size_t size, size_t alignment) {
    size_t block_size = sysconf(_SC_PAGE_SIZE);
    size_t offset = (size_t).alignment - 1;
    void *ptr = NULL;

    do {
        ptr = valloc(size + offset);
        if (!ptr) break;
    } while ((size_t)ptr & offset);

    return ptr;
}

