#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <threads.h>

// Define the maximum number of items allowed in the collection
#define MAX_ITEMS 10000

// Define the structure for a single item in the collection
typedef struct {
    int index;
    float value;
} Item;

// Define the structure for the collection itself
typedef struct {
    Item* items; // Array to store the actual items
    unsigned int size; // Current number of items in the collection
    unsigned int capacity; // Maximum number of items allowed
    thrd_t lock; // Lock for thread-safe operations
} Collection;

// Function to create a new collection with an initial capacity
Collection* create_collection(unsigned int initial_capacity) {
    Collection* coll = (Collection*)malloc(sizeof(Collection));
    if (!coll) return NULL;
    coll->items = (Item*)calloc(initial_capacity, sizeof(Item));
    if (!coll->items) {
        free(coll);
        return NULL;
    }
    coll->size = 0;
    coll->capacity = initial_capacity;
    coll->lock = thrd_create_np(NULL, NULL); // Create a lock
    if (!coll->lock) {
        free(coll->items);
        free(coll);
        return NULL;
    }
    return coll;
}

// Function to insert an item into the collection with a unique key
int insert_item(Collection* coll, const char* key, int index, float value) {
    // Calculate the hash value for the given key
    unsigned int hash = (unsigned int)hash_string(key);

    // Find the next available slot in the array using linear probing
    unsigned int i;
    for (i = 0; i < coll->size; i++) {
        if (coll->items[i].index == -1) break; // Found an empty slot
    }

    // If no slots are available, double the capacity of the collection
    if (i >= coll->capacity) {
        unsigned int new_capacity = 2 * coll->capacity;
        Item* new_items = (Item*)realloc(coll->items, new_capacity * sizeof(Item));
        if (!new_items) return -1; // Allocation failed
        coll->items = new_items;
        coll->capacity = new_capacity;
    }

    // Insert the item into the collection at the calculated slot
    coll->items[i].index = index;
    coll->items[i].value = value;

    // Update the size of the collection
    coll->size++;

    return 0; // Successful insertion
}

// Function to retrieve an item from the collection by its unique key
Item* get_item(Collection* coll, const char* key) {
    unsigned int hash = (unsigned int)hash_string(key);

    // Search for the item using linear probing
    unsigned int i;
    for (i = 0; i < coll->size; i++) {
        if (coll->items[i].index != -1 && strcmp((char*)key, (char*)coll->items[i].index) == 0) break; // Found the item
    }

    if (i >= coll->size) return NULL; // Item not found

    // Lock for thread-safe access to the retrieved item
    thrd_create_np(coll->lock, NULL); // Acquire lock
    // ... (access the item)
    thrd_yield_np(); // Release lock

    return &coll->items[i]; // Return the retrieved item
}

// Function to free allocated resources when the library is no longer in use
void destroy_collection(Collection* coll) {
    if (!coll) return; // Nothing to clean up

    // Free items array and its contents
    for (unsigned int i = 0; i < coll->size; i++) {
        Item* item = &coll->items[i];
        if (item->index != -1) free(item); // Not a placeholder, so we can safely free it
    }
    free(coll->items);

    // Free the lock and any other allocated resources
    thrd_destroy_np(coll->lock);
    free(coll);
}

// Helper function to calculate the hash value for a given string
unsigned int hash_string(const char* str) {
    unsigned int hash = 0;
    while (*str) {
        hash += (unsigned int)*str;
        str++;
    }
    return hash;
}
