    char* event_types = NULL;
    time_t* timestamps = NULL;
    struct event* events = NULL;

    // Calculate the number of events based on the maximum size in bytes
    if (max_size_bytes < sizeof(float) + sizeof(char) + sizeof(time_t)) {
        return -1;  // Error: insufficient memory for a single event
    }
    num_events = max_size_bytes / (sizeof(float) + sizeof(char) + sizeof(time_t));

    // Allocate and initialize arrays
    if (!(sensor_readings = malloc(num_events * sizeof(float)))) {
        free(sensor_readings);
        return -1;  // Error: unable to allocate memory for sensor readings
    }
    memset(sensor_readings, 0, num_events * sizeof(float));

    if (!(event_types = malloc(num_events * sizeof(char)))) {
        free(event_types);
        free(sensor_readings);
        return -1;  // Error: unable to allocate memory for event types
    }
    memset(event_types, '\0', num_events * sizeof(char));

    if (!(timestamps = malloc(num_events * sizeof(time_t)))) {
        free(timestamps);
        free(event_types);
        free(sensor_readings);
        return -1;  // Error: unable to allocate memory for timestamps
    }
    time_t timestamp = *initial_timestamp;
    for (size_t i = 0; i < num_events; ++i) {
        timestamp = time_add(timestamp, 1);  // Calculate the next timestamp one second later
        timestamps[i] = timestamp;
    }

    if (!(events = malloc(num_events * sizeof(struct event)))) {
        free(events);
        free(timestamps);
        free(event_types);
        free(sensor_readings);
        return -1;  // Error: unable to allocate memory for events
    }
    for (size_t i = 0; i < num_events; ++i) {
        struct event event;
        event.sensor_reading = sensor_readings[i];
        event.event_type = event_types[i];
        event.timestamp = timestamps[i];
        events[i] = event;
    }

    return 0;  // Success
}

int main() {
    int max_size_bytes = 1024 * 1024;  // Adjust the maximum size to your needs
    int initial_timestamp = time(NULL);

    if (allocate_and_initialize_arrays(max_size_bytes, &initial_timestamp)) {
        printf("Error allocating and initializing arrays.\n");
        return -1;
    }

    // Use the allocated arrays...

    free(events);
    free(timestamps);
    free(event_types);
    free(sensor_readings);

    return 0;
}

struct event {
    float sensor_reading;
    char event_type;
    time_t timestamp;
};

time_t time_add(time_t t, int seconds) {
    struct tm* tm = localtime(&t);
    tm->tm_sec += seconds;
    return mktime(tm);
}
