typedef struct {
    int key;
    long offset;
} record;

record* allocateArrays(int arraySize) {
    if (arraySize > MAX_MEMORY / (sizeof(long) + sizeof(int))) {
        return NULL; // error: out of memory
    }
    record* records = (record*) malloc(arraySize * sizeof(record));
    int* keys = (int*) malloc(arraySize * sizeof(int));
    long* offsets = (long*) malloc(arraySize * sizeof(long));

    for (int i = 0; i < arraySize; i++) {
        keys[i] = i;
        offsets[i] = i;
    }
    return records;
}

void generateRandomValues(record* records, int arraySize) {
    srand(time(NULL));
    for (int i = 0; i < arraySize; i++) {
        records[i].key = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        // offset value generation...
    }
}

void sortRecords(record* records, int arraySize) {
    qsort(records, arraySize, sizeof(record), compareRecords);
}

int compareRecords(const void* a, const void* b) {
    record* rec1 = (record*) a;
    record* rec2 = (record*) b;
    return rec1->key - rec2->key; // ascending order
}

record* getRecord(int index, int arraySize) {
    if (index < 0 || index >= arraySize) {
        return NULL; // error: out of bounds
    }
    return &records[index];
}

