#define MAX_SIZE 1024*1024 // 1MB maximum size
#define MAX_TASKS 1000      // Maximum number of tasks allowed

// Structure to represent a task with priority and description
typedef struct {
    int priority;
    char* description;
} Task;

// Function prototypes
Task* create_task_array(int num_tasks);
void sort_tasks(Task* tasks, int num_tasks);
int compare_tasks(const void* a, const void* b);
void free_task_array(Task* tasks);

int main() {
    int num_tasks = 0; // User input for number of tasks
    Task* task_array = NULL;

    while (num_tasks < 1 || num_tasks > MAX_TASKS) {
        printf("Enter the number of tasks (1-%d): ", MAX_TASKS);
        scanf("%d", &num_tasks);

        if (num_tasks < 1 || num_tasks > MAX_TASKS) {
            printf("Invalid input. Please try again.\n");
        }
    }

    task_array = create_task_array(num_tasks);

    // Perform tasks and sort based on priority
    sort_tasks(task_array, num_tasks);

    free_task_array(task_array);

    return 0;
}

Task* create_task_array(int num_tasks) {
    Task* task_array = NULL;

    if (num_tasks > 0 && num_tasks <= MAX_TASKS) {
        task_array = (Task*)malloc(num_tasks * sizeof(Task));
        for (int i = 0; i < num_tasks; i++) {
            // Allocate memory for each task description
            char* desc = malloc(256); // Assuming max description length is 255 bytes
            printf("Enter priority and description for task %d: ", i);
            scanf("%d", &task_array[i].priority);
            scanf("%s", desc);

            // Set the task description pointer in the structure
            task_array[i].description = desc;
        }
    } else {
        printf("Invalid number of tasks. Please try again.\n");
    }

    return task_array;
}

void sort_tasks(Task* tasks, int num_tasks) {
    qsort(tasks, num_tasks, sizeof(Task), compare_tasks);
}

int compare_tasks(const void* a, const void* b) {
    Task* task1 = (Task*)a;
    Task* task2 = (Task*)b;

    // Compare priority levels
    if (task1->priority < task2->priority) return -1;
    else if (task1->priority > task2->priority) return 1;
    else {
        // If priorities are equal, compare descriptions by length
        int desc_len1 = strlen(task1->description);
        int desc_len2 = strlen(task2->description);

        if (desc_len1 < desc_len2) return -1;
        else if (desc_len1 > desc_len2) return 1;
    }

    return 0; // Equal
}

void free_task_array(Task* tasks) {
    for (int i = 0; i < MAX_TASKS; i++) {
        if (tasks[i].description != NULL) {
            free(tasks[i].description);
        }
    }

    free(tasks);
}
