void* dynamicMemAllocate(size_t size) {
    void *ptr = malloc(size);
    if (!ptr && !retryMalloc(size)) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    return ptr;
}

int retryMalloc(size_t size) {
    for (int i = 0; i < 5; i++) {
        void *ptr = malloc(size);
        if (ptr) return 1;
    }
    return 0;
}

void logMemUsage(size_t size) {
    printf("Total memory usage: %zu bytes.\n", size);
}

