NFAPI_RX_FRAME_INFO_PDU_T** nfapi_rx_frame_info_pdu_list(int M, float similarity_threshold) {
    int i;
    NFAPI_RX_FRAME_INFO_PDU_T** list = (NFAPI_RX_FRAME_INFO_PDU_T**)malloc((M+1)*sizeof(NFAPI_RX_FRAME_INFO_PDU_T*));

    if(list == NULL){
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for(i=0; i<=M; i++){
        list[i] = (NFAPI_RX_FRAME_INFO_PDU_T*)malloc(sizeof(NFAPI_RX_FRAME_INFO_PDU_T));

        // Randomly set RX_QUALITY
        list[i]->RX_QUALITY = (float)rand() / RAND_MAX;

        if(list[i] == NULL){
            printf("Memory allocation failed.\n");
            for(j=0; j<i; j++){
                free(list[j]);
            }
            for(k=i-1; k>=0; k--){
                free(list[k]);
            }
            return NULL;
        }
    }

    // Ensure no two consecutive RX_QUALITY values in the list are within similarity_threshold
    for(i=0; i<M-1; i++){
        while(abs(list[i]->RX_QUALITY - list[i+1]->RX_QUALITY) <= similarity_threshold){
            free(list[i]);
            i--;
            if(i<0){
                printf("Memory allocation failed.\n");
                for(j=0; j<i; j++){
                    free(list[j]);
                }
                for(k=i-1; k>=0; k--){
                    free(list[k]);
                }
                return NULL;
            }
            list[i+1]->RX_QUALITY = (float)rand() / RAND_MAX;
        }
    }

    return list;
}

