    // Find the cell statistics entry with the matching CELL_ID
    for (int i = 0; i < list->size; i++) {
        if (list->cells[i].CELL_ID == cell_id) {
            pthread_mutex_lock(&list->lock);
            list->cells[i] = updated_stats;
            pthread_mutex_unlock(&list->lock);
