#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_FLOAT_SIZE 1000000
#define MAX_CHAR_SIZE 50000
#define RANDOM_RANGE 10.0f
#define SEED 123

typedef struct {
    float value;
    struct node* next;
} node;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(1);
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

int main() {
    int num_floats, num_chars;
    printf("Enter the number of floats: ");
    scanf("%d", &num_floats);
    printf("Enter the number of chars: ");
    scanf("%d", &num_chars);

    // Initialize random seed
    srand(SEED);

    // Allocate memory for arrays
    float* floats = my_malloc(num_floats * sizeof(float));
    char* chars = my_malloc(num_chars * sizeof(char));

    node* head = NULL;
    node** nodes = (node**)my_malloc((num_floats + 1) * sizeof(node*));

    // Initialize linked list
    for (int i = 0; i < num_floats; i++) {
        float val = ((float)(rand() / (float)RAND_MAX)) * RANDOM_RANGE;
        while (i > 0 && val == nodes[i-1]->value) {
            val = ((float)(rand() / (float)RAND_MAX)) * RANDOM_RANGE;
        }
        node* node = (node*)my_malloc(sizeof(node));
        node->value = val;
        node->next = NULL;
        if (!head) {
            head = node;
        } else {
            nodes[i]->next = node;
        }
        nodes[i] = node;
    }

    // Initialize char array
    for (int i = 0; i < num_chars; i++) {
        char c = rand() % 26 + 'a';
        chars[i] = c;
    }

    // Release memory
    my_free(floats);
    my_free(chars);
    for (int i = 0; i <= num_floats; i++) {
        if (nodes[i]) {
            node* temp = nodes[i];
            while (temp->next) {
                temp = temp->next;
            }
            my_free(temp);
        }
    }

    return 0;
}

