void initLTE_RRC_RECONFIGURATION_MESSAGE(LTE_RRC_RECONFIGURATION_MESSAGE **lte_rrc_reconfiguration_messages, int num_messages) {
    for (int i = 0; i < num_messages; i++) {
        LTE_RRC_RECONFIGURATION_MESSAGE *message = malloc(sizeof(LTE_RRC_RECONFIGURATION_MESSAGE));

        // Initialize RRC reconfiguration tag
        message->rrc_reconfiguration_tag = 1;

        // Initialize MME cell reconfiguration info array
        int num_mme_cells = 5;
        MME_CELL_RECONFIGURATION_INFO *mme_cell_info = malloc(num_mme_cells * sizeof(MME_CELL_RECONFIGURATION_INFO));

        for (int j = 0; j < num_mme_cells; j++) {
            MME_CELL_RECONFIGURATION_INFO cell_info;
            cell_info.valid_tag = 1;
            cell_info.mme_cell_id = i + j;

            mme_cell_info[j] = cell_info;
