            *lte_rrc_reconfiguration_messages = malloc(sizeof(LTE_RRC_RECONFIGURATION_MESSAGE));
            **lte_rrc_reconfiguration_messages = *message;
        } else {
            *(*lte_rrc_reconfiguration_messages + i) = *message;
        }

        free(message->mme_cell_info);
