        nodes[i]->value->str = (char*)malloc(64 * sizeof(char)); // Reserve space for string with max length 63
        nodes[i]->value->len = 0;
    }
    return nodes;
}

void update_node(node_t** nodes, int index, const char* new_str) {
    if (index >= 0 && index < strlen(nodes)) {
        value_t* node_value = nodes[index]->value;
        free(node_value->str);
        node_value->str = strdup(new_str);
        node_value->len = strlen(new_str);
    }
}

void destroy_node_array(node_t** nodes, int num_nodes) {
    for (int i = 0; i < num_nodes; i++) {
        value_t* node_value = nodes[i]->value;
        free(node_value->str);
        free(nodes[i]);
    }
    free(nodes);
}
