Here is the code block for converting a provided JPEG file into a PDF file:

```java
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;

public class JavaMethod {
    public int convertJPEGToPDF(String inputFilePath, String outputFilePath) throws Exception {
        // Read the JPEG file
        FileInputStream fis = new FileInputStream(inputFilePath);
        byte[] imageData = new byte[fis.available()];
        fis.read(imageData);

        // Convert the JPEG image to a PDF page
        ImageConverter converter = new ImageConverter();
        BufferedImage bufferedImage = converter.convertJPEGToBufferedImage(imageData);

        // Create a PDF document
        File file = new File(outputFilePath);
        FileOutputStream fos = new FileOutputStream(file);
        PdfDocument pdf = new PdfDocument();

        // Add the converted image to the PDF page
        Page page = pdf.newPage();
        Graphics2D g2d = page.createGraphics();
        g2d.drawImage(bufferedImage, 0, 0, page.getWidth(), page.getHeight());
        g2d.dispose();
        fos.write(pdf.toByteArray());
        fos.close();

        return 0;
    }
}
