// Define the record structure
typedef struct {
    int value;
} record;

// Function to generate offsets using a linear congruential generator (LCG)
long offset_generator(int index, long a, long c) {
    return (a * index + c) % 9223372036854775807L;
}

// Allocate memory for the given components
record** allocate_memory(int min_offset, int max_offset, int key_count, int record_count, int* a, int* c) {
    // Calculate the size of the offset array
    int offset_size = max_offset - min_offset + 1;

    // Dynamically allocate memory for the offset array
    long* offsets = (long*)malloc(offset_size * sizeof(long));

    if (!offsets) {
        return NULL; // Handle allocation failure
    }

    // Initialize the offset array using the offset_generator function
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = offset_generator(i + min_offset, *a, *c);
    }

    // Dynamically allocate memory for the key array and initialize it to zero
    int* keys = (int*)malloc(key_count * sizeof(int));

    if (!keys) {
        free(offsets); // Free allocated memory in case of failure
        return NULL;
    }

    for (int i = 0; i < key_count; i++) {
        keys[i] = 0;
    }

    // Dynamically allocate memory for the record array and initialize it to zero
    record* records = (record*)malloc(record_count * sizeof(record));

    if (!records) {
        free(offsets);
        free(keys); // Free allocated memory in case of failure
        return NULL;
    }

    for (int i = 0; i < record_count; i++) {
        records[i].value = 0;
    }

    // Return a pointer to the dynamically allocated arrays
    return (record**)malloc(1 * sizeof(record*) + offset_size * sizeof(long) + key_count * sizeof(int));
}

