// Dynamic array of NFAPI_RRC_MSG structures
NFAPI_RRC_MSG **rrc_messages = NULL;
int rrc_message_count = 0;
pthread_mutex_t rrc_message_lock = PTHREAD_MUTEX_INITIALIZER;

void *allocate_ues(int num_ues) {
    return realloc(NULL, num_ues * sizeof(NFAPI_RRC_MSG *));
}

void *reallocate_ue_messages(void *ptr, int new_size) {
    return realloc(ptr, new_size * sizeof(NFAPI_RRC_MSG *));
}

int add_rrc_message(uint32_t ue_id, NFAPI_RRC_MSG *message) {
    pthread_mutex_lock(&rrc_message_lock);
    if (rrc_message_count >= MAX_MESSAGES) {
        // Handle edge case: out-of-memory condition
        rrc_messages = reallocate_ue_messages(rrc_messages, 2 * MAX_MESSAGES);
        rrc_message_count *= 2;
    }
    NFAPI_RRC_MSG **new_arr = realloc(rrc_messages, (rrc_message_count + 1) * sizeof(NFAPI_RRC_MSG *));
    if (!new_arr) {
        // Handle edge case: out-of-memory condition
        pthread_mutex_unlock(&rrc_message_lock);
        return -1;
    }
    rrc_messages = new_arr;
    rrc_messages[rrc_message_count] = message;
    (rrc_message_count)++;
    pthread_mutex_unlock(&rrc_message_lock);
    return 0;
}

NFAPI_RRC_MSG *get_rrc_message(uint32_t ue_id) {
    pthread_mutex_lock(&rrc_message_lock);
    for (int i = 0; i < rrc_message_count; i++) {
        if (rrc_messages[i]->ue_id == ue_id) {
            NFAPI_RRC_MSG *message = rrc_messages[i];
            pthread_mutex_unlock(&rrc_message_lock);
            return message;
        }
    }
    pthread_mutex_unlock(&rrc_message_lock);
    return NULL;
}

void update_rrc_message(uint32_t ue_id, int type, uint16_t seq_num) {
    pthread_mutex_lock(&rrc_message_lock);
    for (int i = 0; i < rrc_message_count; i++) {
        if (rrc_messages[i]->ue_id == ue_id) {
            rrc_messages[i]->type = type;
            rrc_messages[i]->seq_num = seq_num;
            pthread_mutex_unlock(&rrc_message_lock);
            return;
        }
    }
    pthread_mutex_unlock(&rrc_message_lock);
}

int main() {
    // Initialize the dynamic array
    rrc_messages = allocate_ues(MAX_UE);

    // Add and update RRC messages
    add_rrc_message(1, (NFAPI_RRC_MSG *)malloc(sizeof(NFAPI_RRC_MSG)));
    update_rrc_message(1, 2, 3);

