// Define the linked list structure
typedef struct LLNode {
    NFAPI_UL_CQI_REPORT_PDU_T* data;
    struct LLNode* next;
} LLNode;

// Function to create a new node
LLNode* llCreateNode(NFAPI_UL_CQI_REPORT_PDU_T* data) {
    LLNode* newNode = (LLNode*)malloc(sizeof(LLNode));
    if (!newNode) return NULL; // Handle allocation failure
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Function to add a new node at the end of the list
void llAddTail(LLNode** head, NFAPI_UL_CQI_REPORT_PDU_T* data) {
    LLNode* newNode = llCreateNode(data);
    if (!newNode) return; // Handle allocation failure
    if (*head == NULL) *head = newNode;
    else {
        LLNode* curr = *head;
        while (curr->next) curr = curr->next;
        curr->next = newNode;
    }
}

// Function to remove a node with matching RNTI value
void llRemoveByRNTI(LLNode** head, int targetRNTI) {
    if (*head == NULL) return; // List is empty
    LLNode* prev = *head;
    LLNode* curr = (*head)->next;
    while (curr) {
        if (curr->data->RNTI == targetRNTI) {
            if (prev == *head) {
                *head = curr;
            } else {
                prev->next = curr->next;
            }
            free(curr);
            return; // Node found and removed
        }
        prev = curr;
        curr = curr->next;
    }
}

// Function to retrieve a node by RNTI value
NFAPI_UL_CQI_REPORT_PDU_T* llGetByRNTI(LLNode* head, int targetRNTI) {
    LLNode* curr = head;
    while (curr) {
        if (curr->data->RNTI == targetRNTI) return curr->data; // Node found
        curr = curr->next;
    }
    return NULL; // Node not found
}

// Function to free the linked list
void llFree(LLNode** head) {
    LLNode* curr = *head;
    LLNode* next = NULL;
    while (curr) {
        next = curr->next;
        free(curr);
        curr = next;
    }
    *head = NULL; // Set head to NULL
}

