record* manage_memory_allocation(int offset_count, int key_count, int key_substring_length) {
    if (offset_count <= 0 || key_count <= 0) {
        return NULL; // invalid count
    }

    long* offsets = (long*)malloc(offset_count * sizeof(long));
    int* keys = (int*)malloc(key_count * sizeof(int));

    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        return NULL; // allocation failed
    }

    record* records = (record*)malloc((key_count + offset_count) * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL; // allocation failed
    }

    int i;
    for (i = 0; i < key_count; i++) {
        keys[i] = rand() % 1000 + 1; // generate random number within range [1, 1000]
    }

    srand(time(NULL)); // seed random number generator

    for (i = 0; i < offset_count; i++) {
        offsets[i] = i;
    }
    for (i = 0; i < key_count; i++) {
        records[i].id = 'K';
        records[i].value = keys[i];
        records[i].key = (key_record*)malloc(sizeof(key_record));
        if (!records[i].key) {
            free(offsets);
            free(keys);
            free(records);
            return NULL; // allocation failed
        }
        records[i].key->offset = offsets[i % offset_count]; // reference the offset array
        char substring[key_substring_length];
        for (int j = 0; j < key_substring_length && i < key_count; j++) {
            substring[j] = 'a' + (i % 26); // generate a substring using ASCII characters
            records[i].key->substring = substring;
        }
    }

    free(offsets);
    free(keys);

    return records;
}
