void add_node(NR_UE_MEASUREMENT_REPORT_T* new_data) {
    struct node* new_node = (struct node*)malloc(sizeof(struct node));
    if (new_node == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    new_node->data = *new_data;
    new_node->prev = NULL;
    new_node->next = dllist;

    if (dllist != NULL)
        dllist->prev = &new_node->data;
    else
        dllist = &new_node->data;

    dllist = &new_node->data;
    node_count++;
}

void remove_node() {
    if (node_count == 0) {
        printf("No nodes to remove.\n");
        return;
    }

    struct node* temp = dllist;
    dllist = dllist->next;
    free(temp);
    node_count--;
}
