    for (int i = 0; i < numRecords; i++) {
        records[i].offset = i;
        records[i].key = rand() % 1000;
        records[i].weight = (float)i / 10.0f;
        records[i].status = 'N';
    }
    return records;
}

void manageRecords(int* numRecords, int maxCapacity) {
    Record** records = NULL;
    Record* currentRecords = NULL;

    while (*numRecords < maxCapacity) {
        if (records == NULL || *numRecords >= *records + sizeof(Record)) {
            records = (Record**)realloc(records, (*numRecords + 1) * sizeof(Record*));
            currentRecords = initRecords(*numRecords);
            for (int i = 0; i < *numRecords; i++) {
                records[i] = &currentRecords[i];
            }
        }
    }

    printf("Number of records: %d\n", *numRecords);
}
