typedef struct {
    long duration;
    int priority;
    double resource_usage;
    char status;
} task;

task** tasks = NULL;
int task_count = 0;
int max_tasks = 10000000; // 10 million
int task_size = sizeof(task);

void init_tasks() {
    tasks = (task**)malloc(max_tasks * sizeof(task*));
    for(int i = 0; i < max_tasks; i++) {
        tasks[i] = (task*)malloc(task_size);
    }
}

void free_tasks() {
    for(int i = 0; i < task_count; i++) {
        free(tasks[i]);
    }
    free(tasks);
}

int insert_task(long duration, int priority) {
    if(task_count >= max_tasks) {
        max_tasks *= 2;
        tasks = (task**)realloc(tasks, max_tasks * sizeof(task*));
        for(int i = task_count; i < max_tasks; i++) {
            tasks[i] = (task*)malloc(task_size);
        }
    }
    tasks[task_count]->duration = duration;
    tasks[task_count]->priority = priority;
    tasks[task_count]->resource_usage = (double)rand() / RAND_MAX;
    tasks[task_count]->status = 'N'; // New
    task_count++;
    return task_count - 1;
}

int filter_tasks(int priority, double resource_usage) {
    for(int i = 0; i < task_count; i++) {
        if(tasks[i]->priority == priority && tasks[i]->resource_usage >= resource_usage) {
            return i;
        }
    }
    return -1;
}

void update_task_status(int index, char status) {
    if(index >= 0 && index < task_count) {
        tasks[index]->status = status;
    }
}

void log_operation(char* operation, int task_index) {
    printf("Task %d: %s\n", task_index, operation);
}
