// Define the structure for UE_STATUS_UPDATE_PDU_T
typedef struct {
    char ue_identifier[16];
    int measurement_report;
    int cell_measurement_report;
} UE_STATUS_UPDATE_PDU_T;

// Define the list structure
typedef struct {
    UE_STATUS_UPDATE_PDU_T* elements;
    int size;
    int capacity;
} dynamic_list_t;

// Initialize a new dynamic list with initial capacity M
dynamic_list_t* initialize_dynamic_list(int M) {
    dynamic_list_t* list = (dynamic_list_t*)malloc(sizeof(dynamic_list_t));
    list->elements = (UE_STATUS_UPDATE_PDU_T*)malloc(M * sizeof(UE_STATUS_UPDATE_PDU_T));
    list->size = 0;
    list->capacity = M;
    return list;
}

// Insert a new UE_STATUS_UPDATE_PDU_T at the end of the list
void insert_ue_status_update(dynamic_list_t* list, UE_STATUS_UPDATE_PDU_T* ue_status_update) {
    if (list->size == list->capacity) {
        // Resize the array if it's full
        list->elements = realloc(list->elements, (list->capacity + 10) * sizeof(UE_STATUS_UPDATE_PDU_T));
        list->capacity += 10;
    }
    list->elements[list->size] = *ue_status_update;
    list->size++;
}

// Delete the UE_STATUS_UPDATE_PDU_T at the given index
void delete_ue_status_update(dynamic_list_t* list, int index) {
    if (index >= list->size)
        return; // Return without modifying anything

    // Shift all elements after index to the left
    for (int i = index; i < list->size - 1; i++) {
        list->elements[i] = list->elements[i + 1];
    }

    // Decrement size and free the last element if necessary
    if (list->size > 0 && list->capacity == list->size) {
        list->elements = realloc(list->elements, list->size * sizeof(UE_STATUS_UPDATE_PDU_T));
        list->capacity = list->size;
    }
    list->size--;
}

// Print the contents of the dynamic list
void print_ue_status_updates(dynamic_list_t* list) {
    for (int i = 0; i < list->size; i++) {
        printf("UE Identifier: %s, Measurement Report: %d, Cell Measurement Report: %d\n",
            list->elements[i].ue_identifier,
            list->elements[i].measurement_report,
            list->elements[i].cell_measurement_report);
    }
}

// Free the dynamic list and its contents
void free_dynamic_list(dynamic_list_t* list) {
    if (list != NULL) {
        for (int i = 0; i < list->size; i++) {
            // Do not free UE_STATUS_UPDATE_PDU_T elements here, it will be done automatically when the array is freed
        }
        free(list->elements);
        free(list);
    }
}

// Thread-safe version of print_ue_status_updates for concurrent access
void* thread_safe_print_ue_status_updates(void* arg) {
    dynamic_list_t* list = (dynamic_list_t*)arg;
    pthread_mutex_lock(&list->mutex); // Lock the mutex before accessing shared data
    for (int i = 0; i < list->size; i++) {
        printf("UE Identifier: %s, Measurement Report: %d, Cell Measurement Report: %d\n",
            list->elements[i].ue_identifier,
            list->elements[i].measurement_report,
            list->elements[i].cell_measurement_report);
    }
    pthread_mutex_unlock(&list->mutex); // Unlock the mutex after accessing shared data
    return NULL;
}

int main() {
    dynamic_list_t* list = initialize_dynamic_list(10);

    UE_STATUS_UPDATE_PDU_T ue_status_update1 = {"UE001", 123, 456};
    UE_STATUS_UPDATE_PDU_T ue_status_update2 = {"UE002", 789, 101112};

    insert_ue_status_update(list, &ue_status_update1);
    insert_ue_status_update(list, &ue_status_update2);

    // Create and start a thread for concurrent access
    pthread_t thread;
    pthread_create(&thread, NULL, thread_safe_print_ue_status_updates, list);

    print_ue_status_updates(list); // Print the contents of the dynamic list

    // Free the dynamic list and its contents
    free_dynamic_list(list);

    return 0;
}
