#define MAX_N 10000
#define RNTI_MIN 0
#define RNTI_MAX 65535

typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int crcFlagCount = 0;
time_t lastUpdate = 0;

void* allocateArray(int N) {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDIFICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG[15] = '\0';
        array[i].CRC_INDICATION_REL8_TAG[15] = '\0';

        srand(time(NULL));
        int randomIndex = rand() % 2;
        array[i].CRC_INDICATION_REL8_TAG[randomIndex] = '1';

        // Validate RNTI values
        if (array[i].RNTI < RNTI_MIN || array[i].RNTI > RNTI_MAX) {
            array[i].RNTI = RNTI_MIN;
        }
    }

    return array;
}

int main(int argc, char* argv[]) {
    int N = atoi(argv[1]);

    if (N > MAX_N) {
        printf("Error: Maximum allowed value exceeded.\n");
        return 1;
    }

    void* array = allocateArray(N);

    if (!array) {
        printf("Memory allocation failed.\n");
        return 2;
    }

    // Update CRC indication count and last update time
    pthread_mutex_lock(&mutex);
    crcFlagCount += N;
    lastUpdate = time(NULL);
    pthread_mutex_unlock(&mutex);

    free(array);
    return 0;
}
