    if (pdu->CRCFLAG) {
        total_crc_indications++;
    }
}

void track_crc_indication_timestamps(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    clock_t current_time = clock();
    if (difftime(current_time, last_update_time) > 10) { // adjust the time difference as needed
        // process all accumulated CRC indications here
        total_crc_indications = 0;
        last_update_time = current_time;
    }
}

void handle_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    update_crc_indication_count(pdu);
    track_crc_indication_timestamps(pdu);
}

int main() {
