void init_device(device_state* dev) {
    dev->protocol_buffer = malloc(1024);
    dev->buffer_size = 1024;
}

void free_device(device_state* dev) {
    free(dev->protocol_buffer);
}

void add_device(device_state** devices, size_t* num_devices, device_state* dev) {
    *num_devices += 1;
    *devices = realloc(*devices, (*num_devices + 1) * sizeof(device_state*));
    (*devices)[*num_devices - 1] = dev;
}

void remove_device(device_state** devices, size_t* num_devices, int index) {
    memmove(&((*devices)[index]), &((*devices)[index+1]), (*num_devices - index - 1) * sizeof(device_state*));
    (*num_devices)--;
    *devices = realloc(*devices, *num_devices * sizeof(device_state*));
}

void print_device(device_state* dev) {
    printf("Value: %f\n", dev->value);
    printf("Mode: %d\n", dev->mode);
    printf("Config: %s\n", dev->config);
    printf("Buffer Size: %zu\n", dev->buffer_size);
