#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000
#define LOG_BUFFER_SIZE 1024

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* list = NULL;
int list_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = NULL;
int logging_enabled = 1;
int min_log_buffer_size = LOG_BUFFER_SIZE;

void init_list() {
    pthread_mutex_init(&lock, NULL);
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T* new_entry) {
    pthread_mutex_lock(&lock);

    if (list == NULL || list_size >= MAX_LIST_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T)*(list_size + 1));
        if (!new_list) {
            free(new_entry->rx_ue_info);
            pthread_mutex_unlock(&lock);
            return;
        }
        list = new_list;
    }

    for (int i = 0; i < list_size; i++) {
        if (memcmp(&list[i], &new_entry, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
            free(new_entry->rx_ue_info);
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    list[list_size] = *new_entry;
    list_size++;
    free(new_entry->rx_ue_info);
    pthread_mutex_unlock(&lock);
}

void serialize_list(char* buffer, int size) {
    pthread_mutex_lock(&lock);

    if (list_size > size) {
        pthread_mutex_unlock(&lock);
        return;
    }

    for (int i = 0; i < list_size; i++) {
        memcpy(buffer + i * sizeof(NFAPI_CRC_INDICATION_PDU_T), &list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    pthread_mutex_unlock(&lock);
}

void deserialize_list(char* buffer, int size) {
    pthread_mutex_lock(&lock);

    if (size < list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        pthread_mutex_unlock(&lock);
        return;
    }

    for (int i = 0; i < size / sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
        memcpy(&list[i], buffer + i * sizeof(NFAPI_CRC_INDICATION_PDU_T), sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    pthread_mutex_unlock(&lock);
}

void log_entry(NFAPI_CRC_INDICATION_PDU_T* entry) {
    if (logging_enabled) {
        char log_buffer[LOG_BUFFER_SIZE];
        sprintf(log_buffer, "RNTI: %d, CRCFLAG: %d\n", entry->rnti, entry->crc_indication_rel8.crcflag);
        fwrite(log_buffer, 1, strlen(log_buffer), log_file);
    }
}

void set_logging(int enabled) {
    logging_enabled = enabled;
}

void set_min_log_buffer_size(int size) {
    min_log_buffer_size = size;
}

int main() {
    init_list();

    // Add entries to the list
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_entry->rx_ue_info = // Set RX_UE_INFORMATION_TAG fields
        new_entry->rnti = // Set RNTI field
        new_entry->crc_indication_rel8 = // Set CRC_INDICATION_REL8_TAG fields

        add_to_list(new_entry);

        if (logging_enabled) {
            log_file = fopen("log.txt", "a");
            fwrite(new_entry->rx_ue_info, 1, strlen(new_entry->rx_ue_info), log_file);
            fclose(log_file);
        }
    }

    // Serialize the list
    char buffer[MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T)];
    serialize_list(buffer, MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Deserialize the list
    deserialize_list(buffer, MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    return 0;
}
