typedef struct {
    int key;
    long offset;
} record_t;

int process_data(const char *config_file_path) {
    FILE *file = fopen(config_file_path, "r");
    if (!file) return -1; // error handling

    int num_offsets, num_keys;
    fscanf(file, "%d %d", &num_offsets, &num_keys);

    long *offsets = (long *)malloc(num_offsets * sizeof(long));
    for (int i = 0; i < num_offsets; i++) offsets[i] = 0;

    int *keys = (int *)malloc(num_keys * sizeof(int));
    srand(time(NULL)); // seeding random number generator
    for (int i = 0; i < num_keys; i++) {
        int key;
        do {
            key = rand() % (num_offsets - 1);
        } while (key == (keys[i] >= 0 ? keys[i] : keys[i-1]));
        keys[i] = key;
    }

    record_t *records = (record_t *)malloc(num_keys * sizeof(record_t));
    for (int i = 0; i < num_keys; i++) {
        records[i].key = keys[i];
        long offset = rand() % num_offsets;
        if (offsets[offset] == 0) { // to ensure uniqueness
            offsets[offset] = 1;
            records[i].offset = offset;
        } else {
            i--; // try again with a different offset
        }
    }

    fclose(file);

    free(offsets);
    free(keys);
    free(records);

    return 0; // success
}
