void* manage_memory(size_t numOffsets, size_t numKeys, int minValue, int maxValue, size_t memoryLimit) {
    // Initialize the random number generator with a custom seed
    srand(time(NULL));

    // Calculate the initial sizes for the arrays based on the input parameters
    size_t initNumOffsets = numOffsets;
    size_t initNumKeys = numKeys;

    // Allocate and initialize the offset array
    long* offsets = malloc(initNumOffsets * sizeof(long));
    if (!offsets) {
        // Handle memory allocation failure
        return NULL;
    }

    // Initialize the key array
    int* keys = malloc(initNumKeys * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Allocate and initialize the record array
    record* records = malloc(initNumOffsets * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the record structures with random values
    for (size_t i = 0; i < initNumOffsets; i++) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }

    // Serialize the initialized data structures into a binary file format
    serialization_protocol_t* protocol = create_serialization_protocol();
    if (!protocol) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    byte_t* serializedData = serialize_data(protocol, offsets, keys, records, initNumOffsets);
    if (!serializedData) {
        destroy_serialization_protocol(protocol);
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Write the serialized data to a binary file
    FILE* file = fopen("data.bin", "wb");
    fwrite(serializedData, 1, protocol->getSerializedSize(), file);
    fclose(file);

    destroy_serialization_protocol(protocol);

    // Deallocate memory
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}
