struct pool {
    NFAPI_CRC_INDICATION_PDU_T* buffer;
    int size;
    pthread_mutex_t lock;
};

void init_pool(struct pool* p, int size) {
    p->buffer = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    p->size = size;
    pthread_mutex_init(&p->lock, NULL);
}

int get_next_index(struct pool* p) {
    int i;
    for (i = 0; i < p->size; i++) {
        if (!p->buffer[i].rx_ue_info.valid) {
            return i;
        }
    }
    return -1; // no free slot
}

void set_crc_flag(NFAPI_CRC_INDICATION_PDU_T* pdu, int flag) {
    pdu->crc_ind_rel8.flag = flag;
}

