void read_crc_indications(FILE *file, int max_size, int retries) {
    NFAPI_CRC_INDICATION_PDU_T *crc_indications = NULL;
    uint16_t num_crc_indications = 0;

    // Read CRC indications from file
    while (fscanf(file, "%x %hu %s", &crc_indications[num_crc_indications].rx_ue_info, 
                  &crc_indications[num_crc_indications].RNTI, crc_indications[num_crc_indications].crc_ind_rel8.crcflag) == 3 && num_crc_indications < max_size) {
        num_crc_indications++;
    }

    // Deallocate memory if reading from file fails
    if (ferror(file)) {
        for (int i = 0; i < num_crc_indications; i++) {
            free(crc_indications[i].rx_ue_info);
            free(crc_indications[i].crc_ind_rel8.crcflag);
        }
        free(crc_indications);
        return;
    }

    // Read integers from standard input
