    uint16_t num_integers = 0;

    while (scanf("%u", &integers[num_integers]) == 1 && num_integers < max_size) {
        num_integers++;
    }

    // Deallocate memory if reading from standard input fails
    if (ferror(stdin)) {
        for (int i = 0; i < num_integers; i++) {
            free(integers[i]);
        }
        free(integers);
