#include <time.h>

typedef struct {
    int key;
    char data[1];
} record_t;

void* manage_memory(int size) {
    void* mem = malloc(size);
    if (mem == NULL) return NULL; // handle error
    // init int key array with sequential values starting from 0
    int* keys = (int*)(((char*)mem) + sizeof(record_t));
    for (int i = 0; i < size / sizeof(record_t); i++) {
        keys[i] = i;
    }
    return mem;
}

void free_memory(void* mem) {
    free(mem);
}

void serialize_to_file(const void* data, int size, const char* file_name) {
    FILE* file = fopen(file_name, "wb");
    if (file == NULL) return; // handle error
    fwrite(data, 1, size, file);
    fclose(file);
}

void deserialize_from_file(void** data, int* size, const char* file_name) {
    FILE* file = fopen(file_name, "rb");
    if (file == NULL) return; // handle error
    fseek(file, 0, SEEK_END);
    *size = ftell(file);
    rewind(file);
    *data = malloc(*size);
    fread(*data, 1, *size, file);
    fclose(file);
}

int main() {
    const int RECORD_SIZE = sizeof(record_t) + 1; // include null terminator
    const int THRESHOLD = 10; // dynamic resizing threshold

    srand(42); // set custom seed value for reproducibility

    void* mem = manage_memory(RECORD_SIZE * THRESHOLD);
    if (mem == NULL) return -1; // handle error

    record_t* records = (record_t*)mem;
    int key_count = 0;
    while (key_count < THRESHOLD) {
        int random_key = rand() % RECORD_SIZE;
        record_t* new_record = (record_t*)((char*)mem + key_count * RECORD_SIZE);
        new_record->key = random_key;
        for (int i = 0; i < RECORD_SIZE - 1; i++) {
            new_record->data[i] = '\0';
        }
        key_count++;
    }

    serialize_to_file(mem, RECORD_SIZE * THRESHOLD, "data.bin");

    void* deserialized_data;
    int deserialized_size;
    deserialize_from_file(&deserialized_data, &deserialized_size, "data.bin");
    free_memory(deserialized_data);

    // AngularJS integration omitted for brevity

    return 0;
}

