NFAPI_CRC_INDICATION_PDU_T** nfaPiCrcIndicationPduList = NULL;
int nfaPiCrcIndicationPduCount = 0;
int nfaPiCrcIndicationPduCapacity = 0;

void nfaPiCrcIndicationPduListInit(int capacity) {
    if (nfaPiCrcIndicationPduList != NULL) return; // already initialized

    nfaPiCrcIndicationPduCapacity = capacity;
    nfaPiCrcIndicationPduCount = 0;

    nfaPiCrcIndicationPduList = (NFAPI_CRC_INDICATION_PDU_T**)malloc((nfaPiCrcIndicationPduCapacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
}

void nfaPiCrcIndicationPduInsert() {
    if (nfaPiCrcIndicationPduCount >= nfaPiCrcIndicationPduCapacity) {
        int newCapacity = (int)(nfaPiCrcIndicationPduCapacity * 1.5);
        NFAPI_CRC_INDICATION_PDU_T** tempList = (NFAPI_CRC_INDICATION_PDU_T**)my_realloc(nfaPiCrcIndicationPduList, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        nfaPiCrcIndicationPduList = tempList;
        nfaPiCrcIndicationPduCapacity = newCapacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* p = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    p->RX_UE_INFORMATION_TAG = rand() % 1000;
    p->RNTI = rand() % 10000;
    p->CRC_INDICATION_REL8_TAG = rand() % 100;

    nfaPiCrcIndicationPduList[nfaPiCrcIndicationPduCount++] = p;
}

void nfaPiCrcIndicationPduRemove(int index) {
    if (index < 0 || index >= nfaPiCrcIndicationPduCount) return; // invalid index

    free(nfaPiCrcIndicationPduList[index]);
    for (int i = index; i < nfaPiCrcIndicationPduCount - 1; i++) {
        NFAPI_CRC_INDICATION_PDU_T* p = nfaPiCrcIndicationPduList[i];
        nfaPiCrcIndicationPduList[i] = nfaPiCrcIndicationPduList[i + 1];
    }
    free(nfaPiCrcIndicationPduList[--nfaPiCrcIndicationPduCount]);
}

void updateRnti(int index) {
    if (index < 0 || index >= nfaPiCrcIndicationPduCount) return; // invalid index

    NFAPI_CRC_INDICATION_PDU_T* p = nfaPiCrcIndicationPduList[index];
    int newRnti = rand() % 10000;
    p->RNTI = newRnti;

    if (p->RX_UE_INFORMATION_TAG == 0 && p->CRC_INDICATION_REL8_TAG == 0) {
        // verify integrity
        p->RX_UE_INFORMATION_TAG = newRnti % 2 ? 1 : 0;
        int calculatedCrc = (newRnti * 12345 + p->RX_UE_INFORMATION_TAG) % 100;
        if (p->CRC_INDICATION_REL8_TAG != calculatedCrc) {
            // data integrity failure, handle it
            printf("Data integrity failure at index %d.\n", index);
        }
    }
}

void main() {
    srand(time(NULL)); // initialize random seed

    nfaPiCrcIndicationPduListInit(100);

    for (int i = 0; i < 5000; i++) {
        nfaPiCrcIndicationPduInsert();
        if (i % 100 == 0) updateRnti(i / 100);
    }

    // remove elements
    for (int i = 0; i < 5000; i += 50) {
        nfaPiCrcIndicationPduRemove(i);
    }
}
