    int value;
} Record;

int render_footer(Record** records, size_t num_records, char*** scripts, size_t num_scripts) {
    srand(SEED_DEFAULT);

    // Initialize arrays for 'long' offset values and 'int' keys
    long* offsets = NULL;
    int* keys = NULL;
    size_t num_offsets = 0;
    size_t num_keys = 0;

    while (num_offsets + num_keys <= MAX_OFFSETS) {
        if ((offsets = realloc(offsets, sizeof(long)*(num_offsets+1))) == NULL) {
            printf("Error allocating memory for offsets.\n");
            return -1;
        }
        if ((keys = realloc(keys, sizeof(int)*(num_keys+1))) == NULL) {
            printf("Error allocating memory for keys.\n");
            free(offsets);
            return -1;
        }

        // Generate random 'long' offset values and 'int' keys
        offsets[num_offsets] = rand();
        keys[num_keys] = rand() % 1000;

        num_offsets++;
        num_keys++;

        if (num_offsets + num_keys > MEMORY_THRESHOLD) {
            printf("Memory usage exceeded threshold. Cleaning up resources.\n");
            free(offsets);
            free(keys);
            return -1;
        }
    }

    // Initialize array of 'record' structures
    Record* record_array = NULL;
    size_t num_records_total = 0;

    while (num_records_total < num_records) {
        if ((record_array = realloc(record_array, sizeof(Record)*(num_records_total+1))) == NULL) {
            printf("Error allocating memory for records.\n");
            free(offsets);
            free(keys);
            return -1;
        }

        // Generate random 'int' values for each record
        Record new_record;
        int value = rand() % 1000;
        while (record_array[num_records_total-1].value == value) {
            value = rand() % 1000;
        }
        new_record.value = value;

        record_array[num_records_total] = new_record;
        num_records_total++;
    }

    // Render each script object as a <script> tag
    char* footer_html = malloc(strlen("<footer>") + 1);
    sprintf(footer_html, "<footer>");

    for (size_t i = 0; i < num_scripts; i++) {
        char* script_html = malloc(strlen("<script id=\"" + scripts[i][0] + "\">") + strlen(scripts[i][1]) + 5);
        sprintf(script_html, "<script id=\"%s\">%s</script>", scripts[i][0], scripts[i][1]);

        footer_html = realloc(footer_html, strlen(footer_html) + strlen(script_html));
        strcat(footer_html, script_html);

        free(script_html);
    }

    footer_html = realloc(footer_html, strlen(footer_html) + 6);
    strcat(footer_html, "</footer>");

    return strlen(footer_html);
}
