int update_record(int* keys, long* offsets, int* values, int index) {
    if (index < 0 || index >= MAX_SIZE) {
        return -1; // out-of-bounds index
    }
    values[index] = (values[index] + 1) % RANGE;
    keys[index]++;
    return 0;
}

int init_records(int max_size, int* keys, long* offsets, int* values) {
    for (int i = 0; i < max_size; i++) {
        if (i > 0 && keys[i] == keys[i - 1]) {
            // Ensure no two consecutive records have the same value
            i--;
            continue;
        }
        values[i] = rand() % RANGE;
    }
    return max_size;
}

void free_memory(int* keys, long* offsets, int* values) {
    free(keys);
    free(offsets);
    free(values);
}

int main() {
    // Initialize random number generator
    srand(time(NULL));
    int max_size = MIN(MAX_SIZE, THRESHOLD);
    int* keys = (int*)malloc(max_size * sizeof(int));
    long* offsets = (long*)malloc(max_size * sizeof(long));
