void* allocateArrays(int offsetSize, int keyValueSize) {
    // Calculate the total size of the arrays in bytes
    int totalSize = offsetSize * sizeof(long) + keyValueSize * sizeof(int);

    // Check if the total size exceeds the threshold
    if (totalSize > 1024 * 1024) { // 1MB threshold
        printf("Error: Total size exceeds the maximum allowed size.\n");
        return NULL;
    }

    // Dynamically allocate memory for the arrays
    void* offsetArray = malloc(offsetSize * sizeof(long));
    void* keyValueArray = malloc(keyValueSize * sizeof(int));

    if (!offsetArray || !keyValueArray) {
        printf("Error: Memory allocation failed.\n");
        free(offsetArray);
        free(keyValueArray);
        return NULL;
    }

    // Initialize the arrays
    for (int i = 0; i < offsetSize; i++) {
        ((long*)offsetArray)[i] = i * sizeof(long);
    }
    for (int i = 0; i < keyValueSize; i++) {
        ((int*)keyValueArray)[i] = i;
    }

    return malloc(sizeof(Record) * offsetSize);
}

// Function to generate random records
void* generateRecords(int recordCount, int minValue, int maxValue) {
    // Initialize the seed for the random number generator
    srand(time(NULL));

    // Allocate memory for the records array
    void* records = malloc(recordCount * sizeof(Record));

    if (!records) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    // Generate and initialize the records
    Record* record = (Record*)records;
    for (int i = 0; i < recordCount; i++) {
        int value = rand() % (maxValue - minValue + 1) + minValue;

        // Ensure no two consecutive records have the same value
        if (i > 0 && value == ((Record*)records)[i-1].value) {
            value = rand() % (maxValue - minValue + 1) + minValue;
        }

        record[i].value = value;
    }

    return records;
}

