typedef struct {
    float temp;
    time_t last_update;
    int error_count;
} sensor_reading;

sensor_reading *sensors[MAX_SENSORS];
pthread_mutex_t sensor_lock = PTHREAD_MUTEX_INITIALIZER;

void* generate_temperature_readings(void* arg) {
    int sensor_id = *(int*)arg;
    srand(time(NULL) + sensor_id); // ensure unique random seed for each sensor

    while (1) {
        float temp = rand() / (float)RAND_MAX * 100 - 50; // simulate environmental variability
        time_t now = time(NULL);
        pthread_mutex_lock(&sensor_lock);
        sensors[sensor_id]->temp = temp;
        sensors[sensor_id]->last_update = now;
        sensors[sensor_id]->error_count = 0;
        pthread_mutex_unlock(&sensor_lock);

        usleep(100000); // simulate a 100ms delay between readings
    }

    return NULL;
}

int main() {
    int i, sensor_id;

    for (i = 0; i < MAX_SENSORS; i++) {
        sensors[i] = malloc(sizeof(sensor_reading));
        pthread_create(&sensor_id, NULL, generate_temperature_readings, &i);
    }

    // simulate disconnection and reconnection
    while (1) {
        sleep(2); // wait for 2 seconds before disconnecting a random sensor

        int disconnected_sensor_id = rand() % MAX_SENSORS;
        pthread_mutex_lock(&sensor_lock);
        free(sensors[disconnected_sensor_id]);
        sensors[disconnected_sensor_id] = NULL; // mark as disconnected
        pthread_mutex_unlock(&sensor_lock);

        sleep(1); // wait for 1 second before reconnecting the same sensor

        if (sensors[disconnected_sensor_id] == NULL) {
            sensors[disconnected_sensor_id] = malloc(sizeof(sensor_reading));
            pthread_create(&sensor_id, NULL, generate_temperature_readings, &disconnected_sensor_id);
        }
    }

    return 0;
}

