    } catch (exception& e) {
        printf("Error: Unable to compute MD5 hash.\n");
        free(offsets);
        free(keys);
        free(records); // Ensure proper cleanup
        return -1;
    }

    // Handle errors and handle memory deallocation properly
    if (!offsets || !keys || !records) {
        printf("Error: Unable to allocate memory.\n");
        free(md5_hash);
        free(offsets);
        free(keys);
        free(records); // Ensure proper cleanup
        return -1;
