        printf("Memory allocation exceeded maximum size.\n");
        return 1;
    }

    initSensorAcquisitionLibrary();

    int status = allocateArrays(numIdentifiers, numMeasurements);

    finalizeSensorAcquisitionLibrary();

    if (status != 0) {
        // Handle memory allocation errors
    }

    return 0;
}

