// Custom structure to represent LTE cell information
typedef struct {
    int CELL_ID;
    int PCI;
    int RSSI;
    int TX_POWER_LEVEL;
    float SINR;
} LTE_CELL_INFO_T;

// Function to initialize and populate an array of LTE_CELL_INFO_T structures
LTE_CELL_INFO_T** init_lte_cell_info(int num_entries) {
    // Allocate memory for the array of LTE_CELL_INFO_T structures
    LTE_CELL_INFO_T** lte_cell_info = (LTE_CELL_INFO_T**)malloc(num_entries * sizeof(LTE_CELL_INFO_T*));

    if (!lte_cell_info) {
        printf("Error: Unable to allocate memory for LTE cell info.\n");
        return NULL;
    }

    // Initialize hash table for unique CELL_ID values
    int* cell_id_hash = (int*)malloc(1000 * sizeof(int));
    int cell_id_index = 0;

    // Iterate over the specified number of entries
    for (int i = 0; i < num_entries; i++) {
        LTE_CELL_INFO_T* entry = (LTE_CELL_INFO_T*)malloc(sizeof(LTE_CELL_INFO_T));

        if (!entry) {
            printf("Error: Unable to allocate memory for LTE cell info entry.\n");
            free(lte_cell_info);
            return NULL;
        }

        // Generate unique CELL_ID value
        int cell_id = rand() % 1000 + 1;
        while (cell_id_hash[cell_id] > 0) {
            cell_id = rand() % 1000 + 1;
        }
        cell_id_hash[cell_id] = i;

        entry->CELL_ID = cell_id;
        // Generate random PCI value
        entry->PCI = rand() % 500 + 1;

        // Generate random RSSI value
        entry->RSSI = rand() % 100 + 1;

        // Generate random TX_POWER_LEVEL value within valid range
        int tx_power_level = rand() % 10 + 1;
        if (tx_power_level > 7) {
            tx_power_level = 7;
        }
        entry->TX_POWER_LEVEL = tx_power_level;

        // Generate random SINR value within valid range
        float sinr = (float)(rand() % 1000 + 1) / 10.0f;
        if (sinr > 30.0f) {
            sinr = 30.0f;
        }
        entry->SINR = sinr;

        // Add entry to array
        lte_cell_info[i] = entry;
    }

    free(cell_id_hash);

    return lte_cell_info;
}

// Function to serialize the populated data into a binary format
int serialize_lte_cell_info(LTE_CELL_INFO_T** lte_cell_info, int num_entries) {
    // Serialize the LTE cell info array
    FILE* file = fopen("lte_cell_info.bin", "wb");

    if (!file) {
        printf("Error: Unable to open file for writing.\n");
        return -1;
    }

    fwrite(&num_entries, sizeof(int), 1, file);

    for (int i = 0; i < num_entries; i++) {
        LTE_CELL_INFO_T* entry = lte_cell_info[i];

        fwrite(&entry->CELL_ID, sizeof(int), 1, file);
        fwrite(&entry->PCI, sizeof(int), 1, file);
        fwrite(&entry->RSSI, sizeof(int), 1, file);
        fwrite(&entry->TX_POWER_LEVEL, sizeof(int), 1, file);
        fwrite(&entry->SINR, sizeof(float), 1, file);
    }

    fclose(file);

    return 0;
}

int main() {
    int num_entries = 10;

    LTE_CELL_INFO_T** lte_cell_info = init_lte_cell_info(num_entries);

    if (!lte_cell_info) {
        printf("Error: Unable to initialize LTE cell info.\n");
        return -1;
    }

    // Serialize the populated data into a binary format
    serialize_lte_cell_info(lte_cell_info, num_entries);

    for (int i = 0; i < num_entries; i++) {
        free(lte_cell_info[i]);
    }
    free(lte_cell_info);

    return 0;
}
