conn_context *conn_pool = NULL;
int pool_size = 0;
int max_connections = 10;
int min_connections = 2;
int heartbeat_interval = 300; // seconds
int retry_delay = 1000; // milliseconds

void create_connection(char *uri, time_t start_time) {
    conn_context *new_conn = (conn_context *)malloc(sizeof(conn_context));
    new_conn->id = pool_size++;
    new_conn->uri = strdup(uri);
    new_conn->start_time = start_time;
    new_conn->latency = (double)rand() / RAND_MAX;
    new_conn->throughput = (double)rand() / RAND_MAX;
    for(int i=0; i<5; i++) {
        new_conn->offset[i] = rand();
    }
    conn_pool = realloc(conn_pool, (pool_size + 1) * sizeof(conn_context));
    conn_pool[pool_size-1] = new_conn;
}

void free_connection(int index) {
    if(index >= 0 && index < pool_size) {
        free(conn_pool[index]->uri);
        free(conn_pool[index]);
        for(int i=index; i<pool_size-1; i++) {
            memmove(&conn_pool[i], &conn_pool[i+1], (pool_size-index-1)*sizeof(conn_context));
        }
        pool_size--;
    }
}

