typedef struct {
    int RNTI;
    unsigned int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom linked list node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Initialize the head of the linked list
Node* initializeList() {
    return NULL;
}

// Add a new element to the end of the linked list
void addElement(Node** head, NFAPI_CRC_INDICATION_PDU_T newData) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed.\n");
        return;
    }
    newNode->data = newData;
    newNode->next = (*head);
    *head = newNode;
}

// Update an existing element by RNTI
void updateElement(Node** head, int newRNTI, unsigned int newCRCFLAG) {
    Node* current = *head;
    while (current && current->data.RNTI != newRNTI) {
        current = current->next;
    }
    if (!current) {
        printf("No element found with RNTI %d.\n", newRNTI);
        return;
    }
    current->data.CRCFLAG = newCRCFLAG;
}

// Retrieve an element by RNTI
NFAPI_CRC_INDICATION_PDU_T* retrieveElement(Node** head, int targetRNTI) {
    Node* current = *head;
    while (current && current->data.RNTI != targetRNTI) {
        current = current->next;
    }
    if (!current) {
        printf("No element found with RNTI %d.\n", targetRNTI);
        return NULL;
    }
    return &current->data;
}

// Free the linked list
void freeList(Node** head) {
    Node* current = *head;
    Node* nextNode;
    while (current) {
        nextNode = current->next;
        free(current);
        current = nextNode;
    }
    *head = NULL;
}
