metadata* setup_metadata() {
    metadata* meta = (metadata*)malloc(sizeof(metadata));
    meta->name = (char*)malloc(32);
    strcpy(meta->name, "Config Name");
    meta->version = 1;
    meta->timestamp = time(NULL);
    return meta;
}

