    if (!meta) return;
    free((void*)meta->name);
    free((void*)meta);
}

record* setup_record(int idx) {
    record* rec = (record*)malloc(sizeof(record));
    char buffer[32];
    sprintf(buffer, "Record %d", idx);
    rec->value = idx;
    rec->buffer = (char*)malloc(strlen(buffer) + 1);
    strcpy(rec->buffer, buffer);
    return rec;
}

void free_record(record* rec) {
    if (!rec) return;
    free((void*)rec->buffer);
    free((void*)rec);
}

