    EVP_add_cipher(AES_cbc, NULL, NULL);
    EVP_add_digest(MD5, NULL);
    EVP_add_digest(SHA256, NULL);
    RSA_generate_key_ex(2048, 65537, NULL, &rsa_keys[0]);

    for (int i = 0; i < 5; i++) {
        // Encrypt and decrypt data
        AES_cbc_encrypt((char*)records[i].buffer, (char*)buffers[i], strlen(records[i].buffer) + 1);
        MD5_Init();
        SHA256_Init();

        // Perform logging and monitoring
        printf("Operation %d complete\n", i);
    }

    for (int i = 0; i < 5; i++) {
        free(buffers[i]);
        free_record(&records[i]);
    }
    free_metadata(&meta);

    return 0;
}
