        for (size_t j = 0; j < 5; j++) {
            records[i].data[j] = '\0'; // Initialize 'char' array with null terminator
        }
    }

    // Allocate memory and initialize 'float' values array
    float* floats = (float*)aligned_alloc(sizeof(float), sizeof(float) * float_size);

    // Allocate memory for 'char' arrays with specified length and align to nearest 4-byte boundary
