    public DynamicMeasurementReportGenerator(int minRNTI, int maxRNTI, int ageThreshold)
    {
        this.minRNTI = minRNTI;
        this.maxRNTI = maxRNTI;
        this.ageThreshold = ageThreshold;
    }

    public void GenerateReports(int reportCount)
    {
        lock (syncLock)
        {
            this.reportCount = reportCount;
            reports = new NR_UE_MEASUREMENT_REPORT_T[reportCount];

            for (int i = 0; i < reportCount; i++)
            {
                bool isValidReport = false;

                while (!isValidReport)
                {
                    int rnti = UnityEngine.Random.Range(minRNTI, maxRNTI + 1);
