    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDATION_PDU_T));

    for (int i = 0; i < N; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 100;
        list[i].RNTI = rand() % 10000;
        list[i].CRCFLAG = rand() % 2;

        // Read CRC indication structures and integers from standard input
        int num;
        while (scanf("%d", &num) != 1) {
            printf("Invalid input. Please enter a valid integer.\n");
            continue;
        }

        // Store them in arrays
        int* arr = (int*)malloc(sizeof(int));
        *arr = num;

        // Find and print the largest integer in the array using a helper function
        int largest = find_largest(arr);
        printf("The largest integer is: %d\n", largest);

        free(arr);
    }

    return list;
}

int find_largest(int* arr) {
    if (arr == NULL || *arr == 0) {
        return -1; // Error
    }

    int max = *arr;
    while (*arr != 0) {
        if (*arr > max)
            max = *arr;
        (*arr)++;
    }
    return max;
}

