Record* allocate_records(int num_records) {
    Record* records = NULL;
    size_t total_memory = 0;
    size_t available_memory = 0;

    // Monitor system memory and prevent resource exhaustion
    available_memory = get_available_system_memory();

    for (int i = 0; i < num_records; i++) {
        Record* record = (Record*) malloc(sizeof(Record));

        // Initialize int field with a random value within the given range
        srand(time(NULL));
        int value = rand() % 100; // Replace with desired range

        if (i > 0) {
            // Ensure no two consecutive records have the same value
            while (value == ((records[i-1])->int_field)) {
                value = rand() % 100;
            }
        }

        record->key = value;

        // Allocate memory for offset and integrate any external data sources
        long* offset = (long*) malloc(sizeof(long));
        if (offset != NULL) { // Replace with your logic to handle external data sources
            *offset = i; // Initialize offset for the current record
        }

        record->offset = *offset;

        total_memory += sizeof(Record) + sizeof(long);

        // Check system memory usage and prevent exhaustion
        if (total_memory > available_memory * 0.8) {
            printf("Memory alert! Available memory: %zu, Total allocated: %zu.\n", available_memory, total_memory);
            return NULL; // or handle the situation as needed
        }

        records = realloc(records, (i + 1) * sizeof(Record*));
        if (records == NULL) {
            printf("Memory allocation failed!\n");
            return NULL;
        }

        records[i] = record;
    }

    return records;
}

