        int val = rand() % max_value + 1;
        while (i > 0 && val == records[i - 1].value) {
            val = rand() % max_value + 1;
        }
        records[i].value = val;
    }

    return records;
}

void free_records(Record* records, int count) {
    free(records);
}

int main() {
    // Example usage
    Record* records = create_records(10, 100);
    for (int i = 0; i < 10; i++) {
        printf("%d ", records[i].value);
    }
    printf("\n");

    free_records(records, 10);

    return 0;
}
