#include <sstream>
#include <json/json.h>

class Task {
public:
    int priority;
    std::string description;

    Task(int priority, const std::string& description) : priority(priority), description(description) {}
};

class TaskManager {
private:
    std::vector<std::unique_ptr<Task>> tasks;
    size_t availableMemory = 0;
    double memoryThreshold = 0.8; // 80% threshold
    bool memoryAlertTriggered = false;

public:
    TaskManager(size_t availableMemory) : availableMemory(availableMemory) {}

    void addTask(int priority, const std::string& description) {
        if (availableMemory * memoryThreshold > getUsedMemory()) {
            tasks.push_back(std::make_unique<Task>(priority, description));
        } else {
            std::cout << "Memory alert! Cannot add task." << std::endl;
        }
    }

    void updateTask(int priority, const std::string& newDescription) {
        for (auto& task : tasks) {
            if (task->priority == priority) {
                task->description = newDescription;
                return;
            }
        }
    }

    Task* getTaskByPriority(int priority) {
        for (const auto& task : tasks) {
            if (task->priority == priority) {
                return task.get();
            }
        }
        return nullptr;
    }

    void executeTasks() {
        std::vector<Task*> sortedTasks = tasks;
        std::sort(sortedTasks.begin(), sortedTasks.end(),
                  [](const Task* a, const Task* b) { return a->priority > b->priority; });

        for (Task* task : sortedTasks) {
            if (!memoryAlertTriggered) {
                executeTask(task);
            } else {
                std::cout << "Memory alert! Cannot execute tasks." << std::endl;
                break;
            }
        }
    }

private:
    size_t getUsedMemory() const {
        // Calculate used memory based on the number of tasks and their descriptions
        return 0; // TO DO: implement actual memory usage calculation
    }

    void executeTask(Task* task) {
        // Execute the task
        std::cout << "Executing task: " << task->description << std::endl;
    }
};

class TaskReader {
public:
    void readTasksFromJSON(const std::string& jsonFile, TaskManager& taskManager) {
        Json::Value root;
        std::ifstream file(jsonFile);
        Json::Reader reader;
        if (file.is_open()) {
            file >> reader;
            for (auto& taskJson : root["tasks"].asArray()) {
                int priority = taskJson["priority"].asInt();
                std::string description = taskJson["description"].asString();
                taskManager.addTask(priority, description);
            }
        }
    }

    void readTasksFromCSV(const std::string& csvFile, TaskManager& taskManager) {
        std::ifstream file(csvFile);
        if (file.is_open()) {
            std::string line;
            while (std::getline(file, line)) {
                size_t commaPos = line.find(',');
                int priority = std::stoi(line.substr(0, commaPos));
                std::string description = line.substr(commaPos + 1).substr(0, line.size() - 1);
                taskManager.addTask(priority, description);
            }
        }
    }
};

int main() {
    TaskReader reader;
    TaskManager taskManager(1024); // Initialize with 1 GB of available memory

    reader.readTasksFromJSON("tasks.json", taskManager);

    reader.readTasksFromCSV("tasks.csv", taskManager);

    taskManager.executeTasks();

    return 0;
}
