#include <stdio.h>
#include <stdlib.h>

typedef struct Event {
    long timestamp;
    struct Event* next;
} Event;

Event* createEvent(long timestamp) {
    Event* event = (Event*)malloc(sizeof(Event));
    event->timestamp = timestamp;
    event->next = NULL;
    return event;
}

void insertEvent(Event** head, long timestamp) {
    Event* newEvent = createEvent(timestamp);
    if (*head == NULL || (*head)->timestamp >= timestamp) {
        newEvent->next = *head;
        *head = newEvent;
    } else {
        Event* current = *head;
        while (current->next && current->next->timestamp < timestamp)
            current = current->next;
        newEvent->next = current->next;
        current->next = newEvent;
    }
}

void printList(Event* head) {
    while (head != NULL) {
        printf("%ld ", head->timestamp);
        head = head->next;
    }
    printf("\n");
}

int main() {
    Event* root = NULL;

    // Example usage
    insertEvent(&root, 3);
    insertEvent(&root, 1);
    insertEvent(&root, 4);
    insertEvent(&root, 2);

    printList(root);

    return 0;
}
