#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_INTERFACES 100
#define MAX_PERFORMANCE_METRICS 10

typedef struct {
    int interface_id;
    char ip_address[20];
    char subnet_mask[20];
    char gateway[20];
    double latency[MAX_PERFORMANCE_METRICS];
    double throughput[MAX_PERFORMANCE_METRICS];
    time_t timestamp;
} InterfaceConfig;

InterfaceConfig* initialize_interface_config(int id, const char* ip, const char* subnet, const char* gateway) {
    InterfaceConfig* config = (InterfaceConfig*)malloc(sizeof(InterfaceConfig));
    config->interface_id = id;
    strcpy(config->ip_address, ip);
    strcpy(config->subnet_mask, subnet);
    strcpy(config->gateway, gateway);
    for(int i = 0; i < MAX_PERFORMANCE_METRICS; i++) {
        config->latency[i] = 0.0;
        config->throughput[i] = 0.0;
    }
    config->timestamp = time(NULL);
    return config;
}

void update_performance_metrics(InterfaceConfig* config, double latency_value, double throughput_value) {
    int i = 0;
    while(i < MAX_PERFORMANCE_METRICS && (config->latency[i] + latency_value > 0.0 || config->throughput[i] + throughput_value > 0.0)) {
        i++;
    }
    for(int j = i; j < MAX_PERFORMANCE_METRICS; j++) {
        config->latency[j-1] = config->latency[j];
        config->throughput[j-1] = config->throughput[j];
    }
    config->latency[i] = latency_value;
    config->throughput[i] = throughput_value;
}

void print_interface_config(InterfaceConfig* config) {
    printf("Interface ID: %d\n", config->interface_id);
    printf("IP Address: %s\n", config->ip_address);
    printf("Subnet Mask: %s\n", config->subnet_mask);
    printf("Gateway: %s\n", config->gateway);
    printf("Latency: ");
    for(int i = 0; i < MAX_PERFORMANCE_METRICS; i++) {
        printf("%f ", config->latency[i]);
    }
    printf("\n");
    printf("Throughput: ");
    for(int i = 0; i < MAX_PERFORMANCE_METRICS; i++) {
        printf("%f ", config->throughput[i]);
    }
    printf("\n");
    printf("Timestamp: %lu\n", config->timestamp);
}

int main() {
    InterfaceConfig* interface_configs[MAX_INTERFACES];

    // Initialize interfaces
    for(int i = 0; i < MAX_INTERFACES; i++) {
        char ip[20], subnet[20], gateway[20];
        printf("Enter IP address, subnet mask, and gateway for interface %d: ", i);
        scanf("%s %s %s", ip, subnet, gateway);
        InterfaceConfig* config = initialize_interface_config(i, ip, subnet, gateway);
        interface_configs[i] = config;
    }

    // Update performance metrics
    int i = 0;
    while(i < MAX_INTERFACES) {
        printf("Enter latency and throughput for interface %d: ", i);
        double latency, throughput;
        scanf("%lf %lf", &latency, &throughput);
        update_performance_metrics(interface_configs[i], latency, throughput);
        i++;
    }

    // Print interface configurations
    i = 0;
    while(i < MAX_INTERFACES) {
        print_interface_config(interface_configs[i]);
        i++;
    }

    return 0;
}
