#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char RX_UE_INFORMATION_TAG[64];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[64];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_pdu = NULL;
int nfapi_crc_indication_pdu_count = 0;

void add_nfapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *new_pdu) {
    NFAPI_CRC_INDICATION_PDU_T *temp = (NFAPI_CRC_INDICATION_PDU_T *)realloc(nfapi_crc_indication_pdu, 
                                                                        (nfapi_crc_indication_pdu_count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if(temp == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    nfapi_crc_indication_pdu = temp;
    memcpy(&nfapi_crc_indication_pdu[nfapi_crc_indication_pdu_count], new_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    nfapi_crc_indication_pdu_count++;
}

void remove_nfapi_crc_indication_pdu(int RNTI) {
    for(int i = 0; i < nfapi_crc_indication_pdu_count; i++) {
        if(nfapi_crc_indication_pdu[i].RNTI == RNTI) {
            memmove(&nfapi_crc_indication_pdu[i], &nfapi_crc_indication_pdu[i + 1], 
                    (nfapi_crc_indication_pdu_count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            nfapi_crc_indication_pdu_count--;
            return;
        }
    }
}

void update_nfapi_crc_indication_pdu(int index, int CRCFLAG) {
    if(index >= 0 && index < nfapi_crc_indication_pdu_count) {
        nfapi_crc_indication_pdu[index].CRCFLAG = CRCFLAG;
    } else {
        printf("Invalid index\n");
    }
}

void serialize_nfapi_crc_indication_pdu_to_file(char *filename) {
    FILE *file = fopen(filename, "wb");
    if(file == NULL) {
        printf("File open failed\n");
        return;
    }
    for(int i = 0; i < nfapi_crc_indication_pdu_count; i++) {
        fwrite(&nfapi_crc_indication_pdu[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);
}

void deserialize_nfapi_crc_indication_pdu_from_file(char *filename) {
    FILE *file = fopen(filename, "rb");
    if(file == NULL) {
        printf("File open failed\n");
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T *temp = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    while(fread(temp, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_nfapi_crc_indication_pdu(temp);
    }
    fclose(file);
    free(temp);
}

