    char RNTI[RNTI_MAX_LENGTH];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* list = NULL;
int active_count = 0;

void nfaPI_CRC_indication_pdu_list_init() {
    pthread_mutex_init(&list_lock, NULL);
    list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memset(list, 0, MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

int nfaPI_CRC_indication_pdu_list_add(char* RX_UE_INFORMATION_TAG, char* RNTI) {
    pthread_mutex_lock(&list_lock);

    if (active_count >= MAX_LIST_SIZE) {
        printf("List is full. Cannot add more elements.\n");
        pthread_mutex_unlock(&list_lock);
        return -1;
    }

    list[active_count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    strcpy(list[active_count].RNTI, RNTI);
    list[active_count].CRCFLAG = rand() % (2 ^ 16); // Randomly set CRCFLAG

    active_count++;
    pthread_mutex_unlock(&list_lock);

    return 0;
}

int nfaPI_CRC_indication_pdu_list_remove(char* RNTI) {
    pthread_mutex_lock(&list_lock);

    for (int i = 0; i < active_count; i++) {
        if (!strcmp(list[i].RNTI, RNTI)) {
            memmove(&list[i], &list[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (active_count - i - 1));
            active_count--;
            return 0;
        }
    }

    pthread_mutex_unlock(&list_lock);

    printf("RNTI not found in the list.\n");
    return -1;
}

int nfaPI_CRC_indication_pdu_list_update(char* RX_UE_INFORMATION_TAG, char* RNTI) {
    pthread_mutex_lock(&list_lock);

    for (int i = 0; i < active_count; i++) {
        if (!strcmp(list[i].RNTI, RNTI)) {
            strcpy(list[i].RX_UE_INFORMATION_TAG, RX_UE_INFORMATION_TAG);
            return 0;
        }
    }

    pthread_mutex_unlock(&list_lock);

    printf("RNTI not found in the list.\n");
    return -1;
}

void nfaPI_CRC_indication_pdu_list_deinit() {
    free(list);
    pthread_mutex_destroy(&list_lock);
}
