// Custom linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Custom linked list
void add(NFAPI_CRC_INDICATION_PDU_T* new_data, Node** head_ref) {
    // Create a new node
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        return;
    }
    new_node->data = *new_data;

    // Check if the list is empty
    if (*head_ref == NULL) {
        *head_ref = &new_node;
        new_node->next = NULL;
    } else {
        Node* last = *head_ref;
        while (last->next)
            last = last->next;
        last->next = &new_node;
    }
}

void update(RNTI rnti, NFAPI_CRC_INDICATION_PDU_T* new_data, Node** head_ref) {
    Node* current = *head_ref;
    if (!current) return;  // List is empty

    while (current) {
        if (current->data.rnti == rnti) {
            free(current);  // Free old node
            add(new_data, &current);
            break;
        }
        current = current->next;
    }
}

NFAPI_CRC_INDICATION_PDU_T* retrieve(RNTI rnti, Node** head_ref) {
    Node* current = *head_ref;
    if (!current) return NULL;  // List is empty

    while (current) {
        if (current->data.rnti == rnti)
            return &current->data;
        current = current->next;
    }
    return NULL;  // Not found
