UmTsPhyParam* umtsPhyParamInit(int numParams, int* numParamsPtr) {
    UmTsPhyParam* params = (UmTsPhyParam*)malloc(sizeof(UmTsPhyParam) * numParams);

    if(params == NULL) {
        return NULL;
    }

    // Initialize random seed
    srand(time(NULL));

    for(int i = 0; i < numParams; i++) {
        params[i].timingAdvance = rand() % 256; // Randomly generated timing advance value

        // Calculate frequency offset based on signal strength metric (e.g., RSSI)
        float rssi = rand() % 100 + 1; // Random signal strength value
        params[i].frequencyOffset = (rssi / 100.0) * 20.0f - 10.0f;

        // Calculate channel quality indicator based on frequency offset and timing advance
        params[i].channelQualityIndicator = (int)(params[i].frequencyOffset * 2.0 + params[i].timingAdvance);

        // Validate configuration to ensure performance criteria are met
        if(params[i].channelQualityIndicator < 1 || params[i].channelQualityIndicator > 30) {
            // Handle invalid configuration by retrying or skipping the current iteration
            printf("Invalid configuration: %d\n", i);
        }
    }

    *numParamsPtr = numParams;

    return params;
}

