#include <stdlib.h>
#include <pthread.h>

typedef struct {
    LTETransportChannelType type;
    uint32_t rnti;
    uint8_t channelStatus;
    void* transportData;
    size_t dataLength;
} LTEPHY_TransportChannelInfo;

void ltephy_transport_channel_info_init(LTEPHY_TransportChannelInfo** info, size_t maxChannels) {
    *info = (LTEPHY_TransportChannelInfo*)malloc(maxChannels * sizeof(LTEPHY_TransportChannelInfo));
    pthread_mutex_init(&(*info)->lock, NULL);
}

void ltephy_transport_channel_info_free(LTEPHY_TransportChannelInfo* info) {
    free(info->transportData);
    free(info);
    pthread_mutex_destroy(&info->lock);
}

int ltephy_transport_channel_info_insert(LTEPHY_TransportChannelInfo** info, LTETransportChannelType type, uint32_t rnti, uint8_t channelStatus, void* transportData, size_t dataLength) {
    // Calculate the new size
    size_t newSize = (*info)->size + 1;

    // Check if there's enough memory for a new structure
    if (newSize > *info->maxChannels) {
        return -1; // Not enough memory
    }

    // Lock access to the array
    pthread_mutex_lock(&(*info)->lock);

    // Insert the new structure at the end of the array
    LTEPHY_TransportChannelInfo* newInfo = &((*info)[newSize-1]);
    newInfo->type = type;
    newInfo->rnti = rnti;
    newInfo->channelStatus = channelStatus;
    newInfo->transportData = malloc(dataLength);
    newInfo->dataLength = dataLength;

    // Unlock access to the array
    pthread_mutex_unlock(&(*info)->lock);

    return 0; // Success
}

int ltephy_transport_channel_info_delete(LTEPHY_TransportChannelInfo** info, size_t index) {
    // Lock access to the array
    pthread_mutex_lock(&(*info)->lock);

    // Check if the index is within bounds
    if (index >= (*info)->size) {
        return -1; // Index out of range
    }

    // Delete the structure at the specified index
    free((*info)[index].transportData);
    for (int i = index; i < (*info)->size-1; i++) {
        (*info)[i] = (*info)[i+1];
    }
    (*info)--->size;

    // Unlock access to the array
    pthread_mutex_unlock(&(*info)->lock);

    return 0; // Success
}
