    long *offsets;
    int *keys;
    record **records;
    int *record_values;
    int num_records;

    printf("Enter the number of keys: ");
    scanf("%d", &key_count);
    printf("Enter the number of offsets: ");
    scanf("%d", &offset_count);
    printf("Enter the maximum size for memory allocation (in bytes): ");
    scanf("%d", &max_size);
    printf("Enter the maximum consecutive duplicate values allowed: ");
    scanf("%d", &max_consecutive_duplicates);

    // Allocate and initialize key and offset arrays
    keys = (int *)malloc(key_count * sizeof(int));
    offsets = (long *)malloc(offset_count * sizeof(long));

    // Initialize record array
    num_records = 0;
    while (num_records < key_count) {
        // Generate random value within a given range
        int value;
        do {
            // Ensure no two consecutive records have the same value
            value = rand() % 100 + 1; // Adjust the range if necessary
        } while (rand() % max_consecutive_duplicates == 0 && num_records > 0);

        record_values = (int *)malloc(num_records * sizeof(int));
        for (int i = 0; i < num_records; i++) {
            record_values[i] = value;
        }

        records = (record **)malloc((num_records + 1) * sizeof(record *));
        for (int i = 0; i <= num_records; i++) {
            records[i] = (record *)malloc(sizeof(record));
            records[i]->value = record_values[i];
        }

        // Update pointers and increment the number of records
        for (int i = num_records; i > 0; i--) {
            records[i]->value = record_values[i - 1];
        }
        num_records++;

        free(record_values);
    }

    // Free allocated memory and exit
    free(keys);
    free(offsets);

    return 0;
}
