#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TRANSACTIONS 1000

typedef struct {
    char* data_block;
    int key;
} node;

typedef struct {
    node* node_ptr;
    unsigned long timestamp;
    enum status {
        PENDING,
        PROCESSING,
        COMPLETED,
        FAILED
    } status;
} transaction;

transaction* transactions[MAX_TRANSACTIONS];
int num_transactions = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* producer_thread_func(void* arg) {
    int i = 0;
    while (1) {
        pthread_mutex_lock(&lock);
        if (num_transactions < MAX_TRANSACTIONS) {
            transactions[num_transactions] = malloc(sizeof(transaction));
            transactions[num_transactions]->node_ptr = malloc(sizeof(node));
            transactions[num_transactions]->data_block = malloc(strlen("default_data") + 1);
            strcpy(transactions[num_transactions]->data_block, "default_data");
            transactions[num_transactions]->key = i++;
            transactions[num_transactions]->timestamp = time(NULL);
            transactions[num_transactions]->status = PENDING;
            num_transactions++;
        } else {
            pthread_cond_wait(&cond, &lock);
        }
        pthread_mutex_unlock(&lock);
    }
}

void* consumer_thread_func(void* arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        for (int i = 0; i < num_transactions; i++) {
            if (transactions[i]->status == PENDING) {
                transactions[i]->timestamp = time(NULL);
                transactions[i]->status = PROCESSING;
                printf("Transaction %d started\n", i);
                break;
            }
        }
        pthread_mutex_unlock(&lock);

        // simulate processing
        sleep(1);

        pthread_mutex_lock(&lock);
        for (int i = 0; i < num_transactions; i++) {
            if (transactions[i]->status == PROCESSING) {
                transactions[i]->timestamp = time(NULL);
                transactions[i]->status = COMPLETED;
                printf("Transaction %d completed\n", i);
                break;
            }
        }
        pthread_mutex_unlock(&lock);

        // simulate logging
        FILE* log_file = fopen("log.txt", "a");
        for (int i = 0; i < num_transactions; i++) {
            fprintf(log_file, "Transaction %d: status=%d\n", i, transactions[i]->status);
        }
        fclose(log_file);

        // signal producer thread
        pthread_cond_signal(&cond);
    }
}

int main() {
    pthread_t producer_thread;
    pthread_create(&producer_thread, NULL, producer_thread_func, NULL);

    for (int i = 0; i < 10; i++) {
        pthread_t consumer_thread;
        pthread_create(&consumer_thread, NULL, consumer_thread_func, NULL);
    }

    sleep(30); // run for 30 seconds

    return 0;
}
