typedef struct {
    int value;
} record_t;

record_t* generateRecords(int keyCount, int maxMemoryBudget) {
    int i, j;
    long* offsetValues;
    int* keys;
    record_t* records;
    srand(time(NULL)); // Initialize random seed
    int cacheSize = 100; // Default cache size
    int maxConsecutiveSameValue = 5; // Default maximum consecutive same value

    // Check for invalid inputs
    if (keyCount <= 0 || maxMemoryBudget <= 0) {
        return NULL;
    }

    // Calculate memory budget for offset values and keys arrays
    long offsetValuesSize = keyCount * sizeof(long);
    int keysSize = keyCount * sizeof(int);

    if ((offsetValuesSize + keysSize) > maxMemoryBudget) {
        printf("Error: Memory budget exceeded.\n");
        return NULL;
    }

    // Allocate memory for offset values and keys arrays
    offsetValues = (long*)malloc(offsetValuesSize);
    keys = (int*)malloc(keysSize);

    if (!offsetValues || !keys) {
        printf("Error: Memory allocation failed.\n");
        free(offsetValues);
        free(keys);
        return NULL;
    }

    // Initialize offset values and keys
    for (i = 0; i < keyCount; i++) {
        long randomValue = rand() % 10000; // Generate random value
        while (j < maxConsecutiveSameValue && randomValue == records[j].value) {
            randomValue = rand() % 10000; // Regenerate if same as previous
        }
        offsetValues[i] = randomValue;
        keys[i] = i; // Initialize key with current index
    }

    // Calculate memory budget for records array
    int recordSize = sizeof(record_t);
    int recordsSize = keyCount * recordSize;

    if (recordsSize > maxMemoryBudget) {
        printf("Error: Memory budget exceeded.\n");
        free(offsetValues);
        free(keys);
        return NULL;
    }

    // Allocate memory for records array
    records = (record_t*)malloc(recordsSize);

    if (!records) {
        printf("Error: Memory allocation failed.\n");
        free(offsetValues);
        free(keys);
        return NULL;
    }

    // Initialize records with random values
    for (i = 0; i < keyCount; i++) {
        record_t* currentRecord = &records[i];
        long randomValue = rand() % 10000; // Generate random value
        while (j < maxConsecutiveSameValue && randomValue == records[j].value) {
            randomValue = rand() % 10000; // Regenerate if same as previous
        }
        currentRecord->value = (int)randomValue;
    }

    return records;
}

