void manage_NFAPI_RRC_PDU(int N, NFAPI_RRC_PDU **pdu_list) {
    // Initialize a random seed for generating random numbers
    srand(time(NULL));

    // Allocate memory for the list of PDUs
    *pdu_list = (NFAPI_RRC_PDU *)malloc(N * sizeof(NFAPI_RRC_PDU));

    // Populate each PDU with random data and read from standard input
    for(int i=0; i<N; i++) {
        (*pdu_list)[i].RRC_PDU_TAG = rand() % 100;

        // Allocate memory for the RRC NAS MESSAGE
        int message_length = rand() % 100;
        (*pdu_list)[i].RRC_NAS_MESSAGE = (char *)malloc((message_length + 1) * sizeof(char));

        // Read from standard input and store in the message
        fgets((*pdu_list)[i].RRC_NAS_MESSAGE, message_length + 1, stdin);

        // Null-terminate the message string
        (*pdu_list)[i].RRC_NAS_MESSAGE[message_length] = '\0';
    }
}

// Function to handle dynamic memory allocation and deallocation
void free_PDU_list(NFAPI_RRC_PDU *pdu_list, int N) {
    for(int i=0; i<N; i++) {
        free(pdu_list[i].RRC_NAS_MESSAGE);
    }

    free(pdu_list);
}

// Function to implement a custom logging mechanism
void log_message(const char *level, const char *message) {
    printf("[%s] %s\n", level, message);
}

int main() {
    // Define the number of PDUs and allocate memory for the list
    int N = 10;
    NFAPI_RRC_PDU *pdu_list;

    // Call the function to manage the PDUs
    manage_NFAPI_RRC_PDU(N, &pdu_list);

    // Free the memory allocated by the PDU list
    free_PDU_list(pdu_list, N);

    return 0;
}
