// Function to create a new session
Session* create_session(char* session_id, time_t timestamp, char* client_ip) {
    Session* session = (Session*)malloc(sizeof(Session));
    session->session_id = malloc(strlen(session_id) + 1);
    strcpy(session->session_id, session_id);
    session->timestamp = timestamp;
    session->client_ip = malloc(strlen(client_ip) + 1);
    strcpy(session->client_ip, client_ip);
    session->events = NULL;
    return session;
}

// Function to add an event to a session
void add_event(Session* session, char* event) {
    list* new_events = (list*)malloc(sizeof(list));
    new_events->next = session->events;
    session->events = new_events;
    new_events->data = malloc(strlen(event) + 1);
    strcpy(new_events->data, event);
}

// Function to manage the buffer system
Buffer* create_buffer(int capacity) {
    Buffer* buffer = (Buffer*)malloc(sizeof(Buffer));
    buffer->capacity = capacity;
    buffer->size = 0;
    buffer->data = (void**)malloc(capacity * sizeof(void*));
    pthread_mutex_init(&buffer->mutex, NULL);
    return buffer;
}

// Function to add a session to the buffer
void add_session(Buffer* buffer, Session* session) {
    pthread_mutex_lock(&buffer->mutex);
    if(buffer->size >= buffer->capacity) {
        // Handle buffer overflow (e.g., by resizing the buffer)
    }
    buffer->data[buffer->size++] = session;
    pthread_mutex_unlock(&buffer->mutex);
}

// Function to get a session from the buffer
Session* get_session(Buffer* buffer, int index) {
    pthread_mutex_lock(&buffer->mutex);
    Session* session = (Session*)buffer->data[index];
    pthread_mutex_unlock(&buffer->mutex);
    return session;
}

// Function to remove a session from the buffer
void remove_session(Buffer* buffer, int index) {
    pthread_mutex_lock(&buffer->mutex);
    if(index < 0 || index >= buffer->size) {
        // Handle invalid index (e.g., by returning an error)
    }
    for(int i = index; i < buffer->size - 1; i++) {
        buffer->data[i] = buffer->data[i + 1];
    }
    buffer->size--;
    pthread_mutex_unlock(&buffer->mutex);
}

