    int* offsets = (int*)malloc(key_count * sizeof(int));

    // Initialize record pointers to corresponding offsets
    for (int i = 0; i < key_count; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        records[i]->offset = &offsets[i];
        records[i]->index = keys[i];
        records[i]->ref_count = 1;
    }

    // Free allocated memory
    free(offsets);

    return records;
