typedef struct LTE_CELL_INFO_T {
    int cell_id;
    int pci;
    int rssi;
    int tx_power_level;
    float sinr;
    struct NFAPI_CRC_INDICATION_PDU_T* crc_indication_list;
} LTE_CELL_INFO_T;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

LTE_CELL_INFO_T* init_cell_info(int num_cells, int num_crc_entries) {
    LTE_CELL_INFO_T* cell_info = (LTE_CELL_INFO_T*)malloc(num_cells * sizeof(LTE_CELL_INFO_T));
    for (int i = 0; i < num_cells; i++) {
        cell_info[i].cell_id = rand() % (1 << 16);
        // Ensure unique CELL_ID values
        int collision;
        do {
            collision = 0;
            for (int j = 0; j < i; j++) {
                if (cell_info[j].cell_id == cell_info[i].cell_id) {
                    collision = 1;
                    break;
                }
            }
        } while (collision);
        // Populate the rest of the structure
        cell_info[i].pci = rand() % (1 << 4);
        cell_info[i].rssi = rand() % (1 << 8);
        cell_info[i].tx_power_level = rand() % (1 << 4);
        cell_info[i].sinr = (float)rand() / RAND_MAX;
        // Dynamically allocate memory for the CRC indication list
        int crc_list_size = num_crc_entries;
        cell_info[i].crc_indication_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(crc_list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        for (int j = 0; j < crc_list_size; j++) {
            // Populate the CRC indication list
            NFAPI_CRC_INDICATION_PDU_T* crc_entry = &cell_info[i].crc_indication_list[j];
            crc_entry->rx_ue_information_tag = rand() % (1 << 16);
            crc_entry->rnti = rand() % (1 << 4);
            crc_entry->crc_indication_rel8_tag = rand() % (1 << 8);
            crc_entry->crcflag = rand() & 0x01;
        }
    }
    return cell_info;
}

void free_cell_info(LTE_CELL_INFO_T* cell_info, int num_cells) {
    for (int i = 0; i < num_cells; i++) {
        // Deallocate memory for the CRC indication list
        if (cell_info[i].crc_indication_list) {
            free(cell_info[i].crc_indication_list);
        }
    }
    free(cell_info);
}

void serialize_cell_info(LTE_CELL_INFO_T* cell_info, int num_cells, FILE* file) {
    // Serialize the LTE CELL INFO T structure
    for (int i = 0; i < num_cells; i++) {
        fwrite(&cell_info[i], sizeof(LTE_CELL_INFO_T), 1, file);
        // Serialize the CRC indication list
        fwrite(cell_info[i].crc_indication_list, sizeof(NFAPI_CRC_INDICATION_PDU_T), cell_info[i].crc_indication_list_length, file);
    }
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_crc_entries(FILE* file) {
    NFAPI_CRC_INDICATION_PDU_T* crc_entries = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    fread(crc_entries, sizeof(NFAPI_CRC_INDINATION_PDU_T), 1, file);
    return crc_entries;
}

int main() {
    // Initialize the random number generator
    srand(time(NULL));

    int num_cells = 10; // Set the desired number of cell entries
    int num_crc_entries = 5; // Set the desired number of CRC indication entries per cell

    LTE_CELL_INFO_T* cell_info = init_cell_info(num_cells, num_crc_entries);

    // Perform any necessary resource monitoring or logging

    // Serialize the cell information for later use or transmission
    FILE* file = fopen("cell_info.bin", "wb");
    serialize_cell_info(cell_info, num_cells, file);
    fclose(file);

    // Deallocate memory for the cell information structure
    free_cell_info(cell_info, num_cells);

    return 0;
}

