double getRandomValue(double min, double max) {
    static uint32_t seed = 0;
    // Seed the random number generator if necessary
    if (!seed) {
        srand(time(NULL));
        seed = rand();
    }
    // Use a bloom filter to cache previously generated values
    int cached = -1; // Initialize as not found in cache
    // Check the cache for a value within the range
    for (int i = 0; i < BLOOM_FILTER_SIZE; i++) {
        if (bloom_filter[i] == seed) {
            cached = i;
            break;
        }
    }
    // If a cached value is found, use it; otherwise generate a new one
    double result = (cached >= 0) ? bloom_filter[cached] : ((double)rand() / RAND_MAX * (max - min) + min);
    return result;
}

