void* manage_memory(char *file_path, int64_t **offsets, size_t offsets_size, int **keys, size_t keys_size, int **records, size_t records_size) {
    // Read file and load into offsets array
    FILE *fp = fopen(file_path, "rb");
    if (fp == NULL) {
        return NULL;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    rewind(fp);

    *offsets = malloc((file_size / sizeof(int64_t)) + 1);
    fread(*offsets, sizeof(int64_t), file_size / sizeof(int64_t), fp);

    fclose(fp);

    // Populate keys array
    int network_call_result = network_api_call(keys, &keys_size);
    if (network_call_result != 0) {
        return NULL;
    }

    // Deduplicate and preserve order in keys array
    size_t i, j;
    for (i = 0; i < keys_size - 1; i++) {
        for (j = i + 1; j < keys_size; j++) {
            if (keys[i] == keys[j]) {
                memmove(&keys[j], &keys[j+1], sizeof(int) * (keys_size - j - 1));
                keys_size--;
                j--;
            }
        }
    }

    // Generate random unique records
    for (i = 0; i < records_size; i++) {
        int64_t record_id;
        do {
            record_id = rand() % INT_MAX;
        } while (find_record(record_id, *records) != -1);
        records[i] = &record_id;
    }

    // Free allocated memory
    free(*offsets);

    return NULL;
}

int main(int argc, char const *argv[]) {
    int64_t *offsets;
    int *keys;
    int *records;

    manage_memory("example.txt", &offsets, 0, &keys, 0, &records, 0);

    return 0;
}
