            for (int j = 0; j < symbol_per_frame; j++) {
                contexts[i].symbols[j].index = j;
                contexts[i].symbols[j].signal_strength = rand() % 100 + 1;  // Generate unique signal strength values within a range
            }
        } else {
            contexts[i].symbol_count = 0;
            contexts[i].symbols = NULL;
        }

        contexts[i].symbol_count = symbol_per_frame;
    }

    return contexts;
}

void mac_rx_context_free(MAC_RX_CONTEXT_T* contexts, int frame_count) {
    for (int i = 0; i < frame_count; i++) {
        if (contexts[i].symbols) {
            free(contexts[i].symbols);
        }
    }

