    // Initialize record array with dynamic resizing using a linked list
    NFAPI_CRC_INDICATION_PDU_T** records = (NFAPI_CRC_INDICATION_PDU_T**)malloc(array_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < array_size; i++) {
