        records[i]->rnti = rand() % 100;
        strcpy(records[i]->crc_indication, "CRC Indicator");
    }

    // Initialize float values
    float* floats = (float*)malloc(array_size * sizeof(float));
    for (int i = 0; i < array_size; i++) {
