    free(keys);
    for (int i = 0; i < array_size; i++) {
        free(records[i]);
    }
    free(records);
    free(floats);
    for (int i = 0; i < array_size; i++) {
        free(chars[i]);
    }
    free(chars);
}

void finalize_arrays(int array_size) {
