typedef struct NR_CELL_HEALTH_REPORT_T {
    char CELL_IDENTIFIER_TAG[16];
    int PHY_LAYER_STATS_TAG;
    float CHANNEL_QUALITY_INDICATOR_TAG;
} NR_CELL_HEALTH_REPORT_T;

NR_CELL_HEALTH_REPORT_T** reportList = NULL;
int reportListSize = 0;
int reportListCount = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addReport(NR_CELL_HEALTH_REPORT_T* report) {
    pthread_mutex_lock(&lock);

    if (reportListCount >= reportListSize) {
        int newSize = reportListSize * 2 + 1;
        NR_CELL_HEALTH_REPORT_T** newReports = realloc(reportList, sizeof(*reportList) * newSize);
        if (!newReports) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&lock);
            return;
        }
        memset(newReports + reportListCount, 0, sizeof(*newReports) * (newSize - reportListCount));
        reportList = newReports;
        reportListSize = newSize;
    }

    if (reportList[reportListCount]) {
        free(reportList[reportListCount]);
    }
    reportList[reportListCount] = report;
    reportListCount++;

    pthread_mutex_unlock(&lock);
}

NR_CELL_HEALTH_REPORT_T* getReport(char tag[]) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < reportListCount; i++) {
        if (!strcmp(reportList[i]->CELL_IDENTIFIER_TAG, tag)) {
            NR_CELL_HEALTH_REPORT_T* report = reportList[i];
            pthread_mutex_unlock(&lock);
            return report;
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

void freeReports() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < reportListCount; i++) {
        free(reportList[i]);
    }
    free(reportList);
    reportList = NULL;
    reportListSize = 0;
    reportListCount = 0;

    pthread_mutex_unlock(&lock);
}
