#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int CELL_ID;
    int PCI;
    int RSSI;
    float TX_POWER_LEVEL;
    float SINR;
} LTE_CELL_INFO_T;

void populateNFAPIAndCellInfo(int numCRCIndications, int numRows) {
    // Initialize CRC indication structures
    NFAPI_CRC_INDICATION_PDU_T *nfaPiStructs = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numCRCIndications * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < numCRCIndications; i++) {
        nfaPiStructs[i].RX_UE_INFORMATION_TAG = rand() % 100;
        nfaPiStructs[i].RNTI = rand() % 256;
        nfaPiStructs[i].CRC_INDICATION_REL8_TAG = (uint32_t)rand();
    }

    // Initialize LTE cell info structures
    LTE_CELL_INFO_T **lteCellInfoArray = (LTE_CELL_INFO_T **)malloc(numRows * sizeof(LTE_CELL_INFO_T *));
    for (int i = 0; i < numRows; i++) {
        LTE_CELL_INFO_T *cellInfoStruct = (LTE_CELL_INFO_T *)malloc(sizeof(LTE_CELL_INFO_T));

        // Initialize cell info fields
        cellInfoStruct->CELL_ID = rand() % 100;
        cellInfoStruct->PCI = rand() % 256;
        cellInfoStruct->RSSI = rand() % 1000;

        // Limit TX power level and SINR to valid ranges
        cellInfoStruct->TX_POWER_LEVEL = (float)rand() / RAND_MAX * 10.0;
        cellInfoStruct->SINR = (float)rand() / RAND_MAX * 20.0;

        lteCellInfoArray[i] = cellInfoStruct;
    }

    // Find the largest integer from CRC indication structures
    int maxInt = 0;
    for (int i = 0; i < numCRCIndications; i++) {
        if (nfaPiStructs[i].RX_UE_INFORMATION_TAG > maxInt) {
            maxInt = nfaPiStructs[i].RX_UE_INFORMATION_TAG;
        }
    }

    // Serialize the populated data into a binary format
    FILE *fp = fopen("output.bin", "wb");
    fwrite(nfaPiStructs, sizeof(NFAPI_CRC_INDICATION_PDU_T), numCRCIndications, fp);
    fwrite(lteCellInfoArray[0], sizeof(LTE_CELL_INFO_T), numRows, fp);

    fclose(fp);

    // Free memory
    free(nfaPiStructs);
    for (int i = 0; i < numRows; i++) {
        free(lteCellInfoArray[i]);
    }
    free(lteCellInfoArray);
}

int main() {
    int numCRCIndications, numRows;
    scanf("%d %d", &numCRCIndications, &numRows);
    populateNFAPIAndCellInfo(numCRCIndications, numRows);
    return 0;
}
