typedef enum { NORMAL, WARNING, ERROR } severity_t;

typedef struct {
    long timestamp;
    int id;
    char message[64];
    severity_t level;
} log_entry_t;

log_system_t* init_log_system(int max_entries) {
    log_system_t* log_sys = (log_system_t*)malloc(sizeof(log_system_t));
    if (!log_sys) return NULL; // Handle memory allocation failure

    log_sys->max_entries = max_entries;
    log_sys->entries = (log_entry_t*)malloc(max_entries * sizeof(log_entry_t));
    if (!log_sys->entries) {
        free(log_sys); return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < max_entries; i++) {
        log_sys->entries[i].timestamp = i;
        log_sys->entries[i].id = i + 1;
        strcpy(log_sys->entries[i].message, "INFO");
        log_sys->entries[i].level = NORMAL;
    }

    return log_sys;
}

int main() {
    int num_log_sys = 2; // Example usage: define two log systems
    log_system_t* log_sys_arr[num_log_sys];

    for (int i = 0; i < num_log_sys; i++) {
        int max_entries = i + 1; // Define varying maximum entry limits
        log_sys_arr[i] = init_log_system(max_entries);
    }

    // Example usage: print the initial state of each log system
    for (int i = 0; i < num_log_sys; i++) {
        log_system_t* log_sys = log_sys_arr[i];
        printf("Log System %d:\n", i + 1);
        for (int j = 0; j < log_sys->max_entries; j++) {
            log_entry_t* entry = &log_sys->entries[j];
            printf("Timestamp: %ld, ID: %d, Message: '%s', Level: %s\n",
                   entry->timestamp, entry->id, entry->message, severity_str(entry->level));
        }
    }

    // Remember to free the allocated memory when done
    for (int i = 0; i < num_log_sys; i++) {
        log_system_t* log_sys = log_sys_arr[i];
        free(log_sys->entries);
        free(log_sys);
    }

    return 0;
}

// Define severity string mappings as needed
char* severity_str(severity_t level) {
    switch (level) {
        case NORMAL: return "NORMAL";
        case WARNING: return "WARNING";
        case ERROR: return "ERROR";
        default: return "UNKNOWN";
    }
}
