// Define a structure to represent an identifier
typedef struct {
    char domain[50];
    char path[50];
    char query[50];
} Identifier;

// Function to generate the identifier from the URL
void generateIdentifier(char* url, Identifier* id) {
    // Parse the URL into its components
    int i = 0;
    while (i < strlen(url)) {
        if (url[i] == '/') {
            strcpy(id->path, &url[i+1]);
            break;
        }
        i++;
    }

    // Extract the domain name and query parameters
    for (int j = 0; j < i; j++) {
        if (url[j] == '://') {
            strcpy(id->domain, &url[j+3]);
            int k = 0;
            while (k < strlen(url)-i) {
                if (url[i+k] == '?') {
