// Function to read compressed file in an efficient streaming manner
double readCompressedFile() {
    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    int ret;
    unsigned char in[BUFFER_SIZE];
    FILE *fp = fopen("file_name.compressed", "rb");
    if (!fp) {
        printf("Error: Unable to open file.\n");
        return -1.0;
    }

    deflateInit(&strm, Z_DEFAULT_COMPRESSION);
    do {
        strm.avail = fread(in, 1, BUFFER_SIZE, fp);
        strm.next_in = in;
        while (strm.avail > 0) {
            ret = deflate(&strm, Z_NO_FLUSH);
            if (ret < 0) {
                printf("Error: deflation failed.\n");
                return -1.0;
            }
            strm.next_out = in + strm.total_out;
            strmavail = BUFFER_SIZE - strm.total_out;
        }
    } while (strm.total_out < file_size);

    fclose(fp);
    deflateEnd(&strm);
}

// Custom character generator with a user-specified seed
char customCharacterGenerator(int index) {
    srand(index);
    static char chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    return chars[rand() % strlen(chars)];
