typedef struct {
    int key;
    long offset;
} record;

record* initArrays(size_t size, size_t blockSize) {
    // Initialize arrays with sequential values for keys and random values for offsets
    record* records = (record*)malloc(size * sizeof(record));
    int* keys = (int*)malloc(size * sizeof(int));
    long* offsets = (long*)malloc(size * sizeof(long));

    if (!records || !keys || !offsets) {
        printf("Error allocating memory.\n");
        return NULL;
    }

    for (size_t i = 0; i < size; i++) {
        keys[i] = i;
        offsets[i] = rand() % (blockSize - 1);
    }

    record* result = (record*)malloc(size * sizeof(record));

    if (!result) {
        printf("Error allocating memory.\n");
        return NULL;
    }

    for (size_t i = 0; i < size; i++) {
        record r;
        r.key = keys[i];
        r.offset = offsets[i];
        result[i] = r;
    }

    free(keys);
    free(offsets);

    return result;
}
