#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
    int data;
} record;

record** manage_memory(int* num_records) {
    // Initialize the arrays
    record** records = (record**)malloc(1 * sizeof(record*));
    long* offsets = (long*)malloc(10000 * sizeof(long));
    int* keys = (int*)malloc(10000 * sizeof(int));

    // Initialize metadata
    time_t last_modified;
    *num_records = 0;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    void* thread_function(void* arg) {
        record** records = (record**)arg;
        for (int i = 0; i < 10000; i++) {
            // Allocate and initialize a new record
            record* new_record = (record*)malloc(sizeof(record));
            new_record->key = i % 10000;
            new_record->offset = offsets[i];
            new_record->data = rand() % 1000;

            pthread_mutex_lock(&mutex);
            records[(*num_records)++] = &new_record;
            pthread_mutex_unlock(&mutex);
        }
    }

    // Create threads to fill the arrays
    pthread_t thread;
    pthread_create(&thread, NULL, thread_function, (void*)records);

    // Wait for all threads to finish
    pthread_join(thread, NULL);

    return records;
}

int main() {
    int num_records;
    record** records = manage_memory(&num_records);
    free(records[0]);
    free(records);
    return 0;
}
