typedef struct {
    time_t timestamp;
    int type;
    char *tag;
} Event;

Event *initEvents(int n) {
    return (Event *)malloc(n * sizeof(Event));
}

void freeEvents(Event *events, int n) {
    for (int i = 0; i < n; ++i) {
        free(events[i].tag);
    }
    free(events);
}

void printEvents(Event *events, int n) {
    printf("Timestamp\tType\tTag\n");
    for (int i = 0; i < n; ++i) {
        printf("%lu\t%d\t%s\n", events[i].timestamp, events[i].type, events[i].tag);
    }
}

void sortEvents(Event *events, int n) {
    qsort(events, n, sizeof(Event), compareEvents);
}

int compareEvents(const void *a, const void *b) {
    Event *eventA = (Event *)a;
    Event *eventB = (Event *)b;
    return eventA->timestamp - eventB->timestamp;
}

void processEvents() {
    int n;
    scanf("%d", &n);

    Event *events = initEvents(n);

    for (int i = 0; i < n; ++i) {
        Event event;
        scanf("%lu %d %s", &event.timestamp, &event.type, event.tag);

        // Add logic to handle duplicate timestamps
        // ...

        events[i] = event;
    }

    sortEvents(events, n);

    int earliestTimestamp = events[0].timestamp;
    int latestTimestamp = events[n - 1].timestamp;

    printf("Earliest timestamp: %lu\n", earliestTimestamp);
    printf("Latest timestamp: %lu\n", latestTimestamp);

    printEvents(events, n);

    freeEvents(events, n);
}

int main() {
    processEvents();
    return 0;
}
