    int num_active_reports = 0;
    for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
        if (measurement_reports[i].RNTI != 0) {
            num_active_reports++;
        }
    }
    if (num_active_reports > ALERT_THRESHOLD) {
        printf("Alert: Number of active measurement reports exceeds threshold.\n");
    }

    // Provide an API for external applications to query the current status
    for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
        if (measurement_reports[i].RNTI != 0) {
            printf("Report %d: Timestamp - %s, Validity Status - %s\n", i, measurement_reports[i].RX_UE_INFORMATION_TAG, "Valid");
        }
    }

    // Periodically clear old measurement reports
    time_t current_time = time(NULL);
    for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
        if (current_time - measurement_reports[i].timestamp > DEFAULT_VALIDITY_THRESHOLD) {
            free(measurement_reports[i].RX_UE_INFORMATION_TAG);
            measurement_reports[i] = measurement_reports[MAX_ARRAY_SIZE - 1];
        }
    }

    // Handle fragmentation issues
    void *mem_pool = malloc(1024); // Initialize a memory pool of size 1024 bytes
    for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
        if (measurement_reports[i].RNTI != 0) {
            NR_UE_MEASUREMENT_REPORT_T *report = (NR_UE_MEASUREMENT_REPORT_T *)malloc(sizeof(NR_UE_MEASUREMENT_REPORT_T));
            // Check for fragmentation and handle it
            mem_pool = realloc(mem_pool, sizeof(report));
        }
    }

    return 0;
}
