#define MAX_UES 1000
#define MIN_UES 10
#define MAX_SNR 40
#define MIN_SNR -30

typedef struct {
    int ue_id;
    float rssi;
    float snr;
    int cell_id;
    time_t timestamp;
} UEContext;

UEContext* ues = NULL;
int num_uces = 0;

void init_ue(int ue_id) {
    UEContext* new_ue = (UEContext*)malloc(sizeof(UEContext));
    if (!new_ue) return; // Handle memory allocation failure
    new_ue->ue_id = ue_id;
    new_ue->rssi = (float)(rand() % (MAX_SNR - MIN_SNR + 1)) + MIN_SNR;
    new_ue->snr = (float)(rand() % (MAX_SNR - MIN_SNR + 1)) + MIN_SNR;
    new_ue->cell_id = rand() % 100; // Random cell ID
    new_ue->timestamp = time(NULL);
}

void export_json(const char* filename) {
    json_object* root = json_object_new_object();
    for (int i = 0; i < num_uces; i++) {
        UEContext* ue = &ues[i];
        json_object* ue_obj = json_object_new_object();
        json_object_object_add(ue_obj, "ue_id", json_stringtentify(&json_object_to_json_string(json_integer_create(ue->ue_id))));
        json_object_object_add(ue_obj, "rssi", json_real_create(ue->rssi));
        json_object_object_add(ue_obj, "snr", json_real_create(ue->snr));
        json_object_object_add(ue_obj, "cell_id", json_integer_create(ue->cell_id));
        json_object_object_add(root, integer_to_string(i), ue_obj);
    }
    FILE* f = fopen(filename, "w");
    if (f) {
        json_write_file(root, f);
        fclose(f);
    } else {
        printf("Error writing file: %s\n", filename);
    }
    json_decref(root);
}

void background_thread() {
    // Periodically scan the UE context list for inactive contexts
    while (1) {
        sleep(10); // Adjust the timeout period as needed
        for (int i = 0; i < num_uces; i++) {
            UEContext* ue = &ues[i];
            if ((time(NULL) - ue->timestamp) > 60 * 5) { // Inactive context threshold in seconds
                free(ue);
                ues[i] = ues[--num_uces]; // Shift inactive context to the end and decrement count
                break;
            }
        }
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator

    // Initialize the UE list with random values for signal quality indicators (RSSI) and signal-to-noise ratio (SNR)
    for (int i = 0; i < MIN_UES; i++) {
        init_ue(i);
    }

    // Start the background thread
    pthread_t thread;
    pthread_create(&thread, NULL, &background_thread, NULL);

    // Export UE context data to a JSON file periodically
    while (1) {
        sleep(30); // Adjust the export interval as needed
        char filename[20];
        sprintf(filename, "ue_contexts_%d.json", time(NULL));
        export_json(filename);
    }

    return 0;
}
