        int thread_id = i;

        pthread_create(&threads[i], NULL, 
                       &measurement_report_initializer, 
                       (void *)thread_id);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
