    NR_UE_MEASUREMENT_REPORT_T report;
    report.ue_info.rnti = thread_id + 1;
    strcpy(report.ue_info.rx_ue_information_tag, "RX_UE_INFORMATION_TAG");
    report.meas_result.measurement_type = rand() % 10; // random measurement type
    report.meas_result.value = (double)rand() / RAND_MAX; // random value

    if (!measurement_reports) {
        measurement_reports = (NR_UE_MEASUREMENT_REPORT_T *)malloc(NR_UE_MEASUREMENT_REPORT_T * sizeof(NR_UE_MEASUREMENT_REPORT_T));
        if (!measurement_reports) {
            printf("Failed to allocate memory for measurement reports.\n");
            pthread_exit(NULL);
        }
    }

    measurement_reports[report_count++] = report;
}

int is_measurement_report_initialized(int rnti) {
    for (int i = 0; i < report_count; i++) {
        if (measurement_reports[i].ue_info.rnti == rnti) {
            return 1;
        }
    }

    return 0;
}

void log_initialization_attempts() {
    printf("Initialization attempts: %d successful, %d failed.\n", initialized_attempts, failed_attempts);
}

int main() {
    int num_threads = (report_count > MAX_THREADS) ? MAX_THREADS : report_count;
    initialize_measurement_reports(num_threads);

    log_initialization_attempts();

    return 0;
}
