        (*weathers)[i] = (char *)malloc(MAX_WEATHER_DATA);
        if ((*weathers)[i] == NULL) {
            printf("Error: Weather array allocation failed.\n");
            free(*temperatures);
            for (int j = 0; j < i; j++) {
