['```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_MEMORY 1024 * 1024 * 10 // 10MB maximum memory usage
#define MEMORY_THRESHOLD 90 // percentage threshold for sending alerts
#define LOG_SIZE 1000 // size of log buffer

typedef struct record {
    int value;
} record_t;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed!\n");
        return NULL;
    }
    return ptr;
}

int init_data_structure(int num_records, long** offsets, int** keys, record_t*** records) {
    // Calculate required memory size based on num_records
    size_t total_size = sizeof(long) * num_records + sizeof(int) * num_records + sizeof(record_t) * num_records;

    if (total_size > MAX_MEMORY) {
        fprintf(stderr, "Memory allocation failed! Total size exceeds %ld bytes.\n", MAX_MEMORY);
        return -1;
    }

    // Allocate memory for offsets
    long* offsets_ptr = allocate_memory(total_size / 2);
    if (!offsets_ptr)
        return -1;

    // Allocate memory for keys
    int* keys_ptr = allocate_memory(total_size / 4);
    if (!keys_ptr) {
        free(offsets_ptr);
        return -1;
    }

    // Allocate memory for records
    record_t** records_ptr = allocate_memory(total_size / 8);
    if (!records_ptr) {
        free(offsets_ptr);
        free(keys_ptr);
        return -1;
    }

    *offsets = offsets_ptr;
    *keys = keys_ptr;
    *records = records_ptr;

    return 0;
}

void monitor_memory(size_t total_size, int num_records, long* offsets, int* keys, record_t** records) {
    size_t current_usage = total_size / (1024 * 1024);

    if (current_usage > MEMORY_THRESHOLD) {
        // Send alert or log memory usage
        fprintf(stderr, "Memory usage exceeds %d%%! Current usage: %ld MB.\n", MEMORY_THRESHOLD, current_usage);
    }
}

void* log_memory(void*) {
    size_t total_size = 0;
    int num_records = 0;

    while (1) {
        // Monitor memory usage and send alerts if necessary
        monitor_memory(total_size, num_records, *offsets, *keys, *records);

        // Log memory usage periodically
        if (total_size > LOG_SIZE) {
            FILE* log_file = fopen("memory.log", "a");
            fprintf(log_file, "%ld MB\n", total_size / (1024 * 1024));
            fclose(log_file);
            total_size -= LOG_SIZE;
        }

        // Sleep for a while before monitoring again
        sleep(1);
    }
}

void* thread_func(void*) {
    // Simulate data processing operation
    // ...

    return NULL;
}

int main() {
    pthread_t thread;

    int num_records = 1000;
    long* offsets;
    int* keys;
    record_t** records;

    if (init_data_structure(num_records, &offsets, &keys, &records) < 0)
        return -1;

    // Create and start a new thread for data processing
    pthread_create(&thread, NULL, thread_func, NULL);

    return 0;
}
