#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define the maximum size of a record buffer
#define RECORD_BUFFER_SIZE 1024

// Define the initial capacity of the hash table
#define HASH_TABLE_CAPACITY 128

// Define the range for initializing random values in records and nodes
#define RANDOM_VALUE_RANGE 1000

typedef struct {
    int value;
    char *buffer;
    struct node *node_ref;
} record;

typedef struct {
    struct node *next;
    int metadata;
} node;

record **records;
int *keys;
node *head;
node *tail;
unsigned long long hash_table[HASH_TABLE_CAPACITY];

void initialize_data_structures(int num_records, int buffer_size) {
    // Validate input parameters
    if (num_records < 1 || buffer_size < RECORD_BUFFER_SIZE) {
        printf("Invalid input parameters. Aborting initialization.\n");
        return;
    }

    // Initialize the hash table with a random seed
    srand(time(NULL));

    // Allocate memory for records, keys, and nodes
    records = (record **)malloc(num_records * sizeof(record *));
    keys = (int *)malloc(num_records * sizeof(int));
    head = (node *)malloc(sizeof(node));
    tail = head;
    head->next = NULL;

    // Initialize each record structure with a random value and buffer
    for (int i = 0; i < num_records; i++) {
        records[i] = (record *)malloc(sizeof(record));
        records[i]->value = rand() % RANDOM_VALUE_RANGE;
        records[i]->buffer = (char *)malloc(buffer_size);
        // Initialize the node reference with a null pointer
        records[i]->node_ref = NULL;

        // Add the record to the hash table
        unsigned long long key = keys[i] = i;
        int index = key % HASH_TABLE_CAPACITY;
        while (hash_table[index]) {
            index = (index + 1) % HASH_TABLE_CAPACITY;
        }
        hash_table[index] = (unsigned long long)records[i];
    }

    // Initialize the linked list of nodes
    node *current = head;
    for (int i = 0; i < num_records - 1; i++) {
        node *new_node = (node *)malloc(sizeof(node));
        new_node->next = NULL;
        current->next = new_node;
        current = new_node;
    }
}
