    float value;
    char name[PROFILE_STRING_MAX_LENGTH];
    unsigned long id;
} Profile;

Profile* init_profiles(int num_profiles, int* err) {
    if (num_profiles <= 0 || !err)
        return NULL;

    *err = 0;
    Profile* profiles = (Profile*)malloc(num_profiles * sizeof(Profile));
    if (!profiles) {
        *err = -1; // Memory allocation failed
        return NULL;
    }

    for (int i = 0; i < num_profiles; i++) {
        profiles[i].value = (float)(rand() / (RAND_MAX + 1.0));
        sprintf(profiles[i].name, "Profile %d", i);
        profiles[i].id = rand();
    }
    return profiles;
}

void release_profiles(Profile* profiles, int num_profiles) {
    if (!profiles)
        return;

    free(profiles);
}

