    int num_profiles = 0;
    float* values = NULL;
    unsigned long* ids = NULL;
    int err = 0;
    Profile* profiles = NULL;
    FILE* log_file = fopen("log.txt", "w");

    // Read user input
    printf("Enter the number of profiles: ");
    scanf("%d", &num_profiles);

    // Validate input and calculate total memory usage
    if (num_profiles <= 0 || num_profiles > PROFILE_ARRAY_MAX_SIZE) {
        err = -2; // Invalid profile count
    } else {
        values = (float*)malloc(num_profiles * sizeof(float));
