        printf("Enter the size of float and unsigned long arrays: ");
        scanf("%d %d", &num_profiles, &num_profiles);

        // Validate input again
        if (num_profiles > MAX_SIZE / (sizeof(float) + sizeof(unsigned long))) {
            err = -3; // Memory limit exceeded
        }
    }

    if (!err) {
        profiles = init_profiles(num_profiles, &err);
        if (profiles)
            release_profiles(profiles, num_profiles);
    }

    fclose(log_file);

