```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
    int data;
} record_t;

struct {
    record_t* records;
    int* keys;
    long* offsets;
    size_t record_count;
    pthread_mutex_t lock;
} *record_manager_t;

record_manager_t record_manager_init(size_t record_count) {
    record_manager_t manager = malloc(sizeof(*manager));
    if (manager == NULL)
        return NULL;

    manager->records = malloc(record_count * sizeof(*manager->records));
    if (manager->records == NULL) {
        free(manager);
        return NULL;
    }

    manager->keys = malloc(record_count * sizeof(*manager->keys));
    if (manager->keys == NULL) {
        free(manager->records);
        free(manager);
        return NULL;
    }

    manager->offsets = malloc(record_count * sizeof(*manager->offsets));
    if (manager->offsets == NULL) {
        free(manager->keys);
        free(manager->records);
        free(manager);
        return NULL;
    }

    manager->record_count = record_count;

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void record_manager_free(record_manager_t manager) {
    if (manager == NULL)
        return;

    free(manager->records);
    free(manager->keys);
    free(manager->offsets);
    free(manager);

    pthread_mutex_destroy(&manager->lock);
}
