// Define the LTE_CELL_INFO_T structure
typedef struct {
    uint16_t cell_id;
    int8_t pci;
    int8_t rssi;
    int8_t tx_power_level;
    float sinr;
} LTE_CELL_INFO_T;

// Function to generate a random LTE CELL ID
uint16_t rand_cell_id(void) {
    static uint16_t last_cell_id = 0;
    static unsigned int seed = time(NULL);
    static const unsigned int max_cell_id = 65535; // Assuming max_cell_id is the maximum cell ID

    seed = (seed * 1103515245 + 12345) % 2^31;
    uint16_t new_cell_id = (uint16_t)(seed % max_cell_id);

    if (new_cell_id == last_cell_id)
        new_cell_id = (last_cell_id + 1) % max_cell_id;

    last_cell_id = new_cell_id;
    return new_cell_id;
}

// Function to generate a random PCI value
int8_t rand_pci(void) {
    static int8_t last_pci = 0;
    static const unsigned int max_pci = 110;

    if (last_pci == max_pci - 1)
        last_pci = 0;
    else
        ++last_pci;

    return (int8_t)last_pci;
}

// Function to generate a random RSSI value
int8_t rand_rssi(void) {
    static int8_t last_rssi = 0;
    static const unsigned int max_rssi = 127; // Assuming max_rssi is the maximum RSSI

    if (last_rssi == max_rssi)
        last_rssi = -max_rssi;

    return (int8_t)(last_rssi + rand() % ((max_rssi - (-max_rssi)) + 1));
}

// Function to generate a random TX POWER LEVEL value
int8_t rand_tx_power_level(void) {
    static int8_t last_tx_power_level = 0;
    static const unsigned int max_tx_power_level = 31; // Assuming max_tx_power_level is the maximum TX power level

    if (last_tx_power_level == max_tx_power_level)
        last_tx_power_level = -max_tx_power_level;

    return (int8_t)(last_tx_power_level + rand() % ((max_tx_power_level - (-max_tx_power_level)) + 1));
}

// Function to generate a random SINR value
float rand_sinr(void) {
    static float last_sinr = 0.0;
    static const float max_sinr = 40.0; // Assuming max_sinr is the maximum SINR

    if (last_sinr >= max_sinr)
        last_sinr = -max_sinr;

    return (float)(last_sinr + rand() % ((int)max_sinr - (-max_sinr)) * 1.0);
}

// Function to initialize and populate an array of LTE_CELL_INFO_T structures
LTE_CELL_INFO_T* init_cell_info_array(int num_entries, int* error_code) {
    LTE_CELL_INFO_T* cell_info_array = NULL;
    uint16_t current_cell_id;

    if (num_entries <= 0) {
        *error_code = -1; // Invalid number of entries
        return NULL;
    }

    cell_info_array = (LTE_CELL_INFO_T*)malloc(num_entries * sizeof(LTE_CELL_INFO_T));
    if (cell_info_array == NULL) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    for (int i = 0; i < num_entries; ++i) {
        cell_info_array[i].cell_id = rand_cell_id();
        cell_info_array[i].pci = rand_pci();
        cell_info_array[i].rssi = rand_rssi();
        cell_info_array[i].tx_power_level = rand_tx_power_level();
        cell_info_array[i].sinr = rand_sinr();
    }

    return cell_info_array;
}

